import scala.io.{StdIn => in}

object Main extends App {
  val Array(h, w, d) = in.readLine.split(" ").map(_.toInt)
  case class Point(x:Int, y:Int) {
    def manhattan(that: Point): Int = {
      (that.x - this.x).abs + (that.y - this.y).abs
    }
  }
  val table = Array.ofDim[Point](h*w+1)
  val grid = Iterator.continually(in.readLine)
    .take(h)
    .map(_.split(" ").map(_.toInt))
    .toArray

  for{
    i <- 0 until h
    j <- 0 until w
  } table(grid(i)(j)) = new Point(y = i, x = j)

  val acc = Array.ofDim[Int](h*w+1)
  for(i <- 1 to h*w-d) {
    acc(i+d) = acc(i) + (table(i+d) manhattan table(i))
  }

  val out = new java.io.PrintWriter(System.out)
  val q = in.readInt
  Iterator.continually(in.readLine)
    .take(q)
    .map(_.split(" ")map(_.toInt))
    .foreach (e => {
      val l = e(0)
      var r = e(1)
      out.println(acc(r) - acc(l))
    })
  out.flush
}

