import scala.io.{StdIn => in}

object Main extends App {
  val Array(h, w, d) = in.readLine.split(" ").map(_.toInt)
  case class Point(x:Int, y:Int) {
    def -(that: Point): Point = new Point(x - that.x, y - that.y)
    def mDist(): Int = this.x.abs + this.y.abs
  }
  val table = Array.ofDim[Point](h*w+1)
  val grid = Iterator.continually(in.readLine)
    .take(h)
    .map(_.split(" ").map(_.toInt))
    .toArray

  for{
    i <- 0 until h
    j <- 0 until w
  } table(grid(i)(j)) = new Point(y = i, x = j)


  val res = Array.ofDim[Int](h*w+1)
  for(i <- 1 to h*w-d) {
    res(i+d) = res(i) + (table(i+d) - table(i)).mDist 
  }

  val out = new java.io.PrintWriter(System.out)
  val q = in.readInt
  Iterator.continually(in.readLine)
    .take(q)
    .map(_.split(" ")map(_.toInt))
    .foreach (e => {
      val l = e(0)
      var r = e(1)
      out.println(res(r) - res(l))
    })
  out.flush
}

object Main extends App {
  val sc = new java.util.Scanner(System.in)
  val h, w, d = sc.nextInt()
  val n = h * w;
  val pos = Array.fill(n)((0, 0))
  for {
    i <- 0 until h
    j <- 0 until w
  } {
    val a = sc.nextInt() - 1
    pos(a) = (i, j)
  }
  val c = Array.fill(d, n / d)(0)
  for {
    i <- 0 until d
    j <- 0 until n / d
  } {
    if (i + (j + 1) * d < n) {
      val (x1, y1) = pos(i + j * d)
      val (x2, y2) = pos(i + (j + 1) * d)
      c(i)(j) = (x1 - x2).abs + (y1 - y2).abs
    }
  }

  val ca = c.map(_.scanLeft(0)(_ + _))

  val q = sc.nextInt()
  val lr = List.fill(q)((sc.nextInt()-1, sc.nextInt()-1))
  val pw = new java.io.PrintWriter(Console.out)
  for ((l, r) <- lr) {
    val x = l % d
    pw.println(ca(x)(r / d) - ca(x)(l / d))
  }
  pw.flush()
}

