LL d[90001];

void solve()
{
    int H, W, D;
    cin >> H >> W >> D;
    map<int, pos> num_pos;
    REP1 (i, H)
    {
        REP1 (j, W)
        {
            int A;
            cin >> A;
            num_pos[A] = pos{i, j};
        }
    }

    for (int i = D + 1; i <= H * W; i++)
