        pos pL = num_pos[i], pDL = num_pos[i - D];
        d[i] = d[i - D] + abs(pL.x - pDL.x) + abs(pL.y - pDL.y);
    }

    int Q;
    cin >> Q;
    REP1 (_, Q)
    {
        int L, R;
        cin >> L >> R;
        std::cout << d[R] - d[L] << endl;
    }
}

