      masu[A] = i * W + j;
    }
  }
  ll dist[909][909];
  for (int i = 0; i < 909; i ++) {
    for (int j = 0; j < 909; j ++) {
      dist[i][j] = 0;
    }
  }
  for (int i = 1; i <= D; i ++) {
    for (int j = 1; D * j + i < H * W; j ++) {
