    vvi v(h,vi(w));
    rep(i,h)rep(j,w){
        cin>>v[i][j];
        v[i][j]--;
    }
    WAR_FLY wa(h*w);
    for(int i=0;i<h;i++){
        for(int j=0;j<w-1;j++){
            wa.add(v[i][j],v[i][j+1],1);
        }
    }
    for(int i=0;i<w;i++){
        for(int j=0;j<h-1;j++){
            wa.add(v[j][i],v[j+1][i],1);
        }
    }
    wa.warshall_floyd();
    // wa.show();
    int q;
    cin>>q;
    rep(_,q){
        int l,r;
        cin>>l>>r;
