	int tmp;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			cin >> tmp;
			memo[tmp % D][tmp / D] = i * W + j;
		}
	}

	vector<CuSum<int>> cost(D, H*W / D);
	for (int i = 0; i < D; i++) {
		for (int j = H * W /D; j >= 1; j--) {
			memo[i][j] = abs(memo[i][j] / W - memo[i][j - 1] / W) + abs(memo[i][j] % W - memo[i][j - 1] % W);
		}
		memo[i][0] = 0;
		cost[i] = CuSum<int>(memo[i]);
	}

	int Q, L ,R;
	cin >> Q;
	for (int i = 0; i < Q; i++) {
		cin >> L >> R;
		cout << cost[L%D](L / D, R / D - 1) << "\n";
	}

	return 0;
}

