using namespace std;

typedef pair<int,int> ii;
typedef vector<int> vi;
#define REP(i, a, b) for(int i = int(a); i <= int(b); i++)
#define LOOP(i, v) for(int i = 0; i < v.size(); i++)
#define EPS 1e-9
#define INF 1e12
#define debug(x) cerr << "DEBUG : " << (#x) << " => " << (x) << endl

int main()
{
  int N, M, D, Q, L, R;
  int A[300][300];
  ii trouve[90001];
  int cost[90001];
  long long int cumule[90001][21];

  scanf("%d %d %d", &N, &M, &D);
  REP(i, 0, N-1) REP(j, 0, M-1)
  {
    scanf("%d", &A[i][j]);
    trouve[A[i][j]] = make_pair(i, j);
  }

  REP(i, 1, N*M)
  {
    int x1 = trouve[i].first;
    int y1 = trouve[i].second;
    if(i+D <= N*M)
    {
      int x2 = trouve[i+D].first;
      int y2 = trouve[i+D].second;
      cost[i] = max(x2-x1, x1-x2) + max(y2-y1, y1-y2);
      cumule[i][0] = cost[i];
    }
  }
  REP(j, 1, 20)
  {
    REP(i, 1, N*M)
    {
      int newi = i + D*(1 << j);
      int interi = i + D*(1 << (j-1));
      if(newi <= N*M)
      {
        cumule[i][j] = cumule[i][j-1] + cumule[interi][j-1];
        //fprintf(stderr, "%d %d : %lld\n", i, j, cumule[i][j]);
      }
    }
  }

  scanf("%d", &Q);
  REP(i, 1, Q)
  {
    scanf("%d %d", &L, &R);
    int enc = L;
    long long int ans = 0;
    int longueur = (R-L)/D;
    for(int j = 20; j >= 0; j--)
    {
      if(longueur & (1 << j))
      {
        ans = ans + cumule[enc][j];
        enc += (1 << j);
      }
    }
    cout << ans << endl;
  }

  return 0;
}

#include <cstdio>
