using namespace std;
typedef long long LL;
const int inf = 1 << 30;
const LL INF = 1LL << 60;
const int MaxN = 100000;
const double eps = 1e-6;
const double PI = acos(-1.0);

int H, W, D;
int cnt, Q;
struct Point {
	int x, y, id;
	Point () {}
	Point (int _x, int _y, int _id) {
		x = _x; y = _y; id = _id;
	}
	friend bool operator < (const Point A, const Point B) {
		return A.id < B.id;
	}
}PP[MaxN + 5];

int prev[MaxN + 5];

int dis(Point A, Point B) {
	return abs(A.x - B.x) + abs(A.y - B.y);
}

int main()
{
	while(scanf("%d %d %d", &H, &W, &D) != EOF)
	{
		cnt = 0;
		for(int i = 1; i <= H; i++) {
			for(int j = 1; j <= W; j++) {
				int t;
				scanf("%d", &t);
				PP[++cnt] = Point(i, j, t);
			}
		}
		sort(PP + 1, PP + cnt + 1);
		scanf("%d", &Q);
		prev[0] = 0;
		for(int i = 1; i < cnt; i++)
			prev[i] = prev[i - 1] + dis(PP[i], PP[i + 1]);
		for(int cas = 1; cas <= Q; cas++) {
			int L, R;
			scanf("%d %d", &L, &R);
			if(D == 1) {
				printf("%d\n", max(0, prev[R - 1] - prev[L - 1]));
			}
			else {
				int cost = 0;
				int S = L, T = R;
				while(S != T) {
					cost += dis(PP[S + D], PP[S]);
					S += D;
				}
				printf("%d\n", cost);
			}
		}
	}
	return 0;
}

