int myabs(int a, int b) {
  if ( a > b ) {
    return a - b;
  }
  else {
    return b - a;
  }
}

int main() {
  int H, W, D;
  cin >> H >> W >> D;
  vector<int> ii(H*W), jj(H*W);
  rep(i,H) {
    rep(j,W) {
      int A;
      cin >> A;
      ii.at(A-1) = i;
      jj.at(A-1) = j;
    }
  }
  int Q;
  cin >> Q;
  int L, R;
  map<int,map<int,int>> cache;
  int answer = -1;
  bool cache_found = false;
  int x, i, j;
  int next, next_i, next_j;
  rep(q,Q) {
    cin >> L >> R;
    answer = 0;
    cache_found = false;
    if ( cache.count(L) ) {
      if ( cache.at(L).count(R) ) {
        answer = cache.at(L).at(R);
        cache_found = true;
      }
    }
    if ( cache_found == false ) {
      if ( L < R ) {
        x = L;
        i = ii.at(x-1);
        j = jj.at(x-1);
        while(x < R) {
          next = x + D;
          next_i = ii.at(next-1);
          next_j = jj.at(next-1);
          answer += myabs(i, next_i) + myabs(j, next_j);
          cache[L][next] = answer;
          x = next;
          i = next_i;
          j = next_j;
        }
      }
      cache[L][R] = answer;
    }
    cout << answer << endl;
  }
}

