    int A;
    REP (i, H)
    {
        REP (j, W)
        {
            gc(A);

            // 0-indexed
            A--;

            x[A] = i;
            y[A] = j;
        }
    }

    int d[HW_MAX];
    FOR (i, D, HW_MAX)
    {
        d[i] = d[i - D] + abs(x[i] - x[i - D]) + abs(y[i] - y[i - D]);
    }

    int Q;
    gc(Q);

    int L, R;
    int ans;
    while (Q--)
    {
        gc(L);
        gc(R);

        // 0-indexed
        L--;
        R--;

        ans = d[R] - d[L];
        cout << ans << endl;
    }

    return 0;
}

