			loc[x] = { i,j };
		}
	}

	vector<vector<ull> > dist(D);
	for (int i = 0; i < D; ++i)
	{
		auto& x = dist[i]; x.reserve(N / D + 1);
		ull d = 0;
		x.push_back(0);
		for (int j = i; j < N - D; j += D)
		{
			int p = j;
			int q = j + D;
			auto p1 = loc.find(p + 1)->second;
			auto q1 = loc.find(q + 1)->second;
			int theDist = abs(p1.first - q1.first) + abs(p1.second - q1.second);
			d += theDist;
			x.push_back(d);
		}
	}
	int Q;
	cin >> Q;
	for (int i = 0; i < Q; ++i)
	{
		int L, R;
		cin >> L >> R;
		int base = (L - 1) % D;
		int begin = (L - 1) / D;
		int n = (R - L) / D;
		int end = begin + n;
		ull theD = dist[base][end] - dist[base][begin];
		cout << theD << endl;
	}

}

