typedef long long LL; 



int main()
{ 
    int h,w,d;
    cin>>h>>w>>d;
    P p;
    int G=h*w;
    P n[G+1];
    int k[G+1];
    for(int i=1;i<=h;i++){
        p.first=i;
        for(int j=1;j<=w;j++){
            p.second=j;
            int a;
            cin>>a;
            n[a]=p;
        }
    }
    for(int i=1;i<=G;i++){
        int j=i+d;
        if(j>G){k[i]=0;}
        else{
            int x=n[i].first-n[j].first;
            int y=n[i].second-n[j].second;
            if(x<0){x=-x;}
            if(y<0){y=-y;}
            k[i]=x+y;
        }
    }

    LL k2[G+1];
    for(int i=0;i<=G;i++){
            k2[i]=0;
    }
    for(int i=1;i<=G;i++){
        int j=i;
        while(j+d<=G){
            k2[i]=k2[i]+k[j];
            j=j+d;
        }
    }

    int q;
    cin>>q;
    LL ans[q];
    for(int i=0;i<q;i++){ans[i]=0;}
    for(int i=0;i<q;i++){
        int l,r;
        cin>>l>>r;
        ans[i]=k2[l]-k2[r];
    }
    for(int i=0;i<q;i++){
        cout<<ans[i]<<endl;
    }
    return 0;
}

