int main(int argc, char *argv[]){

  int H, W, D;
  cin >> H >> W >> D;
  vector<int> x(H*W+1), y(H*W+1);
  int tmp;
  for(int h = 0; h < H; h++){
    for(int w = 0; w < W; w++){
      cin >> tmp;
      x[tmp] = w;
      y[tmp] = h;
    }
  }
  int Q;
  cin >> Q;
  int L[Q], R[Q];
  for(int i = 0; i < Q; i++){
    cin >> L[i] >> R[i];
  }

  // 実験開始
  vector<int> ans(Q, 0);
  for(int i = 0; i < Q; i++){
    unsigned long long bigger_x = 0, smaller_x = 0;
    unsigned long long bigger_y = 0, smaller_y = 0;
    int from = L[i];
    int to = L[i] + D;
    int times = (R[i] - L[i])/D;
    for(int j = 0; j < times; j++){

      // about x
      if(x[from] > x[to]){
        bigger_x += x[from];
        smaller_x += x[to];
      }else{
        bigger_x += x[to];
        smaller_x += x[from];
      }

      // about y
      if(y[from] > y[to]){
        bigger_y += y[from];
        smaller_y += y[to];
      }else{
        bigger_y += y[to];
        smaller_y += y[from];
      }

      from += D;
      to += D;
    }

    ans[i] = bigger_x - smaller_x + bigger_y - smaller_y;
  }

  for(int i = 0; i < Q; i++){
    printf("%d\n", ans[i]);

  }





  return 0;
}

