template<typename T>
istream& operator >> (istream& is, vector<T>& vec){
    for(T& x: vec){
        is >> x;
    }
    return is;
}

template<typename T>
string join(const vector<T>& vec, string sep = " "){
    stringstream ss;
    for(int i = 0; i < vec.size(); i++){
        ss << vec[i] << (i + 1 == vec.size() ? "" : sep);
    }
    return ss.str();
}

V solve(int h, int w, int d, const M& ass, int q, const V& ls, const V& rs){
    map<P, int> cost;
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            for(int x = 0; x < h; x++){
                for(int y = 0; y < w; y++){
                    int a = ass[i][j];
                    int b = ass[x][y];
                    cost[P(a, b)] = abs(x - i) + abs (y - j);
                }
            }
        }
    }

    V ms(q);
    for(int i = 0; i < q; i++){
        int m = 0;
        int p = ls[i];
        while(p != rs[i]){
            m += cost[P(p, p + d)];
            p += d;
        }
        ms[i] = m;
    }
    return ms;
}

