    int q;
    cin >> q;
    V ls(q), rs(q);
    for(int i = 0; i < q; i++){
        cin >> ls[i] >> rs[i];
    }

    cout << join(solve(h, w, d, ass, q, ls, rs), "\n") << endl;

    return 0;
}

