array<int, 100000> index_of;

array<array<int, 100000>, 400> accum;

int distance_of(int a, int b)
{
    int ax = index_of[a] % 300;
    int ay = index_of[a] / 300;
    int bx = index_of[b] % 300;
    int by = index_of[b] / 300;

    return abs(ax - bx) + abs(ay - by);
}

int main()
{
    for (auto &v : accum) fill(v.begin(), v.end(), 0);
    fill(index_of.begin(), index_of.end(), 0);

    int h, w, d;
    cin >> h >> w >> d;

    for (int i = 0; i < h; i++)
    {
        for (int j = 0; j < w; j++)
        {
            int v;
            cin >> v;
            index_of[v] = i * 300 + j;
        }
    }

    for (int i = 1; i <= h * w / d; i++)
    {
        for (int j = 1; j <= d; j++)
        {
            accum[j][i] = accum[j][i - 1] + distance_of((i - 1) * d + j, i * d + j);
        }
    }

    if (false)
    for (int j = 0; j <= d; j++)
    {
        for (int i = 0; i <= h * w / d; i++)
        {
            cerr << accum[j][i] << " ";
        }
        cerr << endl;
    }

    int q;
    cin >> q;
    for (int i = 0; i < q; i++)
    {
        int l, r;
        cin >> l >> r;
        int index = r % d;
        int offset = 0;
        if (index == 0)
        {
            index = d;
            offset = 1;
        }
        // cerr << index << " " << (r / d) << " " << (l / d) << endl;
        cout << (accum[index][r / d - offset] - accum[index][l / d - offset]) << endl;
    }
}

