#include "bits/stdc++.h"
using namespace std;

using LL = long long int;

#define int long long

const int MAX_H = 305;
const int MAX_W = 305;

int H, W, D;
int A[MAX_H][MAX_W];
struct Pos{
	int x, y;
};
map<int, Pos> Map;

const int MAX_Q = 100005;
int Q;
int L[MAX_Q], R[MAX_Q];

int Dubling[MAX_H*MAX_W][17];

signed main()
{
	cin >> H >> W >> D;
	for(int y = 0; y < H; y++) {
		for(int x = 0; x < W; x++) {
			cin >> A[y][x];
			Map[A[y][x]] = Pos{x, y};
		}
	}

	cin >> Q;
	for(int q = 0; q < Q; q++) {
		cin >> L[q] >> R[q];
	}

	memset(Dubling, -1, sizeof(Dubling));
	for(int i = 1; i <= H*W; i++) {
		Dubling[i][0] = 0;
		if(i+D <= H*W) {
			Dubling[i][1] = abs(Map[i+D].x - Map[i].x) + abs(Map[i+D].y - Map[i].y);
		}
	}

	for(int d = 1; d < 17; d++) {
		int Dist = pow(2,d) * D;
		int prevDist = pow(2, d-1) * D;
		for(int pos = 1; pos <= H*W; pos++) {
			if(pos + Dist > H*W) {
				continue;
			} else {
				Dubling[pos][d+1] = Dubling[pos][d] + Dubling[pos+prevDist][d];
			}
		}
	}

	//cerr << Dubling[4][1] << " " << Dubling[4][2] << endl;

	for(int q = 0; q < Q; q++) {
		int t = (R[q] - L[q])/D;

		int cnt = 0;
		int pos = L[q];
		int ans = 0;
		while(t) {
			if(t&1) {
				ans += Dubling[pos][cnt+1];
				pos += D*pow(2, cnt);
			}

			cnt++;
			t >>= 1;
		}
		cout << ans << endl;
	}

	return 0;
}

