    {
        if(i + D <= N)cost[i][0] = dist(i, i + D);
        else cost[i][0] = 0;
    }
    int tmp = 1;
    for(int i = 1; i < 30; i++)
    {
        tmp *= 2;
        for(int j = 1; j <= N; j++)
