pair<int, int> find_a (vector<vector<int>>& A, int number)
{
	REP (i, A.size())
	REP (j, A[i].size())
	{
		if (A[i][j] == number)
		{
			return make_pair(i, j);
		}
	}

	return make_pair(0, 0);
}

int main () {
