                int tmp_mahou = abs(M[l - 1 + d].second.first - M[l - 1].second.first) + abs(M[l - 1 + d].second.second - M[l - 1].second.second);
                mahou += tmp_mahou;
                dp[l][l + d] = mahou;
            } else {
                mahou += dp[l][l + d];
            }
            l += d;
        }
        cout << mahou << endl;
    }

    return 0;
}

