int main(){
    int n , m , d ; 
    cin >> n >> m >> d ; 
    pair<int,int> pos[n*m+1] ; 
    int grid[n][m] ; 
    int mem[n*m+1] ; 
    memset(mem,-1,sizeof mem) ; 
    for(int i=0;i<n;i++){
    	for(int j=0;j<m;j++){
    		cin >> grid[i][j] ; 
    		pos[grid[i][j]] = { i , j } ; 
    	}
    }
    for(int i=n*m;i>=1;i--){
    	if ( mem[i] == -1 ){
    		debug() << imie(i) ; 
    		mem[i] = 0 ; 
    		int previous = i ; 
    		int start = i-d; 
    		while(start >= 1){
    			debug() << imie(previous) imie(start) ; 
    			auto pre = pos[previous] ; 
    			auto next = pos[start] ; 
    			debug() << imie(pre) imie(next) ; 
    			mem[start] = mem[previous] + abs(pre.first - next.first) + abs(pre.second - next.second) ;
    			debug() << imie(mem[start]) ; 
    			previous = start ; 
    			start -= d ; 
    		}
    	}
    }
    int t ; 
    cin >> t ; 
    while(t--){
    	int l , r ; 
    	cin >> l >> r ; 
    	debug() << imie(l) imie(r) ; 
    	cout << mem[l] - mem[r] << endl;
    }
