int main(){
    int H, W, D;
    cin >> H >> W >> D;
    vector<vector<int>> A(H, vector<int>(W));
    for(int i = 0; i < H; ++i){
        for(int j = 0; j < W; ++j){
            cin >> A[i][j];
        }
    }
    int Q;
    cin >> Q;
    vector<int> L(Q), R(Q);
    for(int i = 0; i < Q; ++i){
        cin >> L[i] >> R[i];
    }

    // キーに対応する座標を格納するコンテナ
    unordered_map<int, P> coord;
    for(int i = 0; i < H; ++i){
        for(int j = 0; j < W; ++j){
            coord[A[i][j]] = P(i + 1, j + 1);
        }
    }

    for(int i = H * W - D + 1; i <= H * W; ++i){
        int now = i;
        while(now > D){
            int temp = sum[now];
            P p1 = coord[now];
            now -= D;
            P p2 = coord[now];

            sum[now] = temp + abs(p2.first - p1.first) + abs(p2.second - p1.second);
        }
    }

    for(int i = 0; i < Q; ++i){
        cout << sum[L[i]] - sum[R[i]] << endl;
    }
}

