int d;
vector<complex<int> > p;
map<pair<int, int>, long long> dp;

int getScore(int a, int b)
{
  if (a == b) return 0;
  if (dp.count(make_pair(a, b))) return dp[make_pair(a, b)];
  if (b - a == d) {
    return dp[make_pair(a, b)] = abs(p[a].real() - p[b].real()) + abs(p[a].imag() - p[b].imag());
  }
  int num = (b - a) / d;
  num /= 2;
  return dp[make_pair(a, b)] = getScore(a, a + num * d) + getScore(a + num * d, b);
}

