void fnc(int d, int lim){
    FOR(i, d){
        int c = 0, j = i;
        while(j<=lim){
            V[i].pb(c);
            if(j+d<=lim) c+= abs(B1[j] - B1[j+d]) + abs(B2[j] - B2[j+d]);
            j+=d;
        }
    }
}

int fnc2(int x, int y, int d){
    int m = x%d;
    x -= m, y -= m;
    return V[m][y/d] - V[m][x/d];
}

