vector < vector < int > > pref;

int dist(pii x, pii y) {
	return abs(x.fr - y.fr) + abs(x.sc - y.sc);
}

void calc(int x) {
	vector < int > pre;
	pre.pb(0);
	int cur = x; 
	while (cur <= n * m) {
		cur += d;
		if (cur > n * m) break;
		pre.pb(pre.back() + dist(ar[cur - d], ar[cur]));
	}
	pref.pb(pre);
}

int get(int l, int r) {
	int ost = l % d;
	if (ost == 0) ost = d;
	l -= ost;
	r -= ost;
	ost--;

	int lt = l / d;
	int rt = r / d;
	// cout << lt << ' ' << rt << endl;
	return pref[ost][rt] - pref[ost][lt];
}

