PII cood[180005];
LL cost[180005];

int main() {
	int h, w, d, q;
	scanf("%d%d%d", &h, &w, &d);
	REP(i, h) {
		REP(j, w) {
			int tmp;
			scanf("%d", &tmp);
			cood[tmp] = MP(i, j);
		}
	}
	REP(i, d) {
		int cur = i + 1;
		cost[cur] = 0;
		cur = cur + d;
		for (; cur <= h*w; cur += d) {
			cost[cur] = cost[cur-d] + abs(cood[cur].first - cood[cur - d].first) + abs(cood[cur].second - cood[cur - d].second);
		}
	}
	scanf("%d", &q);
	REP(i, q) {
		int l, r;
		scanf("%d%d", &l, &r);
		printf("%lld\n", cost[r] - cost[l]);
	}
	return 0;
}

