    vvl cost_sum(D);
    REP(i, D){
        ll sum = 0; PL p_pre = vmap[i].begin()->ss;
        FORMAP(it, vmap[i]){
            if(cost_sum[i].size() == 0){
                cost_sum[i].pb(0); continue;
            }
            PL p_cur = it->ss;
            sum += abs(p_cur.ff - p_pre.ff) + abs(p_cur.ss - p_pre.ss);
