bool isPalindrome(string input_str)
{
	bool ret = true;
	ll i = 0;
	ll j = input_str.length() - 1;

	while (ret && i <= j) {
		ret = ret & (input_str[i] == input_str[j]);
		i++;
		j--;
	}
	return ret;
}

////////////////////
// 2分探索 O(logN)
// ※ソートされていることが前提
////////////////////
ll binary_search(ll target, vector<ll> & search_table)
{
	const ll loop_cnt = 1000;	// 要調整
	ll N = search_table.size();
	ll lb = 0;
	ll ub = N;

	for (int i = 0; i < loop_cnt; ++i) {
		ll mid = (lb + ub) / 2;

		if (target == search_table[mid]) {
			return mid;
		}
		else if (target >= search_table[mid]) {
			lb = mid;
		}
		else {
			ub = mid;
		}
	}

	return ub;
}

