/* Parameters */
int H, W, D, Q;
std::vector<int> R, L;
std::vector<std::vector<int>> A;

auto get_input() -> void
{
  std::cin >> H >> W >> D;
  for (int i = 0; i < H; ++i) {
    A.push_back(std::vector<int>());
    for (int j = 0; j < W; ++j) {
      int tmp;
      std::cin >> tmp;
      A[i].push_back(tmp);
    }
  }
  std::cin >> Q;
  for (int i = 0; i < Q; ++i) {
    int tmpL, tmpR;
    std::cin >> tmpL >> tmpR;
    L.push_back(tmpL);
    R.push_back(tmpR);
  }
}

auto main() -> int
{
  get_input();

  std::vector<std::vector<int>> mod_group(Q);
  for (int i = 0; i < Q; ++i) {
    mod_group[L[i] % Q].push_back(i);
  }

  std::unordered_map<int, std::pair<int, int>> rev_A;
  for (int i = 0; i < H; ++i) {
    for (int j = 0; j < W; ++j) {
      rev_A[A[i][j]] = std::pair<int, int>(i, j);
    }
  }

  std::vector<int> result(Q);
  for (int mod = 0; mod < Q; ++mod) {
    if (mod_group[mod].size() == 0) {
      continue;
    }

    std::vector<int> points;
    for (decltype(auto) index : mod_group[mod]) {
      points.push_back(L[index]);
      points.push_back(R[index]);
    }

    std::sort(points.begin(), points.end());
    points.erase(std::unique(points.begin(), points.end()), points.end());

    std::unordered_map<int, bool> points_map;
    for (decltype(auto) point : points) {
      points_map[point] = true;
    }

    int current_cost = 0;
    std::pair<int, int> current_coord;
    std::unordered_map<int, int> cost_map;

    for (int n = points[0]; n <= points[points.size() - 1]; n += D) {
      if (n == points[0]) {
        current_coord = rev_A[n];
        continue;
      }

      std::pair<int, int> prev_coord = current_coord;
      current_coord = rev_A[n];
      current_cost +=
        std::abs(current_coord.first - prev_coord.first) +
        std::abs(current_coord.second - prev_coord.second);
      if (points_map[n] == true) {
        cost_map[n] = current_cost;
      }
    }

    for (decltype(auto) index : mod_group[mod]) {
      result[index] = cost_map[R[index]] - cost_map[L[index]];
    }
  }
  for (decltype(auto) power : result) {
    std::cout << power << std::endl;
  }
  return 0;
}

