	map<ll, pll> ValueGrid;
	rep(y, 0, H) rep(x, 0, W) ValueGrid[A[y][x]] = { y,x };

	vt<DS_NyaaCumulativeSum<ll>> sum;
	rep(i, 0, D)
	{
		ll j = i;
		vt<ll> test;
		test.push_back(0);
		while (1)
		{
			auto [y1, x1] = ValueGrid[j];
			j += D; if (H * W <= j) break;
			auto [y2, x2] = ValueGrid[j];
			test.push_back(abs(y2 - y1) + abs(x2 - x1));
		}
		sum.push_back(DS_NyaaCumulativeSum(test));
	}

	vt<ll> ans;
	ll Q; cin >> Q;
	rep(i, 0, Q)
	{
		ll l, r; cin >> l >> r; --l, --r;
		if (l == r) ans.push_back(0);
		else ans.push_back(sum[l % D].Range(l / D, (r - l) / D + 1));
	}
	each(i, e, ans) cout << e << endl;
