using MapA = map<int, pair<int, int>>;
using MapM = map<pair<int, int>, ll>;

ll f(int l, int r, int d, MapA& a, MapM& memo) {
  if (memo.find({l, r}) == memo.end()) {
    ll res = 0;
    if (l != r) {
      int i = a[l].first;
      int j = a[l].second;
      int x = a[l + d].first;
      int y = a[l + d].second;
      res = abs(x - i) + abs(y - j) + f(l + d, r, d, a, memo);
    }
    memo.insert({{l, r}, res});
  }
  return memo[{l, r}];
}

