using pii = pair<ll, ll>;

ll solve() {
    ll H, W, D, Q, a;
    cin >> H >> W >> D;
    ll HW = H * W;
    vector<pii> va(HW+1);
    for ( int h = 0; h < H; h++ ) {
        for ( int w = 0; w < W; w++ ) {
            cin >> a;
            va[a] = pii(h,w);
        }
    }
    cin >> Q;
    vector<ll> L(Q), R(Q);
    for ( int i = 0; i < Q; i++ ) {
        cin >> L[i] >> R[i];
    }

    vector<ll> ca(HW+1);
    ll cur = 0;
    for ( ll a = 0; a < HW+1; a++ ) {
        ll b = a - D;
        if ( b >= 1 ) {
            ca[a] = ca[b] + abs(va[a].first - va[b].first) + abs(va[a].second - va[b].second);
        }
    }
    vector<ll> ans(Q);
    for ( int q = 0; q < Q; q++ ) {
        ans[q] = ca[R[q]] - ca[L[q]]; 
    }

    for ( int q = 0; q < Q; q++ ) {
        cout << ans[q] << "\n";
    }

    return 0;
}

int main() {
    solve();
