long long n, m, d;
long long F[100005][2];
vector <long long> V[100005];

int main()
{
	long long x;
	cin >> n >> m >> d;
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++)
		{
			cin >> x;
			F[x][0] = i;
			F[x][1] = j;
		}
	for (int i = 0; i < d; i++)
	{
		long long last = i;
		x = i+d;
		long long sum = 0;
		while (x <= n*m)
		{
			V[i].push_back(sum);
			if (last == 0)
				sum = 0;
			else
				sum += abs(F[last][0] - F[x][0]) + abs(F[last][1] - F[x][1]);
			last = x;
			x += d;
		}
		V[i].push_back(sum);
	}


	int q;
	cin >> q;
	while (q--)
	{
		long long l, r;
		cin >> l >> r;
		cout << V[l%d][r / d] - V[l%d][l / d]<<'\n';
	}
	return 0;
}

