	//char a[302][302];
	int a[302][302];
	int q, l[100001], r[100001];
	int x[90001] = { 0 }, y[90001] = { 0 };

	cin >> h >> w >> d;

	int suu;
	for (i = 0; i < h; i++) {
		for (j = 0; j < w; j++) {
			cin >> a[i][j];
			//suu = (int)a[i][j] - 48;
			suu = a[i][j];
			x[suu] = j;
			y[suu] = i;
		}
	}

	cin >> q;

	//int xsum = 0, ysum = 0, asum = 0;
	long xsum = 0, ysum = 0, asum = 0;
	long ans[90001] = { 0 };

	for (i = 0; i < q; i++) {
		cin >> l[i] >> r[i];
	}


	//long kekal[90001] = { 0 }, kekar[90001] = { 0 };
	map<int, int>m;

	for (i = 0; i < q; i++) {
		int mem = l[i];
		for (;;) {
			if (l[i] == r[i]) break;
			decltype(m)::iterator it = m.find(l[i]);
			if (it != m.end()) {
				if (r[m.at(l[i])] <= r[i]) {
					asum += ans[m.at(l[i])];
					l[i] = r[m.at(l[i])];

				}
			}

			xsum = abs(x[l[i] + d] - x[l[i]]);
			ysum = abs(y[l[i] + d] - y[l[i]]);

			asum = asum + xsum + ysum;

			l[i] += d;

		}

		m.insert(pair<int, int>(mem, i));
		ans[i] = asum;

		cout << asum << endl;
		asum = 0;
	}


	getchar();
	getchar();
	return 0;
}

