    sort(jun.begin(),jun.end(),uppersort);
    int max_a = jun[0].first;

    //po[y][x][i]: 値iに到達するまでにかかる魔力
    vector <vector< vector<int>>> po(H,vector<vector<int>>(W, vector<int>(max_a+1, MOD)));

    for(int i = 0; i < H * W; ++i)
    {
        int y = jun[i].second.first;
        int x = jun[i].second.second;
        int p = jun[i].first;
    //現在値は、設定
        po[y][x][p] = 0;
        //1回でおわらす
        if(p + D <= max_a)
        {
            for(int j = 0; j < i; ++j)
            {
                int t_p = jun[j].first;
                if(t_p != p + D)continue;
