struct node
{
	int x,y;
	node(){}
	node(int x_,int y_)
	{
		x=x_;
		y=y_;
	}
	int operator+(const node &tmp)const
	{
		return std::abs(x-tmp.x)+std::abs(y-tmp.y);
	}
};

struct node ai[500000];

int n,m,d,size,f[22][500000];

int main()
{
	std::cin>>n>>m>>d;
	size=n*m;
	for(int i=1;i<=n;i++)
		for(int v=1;v<=m;v++)
		{
			int x;
