class D {
	int rows, cols;
	int d, q;
	vector<vector<pii>> pos;
	vector<vector<int>> memo;
public:
	D()
	{
		cin >> rows >> cols;
		cin >> d;

		pos.resize(d, vector<pii>((int)ceil((double)rows * cols / d)));

		int v;
		REP(y, rows)
			REP(x, cols)
		{
			cin >> v;

			pos[v % d][(v - v % d) / d] = MP(y, x);
		}

		cin >> q;

	}

	inline int diff(const pii& left, const pii& right)
	{
		return (abs(left.first - right.first) + abs(left.second - right.second));
	}

	void memoize()
	{
		memo.resize(d, vector<int>((int)ceil((double)rows * cols / d)));

		REP(y, d)
		{		
			memo[y][0] = 0;

			REP1O(x, SZ(memo[y]))
			{
				memo[y][x] = memo[y][x - 1] + diff(pos[y][x], pos[y][x - 1]);
			}
		}

	}

