    int A[H][W];
    vector<P> num2xy(H*W+1);
    REP(i,H)REP(j,W){
        cin >> A[i][j];
        num2xy[--A[i][j]] = MP(i,j);
    }

    VVI dist(D);
    REP(i,D){
        dist[i].push_back(0);
        int j = i;
        auto p = num2xy[j]; int pre_x = p.first, pre_y = p.second;
        j += D;
        while(j < H*W){
            p = num2xy[j]; int x = p.first; int y = p.second;
            int cost = abs(x-pre_x) + abs(y-pre_y);
            dist[i].push_back(dist[i].back() + cost);
            pre_x = x; pre_y = y;
            j += D;
        }
    }

    int Q; cin >> Q;
    REP(i,Q){
        int l,r;
        cin >> l >> r; l--; r--;
        cout << dist[r%D][r/D] - dist[l%D][l/D] << endl;
    }

    return 0;
}

