signed main() {
    int H, W, D; cin >> H >> W >> D;
    int N = H * W;
    vector<ii> rA(N); // (y, x)
    repx(i, 1, H + 1, 1) {
        repx(j, 1, W + 1, 1) {
            int a; cin >> a; a--;
            rA[a] = ii(i, j);
        }
    }

    map<ii, int> costs; // (src, dst)

    rep(i, N) {
        int j = i + D;
        if (j < N) {
            int ax = rA[i].first, ay = rA[i].second;
            int bx = rA[j].first, by = rA[j].second;
            costs[ii(i, j)] = abs(ax - bx) + abs(ay - by);
        }
    }

    rep(i, N) {
        int j = i + D + D;
        while (j < N) {
            costs[ii(i, j)] = costs[ii(i, j - D)] + costs[ii(j - D, j)];
            j += D;
        }
    }

    int Q; cin >> Q;
    rept(Q) {
        int L, R; cin >> L >> R; L--; R--;
        cout << costs[ii(L, R)] << endl;
    }

}

