int h,w,d,q;
pii pos[100000];
int start[100000];
vll pre[100000];
ll solve (int l, int r){
    int group = start[l];
    int n1,n2;
    n1 = (l-group)/d + 1;
    n2 = (r-group)/d + 1;
    ll res = pre[group][n2] - pre[group][n1];
    return res;
}
int main(){
	//IO();
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin>>h>>w>>d;
    for(int i=1;i<=h;i++){
        for(int j=1;j<=w;j++){
            int a;cin>>a;
            pos[a] = mp(i,j);
        }
    }

    for(int i=1;i<=h*w;i++){
        if(start[i]==0){
            start[i]=i;
            pre[i].pb(0);pre[i].pb(0);

            for(int j=i+d;j<=h*w;j+=d){
                start[j]=i;
                pii pref,now;
                pref = pos[j-d];
                now = pos[j];
                ll sel = abs(pref.fi-now.fi) + abs(pref.se - now.se);
                ll x = pre[i].back();
                x += sel;
                pre[i].pb(x);
            }
        }
    }

    cin>>q;
    for(int cases=1;cases<=q;cases++){
        int l,r;
        cin>>l>>r;
        ll ans = solve(l,r);
        cout<<ans<<newl;
    }

}

