using namespace std;
typedef long long ll;
struct Node{
    int x,y;
};
Node arr[100000];
int fbs(int x)
{
    if(x>0) return x;
    else return -x;
}
int deal(Node x,Node y)
{
    return fbs(y.x-x.x)+fbs(y.y-x.y);
}
int main()
{
    int h,m,d;
    cin>>h>>m>>d;
    int xx;
    for(int i=1;i<=h;i++)
    {
        for(int j=1;j<=m;j++)
        {
            scanf(" %d",&xx);
            arr[xx].x=i;
            arr[xx].y=j;
        }
    }
    int q;
    cin>>q;
    int x,y;
    for(int i=0;i<q;i++)
    {
        scanf(" %d %d",&x,&y);
        int sum=0;
        int b=x,e=x+d;
        while(b!=y)
        {
            sum+=deal(arr[b],arr[e]);
            b+=d;
            e+=d;
        }
        cout<<sum<<endl;
    }
    return 0;
}

