inline void solve(void){
  in(H,W,D);
  p.resize(H*W+1);
  rep(i,H){
    rep(j,W){
      in(a);
      p[a].ft=i;
      p[a].sd=j;
    }
  }
  for(i=D+1;i<=H*W;i++)d[i]=d[i-D]+abs(p[i].ft-p[i-D].ft)+abs(p[i].sd-p[i-D].sd);
  in(Q);
  while(Q--){
    in(L,R);
    out(d[R]-d[L]);
  }
}

