// 一次元累積和
// テンプレートであることに注意
template< typename T >
class CumulativeSum
{
public:
    vector< T > m_data;
    CumulativeSum() {};
    CumulativeSum(int sz) : m_data(sz, 0) {};

    // k に x を加える O(1)
    void Add(int k, int x) {
        assert(m_data.size() >= k);
        if(m_data.size() <= k) { m_data.push_back(x); }
        else { m_data[k] += x; }
    }

    // 累積和の構築 O(m_data.size())
    void Build() { for(int i = 1; i < m_data.size(); i++) { m_data[i] += m_data[i - 1]; } }

    // 区間 [0, k] の和を返す O(1)
    // 閉区間なので k が含まれることに注意
    T Query(int k) {
        if(k < 0) { return 0; }
        return (m_data[min(k, (int) m_data.size() - 1)]);
    }

    // 区間 [l, h] の和を返す O(1)
    // 閉区間なので k が含まれることに注意
    T Query(int l, int h) { return this->Query(h) - this->Query(l-1); }
};

ll H, W, D, Q;
ll A[MAX_H][MAX_W] = {};
pair<ll, ll> Table[MAX_H * MAX_W] = {};   // 番号の位置
vector< pair<ll, ll> > LR;
map<ll, CumulativeSum<ll> > cs_map;

signed main()
{
    cin >> H >> W >> D;
    REP(i, H) {
        REP(j, W) {
            cin >> A[i][j];
            Table[A[i][j]] = make_pair(i, j);
        }
    }
    cin >> Q;
    REP(i, Q) {
        pair<ll, ll> tmp;
        cin >> tmp.first >> tmp.second;
        LR.push_back(tmp);
    }
    REP(i, Q) {
        ll key = LR[i].first % D;
        ll l = LR[i].first / D, r = LR[i].second / D;
        if(key == 0) {
            l = LR[i].first / D - 1;
            r = LR[i].second / D - 1;
        }
        //DBG("i: %lld key: %lld l: %lld r: %lld\n", i, key, l, r);
        if(cs_map.count(key) == 0) {
            // 累積和の作成
            CumulativeSum<ll> cs_tmp(H * W / D + 100);
            for(ll j = 0; j <= H * W / D; ++j) {
                ll ind = j * D + key;
                if(key == 0) { ind = (j + 1) * D; }
                ll magic = abs(Table[ind+D].first - Table[ind].first) + abs(Table[ind+D].second - Table[ind].second);
                cs_tmp.Add(j, magic);
            }
            cs_tmp.Build();
            cs_map[key] = cs_tmp;
        }
        printf("%lld\n", cs_map[key].Query(l, r-1));
    }
    return 0;
}

