using namespace std;

map<int, pair<int, int>> indexes;

int dp(int curr, int goal, int D, vector<vector<int>>& memo) {
    if (curr == goal) {
        return 0;
    }
    //if (memo[curr][goal] >= 0) {
    //    return memo[curr][goal];
    //}

    pair<int, int> curr_ij = indexes[curr];
    pair<int, int> next_ij = indexes[curr + D];
    int power = abs(next_ij.first - curr_ij.first) + abs(next_ij.second - curr_ij.second);
    power += dp(curr + D, goal, D, memo);
    memo[curr][goal] = power;
    return power;
}

void Main() {
    int H, W, D;
    cin >> H >> W >> D;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int a;
            cin >> a;
            indexes.insert(make_pair(a, make_pair(i, j)));
        }
    }
    int Q;
    cin >> Q;
    vector<vector<int>> memo(H * W + 10, vector<int>(H * W + 10, -1));
    for (int i = 0; i < Q; ++i) {
        int l, r;
        cin >> l >> r;
        if (memo[l][r] >= 0) {
            cout << memo[l][r] << endl;
            continue;
        }

        int power = dp(l, r, D, memo);
        cout << power << endl;
    }
}

