using namespace std;

map<int, pair<int, int>> indexes;
map<pair<int, int>, int> memo;

int dp(int curr, int goal, int D) {
    if (curr == goal) {
        return 0;
    }
    auto p = make_pair(curr, goal);
    if (memo.count(p) > 0) {
        return memo[p];
    }

    pair<int, int> curr_ij = indexes[curr];
    pair<int, int> next_ij = indexes[curr + D];
    int power = abs(next_ij.first - curr_ij.first) + abs(next_ij.second - curr_ij.second);
    power += dp(curr + D, goal, D);
    memo.insert(make_pair(p, power));
    return power;
}

void Main() {
    int H, W, D;
    cin >> H >> W >> D;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
