            cin >> a;
            indexes.insert(make_pair(a, make_pair(i, j)));
        }
    }
    int Q;
    cin >> Q;
    for (int i = 0; i < Q; ++i) {
        int l, r;
        cin >> l >> r;
        int power = dp(l, r, D);
        cout << power << endl;
    }
}

