int main()
{
    int H, W, D;
    cin >> H >> W >> D;

    vector<pair<int, int>> table(H * W + 1);

    for (int i = 1; i <= H; ++i) {
        for (int j = 1; j <= W; ++j) {
            int Aij;
            cin >> Aij;

            table[Aij].first = i;
            table[Aij].second = j;
        }
    }

    vector<vector<int>> costs(H * W + 1, vector<int>(H * W + 1, 0));
    for (int a = 1; a <= H * W; ++a) {
        for (int b = 1; b <= H * W; ++b) {
            auto pos_a = table[a];
            auto pos_b = table[b];

            costs[a][b] = abs(pos_a.first - pos_b.first) + abs(pos_a.second - pos_b.second);
        }
    }

    vector<vector<int>> total_costs(H * W + 1, vector<int>(H * W + 1, 0));
    for (int Li = 1; Li <= H * W; ++Li) {
        for (int Ri = Li; Ri <= H * W; ++Ri) {
            if ((Ri - Li) % D != 0) {
                continue;
            }

            int c = 0;
            int x = Li;

            for (int i = 0; i < (Ri - Li) / D; ++i) {
                c += costs[x][x + D];
                x += D;
            }

            total_costs[Li][Ri] = c;
        }
    }

    int Q;
    cin >> Q;

    for (int i = 0; i < Q; ++i) {
        int Li, Ri;
        cin >> Li >> Ri;
        cout << total_costs[Li][Ri] << endl;
    }

    return 0;
}

