void solve()
{
  int H, W, D;
  cin >> H >> W >> D;
  map<int, P> mp;
  for (int y = 0; y < H; y++) {
    for (int x = 0; x < W; x++) {
      int a;
      cin >> a;
      a--;
      mp[a] = P(x, y);
    }
  }
  dump(mp);
  map<int, vector<int>> co;
  for (int p = 0; p < H * W; p++) {
    int x1, y1, x2, y2;
    tie(x1, y1) = mp[p];
    if (p + D < H * W) {
      tie(x2, y2) = mp[p + D];
      co[p].push_back(abs(x1 - x2) + abs(y1 - y2));
    }
  }
  // ダブリングのテーブル
  for (int b = 0; b < 20; b++) {
    for (int p = 0; p < H * W; p++) {
      int n = p + D * (1 << b);
      if (n < H * W && b < co[n].size()) {
        co[p].push_back(co[p][b] + co[n][b]);
      }
    }
  }
  for (int p = 0; p < H * W; p++) {
    dump(p, co[p]);
  }
  int Q;
  cin >> Q;
  for (int i = 0; i < Q; i++) {
    int l, r;
    cin >> l >> r;
    l--, r--;
    int ans = 0;
    int n = (r - l) / D;
    for (int b = 19; 0 <= b; b--) {
      int p = (1 << b);
      if (p <= n && b < co[l].size()) {
        ans += co[l][b];
        n -= p;
        l += D * p;
        dump(b, p);
      }
    }
    while (l < r) {
      ans += co[l][0];
      l += D;
    }
    cout << ans << endl;
  }
}

