const int MAX_HW = 90000;
const int LOG_HW = 18;
int bx[MAX_HW + 10], by[MAX_HW + 10];
int nxt[MAX_HW + 10][LOG_HW];

signed main() {
    int H, W, D; cin >> H >> W >> D;
    for(int i=0; i<H; i++) {
        for(int j=0; j<W; j++) {
            int val; scanf("%lld", &val);
            bx[val] = i, by[val] = j;
        }
    }

    memset(nxt, -1, sizeof(nxt));
    for(int val=1; val<=H*W; val++) {
        int to = val + D;
        if(to > H*W) continue;
        int x_diff = abs(bx[val] - bx[to]);
        int y_diff = abs(by[val] - by[to]);
        nxt[val][0] = x_diff + y_diff;
        // printf("nxt[%lld][%lld] = %lld\n", val, 0LL, nxt[val][0]);
    }

    for(int k=1; k<LOG_HW; k++) {
        for(int i=1; i<=H*W; i++) {
            if(i + D*(1 << k) > H*W) continue;
            nxt[i][k] = nxt[i][k-1] + nxt[i + D*(1 << (k-1))][k-1];
            // printf("nxt[%lld][%lld] = %lld\n", i, k, nxt[i][k]);
        }
    }

    int Q; scanf("%lld", &Q);
    while(Q--) {
        int L, R; scanf("%lld%lld", &L, &R);
        int step = (R - L) / D;

        int ans = 0, idx = L;
        for(int i=0; i<LOG_HW; i++) {
            if(step >> i & 1) {
                ans += nxt[idx][i];
                idx += (1 << i);
            }
        }
        printf("%lld\n", ans);
    }
    return 0;
}

