int sol(int a) {
  if ( a == (a%D) ) return 0;
  if ( dp[a] != -1 ) return dp[a];
  int b = a - D;
  P ap = UA[a];
  P bp = UA[b];
  return dp[a] = sol(b) + std::abs(ap.x-bp.x) + std::abs(ap.y-bp.y);
}

