			int distY= std::abs(posList[j*d+i][0] - posList[(j-1)*d+i][0]);
			cumSum[i][j]= cumSum[i][j-1]+ distX + distY;
		}
	}

	std::cin>>q;
	qList.resize(q);
	for(int i=0; i<q; i++)
		qList[i].resize(2);

	for(int i=0; i<q; i++)
		std::cin>>qList[i][0]>>qList[i][1];

	for(int i=0; i<q; i++){
		int mod= (qList[i][0]-1)%d;
		int l= (qList[i][0]-1)/d;
		int r= (qList[i][1]-1)/d;
		std::cout<<cumSum[mod][r]- cumSum[mod][l]<<std::endl;
	}

	return 0;
}

