int main()
{
    int H, W, D;
    cin >> H >> W >> D;

    unordered_map<int, pair<int, int>> table;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int Aij;
            cin >> Aij;

            table[Aij].first = i + 1;
            table[Aij].second = j + 1;
        }
    }

    int Q;
    cin >> Q;

    vector<int> L(Q);
    vector<int> R(Q);
    for (int i = 0; i < Q; ++i) {
        cin >> L[i] >> R[i];
    }

    vector<vector<int>> move_costs(
        H * W + 1, vector<int>(H * W + 1, 0)
    );

    for (int a = 1; a <= H * W; ++a) {
        for (int b = 1; b <= H * W; ++b) {
            auto pos_a = table[a];
            auto pos_b = table[b];

            move_costs[a][b] = abs(pos_a.first - pos_b.first) + abs(pos_a.second - pos_b.second);
        }
    }

    vector<vector<int>> total_costs(
        H * W + 1, vector<int>(H * W + 1, 0)
    );

    for (int Li = 1; Li <= H * W; ++Li) {
        for (int Ri = Li; Ri <= H * W; ++Ri) {
            if ((Ri - Li) % D != 0) {
                continue;
            }

            int c = 0;
            for (int x = Li; x != Ri; x += D) {
                c += move_costs[x][x+D];
            }
            total_costs[Li][Ri] = c;
        }
    }

    for (int i = 0; i < Q; ++i) {
        cout << total_costs[L[i]][R[i]] << endl;
    }

    return 0;
}

