using namespace std;
using Int = long long;
using UInt = unsigned long long;
using P = pair<Int, Int>;

Int H, W, D, Q;
vector<P> locs;
map<P, UInt> memo;

UInt dist(Int x, Int r){
    if (x == r){
        return 0;
    }
    if (memo.find(P(x, r)) != memo.end()){
        return memo[P(x, r)];
    }

    P px = locs[x];
    P px_ = locs[x+D];

    Int d = abs(px.first - px_.first) + abs(px.second - px_.second);
    UInt ret = d + dist(x+D, r);
    memo[P(x, r)] = ret; 
    return ret;
}

int main(){
    Int N;

    cin >> H >> W >> D;


    locs = vector<P>((H+1)*(W+1));

    FOR(i, 0, H){
        FOR(j, 0, W){
            Int n;
            cin >> n;
            locs[n] = P(j+1, i+1);
        }
    }

    cin >> Q;

    FOR (i, 0, Q){
        Int L, R;
        cin >> L >> R;
        cout << dist(L, R) << endl;
    }

}

