map<string, int> cache;

int calc(int l, int r) {
  string k = to_string(l)+"|"+to_string(r);
  if (cache.find(k) != cache.end()) {
    return cache[k];
  }
  int ret = abs(table[l].first - table[r].first) + abs(table[l].second - table[r].second);
  cache[k] = ret;
  return ret;
}

