#define VAL_MAX	(10000000000)
ll solve(ll N, vector<ll> & V)
{
	ll ans = -1;	// when -1, OK
	ll tmp = 0;
	ll cnt0 = 0;
	ll cnt1 = 0;
	bool isOK = false;
	vector<ll> V0(N, VAL_MAX);
	vector<ll> V1(N, VAL_MAX);

	// sort
	Rep(i, N) {
		if (i % 2 == 0) V0[cnt0++] = V[i];
		else V1[cnt1++] = V[i];
	}
	sort(V0.begin(), V0.end());
	sort(V1.begin(), V1.end());
	cnt0 = 0;
	cnt1 = 0;
	Rep(i, N) {
		if (i % 2 == 0) V[i] = V0[cnt0++];
		else V[i] = V1[cnt1++];
	}

	for (ll i = 0; i < N - 1; ++i) {
		if (V[i] > V[i + 1]) {
			ans = i;
			break;
		}
	}

	return ans;
}

