    int pre = i, next = i + d;
    while(next < h * w){
      pair<int, int> preid = x[pre], nextid = x[next];
      maryoku[i][next] = abs(preid.first - nextid.first) + abs(preid.second - nextid.second) + maryoku[i][pre];
      pre = next;
      next += d;
    }
  }

  /*rep(i, d){
    rep(j, h * w){
      cout << maryoku[i][j] << " ";
    }
    cout << endl;
  }*/

  int q; cin >> q;
  vector<int> ans(q);
  rep(i, q){
    int l, r; cin >> l >> r;
    l--; r--;
    ans[i] = maryoku[l % d][r] - maryoku[l % d][l];
  }

  rep(i, q){
    cout << ans[i] << endl;
  }
  return 0;
}

