int cost(int A_place[][2], int x, int y) {
  int cost = abs(A_place[y][0] - A_place[x][0]) +
             abs(A_place[y][1] - A_place[x][1]);
  return cost;
}

int total_cost(int A_place[][2], int L, int R, int D) {
  int total = 0;
  for (int i = L; L < R; L += D) {
    total += cost(A_place[][2], L, L + D);
  }
  return total;
}

