#define REP(i, n) for (int i = 0; i < (n); i++)
#define RREP(i, n) for (int i = (n) - 1; i >= 0; i--)
#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define RFOR(i, a, b) for (int i = (a); i > (b); i--)
#define ALL(a) (a).begin(), (a).end()

int H, W, D, A[300][300];
int Q, L, R;
map<int, pii> A_i;
pii cost[300][300];

void solve() {
    int sum = 0;
    for (int i = R - D; i >= L; i -= D) {
        int cur_x = A_i[i].first,     cur_y = A_i[i].second;
        int pri_x = A_i[i + D].first, pri_y = A_i[i + D].second;

        if (cost[cur_x][cur_y].first >= L &&
            cost[cur_x][cur_y].second > 0) {
            sum = cost[cur_x][cur_y].second;
            i = cost[cur_x][cur_y].first + D;
            continue;
        }
        sum += abs(cur_x - pri_x) + abs(cur_y - pri_y);
        cost[cur_x][cur_y] = {L, sum};
    }
    cout << sum << endl;
}

