void solve() {
    int addition = 0;
    bool memo = true;
    while (memo) {
        memo = false;
        int cur_x = A_i[L].first, cur_y = A_i[L].second;

        for (pii cp : cost[cur_x][cur_y]) {
            if (cp.first <= R) {
                addition += cp.second;
                L = cp.first;
                memo = true;
                break;
            }
        }
    }

    int sum = 0;
    for (int i = R - D; i >= L; i -= D) {
        int cur_x = A_i[i].first,     cur_y = A_i[i].second;
        int pri_x = A_i[i + D].first, pri_y = A_i[i + D].second;

        sum += abs(cur_x - pri_x) + abs(cur_y - pri_y);
        cost[cur_x][cur_y].push_back({R, sum});
    }

    cout << sum + addition << endl;
}

