			MyHash[a] = make_pair(i, j);
		}
	}

	int Q;
	cin >> Q;
	vector<int> L(Q), R(Q);

	for (int i = 0; i < Q; i++) {
		cin >> L[i] >> R[i];
	}

	for (int i = 0; i < Q; i++) {
		int x = L[i];
		int mp = 0;
