#define rep(i, n) for(int64_t i = 0; i < (int64_t)(n); i++)
#define NO_ENTRY -2
#define NOT_YET_ANSWERED -1

int myabs(int a, int b) {
  if ( a > b ) {
    return a - b;
  }
  else {
    return b - a;
  }
}

int cache_value(map<int,map<int,int>> &cache, int L, int R) {
  if ( cache.count(L) == false ) {
    return NO_ENTRY;
  }
  if ( cache.at(L).count(R) == false ) {
    return NO_ENTRY;
  }
  return cache.at(L).at(R);
}

int main() {
  int H, W, D;
  cin >> H >> W >> D;
  vector<int> ii(H*W), jj(H*W);
  rep(i,H) {
    rep(j,W) {
      int A;
      cin >> A;
      ii.at(A-1) = i;
      jj.at(A-1) = j;
    }
  }
  int Q;
  cin >> Q;
  vector<int> L(Q), R(Q);
  map<int,map<int,int>> answerMap;
  rep(q,Q) {
    cin >> L.at(q) >> R.at(q);
    answerMap[L.at(q)][R.at(q)] = NOT_YET_ANSWERED;
  }
  int answer = NOT_YET_ANSWERED;
  bool cache_found = false;
  int x, i, j;
  int next, next_i, next_j;
  int LL, RR;
  rep(q,Q) {
    LL = L.at(q);
    RR = R.at(q);
    answer = cache_value(answerMap, LL, RR);
    if ( answer == NOT_YET_ANSWERED ) {
      answer = 0;
      if ( LL < RR ) {
        x = LL;
        i = ii.at(x-1);
        j = jj.at(x-1);
        while(x < RR) {
          next = x + D;
          next_i = ii.at(next-1);
          next_j = jj.at(next-1);
          answer += myabs(i, next_i) + myabs(j, next_j);
          int tmp = cache_value(answerMap, LL, next);
          if ( tmp == NOT_YET_ANSWERED ) {
            answerMap[LL][next] = answer;
          }
          x = next;
          i = next_i;
          j = next_j;
        }
      }
      else {
        answerMap[LL][RR] = answer;
      }
    }
    cout << answer << endl;
  }
}

