typedef long long ll;

int H,W,D;
int A[300][300];
int Q;
int L[100010];
int R[100010];
int acc[100010];

int main ()
{
    cin >> H >> W >> D;
    REP(i,H) REP(j,W) cin >> A[i][j];
    cin >> Q;
    REP(i,Q) cin >> L[i] >> R[i];

    vector < vector < int > > ord;
    REP(x,H) REP(y,W) ord.push_back({A[x][y], x, y});
    sort(ord.begin(), ord.end());

    fill (acc, acc + 100010, -1);

    for (int i = 0; i < ord.size(); i++) {
        if (acc[i + 1] >= 0) break;
        int sum = 0;
        int px = ord[i][1];
        int py = ord[i][2];
        for (int j = i; j < ord.size(); j += D) {
            int x = ord[j][1];
            int y = ord[j][2];
            sum += abs(x - px) + abs(y - py);
            px = x;
            py = y;
            acc[j + 1] = sum;
        }
    }

    REP(i,Q) {
        cout << acc[R[i]] - acc[L[i]] << endl;
    }

    return 0;
}

