int table[301][301];//x,y

const long long int INF = 1000000000;

map<int,pair<int,int>> m; //x,y

long long int memo[301][301];

inline int my_abs(int input){
    if(input < 0){
        input = -input;
    }
    return input;
}

int main() {

    int h,w,d;

    cin >> h >> w >> d;

    for(int i=0; i<h; i++){
        for(int j=0; j<w; j++){
            cin >> table[j][i];
            m[table[j][i]] = make_pair(i,j);
        }
    }

    for(int i=0; i<301; i++){
        for(int j=0; j<301; j++){
            memo[i][j] = INF;
        }
    }

    int q;

    cin >> q;

    while(q--){
        int l,r;

        cin >> l >> r;

        long long int ans = 0;

        pair<int,int> pos = m[l];

        for(int i=l+d; i<=r; i+=d){
            if(memo[i][r] != INF){
                ans += memo[i][r];
                break;
            }
            int tmp = my_abs(pos.first - m[i].first) + my_abs(pos.second - m[i].second);
            memo[i-d][i] = tmp;
            ans += tmp;
            pos = m[i];
        }

        for(int i=r-d; i>l; i-=d){
            if(i-d > 0) {
                memo[i - d][r] = memo[i - d][i] + memo[i][r];
            }
        }

        cout << ans << endl;
    }

    return 0;
}

