struct Point {
    llint y, x;
};
llint kyori(Point a, Point b) {
    return abs(a.x - b.x) + abs(a.y - b.y);
}
int main() {

    llint h, w, d;
    cin >> h >> w >> d;

    map<llint, Point> mp;
    llint tmp;
    REP(i, h) {
        REP(j, w) {
            cin >> tmp;
            mp[tmp] = {i, j};
        }
    }
    vector<vector<llint>> grid(d, vector<llint>((h * 2 + 3 * d - 1) / d, 0ll));
    for(auto x : mp) {
        grid[x.first % d][x.first / d] = kyori(mp[x.first], mp[x.first + d]);

