    vector<vector<llint>> sum(d, vector<llint>((h * 2 + 4 * d - 1) / d, 0ll));
    REP(i, d) {
        REP(j, (h * 2 + 2 * d - 1) / d) {
            sum[i][j + 1] = sum[i][j] + grid[i][j];
        }  
    }
    llint q;
