int calCost(pair<int,int> A,pair<int,int> B){
	return abs(A.first-B.first)+abs(A.second-B.second);
}
void solve(){
	int H,W,D;
	cin >> H >>W>>D;
	vector<vector<int> > A(H,vector<int>(W));
	vector<pair<int,int> > pos(H*W);
	for(int h=0;h<H;++h){
		for(int w=0;w<W;++w){
			cin>>A[h][w];
			A[h][w]--;
			pos[ A[h][w] ].first = h;
			pos[ A[h][w] ].second = w;
		}
	}
	////
	vector<LL> cost(H*W,0);
	for(int i=0;i<D;++i){
		for(int j=1;i+j*D<H*W;++j){
			LL res = calCost(pos[i+(j-1)*D],pos[i+j*D]);
			cost[i+j*D] = cost[i+(j-1)*D] + res;
		}
	}
	////
	int Q;
	cin >> Q;
	int L,R;
	while(Q--){
		cin >> L>>R;
		--L;
		--R;
		cout << cost[R]-cost[L] << endl;
	}
}
