ll manhdist(pair<ll, ll> xy0, pair<ll, ll> xy1)
{
  ll x0 = xy0.first, y0 = xy0.second;
  ll x1 = xy1.first, y1 = xy1.second;
  return abs(x1 - x0) + abs(y1 - y0);
}

int main()
{
