  for (ll i = 0; i < H; i++)
  {
    for (ll j = 0; j < W; j++)
    {
      ll A;
      cin >> A;
      A--;
      P.at(A) = make_pair(i, j);
    }
  }

  vector<ll> acd(H * W, 0);
  for (ll i = D; i < H * W; i++)
  {
    acd.at(i) = acd.at(i - D) + manhdist(P.at(i), P.at(i - D));
