int calc(vector<P>& aa, int s, int e, int d, map<P, int>& cost) {
  if (s == e) return 0;
  if (cost[{s, e}] != 0) return cost[{s, e}];
  int ans = 0;
  if (cost[{s, s+d}] == 0) {
    cost[{s, s+d}] = abs(aa[s].first - aa[s+d].first) + abs(aa[s].second - aa[s+d].second);
  }
  return cost[{s, s+d}] + calc(aa, s+d, e, d, cost);
}

