	// 立っているビットの数を返す
	static int bitcount8(unsigned char b8) {
		// 8 bits 限定アルゴリズムを利用している
		//c_assert( 8 == (CHAR_BIT * sizeof( b8 )) );

		b8 = (unsigned char)( ((b8 & 0xAA) >> 1) + (b8 & 0x55) );
		b8 = (unsigned char)( ((b8 & 0xCC) >> 2) + (b8 & 0x33) );
		b8 = (unsigned char)( ((b8 & 0xF0) >> 4) + (b8 & 0x0F) );

		return b8;
	}

	// 立っているビットの数を返す
	static int bitcount16(unsigned short w16) {
		// 16 bits 限定アルゴリズムを利用している
		//c_assert( 16 == (CHAR_BIT * sizeof( w16 )) );

		w16 = (unsigned short)( ((w16 & 0xAAAA) >> 1) + (w16 & 0x5555) );
		w16 = (unsigned short)( ((w16 & 0xCCCC) >> 2) + (w16 & 0x3333) );
		w16 = (unsigned short)( ((w16 & 0xF0F0) >> 4) + (w16 & 0x0F0F) );
		w16 = (unsigned short)( ((w16 & 0xFF00) >> 8) + (w16 & 0x00FF) );

		return w16;
	}

	// 立っているビットの数を返す
	static int bitcount32(unsigned long dw32) {
		// 32 bits 限定アルゴリズムを利用している
		//c_assert( 32 == (CHAR_BIT * sizeof( dw32 )) );

		dw32 = ((dw32 & 0xAAAAAAAA) >>  1) + (dw32 & 0x55555555);
		dw32 = ((dw32 & 0xCCCCCCCC) >>  2) + (dw32 & 0x33333333);
		dw32 = ((dw32 & 0xF0F0F0F0) >>  4) + (dw32 & 0x0F0F0F0F);
		dw32 = ((dw32 & 0xFF00FF00) >>  8) + (dw32 & 0x00FF00FF);
		dw32 = ((dw32 & 0xFFFF0000) >> 16) + (dw32 & 0x0000FFFF);

		return dw32;
	}

	// 条件を満たす最小の要素のindexを返す
	// 存在しない場合は-1を返す
	// 使い方の例: int result = binarySearch<int>(A, 0, N - 1, [=](int x) { return x >= K; });
	template<typename T> int binarySearch(vector<T> vec, int beginIndex, int endIndex, function<bool(T)> confilm) {
		// 解が両端にある場合や解なしの判定のために、両端の１つ外側から始める
		int lb = beginIndex - 1; // lower bound
		int ub = endIndex + 1; // upper bound

		while (ub - lb > 1) {
			int mid = (ub + lb) / 2;
			if (confilm(vec[mid])) {
				ub = mid;
			} else {
				lb = mid;
			}
		}

		if (ub == endIndex + 1) {
			// 解なし
			return -1;
		}

		return ub;
	}

}

using namespace ValLib;

int H, W, D;
vector<vector<int>> A;
int Q;
vector<pair<int, pair<int, int>>> Kukan;

umap<string, int> memo;

int main()
{
	std::ios::sync_with_stdio(false);

	cin >> H >> W >> D;
	resize(A, H, W);
	for (int y = 0; y < H; ++y) {
		for (int x = 0; x < W; ++x) {
			cin >> A[y][x];
		}
	}
	cin >> Q;
	Kukan.resize(Q);
	for (int i = 0; i < Q; ++i) {
		int l, r;
		cin >> l >> r;
		Kukan[i] = pair<int, pair<int, int>>(i, pair<int, int>(l, r));
	}

	// 区間開始が左の順にソート Dで割った余りごとに分ける
	sort(Kukan.begin(), Kukan.end(), [](const pair<int, pair<int, int>>& p1, const pair<int, pair<int, int>>& p2) {
		if (p1.second.first % D != p2.second.first % D) {
			return p1.second.first % D < p2.second.first % D;
		}
		return p1.second.first < p2.second.first;
	});

	for (int y = 0; y < H; ++y) {
		for (int x = 0; x < W; ++x) {
			for (int y2 = 0; y2 < H; ++y2) {
				for (int x2 = 0; x2 < W; ++x2) {
					if (A[y2][x2] <= A[y][x]) {
						continue;
					}
					if ((A[y2][x2] - A[y][x]) % D > 0) {
						continue;
					}
					stringstream ss;
					ss << A[y][x] << "_" << A[y2][x2];
					int dist = abs(y2 - y) + abs(x2 - x);
					memo[ss.str()] = dist;
				}
			}
		}
	}
	//for (auto a : memo) {
	//	cerr << a.first << " = " << a.second << endl;
	//}

	vector<int> answerVec(Q, 0);

	int lastAmari = -1;
	for (int i = 0; i < Q; ++i) {
		int answer = 0;
		int amari = Kukan[i].second.first % D;
		int mLeft = -1, mRight = -1;
		if (i < Q - 1) {
			int nextAmari = Kukan[i + 1].second.first % D;
			if (amari == nextAmari) {
				// 重複区間をメモする
				mLeft = Kukan[i + 1].second.first;
				mRight = min(Kukan[i].second.second, Kukan[i + 1].second.second);
			}
		}
		if (amari == lastAmari) {
			// たぶんメモ済みの区間
			int left = Kukan[i].second.first;
			int right = min(Kukan[i].second.second, Kukan[i - 1].second.second);
			stringstream ss;
			ss << left << "_" << right;
			if (memo.find(ss.str()) != memo.end()) {
				answer += memo[ss.str()];
			} else {
				for (int n = left; n < right; n += D) {
					stringstream ss;
					ss << n << "_" << (n + D);
					answer += memo[ss.str()];
				}
			}
			// 新区間
			for (int n = right; n < Kukan[i].second.second; n += D) {
				stringstream ss;
				ss << n << "_" << (n + D);
				answer += memo[ss.str()];
			}
		} else {
			// 新区間
			int memoSub = 0;
			for (int n = Kukan[i].second.first; n < Kukan[i].second.second; n += D) {
				stringstream ss;
				ss << n << "_" << (n + D);
				answer += memo[ss.str()];
				// サブメモ
				if (n > mLeft && n <= mRight) {
					memoSub += memo[ss.str()];
				}
			}
			// サブメモ追加
			stringstream ss;
			ss << mLeft << "_" << mRight;
			memo[ss.str()] = memoSub;
		}
		answerVec[Kukan[i].first] = answer;


		lastAmari = Kukan[i].second.first % D;
	}

	for (int i = 0; i < (int)answerVec.size(); ++i) {
		cout << answerVec[i] << endl;
	}

	//getchar();
	//getchar();
}

