    qsort(q, Q, sizeof(struct quest), compare_R);

    for(int i=0;i<Q;i++){
        for(int j=0;j<i;j++){
            if(q[i].L==q[j].L&&q[i].R>=q[j].R){
                q[i].L = q[j].R;
                q[i].ans = q[j].ans;
            }
        }
        while(q[i].L!=q[i].R){
            q[i].ans += mp[q[i].L];
            q[i].L += D;
        }
    }

    // sort by index in ascending order
    qsort(q, Q, sizeof(struct quest), compare_index);
    for(int i=0;i<Q;i++){
        cout << q[i].ans << endl;
    }
    return 0;
}

