/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll h, w, l, r, d, q, a;
map<ll, pl> int_to_pos;
ll ms[301 * 301];

void solve(){
    rep(y, h) rep(x, w){
        in1(a); int_to_pos[a] = mp(x, y);
    }
    rep(i, d) ms[i] = 0; ll x1, x2, y1, y2;
    For(i, d, h * w){
        x1 = int_to_pos[i + 1].e1; x2 = int_to_pos[i + 1 - d].e1;
        y1 = int_to_pos[i + 1].e2; y2 = int_to_pos[i + 1 - d].e2;
        ms[i] += ms[i - d] + abs(x1 - x2) + abs(y1 - y2);   
    }
    in1(q);
    rep(i, q){
        in2(l, r); l--; r--;
        prl(ms[r] - ms[l]);
    }
}

int main(void){
    in3(h, w, d);
    solve();

    return 0;
}

