int main() {
    ll H,W,D;
    cin >> H >> W >> D;
    vector<pair<ll,ll>> pos = vector<pair<ll,ll>>(H * W + 1);
    vector<ll> cost = vector<ll>(H * W + 1);
    for(ll i = 0; i < H * W + 1; i++){
        pos[i].first = 0;
        pos[i].second = 0;
        cost[i] = -1;
    }
    for(ll yi = 0; yi < H; yi++){
        for(ll xi = 0; xi < W; xi++){
            ll tmp;
            cin >> tmp;
            pos[tmp].first = xi;
            pos[tmp].second = yi;
        }
    }
    for(ll i = 1; i <= D; i++){
        cost[i] = 0;
    }
    for(ll i = D + 1; i < H * W + 1; i++){
        cost[i] = cost[i - D] + abs(pos[i].first - pos[i - D].first) + abs(pos[i].second - pos[i - D].second);
    }
    ll Q = 0;
    cin >> Q;
    for(ll i = 0; i < Q; i++){
        ll L,R;
        cin >> L >> R;
        cout << cost[R] - cost[L] << endl;
    }

}

