typedef struct {
    int x;
    int y;
} point;

int main() {
    int H, W, D;
    cin >> H >> W >> D;

    point a[H*W];
    for (int x = 0; x < H; x++) {
        for (int y = 0; y < W; y++) {
            int A;
            cin >> A;
            a[A].x = x;
            a[A].y = y;
        }
    }

    int Q;
    cin >> Q;
    for (int i = 0; i < Q; i++) {
        long long int ans = 0;
        int L, R;
        cin >> L >> R;
        point p = a[L];
        for (;L<R; L+=D) {
            point q = a[L+D];
            ans += abs(p.x-q.x) + abs(p.y-q.y);
            p = q;
        }
        cout << ans << endl;
    }

    return 0;
}

