void AddCost(uint32_t* totalCost, int H, int W, int D, int** s, int l, int r)
{
    static std::unordered_map<int, int> costMemo;
    // static std::unordered_map<int, std::pair<int, int>> mapMemo;

    if (l == r) return;

    int searchNum = 1000 * r + l;
    auto costItr = costMemo.find(searchNum);
    if (costItr != costMemo.end()) {
        // cout << "found cost memo: (" << l << ", " << r << ") is " << costItr->second << endl;
        *totalCost = costItr->second;
        return;
    }

    // コストがメモ化されていないので計算する

    // R_i = L_i + nD なので、L, L + D, L + 2D, ... で R になるまでの整数値だけが必要
    // x_j = L_i + jD とする
    // x_j - L_i % D == 0 && x_j >= L_i なら true
    // cost_j = |x_(j + 1) - x_j

    std::unordered_map<int, std::pair<int, int>> map;
    for (int v = l; v <= r; v += D)
    {
        // cout << "v = " << v << endl;
        // 探している値がメモ化されていたら検索しない
        // auto memoItr = mapMemo.find(v);
        // if (memoItr != mapMemo.end())
        // {
        //     // cout << "found memoed value: " << memoItr->second.first << ", " << memoItr->second.second << endl;
        //     map[v] = memoItr->second;
        // }
        // else
        {
            // メモ化されていなかったので検索する
            // cout << "search value: " << v << endl;
            ForIndex2D(H, W)
            {
                if (s[i][j] == v)
                {
                    std::pair<int, int> target(i, j);
                    // mapMemo[v] = target;
                    map[v] = target;
                    // cout << "memo value: " << target.first << ", " << target.second << endl;
                }
            }}
        }
    }

    for(auto& elem : map)
    {
        int v = elem.first;
        if (v == r) continue; // v == R は計算用に保存してあるだけなので skip

        const auto& currentPair = elem.second;
        const auto& nextPair = map[v + D];
        *totalCost += 
            std::abs(nextPair.first - currentPair.first) + 
            std::abs(nextPair.second - currentPair.second);
    }

    // メモ化
    // cout << "memo cost: (" << l << ", " << r << ") is " << *totalCost << endl;
    costMemo.emplace(searchNum, *totalCost);
}

int main()
{
    int H, W, D;
    cin >> H >> W >> D;

    int** s;
    input2DArray(s, H, W);

    uint32_t Q;
    cin >> Q;

    int** lr;
    input2DArray(lr, Q, 2);

    ForIndex(Q)
    {
        uint32_t cost = 0;
        AddCost(&cost, H, W, D, s, lr[index][0], lr[index][1]);
        cout << cost << endl;
    }

    delete2DArray(lr, Q);
    delete2DArray(s, H);
    return 0;
}

