int Q;
vector<pair<int, int>> LR;
unordered_map<string, int> RESULT;

void solve() {
  for (auto lr : LR) {
    int ans = 0;
    if (lr.first == lr.second) {
      ans = 0;
    } else if (RESULT[lr.first + "," + lr.second] != 0) {
      ans = RESULT[lr.first + "," + lr.second];
    } else {
      for (int x = lr.first; x != lr.second; x += D) {
        ans += abs(A[x + D].first - A[x].first) + abs(A[x + D].second - A[x].second);
        RESULT[lr.first + "," + lr.second] = ans;
      }
    }
    cout << ans << "\n";
  }
}

