								x <= p1.first)
								ox = true;
						}
						if (p1.second <= p2.second) {
							if (p1.second <= y and
								y <= p2.second)
								oy = true;
						}
						else {
							if (p2.second <= y and
								y <= p1.second)
								oy = true;
						}
						if (ox and oy) cnt++;
					}
				}
				if (cnt >= K)
					ans = min(ans, (ll)(abs(p1.first - p2.first) * abs(p1.second - p2.second)));
			}
		}
		cout << ans << endl;
	}
}

namespace abc088c {
	struct edge {
		int from, to, cost;
	};
	bool bellmanFord(vector<edge>& es, vector<ll>& ds, int start) {
		for (auto& d : ds) d = INT64_MAX;
		ds[start] = 0;
		for (int n = 0; n < ds.size(); ++n) {
			for (int i = 0; i < es.size(); ++i) {
				edge e = es[i];
				if (ds[e.from] != INT64_MAX and
					ds[e.to] > ds[e.from] + e.cost) {
					ds[e.to] = ds[e.from] + e.cost;
					if (n == ds.size() - 1)
						return false;
				}
			}
		}
		return true;
	}
	void abc088c()
	{
		cin >> H >> W;
		vector<string> field(H);
		vector<edge> es;
		REP(i, H) cin >> field[i];
		REP(i, H) {
			REP(j, W) {
				if (j + 1 < W and 
					field[i][j] == '.' and
					field[i][j + 1] == '.') {
					int p1 = i * W + j, p2 = p1 + 1;
					es.push_back(edge{ p1, p2, 1 });
					es.push_back(edge{ p2, p1, 1 });
				}
				if (i + 1 < H and
					field[i][j] == '.' and
					field[i + 1][j] == '.') {
					int p1 = i * W + j, p2 = p1 + W;
					es.push_back(edge{ p1, p2, 1 });
					es.push_back(edge{ p2, p1, 1 });
				}
			}
		}
		vector<ll> ds(H*W);
		bellmanFord(es, ds, 0);
		int cnt = 0;
		REP(i, H) {
			REP(j, W) {
				if (field[i][j] == '.') cnt++;
			}
		}
		if (ds[ds.size() - 1] == INT64_MAX)
			cout << "-1" << endl;
		else
			cout << cnt - 1 - ds[ds.size() - 1] << endl;
	}
}

