int
find_pos(int h,
         std::vector<int> const & table,
         int number) {
  auto res = std::find(table.begin(),
                       table.end(),
                       number);
  return std::distance(table.begin(), res);
}

int
move_piece(int l, int r, int w) {
  int lx = l % w;
  int ly = l / w;
  int rx = r % w;
  int ry = r / w;

  return std::abs(lx - rx) + std::abs(ly - ry);
}

int main() {
  int h;
  int w;
  int d;
  std::cin >> h;
  std::cin >> w;
  std::cin >> d;

  std::vector<int> table;
  table.reserve(h*w);

  for (int y=0; y<h; y++) {
    for (int x=0; x<w; x++) {
      int a;
      std::cin >> a;
      table.push_back(a);
    }
  }

  int q;
  std::cin >> q;

  std::map<int, int> memo;

  for (int i=0; i<q; i++) {
    int l;
    int r;
    std::cin >> l;
    std::cin >> r;

    int result=0;

    auto l_pos = find_pos(h, table, l);
    memo[l] = l_pos;

    while (l != r) {
      int step;
      if (memo.find(l+d) == memo.end()) {
        step = find_pos(h, table, l+d);
        memo[l+d] = step;
      } else {
        step = memo[l+d];
      }
      result += move_piece(l_pos, step, w);
      l_pos = step;
      l += d;
    }

    std::cout << result << std::endl;
  }

  return 0;
}

