void solve() {
  ll H, W, D;
  input(H, W, D);
  vec<vecl> A(H, vecl(W));
  input(A);
  ll Q;
  input(Q);
  vecl L(Q), R(Q);
  for (auto &&i : range(Q))
    input(L[i], R[i]);
  ll N = H * W;
  u_map<ll, Pt_ll> pos;
  {
    for (auto &&i : range(H))
      for (auto &&j : range(W))
        pos[A[i][j]] = Pt_ll{i + 1, j + 1};
  }
  vec<vecl> cache(D);
  for (auto &&i : range(1, N + 1)) {
    ll prev = i - D;
    if (cache[i % D].empty()) {
      cache[i % D].push_back(0);
    } else {
      cache[i % D].push_back(pos[prev].dist1(pos[i]));
    }
  }
  vec<vecl> S = cache;
  for (auto &&d : range(D)) {
    partial_sum(S[d].begin(), S[d].end(), S[d].begin());
  }

  dump(H, W, D, Q);
  dump(L);
  dump(R);
  dump(A);
  dump(pos);
  dump(cache);
  dump(S);
  for (auto &&q : range(Q)) {
    ll l = L[q];
    ll r = R[q];
    ll ans = S[r % D][(r - 1) / D] - S[l % D][(l - 1) / D];
    print(ans);
  }
}

