  vpll A(h*w);
  FOR(i,0,h){
    FOR(j,0,w){
      ll now;
        cin>>now;
      now--;
      A[now].fi=i;
      A[now].se=j;
    }
  }

  vll B(h*w);//累積和を作るやつ
  FOR(i,d,h*w){
    ll x=abs(A[i].se-A[i-d].se);
    ll y=abs(A[i].fi-A[i-d].fi);
    B[i]=x+y;
  }
  FOR(i,d,h*w){
    B[i]+=B[i-d];
  }
  ll q;
    cin>>q;
  while(q--){
    ll l,r;
      cin>>l>>r;
    l--;
    r--;
    cout<<B[r]-B[l]<<"\n";
  }
}

