int dfs(int pos,int D){
   if (pos >= D)
   {
       return 0;
   }
   int u = mp[pos];
   int v = mp[D];
   if (dp[u][v] != -1) return dp[u][v]; 
   return dp[u][v] = dfs(pos + d,D) + cost(pos);
}
