void solve()
{
  int h,w,d;
  cin>>h>>w>>d;
  vector<vector<int>> a(h, vector<int>(w, 0));
  vector<ii> f(h*w+1);
  for (int i=0; i<h; i++) {
    for (int j=0; j<w; j++) {
      int t;cin>>t;
      a[i][j]=t;
      f[t] = make_pair(i,j);
    }
  }
  int q; cin>>q;
