struct node
{
	int x,y;
	node(){}
	node(int x_,int y_)
	{
		x=x_;
		y=y_;
	}
	int operator+(const node &tmp)const
	{
		return std::abs(x-tmp.x)+std::abs(y-tmp.y);
	}
};

struct node ai[100000];

int n,m,d,size,f[22][100000];

int main()
{
	std::cin>>n>>m>>d;
	size=n*m;
	for(int i=1;i<=n;i++)
		for(int v=1;v<=m;v++)
		{
			int x;
			std::cin>>x;
			ai[x]=node(i,v);
		}
	for(int i=1;i+d<=size;i++)
		f[0][i]=ai[i]+ai[i+d];
	for(int i=1;i<=21;i++)
		for(int v=1;v<=size;v++)
			if(v+(1<<i)*d<=size)
				f[i][v]=f[i-1][v]+f[i-1][v+(1<<(i-1))*d];
	int q,l,r,t,res;
	std::cin>>q;
	while(q--)
	{
		std::cin>>l>>r;
		t=(r-l)/d;
		res=0;
		for(int i=21;i>=0;i--)
			if((1<<i)&t)
			{
				res+=f[i][l];
				l+=(1<<i)*d;
			}
		std::cout<<res<<std::endl;
	}
	return 0;
}

