int main(){

    int H, W, D;
    cin >> H >> W >> D;
    vector<vector<int> > A(H, vector<int>(W));
    for(int i = 0; i < H; i++) for(int j = 0; j < W; j++) cin >> A[i][j];
    int Q;
    cin >> Q;
    vector<int> L(Q), R(Q);
    for(int i = 0; i < Q; i++) cin >> L[i] >> R[i];

    vector<vector<pair<int, int> > > x(1e6);
    for(int i = 0; i < H; i++) for(int j = 0; j < W; j++) x[A[i][j]].push_back(make_pair(i + 1, j + 1));

    for(int i = 0; i < Q; i++){
        int ans = 1e8;
        for(int j = 0; j < x[L[i]].size(); j++){
            int res = 0;
            int left = L[i], right = R[i];
            while(left != right){
                int min = 1e8;
                int p_i = -1, p_j = -1;
                int p1_i = x[left][j].first, p1_j = x[left][j].second;
                left += D;
                for(int k = 0; k < x[left].size(); k++){
                    int p2_i = x[left][j].first, p2_j = x[left][j].second;
                    if(min > abs(p1_i - p2_i) + abs(p1_j - p2_j)){
                        p_i = p2_i;
                        p_j = p2_j;
                        min = abs(p1_i - p2_i) + abs(p1_j - p2_j);
                    }
                }
                p1_i = p_i;
                p1_j = p_j;
                res += min;
            }
            ans = min(ans, res);
        }
        cout << ans << endl;
    }
    return 0;
}

