struct p2{ ll l, r; };
struct pij{ ll i, j; };

void solve()
{
	ll h, w, d;  cin >> h >> w >> d;
	vector<vector<ll>> a = cinvv<ll>(h, w);
	ll q;  cin >> q;
	vector<p2> lr;
	rep(i, 0, q-1){
		ll l, r;  cin >> l >> r;
		lr.push_back({l,r});
	}
	each(e, lr){
		e.l--; e.r--;
	}

	vector<pij> ij(h*w);
	rep(i, 0, h-1)rep(j, 0, w-1){
		ll val=a[i][j];
		val--;
		ij[val]={i,j};
	}

	vll sc(h*w);
	rep(i, 0, h*w-1){
		ll prei=i-d;
		if (prei<0)continue;
		auto &e=ij[i];
		auto &pree=ij[prei];
		sc[i]=sc[prei]+abs(e.i-pree.i)+abs(e.j-pree.j);
	}
	vll ans;
	rep(i, 0, q-1){
		auto &e=lr[i];
		ans.push_back(sc[e.r]-sc[e.l]);
	}
	coutv(ans,"\n");
}

