struct cell{
    int32_t x;
    int32_t y;
    cell() : x(0), y(0) {}
    cell(int32_t x,int32_t y) : x(x), y(y) {}
    int32_t dist(const cell& rhs){
        return std::abs(x - rhs.x) + std::abs(y - rhs.y);
    }
};

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    int32_t H, W, D;
    std::cin >> H >> W >> D;
    cell cell_array[H*W];
    for(int32_t h = 0; h < H; h++){
        for(int32_t w = 0; w < W; w++){
            int32_t val = 0;
            std::cin >> val;
            cell_array[val - 1] = cell(h+1,w+1);
        }
    }

    int32_t dist_memo[D][H*W/D + 1] = {};
    for(int32_t mod = 0; mod < D; mod++){
        int32_t val = mod + D;
        for(int32_t i = 1; i < H*W/D + 1; i++){
            if(val >= H*W) break;
            dist_memo[mod][i] = dist_memo[mod][i-1] + cell_array[val].dist(cell_array[val-D]);
            val += D;
        }
    }

    int32_t Q, L, R;
    std::cin >> Q;
    for(int32_t i = 0; i < Q; i++){
        std::cin >> L >> R;
        int32_t mod = (L - 1) % D;
        int32_t idx_l = (L - 1) / D;
        int32_t idx_r = (R - 1) / D;
        int32_t cost = dist_memo[mod][idx_r] - dist_memo[mod][idx_l];
        std::cout << cost << std::endl;
    }
    return 0;
}

