int Dist(pair<int, int> p, pair<int, int> q) { // 点Pから点Qへの距離
	return abs(p.first - q.first) + abs(p.second - q.second);
}
int main() {
	int H, W, D;
	cin >> H >> W >> D;
	int A;
	static pair<int, int> num[MAX2]; // ある値がどこにあるか分かっていた方が楽なので
	for (int i = 0;i < H;i ++) {
		for (int j = 0;j < W;j ++) {
			cin >> A;
			num[A - 1] = make_pair(j, i);
		}
	}
	// ここから下準備
	static int SUM[MAX2]; // 累積和
	for (int i = 0;i < D;i ++) {
		SUM[i] = 0; // ここは距離0なのは当然
	}
	for (int i = D;i < H * W;i ++) {
		SUM[i] = SUM[i - D] + Dist(num[i], num[i - D]); // i-Dからiへ行くコストは当然だがi-Dとiの距離に等しいので
//		cout << i << ":" << SUM[i] << endl; // デバッグ用
	}

	int Q, L, R;
	cin >> Q;
	for (int i = 0;i < Q;i ++) {
		cin >> L >> R;
		cout << SUM[R - 1] - SUM[L - 1];
		if (i < Q - 1) cout << endl; // 改行忘れにご注意を
	}
	return 0;
}
/*
31536000のコメント解説欄
ここテンプレで用意してるから、A問題とかだとこの先空欄の危険あり

まず、この手のクエリ型(毎回課題が与えられる)に対し、馬鹿正直にシミュレーションをすべきではない
Qが10^5であり、オーダーの末尾にQが付くので、各クエリのオーダーがO(1)かO(log(HW))でないと計算が間に合わないからだ

まず考えるのは、予め全てのLから全てのRへ行くコストを求めておく方法だね
これが終わっていれば、各クエリはO(1)で終わるでしょう
だけどLR<=300^4=81*10^8より却下

次に、問題自体に着目すると、次のことが分かる
LからRへ行くコストは、LからL+Dへ行くコストとL+DからRへ行くコストの和に等しい
この形式を取る場合、累積和が使えることが多いので検討する
今、累積和としてSUM[HW]を定義し、SUM[i]はi%Dからiまで行くコストの和だと考える
この時、LからRへ行くコストはSUM[R]-SUM[L]で求められることが分かる
(→SUM[R]-SUM[L] = R%DからRへ行くコスト - L%DからLへ行くコストであり、L%D=R%Dである)
よって各クエリに付きO(1)で求められるので、全体はO(Q)で求められることが分かった
下準備にはO(HW)掛かっているので、オーダーはO(max(HW, Q))だね
*/

