using std::vector;
using pii = std::pair<int,int>;
using std::make_pair;
using std::abs;

int cost_between(pii &prev, pii &next) {
	return abs(next.first-prev.first) + abs(next.second-prev.second);
}

int main() {
	// Input
	int H, W, D;
	cin >> H >> W >> D;
	const int SIZE = H * W;
	// squares[A] = pair(x, y)
	vector<pii> squares(SIZE+1);
	for(int h = 0; h < H; ++h) {
	for(int w = 0; w < W; ++w) {
		int A; cin >> A;
		squares[A] = make_pair(w, h);
	}
	}
	// Preparation
	vector<int> cumulative(SIZE+1);
	for(int a = D+1; a <= SIZE; ++a) {
		pii ps = squares[a-D];
		pii ns = squares[a];
		cumulative[a] = cumulative[a-D] + cost_between(ps, ns);
	}
	// Input Calculation, and Output
	int Q; cin >> Q;
	for(int i = 0; i < Q; ++i) {
		int L, R; cin >> L >> R;
		cout << (cumulative[R] - cumulative[L]) << endl;
	}
	return 0;
}

