template<> double InputF() {
	double ret = 0, dp = 1; bool neg = false, adp = false; char c = getchar_unlocked();
	if (c == '-') { neg = true; c = getchar_unlocked(); }
	while (('0' <= c && c <= '9') || c == '.') {
		if (c == '.') {
			adp = true;
		} else if (adp) {
			dp *= 0.1; ret += (c - '0') * dp;
		} else {
			ret = ret * 10.0 + (c - '0');
		}
		c = getchar_unlocked();
	}
	return neg ? -ret : ret;
}
