ll sum[MAX_HW * MAX_HW];
void dfs(int pos, ll cost)
{
    if (visited[pos])
    {
        return;
    }
    sum[pos] = cost;
    visited[pos] = true;
    pii p = indices[pos];
    int dst = pos + D;
    if (dst < H * W)
    {
        pii q = indices[dst];
        int tmp = abs(p.first - q.first) + abs(p.second - q.second);
        dfs(dst, cost + tmp);
    }
}
