            a--;
            indices[a] = mp(i, j);
        }
    }
    for (int i = 0; i < H * W; i++)
    {
        if (!visited[i])
        {
            dfs(i, 0);
        }
    }

    cin >> Q;
    for (int i = 0; i < Q; i++)
    {
        int l, r;
