int H, W, D;
int A[300][300];
PP I[90000];
LL C[90000];
LL CC[90000];
int Q;
int L[100000], R[100000];
int main() {
	cin >> H >> W >> D;
	REP(i, 0, H) {
		REP(j, 0, W) {
			cin >> A[i][j];
			--A[i][j];
			I[A[i][j]] = PP(i, j);
		}
	}
	cin >> Q;

	REP(i, 0, Q) {
		cin >> L[i] >> R[i];
		--L[i]; --R[i];
	}

	REP(i, 0, H * W) {
        if(i - D < 0) {
			C[i] = 0; continue;
        }
		PP p = I[i - D];
		PP q = I[i];
		C[i] = abs(p.first - q.first) + abs(p.second - q.second);
	}

	REP(i, 0, D) {
		int ii = i;
		CC[ii] = C[i];
		ii += D;
		while (ii < H * W) {
			CC[ii] = CC[ii - D] + C[ii];
			ii += D;
		}
	}

	REP(k, 0, Q) {
		cout << CC[R[k]] - CC[L[k]] << endl;
	}

	return 0;
}

