T absi(T x) {
    if (x < static_cast<T>(0)) {
        x *= static_cast<T>(-1);
    }
    return x;
}


struct Pos {
    int i;
    int j;
};

int dist(const Pos& a, const Pos& b)
{
    return absi(a.i - b.i) + absi(a.j - b.j);
}

