void solve(long long H, long long W, long long D, std::vector<std::vector<long long>> A, long long Q, std::vector<long long> L, std::vector<long long> R){
    vector<pair<LL, LL>> flatten(H*W+1);
    for(LL i=0; i<H; i++){
        for(LL j=0; j<W; j++){
            flatten[A[i][j]] =  make_pair(i+1, j+1);
        }
    }
    vector<vector<LL>> arr(D, vector<LL>((H*W+D)/D, 0));
    for(LL i=0; i<D; i++){
        LL acc=0;
        for(LL j=1; j<(H*W+D)/D; j++){
            LL prev=D*(j-1)+i, curr=D*j+i;
            if(curr > H*W)continue;
            acc += (abs(flatten[prev].first-flatten[curr].first)+abs(flatten[prev].second-flatten[curr].second));
            arr[i][j] = acc;
        }
    }

    for(LL i=0; i<Q; i++){
        auto j=R[i]%D;
        cout << arr[j][R[i]/D] - arr[j][L[i]/D] << endl;
    }
}

