int calcMP(PII L, PII R){
	return abs(R.first-L.first)+abs(R.second-L.second);
}


void makeVtoP(){
	repe(i, 1, H)
		repe(j, 1, W) VtoP[A[i][j]] = { i, j };
}


void makeAns(){
	repe(i, 1, D) ans[i][i+D] = calcMP(VtoP[i], VtoP[i+D]);
	repe(i, 2*D+1, H*W) ans[i%D][i] = ans[i%D][i-D]+calcMP(VtoP[i-D], VtoP[i]);
}


