	cin >> H >> W >> D;
	repe(i, 1, H)
		repe(j, 1, W) cin >> A[i][j];

	makeVtoP();
	makeAns();

	cin >> Q;
	rep(i, 0, Q) cin >> L >> R, cout << ans[L%D][R]-ans[L%D][L] << endl;

	return 0;
}

