typedef pair<int,int> P;
//前処理としてDの倍数でk余るやつのsumをすべて覚えときたい
//O(D^3)

map<int,P> mp;
int sum[310][310]; 
//sum[d][r][q+1]でr→q+r→....→d*q+rを表す

int main(){
    int H, W, D;
    cin >> H >> W >> D;
    for(int i=0; i<H; i++){
        for(int j=0; j<W; j++){
            int a; cin >> a;
            mp[a]=P(i,j);
        }
    }

    //前処理していく
    int d=D;
        for(int i=1; i<=H*W; i++){
            int q = i/d; int r=i%d;
            if(q==0){
                sum[r][1]=0;
            }
            else{
                P now = mp[i];  int nowx=now.first, nowy=now.second;
                P bef =mp[i-d]; int befx=bef.first, befy=bef.second;
                sum[r][q+1]=sum[r][q]+abs(nowx-befx)+abs(nowy-befy);
            }
        }

    //答えていく
    int Q;
    cin >> Q;
    for(int i=0; i<Q; i++){
        int l, r;
        cin >> l >> r;
        int q1 = l/D, q2=r/D; int ama= l%D;
        cout << sum[ama][q2+1] -sum[ama][q1+1] << endl;
    }
}

