int exam[limit][2];
std::vector<coord> points(100000);
int main (){
  int h,w,d;
  scanf("%d %d %d\n", &h, &w, &d);
  for( int i=0; i<h; i++){
    for( int j=0; j<w; j++){
      coord p={j, i};
      int tmp;
      scanf("%d", &tmp);
      points[tmp] = p;
    }
  }
  int q;
  scanf("%d", &q);
  for(int i=0; i<q; i++){
    int l,r;
    scanf("%d %d", &l, &r);
    if( l==r){printf("0\n"); continue;}
    int cost=0;
    for( int j=l; j<r; j+=d ){
      coord start = points[j];
      coord end = points[j+d];
      int dx=start.x-end.x, dy=start.y-end.y;
      if( dx < 0 ) dx=-dx;
      if( dy < 0 ) dy=-dy;
      cost += dx+dy;
    }
    printf("%d\n", cost);
  }

  return 0;
}

