pair<int, int> pp[99999], previous;

int main(void)
{
	int h, w, d, q, i, j, a, L, R;

	scanf("%d %d %d" ,&h, &w, &d);
	for (i = 1; i <= h; i++)
		for (j = 1; j <= w; j++)
		{
			scanf("%d" ,&a);
			pp[a] = make_pair(i, j);
		}

	scanf("%d" ,&q);
	while (q--)
	{
		int ans = 0;

		scanf("%d %d" ,&L, &R);

		previous = pp[L];
		for (i = L + d; i <= R; i += d)
		{
			pair<int, int> tmp = pp[i];

			ans += abs(tmp.first - previous.first) + abs(tmp.second - previous.second);
			previous = tmp;
		}

		printf("%d\n" ,ans);
	}
	return 0;
}

