void solve() {
    i64 H,W; RD(H); RD(W);
    i64 D; RD(D);

    vector<Index2> indices(H*W);
    REP(y, H) REP(x, W) {
        i64 a; RD(a); --a;  // 0-based
        indices[a] = Index2(y,x);
    }

    auto f = MEMOIZE<300*300>([D,&indices](auto&& self, i64 i) -> i64 {
        if(i < D) return 0;
        const auto& s = indices[i-D];
        const auto& t = indices[i];
        return (s-t).norm1() + self(i-D);
    });

    i64 Q; RD(Q);
    REP(_, Q) {
        i64 l,r; RD(l); RD(r); --l; --r;  // 0-based
        i64 ans = f(r) - f(l);
        PRINTLN(ans);
    }

