	for(int i=0;i < H;i++){
		for(int j=0;j < W;j++){
			cin >> A[i][j];
			Ax[A[i][j]]=i; //A[i][j]の値が書かれているマスのx座標
			Ay[A[i][j]]=j; //A[i][j]の値が書かれているマスのy座標
		}
	}
	int Q,L[Nmax],R[Nmax]; //L i回目の初期位置 R i回目のgoal Q実技試験数
	cin >> Q;
	for(int i=0;i < Q;i++) cin >> L[i] >> R[i];

	int n,X,Y,I,J,X1,Y1,I1,J1,X2,Y2,ans,flag;
	for(int i=0;i < Q;i++){
		ans=0;n=0;flag=0;
		if((R[i]-L[i])/D % 2 == 0) flag = 1;
		for(;;){
			if(flag==1){
				X = Ax[L[i]+n*D]; Y = Ay[L[i]+n*D];
				X1= Ax[R[i]-n*D]; Y1= Ay[R[i]-n*D];
				if(A[X][Y] == A[X1][Y1]) break;
				n++;
				I = Ax[L[i]+n*D]; J = Ay[L[i]+n*D];
				I1= Ax[R[i]-n*D]; J1= Ay[R[i]-n*D];
				ans+=abs(X-I)+abs(Y-J)+abs(X1-I1)+abs(Y1-J1);
			}else{
				X = Ax[L[i]+n*D]; Y = Ay[L[i]+n*D];
				if(n >= 1){
					X1= Ax[R[i]-(n-1)*D];
					Y1= Ay[R[i]-(n-1)*D];
				}else{
					X1=Ax[R[i]];
					Y1=Ay[R[i]];
				}
				if(A[X][Y] == A[X1][Y1]) break;
				n++;
				I = Ax[L[i]+n*D]; J = Ay[L[i]+n*D];
				if(n >= 1){
					I1= Ax[R[i]-(n-1)*D]; J1= Ay[R[i]-(n-1)*D];
					ans+=abs(X-I)+abs(Y-J)+abs(X1-I1)+abs(Y1-J1);
				}else ans+=abs(X-I)+abs(Y-J);
            }
		}
		cout << ans << endl;
	}
	return 0;
}

