void dfs(const vector<vector<int>>& nodes, map<pair<int, int>, ll>& costs, const int& s, vector<ll>& d) {
  for (auto& t : nodes[s]) {
    if (d[t] != INFL) continue;
    d[t] = d[s] + costs[{min(s, t), max(s, t)}];
    dfs(nodes, costs, t, d);
  }
}

