    vector<vector<int>> A(H, vector<int>(W));
    for(int i = 0; i < H; ++i){
        for(int j = 0; j < W; ++j){
            cin >> A[i][j];
        }
    }
    int Q;
    cin >> Q;
    vector<int> L(Q), R(Q);
    for(int i = 0; i < Q; ++i){
        cin >> L[i] >> R[i];
    }

    // キーに対応する座標を格納するコンテナ
    vector<P> coord(H * W + 1);
    for(int i = 0; i < H; ++i){
        for(int j = 0; j < W; ++j){
