		ll i=l;
		pair<ll,ll> p;
		p=m[l];
		ll count=0;
		while(i<r){
			i+=D;
			auto q=m[i];
			count+=abs(p.first-q.first)+abs(p.second-q.second);
			p=q;
		}
		p(count);
	}

}

