void solve() {
  long H, W, D;
  cin >> H >> W >> D;
  rep (i, H) rep (j, W) {
    long A;
    cin >> A;
    pos[A] = make_pair(i+1, j+1);
  }
  for (long i = 1; i <= D; i++) {
    long current = 0;
    cost[i].push_back(current);
    for (long j = i+D; j <= H*W; j+=D) {
      auto foo = pos[j-D];
      auto bar = pos[j];
      current += abs(foo.first - bar.first) + abs(foo.second - bar.second);
      cost[i].push_back(current);
    }
  }
  long Q;
  cin >> Q;
  rep (i, Q) {
    long L, R;
    cin >> L >> R;
    long foo = L % D;
    if (foo == 0) foo = D;

    long l = (L - foo) / D;
    long r = (R - foo) / D;

    cout << cost[foo][r] - cost[foo][l] << endl;
  }
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

