struct E{
    ll from , to, cost;
};
ll DIST[100005];
//start と 辺の数 m 辺の情報 x を入力
void shortest(LL s , vector<E> &x , ll m){
    REP(i,100000){
        DIST[i] = INF;
    }
    DIST[s] = 0;
    while(1){
        bool t = false;
        REP(i,m){
            E h = x[i];
            if(DIST[h.from] != INF && DIST[h.to] > DIST[h.from] + h.cost){
                DIST[h.to] = DIST[h.from] + h.cost; 
                t = true;
            }
        }
        if(!t){
            break;
        }
    }
}










