pair<int, int> idx[N*N];

int q;

int memo[N*N];

int func(int x)
{
	if( memo[x] > 0 ) {
		return memo[x];
	}
	if( x < d ) {
		return 0;
	}

	int y = x - d;
	int cost = abs( idx[x].first - idx[y].first ) + abs( idx[x].second - idx[y].second );
	int res = cost + func( y );
	return memo[ x ] = res;
}

int main()
{
	int h, w;
	int ans;
	int a;
	int l, r;

	cin >> h >> w >> d;

	for( int i = 0; i < h; i++ ) {
		for( int j = 0; j < w; j++ ) {
			cin >> a;
			a--;
			idx[ a ] = make_pair( j, i );
		}
	}

	cin >> q;
	for( int i = 0; i < q; i++ ) {
		cin >> l >> r;
		l--;
		r--;
		ans = func( r ) - func( l );
		cout << ans << endl;
	}

	return 0;
}

