vector<vector<int>> costs;
int main() {
	int h, w, d, a, inverse[300 * 300];
	scanf("%d %d %d", &h, &w, &d);
	for (int i = 0; i < h; i++)
		for (int j = 0; j < w; j++) {
			scanf("%d", &a);
			inverse[a - 1] = (i << 16) + j;
		}

	costs.resize(d);
	int px, py, x, y;
	for (int i = 0; i < d; i++) {
		costs[i].push_back(0);
		px = inverse[i] >> 16, py = inverse[i] & 0xffff;
		for (int j = i + d; j < h * w; j += d) {
			x = inverse[j] >> 16, y = inverse[j] & 0xffff;
			costs[i].push_back(costs[i].back() + abs(x - px) + abs(y - py));
			px = x, py = y;
		}
	}

	int q, l, r, res;
	scanf("%d", &q);
	for (int i = 0; i < q; i++) {
		scanf("%d %d", &l, &r);
		l--, r--;
		res = costs[r % d][r / d] - costs[l % d][l / d];
		printf("%d\n", res);
	}
}

