bool dfs(lint from,lint to,lint par = -1){
    if(from == to){
        return true;
    }
    for(edge<lint> v : G[from]){
        if(v.to == par)continue;
        if(dfs(v.to,to,from)){
            co.push_back(v.cost);
            return true;
        }
    }
    return false;
}
lint digit(lint a,lint b){
    lint ad = 1,bd = 1;
    while(a > 9){
        ad++;
        a /= 10;
    }
    while(b > 9){
        bd++;
        b /= 10;
    }
    return max(ad,bd);
}

