    if(src == dst){ return cost; }
    int to = src + d;
    rep(i, h){
        rep(j, w){
            if(to == fld[i][j]){ 
                cost += abs(plc.first - i);
                cost += abs(plc.second - j);
                plc = mp(i, j);
                break;
            }
        }
    }
    return move(to, dst, cost, plc);
}

void solve(int l, int r){
    pint place;
    rep(i, h){
        rep(j, w){
            if(l == fld[i][j]){ place = mp(i, j); break; }
        }
    }
    int cost = move(l, r, 0, place);
    cout << cost << endl;
}

