    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> h >> w >> d;
    int n;
    rep(i, h){
        rep(j, w){
            cin >> fld[i][j];
        }
    }
    int q;
    cin >> q;
    vi l(q), r(q);
    rep(i, q){
        cin >> l[i] >> r[i];
        solve(l[i], r[i]);
    }



    return 0;
}

