int H, W, D, Q;
unordered_map<int, pair<int, int>> valueToPosDict;
map<int64_t, int> dp;

int Calc(int64_t L, int64_t R) {
  if (L == R) {
    return 0;
  }

  int64_t h = (L << 32) & R;

  if (dp.find(h) != dp.end()) {
    return dp[h];
  }

  const auto& nextPos = valueToPosDict[L + D];
  const auto& currentPos = valueToPosDict[L];
  int cost = abs(nextPos.first - currentPos.first) +
             abs(nextPos.second - currentPos.second);
  dp[h] = Calc(L + D, R) + cost;
  return dp[h];
}

