typedef long long ll;
typedef pair<int,int> point;
#define rep(i,n) for(i,0,n)


int H, W, D;
int A[300][300];


int Maryoku(point p1, point p2){
	int ans = abs(p1.first-p2.first) + abs(p1.second-p2.second);
	return ans;
}

point SearchP(int target){
	point p;
	for (int i = 0; i < H; ++i){
		for (int j = 0; j < W; ++j){
			if (A[i][j]==target){
				p.first = i;
				p.second = j;
				break;
			}
		}
	}
	return p;
}

int main() {
	// 入力
	cin >> H >> W >> D;
	for (int i = 0; i < H; ++i)
		for (int j = 0; j < W; ++j) cin >> A[i][j];
	int Q;
	cin >> Q;
	int L[Q], R[Q];
	for (int i = 0; i < Q; ++i) cin >> L[i] >> R[i];

	// 解法
	for (int i = 0; i < Q; ++i){
		int ans = 0;
		int step = (R[i]-L[i])/D;
		for (int j = 0; j < step; ++j){
			point p1 = SearchP(L[i] + j * D);
			point p2 = SearchP(L[i] + (j+1) * D);
			ans += Maryoku(p1, p2);
		}
		printf("%d\n", ans);
	}
}

