int getDist(int n1, int n2) {
	int x1, x2, y1, y2;
	bool b1 = false, b2 = false;
	for (int i = 0;i < h;i++) {
		for (int j = 0;j < w;j++) {
			if (n1 == a[i][j]) {
				x1 = i;
				y1 = j;
				b1 = true;
				if (b2) {
					return abs(x1 - x2) + abs(y1 - y2);
				}
			}
			if (n2 == a[i][j]) {
				x2 = i;
				y2 = j;
				b2 = true;
				if (b1) {
					return abs(x1 - x2) + abs(y1 - y2);
				}
			}
		}
	}
}

