	for (int i = 0;i <= h * w;i++) {
		if (i <= d) {
			dist[i] = 0;
		}
		else {
			dist[i] = getDist(i - d, i);
		}
	}

	vector<int> sum;
	sum.resize(h*w + 1);
	for (int i = 1;i <= h * w;i++) {
		if (i <= d) {
