struct Grid
{
    int x=0;
    int y=0;
};

int Magic(Grid from,Grid to)
{
    return abs(to.x-from.x)+abs(to.y-from.y);
}

int main()
{
    int H,W,D;
    cin>>H>>W>>D;
    vector<Grid> G(H*W);
    for (int i=0; i<H*W; ++i)
    {
        int a;
        cin>>a;
        G[a-1].x=i%W;
        G[a-1].y=i/W;
    }

    vector<int> M(H*W,0);
    for (int i=0; i<H*W; ++i)
    {
        if(i-D>=0)
        {
            M[i] = M[i-D] +Magic(G[i-D],G[i] );
        }
    }

    int Q;
    cin>>Q;

    vector<int> ans(Q,0);
    for (int i=0; i<Q; ++i) {
        int L,R;
        cin>>L>>R;
        ans[i]=M[R-1]-M[L-1];
    }

    for (int i=0; i<Q; ++i)
    {
        cout<<ans[i]<<endl;
    }
    return 0;
}

