const ll INF = 1e18;

void solve() {
  ll H, W, D;
  cin >> H >> W >> D;

  VL num_to_h(H * W + 1);
  VL num_to_w(H * W + 1);

  rep(h, H) rep(w, W) {
    ll val;
    cin >> val;

    num_to_h[val] = h;
    num_to_w[val] = w;
  }

  VVL rem_acc(D + 1, VL(0));

  rep1(first, D) {
    ll cur = first;
    ll acc = 0;

    rem_acc[first].emplace_back(acc);

    while (cur + D <= H * W) {
      ll next = cur + D;
      ll cost = abs(num_to_h[cur] - num_to_h[next]) +
                abs(num_to_w[cur] - num_to_w[next]);
      acc += cost;
      rem_acc[first].emplace_back(acc);
      cur = next;
    }
  }

  ll Q;
  cin >> Q;

  rep(i, Q) {
    ll L, R;
    cin >> L >> R;

    ll first = L % D == 0 ? D : L % D;
    ll l_index = (L - first) / D;
    ll r_index = (R - first) / D;

    ll res = rem_acc[first][r_index] - rem_acc[first][l_index];
    cout << res << endl;
  }
}

void solve2() {
  ll H, W, D;
  cin >> H >> W >> D;

  VL num_to_h(H * W + 1);
  VL num_to_w(H * W + 1);

  rep(h, H) rep(w, W) {
    ll val;
    cin >> val;

    num_to_h[val] = h;
    num_to_w[val] = w;
  }

  VL acc(H * W + 1);
  rep1(num, H * W) {
    unless(num + D <= H * W) continue;

    ll cost = abs(num_to_h[num] - num_to_h[num + D]) +
              abs(num_to_w[num] - num_to_w[num + D]);
    acc[num + D] = acc[num] + cost;
  }

  ll Q;
  cin >> Q;

  rep(i, Q) {
    ll L, R;
    cin >> L >> R;

    ll res = acc[R] - acc[L];

    cout << res << endl;
  }
}

