V solve(int h, int w, int d, const M& ass, int q, const V& ls, const V& rs){
    M cost(h * w + 1, V(h * w + 1));
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            for(int x = 0; x < h; x++){
                for(int y = 0; y < w; y++){
                    int a = ass[i][j];
                    int b = ass[x][y];
                    cost[a][b] = abs(x - i) + abs (y - j);
                }
            }
        }
    }

    V ms(q);
    for(int i = 0; i < q; i++){
        int m = 0;
        int p = ls[i];
        while(p != rs[i]){
            m += cost[p][p + d];
            p += d;
        }
        ms[i] = m;
    }
    return ms;
}

