int g[N][N];
PII p[N * N];
vector<vector<LL>> s;

int main()
{
	scanf("%d%d%d", &n, &m, &d);
	for (int i = 1; i <= n; i ++ )
		for (int j = 1; j <= n; j ++ )
		{
			scanf("%d", &g[i][j]);
			p[g[i][j]] = {i, j};
		}

	s.resize(d + 10);
	for (int i = 0; i < d; i ++ )
	{
		s[i].resize((n * m + d - 1) / d + 10);
		s[i][0] = 0;
		for (int j = 0; i + (j + 1) * d <= n * m; j ++ )
		{
			PII st = p[i + j * d], ed = p[i + (j + 1) * d];
			LL sum = abs(st.F - ed.F) + abs(st.S - ed.S);
			s[i][j + 1] = s[i][j] + sum;
		}
	}

	scanf("%d", &k);
	while (k -- )
	{
		int l, r;
		scanf("%d%d", &l, &r);

		int t = l % d;
		printf("%lld\n", s[t][r / d] - s[t][l / d]);
	}
	return 0;
}

