typedef long long ll;
typedef pair<int,int> P;

int H,W;
int D;
int A[300][300];
P coords[100000];

vector<vector<int> > sum;

int cost(int i,int j) {
  P a = coords[i],b=coords[j];
  return abs(a.first - b.first) + abs(a.second-b.second);
}
int main(int argc, char** argv, char** envp) {
  cin >> H >> W >> D;
  for(int i=0;i<H;++i) {
    for(int j=0;j<W;++j) {
      int a;
      scanf("%d", &a);
      a--;
      A[i][j] = a;
      coords[a] = P(i,j);
    }
  }
  sum.resize(D);
  for(int i=0;i<H * W;++i) {
    int s = 0;
    if (i < D) {
      s = 0;
    } else {
      s = sum[i%D].back() + cost(i,i-D);
    }
    sum[i%D].push_back(s);
  }
  int Q;
  cin >> Q;
  for(int i=0;i<Q;++i) {
    int L,R;
    scanf("%d%d", &L, &R);
    --L;--R;
    int answer = sum[L%D][R/D] - sum[L%D][L/D];
    cout << answer << endl;
  }

  return 0;
}

