int main()
{
    int h, w, d, q;
    int i, j, k, p, m;

    cin >> h >> w >> d;

    int a[h][w];

    for(i = 0; i < h; i++) {
        for(j = 0; j < w; j++) {
            cin >> a[i][j];

            place[a[i][j]].first = j;
            place[a[i][j]].second = i;
        }
    }

    cin >> q;

    int l[q], r[q];
    long long int cost[q];

    for(k = 0; k < q; k++) {
        cin >> l[k] >> r[k];
        cost[k] = 0;

        if(l[k] != r[k]) {

            p = l[k];
            m = l[k] + d;

            while(m <= r[k]) {

                if(dp[p][m] != 0) {
                    cost[k] += dp[p][m];
                } else {
                    cost[k] += cal(p, m);
                }

                p += d; m += d;
            }
        }
    }

    for(k = 0; k < q; k++) {
         cout << cost[k] << endl;
    }

    return 0;
}

long long int cal(int l, int r)
{
    dp[l][r] = abs(place[l].first - place[r].first) + abs(place[l].second - place[r].second);

    return dp[l][r];
}

