template <class T> inline T abs(const T& a) { return (a < 0) ? -a : a; }

int main() {
  int H, W, D;
  cin >> H >> W >> D;
  map<int, Pos> as;
  {
    int a;
    for(int h = 1; h <= H; ++h) {
      for(int w = 1; w <= W; ++w) {
        cin >> a;
        as[a] = Pos(h, w);
      }
    }
  }
  vector<ll> ds(H * W + 1);
  for(int i = 1; i <= D; ++i) {
    auto crnt = i;
    ds[crnt] = 0;
    while(true) {
      auto next = crnt + D;
      if(next > H * W) {
        break;
      }
      auto a1 = as[crnt];
      auto a2 = as[next];
      ds[next] = abs(a2.first - a1.first) + abs(a2.second - a1.second) + ds[crnt];
      crnt = next;
    }
  }
  int Q;
  cin >> Q;
  vector<pair<int, int>> qs(Q);
  for(int i = 0; i < Q; ++i) {
    cin >> qs[i].first >> qs[i].second;
  }

  for(auto q : qs) {
    int start = q.first;
    int end = q.second;
    ll ans = ds[end] - ds[start];
    cout << ans << endl;
  }

  return 0;
}

