typedef long long ll;
class Solver{
public:
    static const int MAXN=300;
    class Cell{
    public:
        int x,y,a;
        Cell(){}
        Cell(int i,int j,int v):x(i),y(j),a(v){}
        bool operator<(Cell &c){
            return a<c.a;
        }
    };
    vector<Cell>vctCell;
    vector<int>cost[MAXN*MAXN];
    void solve(){
        int h,w,d;
        cin>>h>>w>>d;
        for(int u=0;u<h;u++){
            for(int v=0;v<w;v++){
                int t;
                cin>>t;
                vctCell.push_back(Cell(u,v,t));
            }
        }
        sort(vctCell.begin(),vctCell.end());
        for(int m=1;m<=d;m++){
            cost[m].push_back(0);
            for(int t=m+d;t<=h*w;t+=d){
                int dist=abs(vctCell[t-d-1].x-vctCell[t-1].x)
                +abs(vctCell[t-d-1].y-vctCell[t-1].y);
                cost[m].push_back(cost[m].back()+dist);
            }
        }
        int q;
        cin>>q;
        while(q--){
            int l,r;
            cin>>l>>r;
            if(r%d)
            cout<<cost[r%d?r%d:d][r/d]-cost[l%d?l%d:d][l/d]<<"\n";
            else 
            cout<<cost[r%d?r%d:d][r/d-1]-cost[l%d?l%d:d][l/d-1]<<"\n";
        }
    }
};
int main()
{
    // freopen("in.txt","r",stdin);
    (new Solver())->solve();
}

