using namespace std;

inline int dis(pair<int,int> x, pair<int,int> y) {
    return abs(x.first-y.first) + abs(x.second - y.second);
}

int main(void) {
    int h, w, d;
    cin >> h >> w >> d;
    vector<pair<int,int>> ra(h*w);
    for(int i=0; i<h; i++)
        for(int j=0; j<w; j++) {
            int a;
            cin >> a;
            a--;
            ra[a] = pair<int,int>(i,j);
        }

    vector<vector<int>> tran(h*w, vector<int>(20));

    for(int x=0; x+d<h*w; x++) {
        tran[x][0] = dis(ra[x], ra[x+d]);
    }
    for(int i=1; d*(1<<i-1)<h*w; i++) {
        for(int x=0; x+d*(1<<i-1)<h*w; x++) {
            tran[x][i] = tran[x][i-1] + tran[x+d*(1<<i-1)][i-1];
        }
    }

    int q;
    cin >> q;
    for(int i=0; i<q; i++) {
        int l, r;
        cin >> l >> r;
        l--, r--;
        long res = 0;
        int n = (r-l)/d;
        for(int i=0; (1<<i)<=n; i++) {
            if(!((1<<i)&n)) continue;
            res += tran[l][i];
            l += d*(1<<i);
        }
        cout << res << endl;
    }
}

