using namespace std;

int calc(int x[], int y[], int start, int end, int preX, int preY, int D);

int main(void){
    //入力部分
    int H, W, D;
    cin>>H>>W>>D;
    vector<int> A;
    for(int i = 0; i < W * H; i++){
        int tmp;
        cin>>tmp;
        A.push_back(tmp);
    }

    int Q;
    cin>>Q;
    int L[Q];
    int R[Q];
    for(int i = 0; i < Q; i++){
        cin>>L[i]>>R[i];
    }
    //入力部分終わり

    //入力Aからある値がどこに入っているかを計算する部分
    int x[W * H];
    int y[W * H];
    for(int i = 0; i < W * H; i++){
        x[A[i]] = i / W;
        y[A[i]] = i % W;
    } 
    for(int i = 0; i < Q; i++){
        int start = L[i];
        int end = R[i];
        cout<<calc(x, y, start, end, x[start], y[start], D)<<endl;
    }

    return 0;
}

int calc(int x[], int y[], int start, int end, int preX, int preY, int D){
    int nextX = x[start];
    int nextY = y[start];
    int magicalPower = abs(nextX - preX) + abs(nextY - preY);

    if(start == end){
        return magicalPower;
    }else{
        return magicalPower + calc(x, y, start + D, end, nextX, nextY, D);
    }
}

