    cin.tie(NULL);

    int h, w, d;
    cin >> h >> w >> d;
    vector < pair < int, int > > pos(h * w + 1);
    for (int i = 1; i <= h; ++i) {
        for (int j = 1; j <= w; ++j) {
            int a;
            cin >> a;
            pos[a] = make_pair(i, j);
        }
    }
    vector < vector < int > > pref(d);
    for (int i = 1; i <= d; ++i) {
        pref[i % d].push_back(0);
        pair < int, int > prv = pos[i];
        for (int j = i + d; j <= h * w; j += d) {
            pref[i % d].push_back(pref[i % d].back() + magic(prv, pos[j]));
            prv = pos[j];
        }
    }
    int q;
