void search(int& x, int& y, int n)
{
	for (size_t i = 0; i < H; i++)
	{
		for (size_t j = 0; j < W; j++)
		{
			if (A[i][j] == n)
			{
				x = j;
				y = i;
				return;
			}
		}
	}
}

int main()
{
	cin >> H >> W >> D;

	for (size_t i = 0; i < H; i++)
	{
		for (size_t j = 0; j < W; j++)
		{
			cin >> A[i][j];
		}
	}

	int Q;
	cin >> Q;

	for (size_t i = 0; i < Q; i++)
	{
		cin >> L[i] >> R[i];
	}

	for (size_t i = 0; i < Q; i++)
	{
		int x, y;
		int l = L[i];
		int r = R[i];
		search(x, y, l);
		l += D;

		long long ans = 0;
		while (l <= r)
		{
			int tx, ty;
			search(tx, ty, l);
			ans += abs(tx - x) + abs(ty - y);
			x = tx;
			y = ty;
			l += D;
		}
		cout << ans << endl;

	}
	return 0;
}

