const int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};

const int MAX_H = 300, MAX_W = 300, MAX_Q = 1e5;
int H, W, D;
int A[MAX_H][MAX_W];
int Q;
int L[MAX_Q], R[MAX_Q];

void input() {
  cin >> H >> W >> D;
  rep(i,H) {
    rep(j,W) {
      cin >> A[i][j];
    }
  }
  cin >> Q;
  rep(i,Q) cin >> L[i] >> R[i];
}

vector<vector<int> > make_table() {
  vector<pii> a(H*W+1);
  for (int i = 0; i < H; ++i) {
    for (int j = 0; j < W; ++j) {
      a[A[i][j]] = pii(i, j);
    }
  }

  vector<vector<int> > res(D+1);
  for (int l = 1; l <= D; ++l) {
    int c = 0;
    for (int k = 0; l + D*k <= H*W; ++k) {
      int d = l + D*k;
      int s = (k == 0 ? d : d - D);
      c += abs(a[s].fi - a[d].fi) + abs(a[s].sc - a[d].sc);
      res[l].push_back(c);
    }
  }

  return res;
}

int main() {
  input();

  vector<vector<int> > qt = make_table();

  for (int i = 0; i < Q; ++i) {
    if (1 <= L[i] && L[i] <= D) {
      int s = L[i], d = (R[i]-L[i])/D;
      cout << qt[s][d] << endl;
    } else if (L[i]%D == 0) {
      int s = D, d1 = L[i]/D-1, d2 = R[i]/D-1;
      cout << qt[s][d2] - qt[s][d1] << endl;
    } else {
      int s = L[i]%D, d1 = (L[i]-s)/D, d2 = (R[i]-s)/D;
      cout << qt[s][d2] - qt[s][d1] << endl;
    }
  }

  return 0;
}

