int H, W, D;
int N;

vector<pair<int, int>> pos;
vvll dp;

ll rec(int l, int r)
{
    if (!(l >= 0 && l < N && r >= 0 && r < N)) return 0;
    if (dp[l][r] >= 0) return dp[l][r];

    ll val = 0;

    if (l == r)
    {
        val = 0;
    }
    else if (l == r - D)
    {
        auto p = pos[l];
        auto q = pos[r];
        val = abs((ll)p.first - (ll)q.first) + abs((ll)p.second - (ll)q.second);
    }
    else
    {
        val = rec(l, r - D) + rec(r - D, r);
    }

    dp[l][r] = dp[r][l] = val;
    return dp[l][r];
}

