                d[i]=INF;
            }
        }
        void add_edge(ll s,ll t,ll cost){
            edge e;
            e.to=t;
            e.cost=cost;
            G[s].emplace_back(e);
        }
        void dijkstra(ll s){
            rep(i,V){
                d[i]=INF;
            }
            d[s]=0;
            priority_queue<pll,vector<pll>,greater<pll>> que;
            que.push(pll(0,s));
            while(!que.empty()){
                pll p=que.top();
                que.pop();
                ll v=p.second;
                if(d[v]<p.first)continue;
                for(auto e:G[v]){
                    if(d[e.to]>d[v]+e.cost){
                        d[e.to]=d[v]+e.cost;
                        que.push(pll(d[e.to],e.to));
                    }
                }
            }
        }
    };

