void solve()
{
	int h,w,d; cin >> h >> w >> d;
	map<int, P> mp;
	rep(i, h)rep(j, w)
	{
		int a;cin >> a;
		mp[a] = {i, j};
	}
	mp[0] = mp[d];
	vector<vector<int>> cost(d, vector<int>(h*w/d+1, 0));
	rep(i, d)rep(j, h * w / d)
	{
		int from = i + d * j;
		int to = i + d * (j + 1);
		if(to > h * w)continue;
		int from_x = mp[from].first, from_y = mp[from].second;
		int to_x = mp[to].first, to_y = mp[to].second;

		cost[i][j+1] = cost[i][j] + abs(from_x-to_x)+abs(from_y-to_y);
	}
	int q; cin >> q;
	vector<ll> ans;
	rep(i, q)
	{
		int l, r; cin >> l >> r;
		int s = l % d;
		int n = l / d,m = r / d;
		ans.push_back(cost[s][m]-cost[s][n]);
	}
	rep(i, q)cout << ans[i] << endl;
	return;
}

int main()
{
