    int R;
    int ans;
};

int compare_R(const void *a, const void *b)
{
    return ((struct quest *)a)->R - ((struct quest *)b)->R;
}

int compare_index(const void *a, const void *b)
{
    return ((struct quest *)a)->index - ((struct quest *)b)->index;
}

int main(){
    int H, W, D;
    cin >> H >> W >> D;
    int *x = new int[H*W+1];
    int *y = new int[H*W+1];
    int *mp = new int[H*W+1];
    for(int i=1;i<=H;i++){
        for(int j=1;j<=W;j++){
            int a;
            cin >> a;
            x[a] = i;
            y[a] = j;
        }
    }
    for(int i=1;i<=H*W-D;i++){
        mp[i] = abs(x[i+D] - x[i]) + abs(y[i+D] - y[i]);
    }
    mp[H*W] = 0;

    int Q;
    cin >> Q;
    struct quest *quests = new struct quest[Q];
    for(int i=0;i<Q;i++){
        quests[i].index = i;
        cin >> quests[i].L >> quests[i].R;
        quests[i].ans = 0;
    }
    // sort by R in ascending order
    qsort(quests, Q, sizeof(struct quest), compare_R);

    for(int i=0;i<Q;i++){
        for(int j=0;j<i;j++){
            if(quests[i].L==quests[j].L&&quests[i].R>=quests[j].R){
                quests[i].L = quests[j].R;
                quests[i].ans = quests[j].ans;
            }
        }
        while(quests[i].L!=quests[i].R){
            quests[i].ans += mp[quests[i].L];
            quests[i].L += D;
        }
    }

    qsort(quests, Q, sizeof(struct quest), compare_index);
    for(int i=0;i<Q;i++){
        cout << quests[i].ans << endl;
    }
    return 0;
}

