void AddCost(uint64_t* totalCost, int D, std::unordered_map<int, std::pair<int, int>>& mapMemo, int l, int r)
{
    static std::unordered_map<int, uint64_t> costMemo;

    if (l == r) return;

    int searchNum = 1000 * r + l;
    auto costItr = costMemo.find(searchNum);
    if (costItr != costMemo.end()) {
        *totalCost = costItr->second;
        return;
    }

    // コストがメモ化されていないので計算する

    // R_i = L_i + nD なので、L, L + D, L + 2D, ... で R になるまでの整数値だけが必要
    // x_j = L_i + jD とする
    // x_j - L_i % D == 0 && x_j >= L_i なら true
    // cost_j = |x_(j + 1) - x_j

    std::unordered_map<int, std::pair<int, int>> map;
    for (int v = l; v <= r; v += D)
    {
        map[v] = mapMemo[v];
    }

    for(auto& elem : map)
    {
        int v = elem.first;
        if (v == r) continue; // v == R は計算用に保存してあるだけなので skip

        const auto& currentPair = elem.second;
        const auto& nextPair = map[v + D];
        const int cost =
            std::abs(nextPair.first - currentPair.first) + 
            std::abs(nextPair.second - currentPair.second);
        *totalCost += static_cast<uint64_t>(cost);
    }

    // メモ化
    costMemo.emplace(searchNum, *totalCost);
}

