    c1[i] = abs(x[i + d] - x[i]) + abs(y[i + d] - y[i]);
  }
  for (int i = 0; i < h * w; ++i) {
    int ii = i;
    for (int j = 0; j < STEP; ++j) {
      if (ii >= h * w) break;
      c2[i] += c1[ii];
      ii += d;
    }
  }
  cin >> q;
  for (int i = 0; i < q; ++i) {
    int l, r;
    cin >> l >> r;
    --l, --r;
    int res = 0;
    while ((r - l) / d > STEP) {
      res += c2[l];
      l += STEP * d;
    }
    for (; l < r; l += d) res += c1[l];
    cout << res << endl;
  }
}

