    vvi A(H, vi(W));
    rep(i, H)
    {
        rep(j, W)
        {
            cin >> A[i][j];
            A[i][j]--;
        }
    }

    //数字から位置を取得できるようにする
    vector<pair<int, int>> pos(N);
    rep(i, H)
    {
        rep(j, W)
        {
