struct cell
{
    int x,y;
};

int distance(const cell& a, const cell& b)
{
    return abs(a.x - b.x) + abs(a.y - b.y);
}

unordered_map<int, int> memo;

int calc_mp(int a, int b, int D, const unordered_map<int, cell>& A_rev)
{
    if(a == b) return 0;
    int idx = 100000*a + b;
    if(memo[idx] == 0)
    {
        int next_a = a + D;
        memo[idx] = distance(A_rev.at(a), A_rev.at(next_a)) + calc_mp(next_a, b, D, A_rev);
    }

    return memo[idx];
}

