const int inf = 1e9;
const int maxn = 333*333;
const int maxq = 1e5+5;
int x[maxn], y[maxn], dist[maxn], L[maxq], R[maxq], vis[maxn];
int h,w,d,q;
map<PII,int> ans;

void dfs(const int src, const int val)
{
    const int v = val+d;
    if (v < maxn) {
        const int cost = dist[val] + abs(x[v]-x[val])+abs(y[v]-y[val]);
        if (cost < dist[v]) {
            dist[v] = cost;
            dfs(src,v);
        }
        const PII k = PII(src,val);
        if (in_(k,ans))
            ans[k] = min(ans[k],dist[val]);
    }
}

