        FOR(i,1,h+1) FOR(j,1,w+1) {
            int a; cin >> a;
            x[a] = i;
            y[a] = j;
        }
        ans.clear();
        cin >> q;
        FOR(i,0,q) {
            cin >> L[i] >> R[i];
            ans[PII(L[i],R[i])] = inf;
        }
        memset(vis,0,sizeof(vis));
        FOR(i,0,q) if (!vis[L[i]]) {
            vis[L[i]]++;
            FOR(j,1,h*w+1)
                dist[j] = inf;
            dist[L[i]] = 0;
            dfs(L[i],L[i]);
        }
        FOR(i,0,q)
            cout << ans[PII(L[i],R[i])] << endl;
    }   
    return 0;
}

