    for (int i = d; i < h * w; i += d)
    {
        for (int j = 0; j < d && i + j < h * w; j++)
        {
            accum[j][i / d] = accum[j][i / d - 1] + distance_of(i - d + j, i + j);
        }
    }

    if (false)
