int main(){
    int h, w, d;
    cin >> h >> w >> d;

    vector<vector<pair<int, int>>> grid(d, vector<pair<int, int>>(h*w/d+1));
    vector<vector<int>> a(h, vector<int>(w));
    for(int i=0; i<h; i++){
        for(int j=0; j<w; j++){
            cin >> a[i][j];
            grid[a[i][j] % d][a[i][j] / d] = make_pair(i,j);
        }
    }

    int q;
    cin >> q;
    vector<int> l(q), r(q);
    for(int i=0; i<q; i++){
        cin >> l[i] >> r[i];
    }

    vector<vector<int>> data(d, vector<int>(h*w/d+1));
    for(int i=0; i<d; i++){
        for(int j=1; j<h*w/d+1; j++){
            data[i][j] = abs(grid[i][j].first - grid[i][j-1].first)
                       + abs(grid[i][j].second - grid[i][j-1].second);
        }
    }

    // cumulative sum for each remainder
    for(int i=0; i<d; i++){
        for(int j=1; j<h*w/d+1; j++){
            data[i][j] += data[i][j-1];
        }
    }

    // solve
    for(int i=0; i<q; i++){
        int j = l[i] % d;
        cout << data[j][r[i]/d] - data[j][l[i]/d] << endl;
    }

