}

#include <bits/stdc++.h>
using namespace std;
#define rep(i, m, n) for (int i = m; i < n; ++i)

int main() {
    int H, W, D;
    cin >> H >> W >> D;
    int N = H * W;
    using P = pair<int, int>;
    using PI = pair<int, P>;
    vector<vector<PI>> A(D);
    rep(i, 0, H) rep(j, 0, W) {
        int a; cin >> a;
        A[a % D].push_back({a, {i + 1, j + 1}});
    }
    rep(i, 0, D) sort(A[i].begin(), A[i].end());
    function<int(P, P)> calc = [&](P a, P b) {
        int y = abs(a.first - b.first);
        int x = abs(a.second - b.second);
        return y + x;
    };
    vector<vector<int>> sum(D, vector<int>(N / D + 2));
    rep(i, 0, D) {
        rep(j, 0, A[i].size() - 1) {
            sum[i][j + 1] = sum[i][j] + calc(A[i][j].second, A[i][j + 1].second);
        }
    }
    int Q; cin >> Q;
    while(Q--) {
        int l, r;
        cin >> l >> r;
        int a = (r - l) / D;
        int n = l / D;
        if(l % D == 0) n--;
        cout << sum[l % D][n + a] - sum[l % D][n] << '\n';
    }
    return 0;
}

