int nxt[353*353][20];

int main(){
  scanf("%d%d%d",&h,&w,&d);
  REP(i,h)REP(j,w)scanf("%d",&a[i][j]),a[i][j]--;
  REP(i,h)REP(j,w)rev[a[i][j]] = pii(i,j);
  REP(i,h*w){
    int to = i+d;
    if(to>=h*w)continue;
    pii s = rev[i];
    pii t = rev[to];
    nxt[i][0] = abs(s.first-t.first) + abs(s.second-t.second);
  }
  FORR(i,0,h*w){
    FOR(j,1,20){
      nxt[i][j] = nxt[i][j-1];
      if(i+(1ll<<(j-1))*d<h*w){
        nxt[i][j] += nxt[i+(1ll<<(j-1))*d][j-1];
      }
    }
  }
  // REP(i,h*w){
