    l--;r--;
    int ans = 0;
    FORR(i,0,20){
      if(l+(1ll<<i)*d<=r){
        ans += nxt[l][i];
        l += (1<<i)*d;
      }
    }
    printf("%d\n",ans);
  }
  return 0;
}

