void solve_abc089() {
	ll h, w, d, q;
	ll ans = 0;

	cin >> h >> w >> d;

	rep(i, h) {
		rep(j, w) {
			cin >> a[i][j];
			m[a[i][j]] = make_pair(i, j);
		}
	}

	// i: dで割った余り
	P prev, next;
	rep(i, d) {
		s[i].push_back(0);
		// j: dの倍数
		for(ll j = 1; j * d <= h * w; j++) {
			prev = make_pair(m[i + (j - 1) * d].first, m[i + (j - 1) * d].second);
			next= make_pair(m[i + j * d].first, m[i + j * d].second);
			s[i].push_back(s[i][j - 1] + abs(next.first - prev.first) + abs(next.second - prev.second));
		}
	}

	cin >> q;
	vector<P> lr(q);
	ll l, r;
	rep(i, q) {
		cin >> l >> r;
		lr[i] = make_pair(l, r);
	}

	rep(i, q) {
		ans = 0;
		l = lr[i].first;
		r = lr[i].second;
		ans += s[l % d][r / d] - s[l % d][l / d];
		cout << ans << "\n";
	}
}

