int H, W, D, Q;
int A_inv[90000];
long long dist_memo[90000];

int dist(int p, int q){
    int dx = (A_inv[p]/W) - (A_inv[q]/W);
    int dy = (A_inv[p]%W) - (A_inv[q]%W);
    return max(dx, -dx) + max(dy, -dy);
}


int main(){
    cin >> H >> W >> D;
    for(int h = 0; h < H; h++){
        for(int w = 0; w < W; w++){
            int A;
            cin >> A;
            A--;
            A_inv[A] = h*W + w;
        }
    }

    int jump_cnt = (H*W-1)/D;

    for(int start = 0; start < D; start++){
        dist_memo[start * (jump_cnt+1)] = 0;
        for(int jc = 1; jc <= jump_cnt && (start + jc*D) < H*W; jc++){
            dist_memo[start * (jump_cnt+1) + jc] = dist_memo[start * (jump_cnt + 1) + jc - 1] + dist(start + D * jc, start + D * (jc-1));
        }
    }


    /*for(int start = 0; start < D; start++){
