void solv() {
	int h,w,d;
	cin >> h >> w >> d;
	pair<int, int> cell[100010];
	for (size_t i = 1; i <= h; i++)
	{
		for (size_t j = 1; j <= w; j++)
		{
			int a;
			cin >> a;
			cell[a] = pii(i,j);
		}
	}

	int q;
	cin >> q;
	ll f[100010], t[100010];
	for (size_t i = 0; i < q ;i++)
	{
		cin >> f[i] >> t[i];
	}

	ll cos[100010];
	memset(cos, -1, sizeof(cos));
	for (size_t i = 1; i < 100010; i++)
	{
		if (cos[i] != -1) continue;
		if (cell[i].first == 0) continue;
		int px = cell[i].first;
		int py = cell[i].second;
		int ti = i + d;
		cos[i] = 0;
		while (ti < 100010)
		{
			if (cell[ti].first == 0) break;
			int nx = cell[ti].first;
			int ny = cell[ti].second;
			cos[ti] = cos[ti - d] + abs(px - nx) + abs(py - ny);
			px = nx;
			py = ny;
			ti += d;
		}
	}

	for (size_t i = 0; i < q; i++)
	{
		int fv = f[i];
		int tv = t[i];
		cout << (cos[tv] - cos[fv]) << endl;
	}
}


