		It(int _x, int _s) :x(_x), s(_s) { assert(s); }
		int operator*() { return x; }
		bool operator!=(It& i) { return 0 < s ? x < i.x : x >= i.x; }
		void operator++() { x += s; }
	};
	int x, y, s;
public:
	step(int _y, int _s = 1) :x(0 < _s ? 0 : _y), y(0 < _s ? _y : 0), s(_s) {}
