	Point operator+() { return *this; }
	Point operator-() { return { -x,-y }; }
	Point operator+(Point p) { return { x + p.x,y + p.y }; }
	Point operator-(Point p) { return { x - p.x,y - p.y }; }
	Point operator*(Point p) { return { x * p.x,y * p.y }; }
	Point operator/(Point p) { return { x / p.x,y / p.y }; }
	Point operator+(int d) { return { x + d,y + d }; }
	Point operator-(int d) { return { x - d,y - d }; }
	Point operator*(int d) { return { x * d,y * d }; }
	Point operator/(int d) { return { x / d,y / d }; }
	Point& operator+=(Point p) { x += p.x; y += p.y; return *this; }
	Point& operator-=(Point p) { x -= p.x; y -= p.y; return *this; }
	Point& operator*=(Point p) { x *= p.x; y *= p.y; return *this; }
	Point& operator/=(Point p) { x /= p.x; y /= p.y; return *this; }
	bool operator==(Point p) { return x == p.x && y == p.y; }
	bool operator!=(Point p) { return x != p.x || y != p.y; }
	bool operator<(Point p) { return x < p.x || (x == p.x && y < p.y); }
	int Dist(Point p) { return abs(x - p.x) + abs(y - p.y); }
	bool inRange(int H, int W) { return 0 <= x && x < W && 0 <= y && y < H; }
	array<Point, 4> Adjacent4() {
		return { Point(x,y + 1),Point(x,y + -1),Point(x + 1,y),Point(x + -1,y) };
	}
	array<Point, 8> Adjacent8() {
		return { Point(x,y + 1),Point(x,y - 1),Point(x + 1,y),Point(x - 1,y),
			Point(x + 1,y + 1),Point(x + 1,y + -1),Point(x - 1,y + 1),Point(x - 1,y - 1) };
	}
	vector<Point> Adjacent4_inRange(int H, int W) {
		vector<Point> ret;
		for (auto P : Adjacent4())
			if (inRange(H, W))ret.push_back(P);
		return ret;
	}
	vector<Point> Adjacent8_inRange(int H, int W) {
		vector<Point> ret;
		for (auto P : Adjacent8())
			if (inRange(H, W))ret.push_back(P);
		return ret;
	}
};

