            cost[i].push_back(cost[i].back()
            + abs(j->second.first - prev(j)->second.first)
            + abs(j->second.second - prev(j)->second.second));
        }
    }

    for (int i = 0; i < q; i++) {
        int a = l[i] % d;
        printf("%d\n", cost[a][(a == 0) ? r[i] / d - 1 : r[i] / d] - cost[a][(a == 0) ? l[i] / d - 1 : l[i] / d]);
    }
