i64 H,W;
i64 D;

vector<Index2> indices;

// x%D から x に行くコスト
i64 f(i64 x) {
    static bool done[300*300] {};
    static i64  memo[300*300];

    if(x < D) return 0;

    if(!done[x]) {
        i64 cost = (indices[x]-indices[x-D]).norm1();
        i64 res = cost + f(x-D);

        memo[x] = res;
        done[x] = true;
    }
    return memo[x];
}

void solve() {
    RD(H); RD(W);
    RD(D);

    indices.resize(H*W);
    REP(y, H) REP(x, W) {
        i64 a; RD(a); --a;  // 0-based
        indices[a] = { y, x };
    }

    i64 Q; RD(Q);
    REP(_, Q) {
        i64 l,r; RD(l); RD(r); --l; --r;  // 0-based
        i64 ans = f(r) - f(l);
        PRINTLN(ans);
    }
}

signed main() {


    solve();

    EXIT();
}

