// 要素数Nの配列A[N]
////////////////////
ll shakutori( ll N, vector<ll> & A )
{
	ll ans = 0;
	ll head = 0;
	ll tail = 0;
	set<ll> memo;

	for (tail = 0; tail < N; tail++) {
		// [head, tail]に同じ数字が2つ以上含まれているときheadを進める
		while (memo.count(A[tail]) != 0) {
			memo.erase(A[head]);
			head++;
		}

		ans = max(ans, tail - head + 1);
		memo.insert(A[tail]);
	}

	return ans;
}

// 数学：		最大公約数、最小公倍数、素因数分解
// 探索：		貪欲法(全探索)、2分探索、ソート
//				BFS(幅優先探索)、DFS(深さ優先探索)
// 探索(発展)：	貪欲法、しゃくとり法、区間累積和
// データ構造：	スタック、キュー、deque
//				ハッシュ、map、リスト
// DP:			桁DP、ビットDP、メモ化再帰
// グラフ:		最短経路(ダイクストラ、ベルマンフォード、ワーシャルフロイト)
//				最小全域木(クラスカル法、プリム法、Union-Find)
//				三角不等式
// その他：		最大フロー、マッチング問題
//				セグメント木、RMQ、BIT、平方分割
// 
//ll dp[500000 * 2000 + 10];	// dp[i日目]までの勝ち数

#define VAL_MAX	(10000000000)
ll solve(ll N, vector<ll> & V)
{
	ll ans = -1;	// when -1, OK
	ll tmp = 0;
	ll cnt0 = 0;
	ll cnt1 = 0;
	bool isOK = false;
	vector<ll> V0(N, VAL_MAX);
	vector<ll> V1(N, VAL_MAX);

	// sort
	Rep(i, N) {
		if (i % 2 == 0) V0[cnt0++] = V[i];
		else V1[cnt1++] = V[i];
	}
	sort(V0.begin(), V0.end());
	sort(V1.begin(), V1.end());
	cnt0 = 0;
	cnt1 = 0;
	Rep(i, N) {
		if (i % 2 == 0) V[i] = V0[cnt0++];
		else V[i] = V1[cnt1++];
	}

	for (ll i = 0; i < N - 1; ++i) {
		if (V[i] > V[i + 1]) {
			ans = i;
			break;
		}
	}

	return ans;
}

