using namespace std;

int num_to_index(int num) {
	return num - 1;
}

pair<int, int> index_to_point(int index, int w) {
	return { (index / w) + 1, (index % w) + 1 };
}

int main()
{
	int h, w, d;
	cin >> h >> w >> d;

	vector<int> map(h * w);
	for (int i = 0; i < h * w; i++) {
		int a;
		cin >> a;
		map[num_to_index(a)] = i;
	}

	vector<int> precomputed_maryoku1(h * w);
	for (int current_index = 0; current_index + d < h * w; current_index++) {
		int next_index = current_index + d;
		auto current_point = index_to_point(map[current_index], w);
		auto next_point = index_to_point(map[next_index], w);
		precomputed_maryoku1[current_index] = abs(current_point.first - next_point.first) + abs(current_point.second - next_point.second);
	}

	vector<vector<uint64_t>> precomputed_maryoku2(h * w);
	for (int i = 0; ; i++) {
		int count = (h * w - (i + 1)) / d;
		if (count == 0) break;

		auto& v = precomputed_maryoku2[i];
		v.reserve(count);

		uint64_t maryoku = 0;
		for (int j = 0; j < count; j++) {
			maryoku += precomputed_maryoku1[i + j * d];
			v.push_back(maryoku);
		}

		precomputed_maryoku2[i] = move(v);
	}

	int q;
	cin >> q;

	for (int i = 0; i < q; i++) {
		int l, r;
		cin >> l >> r;
		auto maryoku = l == r
			? 0
			: precomputed_maryoku2[num_to_index(l)][((r - l) / d) - 1];
		cout << maryoku << endl;
	}

	return 0;
}

