		for(int v=1;v<=m;v++)
		{
			int x;
			std::cin>>x;
			ai[x]=node(i,v);
		}
	for(int i=1;i+d<=size;i++)
		f[0][i]=ai[i]+ai[i+d];
	for(int i=1;i<=21;i++)
		for(int v=1;v<=size;v++)
			if(v+(1<<i)*d<=size)
				f[i][v]=f[i-1][v]+f[i-1][v+(1<<(i-1))*d];
	int q,l,r,t,res;
	std::cin>>q;
