map<int, pair<int, int>> indexes;
map<pair<int, int>, int> memo;

int dp(int curr, int goal, int D) {
    if (curr == goal) {
        return 0;
    }
    auto p = make_pair(curr, curr + D);
    int toNext = 0;
    if (memo.count(p) > 0) {
        toNext += memo[p];
    }
    else {
        pair<int, int> curr_ij = indexes[curr];
        pair<int, int> next_ij = indexes[curr + D];
        toNext += abs(next_ij.first - curr_ij.first) + abs(next_ij.second - curr_ij.second);
    }
    int ret = toNext + dp(curr + D, goal, D);
    return ret;
}

