void solve(){
    int H, W, D;
    cin >> H >> W >> D;
    vector<vector<int>> input_grid (H,vector<int>(W));
    for(int i = 0;i < H;i++){
        for(int j = 0;j < W;j++){
            cin >> input_grid[i][j];
        }
    }
    vector<pair<int,int>> grid (H*W);
    for(int i = 0;i < H;i++){
        for(int j = 0;j < W;j++){
            grid[input_grid[i][j]-1].first = i;
            grid[input_grid[i][j]-1].second = j;
        }
    }

    vector<int> memo (H*W);
    for(int i = 1;i <= D;i++){
        int count = i;
        memo[i-1] = 0;
        count += D;
        while(count <= H*W){
            memo[count-1] = memo[count-D-1]+abs(grid[count-1].first-grid[count-D-1].first)+abs(grid[count-1].second-grid[count-D-1].second);
            count += D;
        }
    }

//    for(int i = 0;i < H*W;i++){
//        cout << "memo[" << i << "] " << memo[i] << endl;
//    }

    int Q;
    cin >> Q;
    for(int i = 0;i < Q;i++){
        int L, R;
        cin >> L >> R;
        cout << memo[R-1]-memo[L-1] << endl;
    }
}

