using int_t = unsigned long long;

int main() {
    int H, W, D;
    scanf("%d %d %d", &H, &W, &D);
    vector<int> Aijs;
    vector<pair<int, int>> idxAndAij;
    int N = H * W;
    for (int ij = 0; ij < N; ij++) {
        int Aij;
        scanf("%d", &Aij);
        Aijs.push_back(Aij);
        idxAndAij.emplace_back(ij, Aij);
    }
    auto dis = [W, H](int idx1, int idx2) {
        return abs(idx1 % W - idx2 % W) + abs(idx1 / H - idx2 / H);
    };
    sort(idxAndAij.begin(), idxAndAij.end(), [](pair<int,int> a, pair<int, int> b) {
        return a.second < b.second;
    });
    vector<int> costs(N, 0);
    for (int Aij = 1; Aij <= N; Aij++) {
        if (Aij - D >= 1) {
            int idxCur = idxAndAij[Aij - 1].first;
            int idxPrev = idxAndAij[Aij - D - 1].first;
            costs[Aij - 1] += costs[Aij - D - 1] + dis(idxCur, idxPrev);
        } else {
            costs[Aij - 1] = 0;
        }
    }
    int Q;
    scanf("%d", &Q);
    for (int q = 0; q < Q; q++) {
        int L, R;
        scanf("%d %d", &L, &R);
        printf("%d\n", costs[R - 1] - costs[L - 1]);
    }
    return 0;
}

