int main(){
    int H, W, D, q;
    cin >> H >> W >> D;
    //A[i]にAij の座標を格納
    vector<pair<int, int>> A(H * W + 1, pair<int, int>(0, 0));
    //cost[i], i % D から i までのコスト
    vector<long long> cost(H * W + 1, 0);
    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            int a;
            cin >> a;
            A[a].first = i;
            A[a].second = j;
        }
    }

    for(int i = 1; i <= D; i++){
        cost[i + D] = abs(A[i].first - A[i + D].first) + abs(A[i].second - A[i + D].second);
    }

    for(int i = D + 1; i < H * W - D; i++){
        cost[i + D] = cost[i] + abs(A[i].first - A[i + D].first) + abs(A[i].second - A[i + D].second);
    }

    cin >> q;
    while(q > 0){
        int s, g;
        cin >> s >> g;
        cout << cost[g] - cost[s] << '\n';
        q--;
    }
    return 0;
}

