int memo[301*301*301*301];

Int dist(Int x, Int r){
    if (x == r){
        return 0;
    }
    if (memo[x + 301*301*r] != 0){
        return memo[x + 301*301*r];
    }

    P px = locs[x];
    P px_ = locs[x+D];

    Int d = abs(px.first - px_.first) + abs(px.second - px_.second);
    Int ret = d + dist(x+D, r);
    memo[x + 301*301*r] = ret; 
    return ret;
}

