        cin >> T[i].first >> T[i].second;
        T[i].first--;
        T[i].second--;
    }
    for(int i=0; i<Q; i++){
        int surp=T[i].first % D;
        int ln=T[i].first/D, rn=T[i].second/D;
        cout << Dists[surp][rn] - Dists[surp][ln] << '\n';
    }
    return 0;
}

