//累積和の問題
//R-L % D == 0であるから，R%D ≡ L%D = xとおく
//クエリは，（xからRに行くためにかかるコスト）-（xからLに行くためにかかるコスト）に単純化される
//即ち，y = 0~D-1において，xからyまでDずつ移動するのにかかるコストをtableで保持し，table[x][y]をもとにクエリ処理する
//計算量は，(D*(H*W) + Q)で，十分間に合う

int H, W, D;
vector<pair<int, int>> idx;
vector<vector<int>> table;

void tableau() {
    for (int i = 0; i < D; i++) {
        table[i][i] = 0;
        int s = i;
        int g = i+D;
        while(g < (H-1)*(W-1)) {
            int cost;
            cost = abs(idx[s].first - idx[g].first);
            cost += abs(idx[s].second - idx[g].second);
            table[i][g] = table[i][s] + cost;
            s += D;
            g += D;
        }
    }
}

int main() {
    cin >> H >> W >> D;
    idx.resize((H-1)*(W-1));
    table.resize(D, vector<int> ((H-1)*(W-1), 0));
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            int a; cin >> a; a--;
            idx[a] = make_pair(i, j);
        }
    }
    tableau();
    int Q; cin >> Q;
    for (int i = 0; i < Q; i++) {
        int L, R; cin >> L >> R; L--; R--;
        int dist;
        int s = L % D;
        dist = table[s][R]-table[s][L];
        cout << dist << endl;
    }
}

