        if(l[k] != r[k]) {

            p = l[k];
            m = l[k] + d;

            while(m <= r[k]) {

                if(dp[p][m] != 0) {
                    cost[k] += dp[p][m];
                } else {
                    cost[k] += cal(p, m);
                }

                p += d; m += d;
            }
        }
    }

    for(k = 0; k < q; k++) {
         cout << cost[k] << endl;
    }

    return 0;
}

long long int cal(int l, int r)
{
    dp[l][r] = abs(place[l].first - place[r].first) + abs(place[l].second - place[r].second);

    return dp[l][r];
}

