using POS = pair<int, int>;

int A[300][300];
unordered_map<int, POS> n_to_pos;
int cum_pow[300 * 300 + 1];

int main() {
	int H, W, D;
	cin >> H >> W >> D;

	for (int i=0; i<H; i++) {
		for (int j=0; j<W; j++) {
			cin >> A[i][j];
			n_to_pos[A[i][j]] = make_pair(i, j);
		}
	}

	// 事前計算
	for (int i=0; i<D; i++) {
		for (int l=i; l<=H*W; l+=D) {
			int r = l + D;

			POS l_pos = n_to_pos[l];
			POS r_pos = n_to_pos[r];

			int pow = abs(l_pos.first - r_pos.first) + abs(l_pos.second - r_pos.second);
			cum_pow[r] = cum_pow[l] + pow;
		}
	}

	int Q;
	cin >> Q;

	vector<int> ans;

	for (int i=0; i<Q; i++) {
		int L, R;
		cin >> L >> R;
		ans.push_back(cum_pow[R] - cum_pow[L]);
	}

	for (int a : ans) {
		cout << a << endl;
	}

	return 0;
}

