int dig[20][190005];
int kai(int a){
  int ans = 1;
  for(int i=0; i<a; ++i) ans *= 2;
  return ans;
}

int main(){
  int h, w, d;
  cin >> h >> w >> d;
  P p[90001];
  for(int i=0; i<h; ++i) for(int j=0; j<w; ++j){
    int x;
    cin >> x;
    p[x] = make_pair(i,j);
  }
  for(int i=1; i+d<=h*w; ++i){
    dig[0][i] = abs(p[i].first - p[i+d].first) + abs(p[i].second -p[i+d].second);
  }
  for(int i=1; i<18; ++i){
    for(int j=1; j<(h*w-kai(i-1)*d); ++j){
      dig[i][j] = dig[i-1][j] + dig[i-1][j+kai(i-1)*d];
    }
  }
  //cout << dig[0][4] << endl;
  int q;
  cin >> q;
  for(int i=0; i<q; ++i){
    int l, r;
    cin >> l >> r;
    int dis = (r-l)/d;
    int i2 = 0;
    int ans = 0;
    while(dis > 0){
      if(dis % 2){
        //cout << i2 << " " << l << " " << dig[i2][l] << endl;
        ans += dig[i2][l];
        l += kai(i2)*d;
      }
      dis /= 2;
      ++i2;
    }
    cout << ans << endl;
  }
}

