	void abc075d()
	{
		cin >> N >> K;
		vector<pair<int, int>> pos(N);
		REP(i, N) cin >> pos[i].first >> pos[i].second;

		ll ans = INT64_MAX;
		REP(i, N) {
			REP(j, N) {
				pair<int, int> p1 = pos[i], p2 = pos[j];
				int cnt = 0;
				REP(k, N) {
					int x = pos[k].first, y = pos[k].second;
					if (k == i or k == j)
						cnt++;
					else {
						bool ox = false, oy = false;
						if (p1.first <= p2.first) {
							if (p1.first <= x and
								x <= p2.first)
								ox = true;
						}
						else {
							if (p2.first <= x and
								x <= p1.first)
								ox = true;
						}
						if (p1.second <= p2.second) {
							if (p1.second <= y and
								y <= p2.second)
								oy = true;
						}
						else {
							if (p2.second <= y and
								y <= p1.second)
								oy = true;
						}
						if (ox and oy) cnt++;
					}
				}
