int cal_magic(int num, int *a)
{
	int from_i = 0, from_j = 0;
	int to_i = 0, to_j = 0;

	FOR(i, 0, H-1){
		FOR(j, 0, W-1){
			if(a[i*W_MAX+j] == num){
				from_i = i;
				from_j = j;
				goto FROM_FOUND;
			}
		}
	}

printf("AAAA impossible 1\n");
FROM_FOUND:
	FOR(i, 0, H-1){
		FOR(j, 0, W-1){
			if(a[i*W_MAX+j] == num + D){
				to_i = i;
				to_j = j;
				goto TO_FOUND;
			}
		}
	}
printf("AAAA impossible 2\n");

TO_FOUND:

	return abs(to_i-from_i) + abs(to_j-from_j);
}

void find_answer(int l, int r, int *a, int index)
{
	int magic = 0;
	int n = 0;

	if(r==l) goto SAME_POS;

	// L + n*d全部あることを確認
	if(is_num_in_A(l+n*D, a) == 0) goto CHECK_ERROR;

	do{
		n++;
		if(is_num_in_A(l+n*D, a) == 0) goto CHECK_ERROR;
	}while((l+n*D)!=r);

	//計算
	n = 0;
	while(l+n*D!=r){
		magic += cal_magic(l+n*D, a);
		n++;
	};

	ans_buf[index] = magic;
	return;

CHECK_ERROR:
SAME_POS:
	ans_buf[index] = 0;
	return;
}

