        for (int x = 0; x < w; x++) {
            int num;
            assert(scanf("%d", &num) == 1);
            num2x[num] = x;
            num2y[num] = y;
        }
    }

    vector<vector<unsigned int> > cumpower(d+1);
    for (int rem = 1; rem <= d; rem++) {
        unsigned int power = 0;
        cumpower[rem].push_back(0);
        for (int i = rem; i <= h * w - d; i += d) {
            int x1 = num2x[i], y1 = num2y[i];
            int x2 = num2x[i + d], y2 = num2y[i + d];
            power += abs(x2 - x1) + abs(y2 - y1);
            cumpower[rem].push_back(power);
        }
    }

    int q;
    assert(scanf("%d", &q) == 1);
    unsigned int *ans = new unsigned int[q];
    for (int i = 0; i < q; i++) {
        unsigned int power = 0;
        int start, end;
        assert(scanf("%d %d", &start, &end) == 2);
        int rem = (start - 1) % d + 1;
        power = cumpower[rem][(end - 1) / d] -
            cumpower[rem][(start - 1) / d];
        ans[i] = power;
    }
    for (int i = 0; i < q; i++)
        printf("%u\n", ans[i]);
}

