#define REP(i, n) for (int i = 0; i < (n); i++)
#define RREP(i, n) for (int i = (n) - 1; i >= 0; i--)
#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define RFOR(i, a, b) for (int i = (a); i > (b); i--)
#define ALL(a) (a).begin(), (a).end()

int H, W, D, A[300][300];
int Q, L, R;
map<int, pii> A_i;
int cost[300][300];

void solve() {
    int sum = 0;
    for (int i = R - D; i >= L; i -= D) {
        pii p_now = A_i[i];
        pii p_before = A_i[i + D];

        if (cost[p_now.first][p_now.second] > 0) {
            sum = cost[p_now.first][p_now.second];
            break;
        }
        sum += abs(p_now.first - p_before.first) + abs(p_now.second - p_before.second);
        cost[p_now.first][p_now.second] = sum;
    }
    cout << sum << endl;
}

int main() {
    cin >> H >> W >> D;
    REP(i, H) REP(j, W) {
        cin >> A[i][j];
        A_i[A[i][j]] = {i, j};
    }
    cin >> Q;
    REP(i, Q) {
        cin >> L >> R;
        solve();
    }
    return 0;
}

