int num_to_index(int num) {
	return num - 1;
}

pair<int, int> index_to_point(int index, int w) {
	return { (index / w) + 1, (index % w) + 1 };
}

int main()
{
	int h, w, d;
	cin >> h >> w >> d;

	vector<int> map(h * w);
	for (int i = 0; i < h * w; i++) {
		int a;
		cin >> a;
		map[num_to_index(a)] = i;
	}

	vector<int> precomputed_maryoku(h * w);
	for (int current_index = 0; current_index + d < h * w; current_index++) {
		int next_index = current_index + d;
		auto current_point = index_to_point(map[current_index], w);
		auto next_point = index_to_point(map[next_index], w);
		precomputed_maryoku[current_index] = abs(current_point.first - next_point.first) + abs(current_point.second - next_point.second);
	}

	int q;
	cin >> q;

	for (int i = 0; i < q; i++) {
		int current_num, r;
		cin >> current_num >> r;

		uint64_t maryoku = 0;
		while (current_num != r) {
			maryoku += precomputed_maryoku[num_to_index(current_num)];
			current_num += d;
		}

		cout << maryoku << endl;
	}

	return 0;
}

