int main() {
    int H, W, D;
    cin >> H >> W >> D;

    int Y[300 * 300];
    int X[300 * 300];
    int tmp;

    for (int h = 0; h < H; h++) {
        for (int w = 0; w < W; w++) {
            cin >> tmp;
            Y[tmp - 1] = h + 1;
            X[tmp - 1] = w + 1;
        }
    }

    int Q, L, R;
    cin >> Q;

    int **C = new int*[D];
    for (int i = 0; i < D; i++)
        C[i] = new int[H * W / D]();

    for (int q = 0; q < Q; q++) {
        cin >> L >> R;

        if (L == R)
            cout << 0 << endl;
        else {
            int A = (L - 1) % D;
            if (C[A][R - 1] == 0) {
                int cost = 0;
                int B = A;
                int _B;
                while (B < H * W) {
                    _B = B + D;
                    cost += abs(Y[_B] - Y[B]) + abs(X[_B] - X[B]);
                    B = _B;
                    C[A][B] = cost;
                }
            }
            cout << C[A][R - 1] - C[A][L - 1] << endl;
        }
    }

    //for (int i = 0; i < D; i++)
    //    delete[] C[i];
    //delete[] C;

    return 0;
}

