template<typename T>
T absi(T x) {
    if (x < static_cast<T>(0)) {
        x *= static_cast<T>(-1);
    }
    return x;
}


struct Pos {
    int i;
    int j;
};

int distanse(const Pos& a, const Pos& b)
{
    return absi(a.i - b.i) + absi(a.j - b.j);
}

int main()
{
    int H, W, D;
    std::cin >> H >> W >> D;

    std::unordered_map<int, Pos> m;

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int a;
            std::cin >> a;
            m[a] = Pos{i, j};
        }
    }

    std::vector<int> dists(H*W+1);

    for (int i = D+1; i <= H*W; ++i) {
        dists[i] = dists[i-D] + distanse(m[i-D], m[i]);
    }

    int Q;
    std::cin >> Q;

    for (int k = 0; k < Q; ++k) {
        // 1 <= l, r <= 300
        int l, r;
        std::cin >> l >> r;

        auto d = dists[r] - dists[l];
        std::cout << d << std::endl;
    }

    return 0;
}

