Int dist(Int x, Int r){
    if (x == r){
        return 0;
    }
    auto _ = P(x, r);
    if (memo.find(_) != end(memo)){
        return memo[_];
    }

    P px = locs[x];
    P px_ = locs[x+D];

    Int d = abs(px.first - px_.first) + abs(px.second - px_.second);
    Int ret = d + dist(x+D, r);
    memo[_] = ret; 
    return ret;
}

