void input() {
	scanf("%lld%lld%lld", &H, &W, &D);
	rep(i, H) rep(j, W) scanf("%lld", &A[i][j]);
	scanf("%lld", &Q);
	//rep(i, Q) scanf("%lld%lld", L + i, R + i);
}


void solve() {
	vector<pair<ll,ll>> m(H*W+1);
	rep(i, H) rep(j, W) {
		m[A[i][j]]=make_pair(i,j);
	}
	debug(m);
	//ll rui[HW_MAX][H*W+1];
	vector<ll> rui(H*W+1,0);
	repeq(l,D){
		ll i=l;
