#include <bits/stdc++.h>
using namespace std;

vector<pair<int, int>> coords;
vector<vector<int>> prefix_sum;

int manhattan(pair<int, int> a, pair<int, int> b){
	return abs(a.first - b.first) + abs(a.second - b.second);
}

int crank(int label, int D){
	return (label - label % D) / D;
}

int main(){
	int H, W, D;
	cin >> H >> W >> D;
	coords.resize(H * W + 3);
	prefix_sum.assign(D + 1, vector<int>());
	int n;
	for (int i = 0; i < H; ++i){
		for (int j = 0; j < W; ++j){
			cin >> n;
			n--;
			coords[n] = {i, j};
		}
	}

	for (int i = 0; i < D; ++i){
		prefix_sum[i].push_back(0);
		for (int j = i + D; j < H * W; j+=D){
			int next_dist = manhattan(coords[j - D], coords[j]);
			prefix_sum[i].push_back(prefix_sum[i].back() + next_dist);
		}
	}
	int q; cin >> q;
	int L, R;
	while(q--){
		cin >> L >> R;
		L--; R--;
		int modulo = L % D;
		vector<int>& psum = prefix_sum[modulo];
		cout << psum[crank(R, D)] - psum[crank(L, D)] << endl;
	}
}

