using namespace std;

class Pair {
private:
public:
	int x = 0;
	int y = 0;

	Pair(){	}

	Pair(int paramX, int paramY){
		x = paramX;
		y = paramY;
	}

	int dist(Pair p){
		return abs(x-p.x) + abs(y-p.y);
	}

	inline int abs(int i){
		return i > 0 ? i : -i;
	}
};

int main(){
	int H, W, D, tmp;
	cin >> H >> W >> D;

	std::vector<Pair> a(H*W+1);
	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			cin >> tmp;
			a[tmp] = Pair(i, j);
		}
	}


	int Q, L, R, cost;
	Pair now, next;
	cin >> Q;

	for(int i = 0; i < Q; i++){
		cost = 0;
		cin >> L >> R;

		if(L != R){
			now = a[L];

			for(;;){
				L += D;
				next = a[L];
				int d = now.dist(next);
				cost += d;
				if(L == R) break;
				now = next;
			}
		}

		cout << cost << endl;

	}

	return 0;
}

