long long int absl(long long int i) {
  if(i<0) {
    return -i;
  } else {
    return i;
  }
}

int main() {
  long long int h,w,d,q,i,j;
  scanf("%lld %lld %lld",&h,&w,&d);
  long long int a;
  long long int ilist[h*w],jlist[h*w];
  long long int preans[h*w][h*w];
  for(i=0;i<h*w;i++) {
    for(j=i;j<h*w;j++) {
      preans[i][j] = -1;
    }
  }
  for(i=0;i<h;i++) {
    for(j=0;j<w;j++) {
      scanf("%lld",&a);
      ilist[a-1] = i;
      jlist[a-1] = j;
    }
  }
  scanf("%lld",&q);
  long long int l[q];
  long long int r[q];
  for(i=0;i<q;i++) {
    scanf("%lld %lld",&l[i],&r[i]);
  }
  for(i=0;i<q;i++) {
    long long int ans = 0;
    if (preans[l[i]-1][r[i]-1]>0) {
      ans = preans[l[i]-1][r[i]-1];
    } else {
    long long int temp = l[i];
    while(temp<r[i]) {
      ans += absl(ilist[temp-1]-ilist[temp+d-1])+absl(jlist[temp-1]-jlist[temp+d-1]);
      temp = temp+d;
    }
    preans[l[i]-1][r[i]-1] = ans;
  }
  printf("%lld\n",ans);
}
  return 0;
}

