int main(int argc, char* argv[]) {
  long long H;
  scanf("%lld", &H);
  long long W;
  scanf("%lld", &W);
  long long D;
  scanf("%lld", &D);
  std::vector<std::vector<long long>> A(H, std::vector<long long>(W));
  map<ll, ll_ll> m;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      scanf("%lld", &A[i][j]);
      m[A[i][j]] = {i, j};
    }
  }
  long long Q;
  scanf("%lld", &Q);
  std::vector<long long> L(Q);
  std::vector<long long> R(Q);
  for (int i = 0; i < Q; i++) {
    scanf("%lld", &L[i]);
    scanf("%lld", &R[i]);
  }

  vector<ll> dists(H * W + 1, 0LL);
  rep(i, 1, D + 1) {
    ll d = 0;
    ll_ll p = m[i];
    for (int s = i + D; s < H * W + 1; s += D) {
      ll_ll next_pos = m[s];
      d += abs(p.first - next_pos.first) + abs(p.second - next_pos.second);
      p = next_pos;
      dists[s] = d;
    }
  }

  rep(i, 0, Q) { put(dists[R[i]] - dists[L[i]]); }
  return 0;
}

