long long int f(const vector<vector<int>>& v1, const vector<pair<int, int>> v2, vector<vector<long long int>>& v3, int l, int r) {
    if (l == r) return 0;
    if (v3[l][r] != -1) return v3[l][r];
    if (l + d == r) {
        return abs(v2[r].first - v2[l].first) + abs(v2[r].second - v2[l].second);
    }
    int m = l + (r - l) / d / 2 * d;
    long long int res = f(v1, v2, v3, l, m) + f(v1, v2, v3, m, r);
    v3[l][r] = res;
    return res;
}

