int H, W, D;
int dp[500][500];
int r[100000];
int c[100000];

int calc(int x, int y)
{
  return abs(r[x] - r[y]) + abs(c[x] - c[y]);
}

int dfs(int x, int y)
{
  int& res = dp[x][y];
  return res = dp[x+D][y] + calc(x, x+D);
}

void init()
{
  cin >> H >> W >> D;
  rep(i, H) {
    rep(j, W) {
      int t;
      cin >> t;
      r[t] = i;
      c[t] = j;
    }
  }
  rreps(i, H*W+1, 1) {
    for (int j = i-D; j >= 0; j-=D) {
      dfs(j, i);
    }
  }
}

