int main()
{
  int64_t H, W, D, Q, a, l, r;
  cin >> H >> W >> D;
  map<int, pair<int, int>> mp;
  for (int i = 1; i <= H; i++)
  {
    for (int j = 1; j <= W; j++)
    {
      cin >> a;
      mp[a] = make_pair(i, j);
    }
  }
  cin >> Q;
  vector<pair<int64_t, int64_t>> lr(Q);
  for (int i = 0; i < Q; i++)
  {
    cin >> l >> r;
    lr.at(i) = make_pair(l, r);
  }
  map<pair<int, int>, int> dp;
  for (int i = 0; i < Q; i++)
  {
    int64_t s = 0;
    tie(l, r) = lr.at(i);
    int init = l;
    while (l != r)
    {
      if (dp.count(make_pair(l, r)) == 0)
      {
        int x = abs(mp.at(l).first - mp.at(l + D).first) + abs(mp.at(l).second - mp.at(l + D).second);
        s += x;
        dp[make_pair(l, r)] = x;
      }
      else
      {
        s += dp.at(make_pair(l, r));
      }
