        while(n <= h*w) {
            ll x, y, nx, ny; // 前のx,y 次のx,y
            x = m[n].first;
            y = m[n].second;
            nx = m[n+d].first;
            ny = m[n+d].second;
            ll dist = my_abs(x-nx) + my_abs(y-ny);
            s += dist;
            sum[i].push_back(s); // 累積
            n += d;
        }
    }

    ll q; cin >> q;
