  exrep(i,1,h*w-d){
    int y=mp[i].first,x=mp[i].second;
    int ny=mp[i+d].first,nx=mp[i+d].second;
    tree.merge(i,i+d,abs(y-ny)+abs(x-nx));
  }
  int q;
  cin >> q;
  rep(i,q){
    int l,r;
    cin >> l >> r;
    cout << tree.diff(l,r) << endl;
  }



  return 0;     
}

