using namespace std;

int main()
{
	int H, W, D;
	cin >> H >> W >> D;

	vector<pair<int, int>> v(H * W);
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < W; ++j) {
			int A;
			cin >> A;
			v[A - 1] = make_pair(i, j);
		}
	}

	auto mp = [&](int x, int y) {
		return abs(v[x].first - v[y].first) + abs(v[x].second - v[y].second);
	};

	vector<vector<int>> ans(D, vector<int>((H * W + D - 1) / D));

	for (int s = 0; s < D; ++s) {
		ans[s][s] = 0;
		for (int x = 1; s + D * x < H * W; ++x) {
			ans[s][x] = ans[s][x - 1] + mp(s + D * x - D,  s + D * x);
		}
	}

	int Q;
	cin >> Q;
	for (int i = 0; i < Q; ++i) {
		int L, R;
		cin >> L >> R;
		--L;
		--R;
		int s = L % D;
		cout << ans[s][(R - s) / D] - ans[s][(L - s) / D] << endl;
	}
}

