int H, W, D, Q;
unordered_map<int, pair<int, int>> valueToPosDict;
int dists[90010];

int Calc(int A) {
  if (dists[A] >= 0) return dists[A];

  dists[A] = 0;
  for (int v = A % D; v < A; v += D) {
    const auto& nextPos = valueToPosDict[v + D];
    const auto& currentPos = valueToPosDict[v];
    dists[A] += abs(nextPos.first - currentPos.first) +
                abs(nextPos.second - currentPos.second);
  }
  return dists[A];
}

