void solve(long long H, long long W, long long D, std::vector<std::vector<long long>> A, long long Q, std::vector<long long> L, std::vector<long long> R){
  vector<pair<ll, ll>> m(H*W+1);
  vector<ll> f(H*W+1);
  for(ll i=0; i<H; i++) {
    for(ll j=0; j<W; j++) {
      m[A[i][j]] = make_pair(i, j);
    }
  }
  for(ll i=1; i<=D; i++) {
    for(ll j=1; j*D+i<=H*W; j++) {
      ll now = j*D+i;
      ll prev = (j-1)*D+i;
      f[now] = f[prev]+abs(m[prev].first-m[now].first)+abs(m[prev].second-m[now].second);
    }
  }
  for(ll i=0; i<Q; i++) {
    std::cout << f[R[i]]-f[L[i]] << std::endl;
  }
}

