void dfs(const int src)
{
    stack<int> S;
    S.push(src);
    while (S.size()) {
        const int u = S.top(); S.pop();
        const int v = u+d;
        if (v < maxn) {
            const int w = abs(x[u]-x[v]) + abs(y[u]-y[v]);
            const int cost = dist[u]+w;
            if (cost < dist[v]) {
                dist[v] = cost;
                S.push(v);
            }
        }
        const PII k = PII(src,u);
        if (in_(k,ans))
            ans[k] = min(ans[k],dist[u]);

    }
}

