            sumInter[origL][L] = sum;

            if (sumInter[L][R] != 0) {
                sum = sumInter[L][R];
                break;
            }

            findsq(L+D, i, j);
            sum += magic(previ, prevj, i, j);
            sumInter[L][R] = sum;
            previ=i; prevj=j;
        }

        cout << sum << endl;
    }

    return 0;
}

