typedef long long ll;

int getDist(int toX, int toY, int fromX, int fromY) {
	return abs(toX - fromX) + abs(toY - fromY);
}

int main() {

	int h, w, d; cin >> h >> w >> d;
	int u = h * w;
	vector<pair<int, int>> coordinate(u + 1);
	for (int i = 1; i <= h; i++) {
		for (int j = 1; j <= w; j++) {
			int a; cin >> a;
			coordinate[a] = { i,j };
		}
	}
	vector<vector<int>> c(u + 2, vector<int>(u + 2, 0));
	for (int i = 1; i <= u; i++) {
		for (int j = 1; j <= u; j++) {
			if (i == j) continue;
			int toX = coordinate[j].first;
			int toY = coordinate[j].second;
			int fromX = coordinate[i].first;
			int fromY = coordinate[i].second;
			c[i][j] = getDist(toX, toY, fromX, fromY);
		}
	}
	int q; cin >> q;
	for (int i = 0; i < q; i++) {
		int l, r; cin >> l >> r;
		int ans = 0;
		if (l == r) {}
		else {
			int prev = l;
			int now = prev + d;
			while (now != r + d) {				
				ans += c[prev][now];
				prev = now;
				now = prev + d;
			}
		}
		cout << ans << endl;
	}
	return 0;
}

