unordered_map<int, pair<int, int>> um;
unordered_map<ll, int> mem;
vector<int> ans;

int rec(int l, int r) {
	if (l == r) return 0;

	ll p = l*1000000+r, t;
	if (mem.find(p) != mem.end()) 
		return mem[p];

	t=abs(um[l].first - um[l + d].first) + abs(um[l].second - um[l + d].second);
	if (l + d != r) t += rec(l + d, r);

	mem.emplace(p, t);

	return t;
}


int main()
{
	cin >> h >> w >> d;
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w ;j++) {
