		}	
	}

	cin >> q;
	for (int i = 0; i < q; i++) {
		int l, r, t=0;
		cin >> l >> r;
		t = rec(l, r);

		ans.push_back(t);
	}

	for (auto it = ans.begin(); it != ans.end(); it++)
		cout << *it << endl;


	return 0;
}

