ll H,W,D;
ll table[310][310];
ll d[10000];
pair<ll,ll> MP[10000];

void dijkstra(ll s){
    priority_queue<pair<ll,ll>> Q;
    d[s] = 0;
    Q.emplace(0,s);
    while(Q.size()){
        ll x = Q.top().second;
        Q.pop();
        if(d[x+D] != INF) continue;
        ll cost = d[x+D] = d[x] + abs(MP[x+D].first - MP[x].first) + abs(MP[x+D].second - MP[x].second);
        Q.emplace(-cost,x+D);
    }
}

