    rep(i,H) rep(j,W){
        cin >> table[i][j];
        MP[table[i][j]].first = i;
        MP[table[i][j]].second = j;
    }
    fill(d,d+10000,INF);
    rep(i,D){
        dijkstra(i+1);
    }
    ll Q;cin >> Q;
    vector<ll> ans(Q);
    rep(i,Q){
        ll L,R;cin >> L >> R;
        ans[i] = d[R]-d[L];
    }
    rep(i,Q) cout << ans[i] << endl;
}

