struct Square
{
    int x, y;
    int cost;

    int Points(const Square &other) const
    {
        return abs(x - other.x) + abs(y - other.y);
    }
};

int main()
{
    int rows, cols, step;
    cin >> rows >> cols >> step;

    vector<Square> squares(rows * cols);
    for (int i = 0; i < rows; i += 1) {
        for (int j = 0; j < cols; j += 1) {
            int num;
            cin >> num;
            squares[num - 1] = Square { .x = i, .y = j };
        }
    }

    for (int i = 0; i < rows * cols; i += 1) {
        if (i < step) {
            squares[i].cost = 0;
        } else {
            int points = squares[i].Points(squares[i - step]);
            squares[i].cost = squares[i - step].cost + points;
        }
    }

    int tests;
