Int dist(Int x, Int r){
    if (x == r){
        return 0;
    }
    if (memo[x][r] != 0){
        return memo[x][r];
    }

    P px = locs[x];
    P px_ = locs[x+D];

    Int d = abs(px.first - px_.first) + abs(px.second - px_.second);
    Int ret = d + dist(x+D, r);
    memo[x][r] = ret; 
    return ret;
}

