template <class T> inline T abs(const T& a) { return (a < 0) ? -a : a; }

int main() {
  int H, W, D;
  cin >> H >> W >> D;
  map<int, Pos> as;
  {
    int a;
    for(int h = 1; h <= H; ++h) {
      for(int w = 1; w <= W; ++w) {
        cin >> a;
        as[a] = Pos(h, w);
      }
    }
  }
  int Q;
  cin >> Q;
  vector<pair<int, int>> qs(Q);
  for(int i = 0; i < Q; ++i) {
    cin >> qs[i].first >> qs[i].second;
  }

  for(auto q : qs) {
    ll ans = 0;
    int crnt = q.first;
    int end = q.second;
    while(crnt != end) {
      auto next = crnt + D;
      // cout << crnt << " -> " << next << endl;
      auto a1 = as[crnt];
      auto a2 = as[next];
      ans += abs(a2.first - a1.first) + abs(a2.second - a1.second);
      crnt = next;
    }
    cout << ans << endl;
  }

  return 0;
}

