using namespace std;

int main(){
	int H, W , D;
	scanf("%d %d %d",&H,&W,&D);
	int max_q = (H*W)/D+1;
	vector<vector<vector<int> > > vv(D, vector<vector<int> >( max_q, vector<int>(2)));
	for(int i = 0; i< W; i++){
		for(int j = 0; j < H ; j++){
		int temp;
		scanf("%d", &temp);		
		vv[temp %D][temp/D][0] = i;
		vv[temp %D][temp/D][1] = j;
		}
	}
	vector<vector<int> > sum(D, vector<int>(max_q));
	for (int i = 0; i< D; i++){
		for (int j = 0; j < max_q;j++){
			if (j != 0 & ( 1 <=i + D * j <= H *W) & !(i == 0 & j == 1)){
				int x  =abs(vv[i][j][0] -vv[i][j-1][0]);
				int y = abs(vv[i][j][1] -vv[i][j-1][1]);
			 	sum[i][j] += x + y+   sum[i][j-1];
			}
			else if (i == 0 & j == 1) sum[i][j] = 0;
			else sum[i][j] = 0;
		}
	}
	int Q;
	scanf("%d",&Q);
	for (int i = 0 ; i <Q; i++){
		int R,L;
		scanf("%d %d",&L,&R);
		int ans = sum[R%D][R/D] - sum[R%D][L/D]; 
		printf("%d\n",ans);
	}	
	return 0;
}

