vector<LL> ans;

void solve(){
	//i(1<=i<=D)と書かれたマスからjと書かれたマスに移動するのに必要なコストをcost[i][j]とおく
	vector<vector<LL>> cost(D+1,vector<LL>(H*W+1,-1));
	for(int i=1;i<=D && i<=H*W;i++) cost[i][i] = 0;

	for(int start=1;start<=D && start<=H*W;start++){
		for(int end=start+D;end<=H*W;end+=D){
			//cout << start << " " << end << endl;
			LL i = A[end-D].second;
			LL j = A[end-D].first;
			LL x = A[end].second;
			LL y = A[end].first;
			cost[start][end] = cost[start][end-D] + abs(x-i) + abs(y-j);
		}
	}

	for(int i=0;i<Q;i++){
		LL start = LR[i].first%D;
		if(start==0) start = D;
		//cout << LR[i].first << " " << LR[i].second << " start=" << start << endl;
		ans.push_back(cost[start][LR[i].second] - cost[start][LR[i].first]);
	}
}

