int main() {
	int H, W, D;
	cin >> H >> W >> D;
	vector<vector<int>> A(H, vector<int>(W));

	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			cin >> A[i][j];
		}
	}

	int Q;
	cin >> Q;
	vector<int> L(Q), R(Q);

	for (int i = 0; i < Q; i++) {
		cin >> L[i] >> R[i];
	}

	for (int i = 0; i < Q; i++) {
		int x = L[i];
		int mp = 0;
		int now_i, now_j;
		int brFlag = 0;

		//初期位置探索
		for (int i = 0; i < H; i++) {
			for (int j = 0; j < W; j++) {
				if (x == A[i][j]) {
					now_i = i;
					now_j = j;
					brFlag = 1;
					break;
				}
			}
			if (brFlag == 1) {
				break;
			}
		}

		while (x != R[i]) {
			brFlag = 0;
			for (int i = 0; i < H; i++) {
				for (int j = 0; j < W; j++) {
					if (A[i][j] == x+D) {
						mp += abs(i - now_i) + abs(j - now_j);
						now_i = i;
						now_j = j;
						brFlag = 1;
						x += D;
						break;
					}
				}
				if (brFlag == 1) {
					break;
				}
			}
		}

		cout << mp << endl;
	}

	return 0;
}

