long long siki(int l, int r){
    if(l == r) return m[P(l, r)] = 0;
    if(m.count(P(l, r))) return m[P(l, r)];
    P v = place[l], u = place[l + D];
    return m[P(l, r)] = abs(v.first - u.first) + abs(v.second - u.second) + siki(l + D, r);
