const int MAXN = 307 * 307;

int H, W, D;
int X[MAXN], Y[MAXN];

vector<int> pref[MAXN];
int sz[MAXN];

void solve() {
	cin >> H >> W >> D;

	for(int i = 0; i < H; ++i) {
		for(int j = 0; j < W; ++j) {
			int val = fetch<int>() - 1;

			X[val] = i;
			Y[val] = j;
		}
	}

	for(int rem = 0; rem < D; ++rem) {
		for(int i = rem; i < H * W; i += D) {
			++sz[rem];
		}

		pref[rem].resize(sz[rem], 0);

		for(int i = rem; i < H * W; i += D) {
			int j = (i - rem) / D;

			if(j == 0) {
				continue;
			}

			pref[rem][j] = pref[rem][j - 1] + abs(X[i] - X[i - D]) + abs(Y[i] - Y[i - D]);
		}

#ifdef __LOCAL
		cout << "@rem=" << rem << '\n';
		cout << "@pref=";

		for(int i = 0; i < sz[rem]; ++i) {
			cout << pref[rem][i] << ' ';
		}

		cout << '\n';
#endif
	}

	int q = fetch<int>();

	while(q--) {
		int L = fetch<int>() - 1;
		int R = fetch<int>() - 1;

		int rem = L % D;
		L -= rem, R -= rem;
		L /= D, R /= D;

		if(L <= R) {
			cout << pref[rem][R] - pref[rem][L] << '\n';
		} else {
			cout << pref[rem][sz[rem] - 1] - pref[rem][R] + pref[rem][L] << '\n';
		}
	}
}

int main() {
	fast_io();
	solve();

	return 0;
}

