pair<int,int> find_integer(vector<vector<int> > &A, int k){
    for(int i=0;i<A.size();i++){
        for(int j=0;j<A[i].size();j++){
            if(k == A[i][j]){
                return make_pair(i,j);
            }
        }
    }
    return make_pair(-1,-1);
}

int main(){
    int H,W,D; cin >> H >> W >> D;
    vector<vector<int> > A(H, vector<int>(W));

    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            cin >> A[i][j];
        }
    }

    vector<vector<int> > route(D, vector<int>(H*W+1,0));
    for(int k=0;k<D;k++){
        int now = k;
        int x,y;
        tie(x,y) = find_integer(A, now);

        while(now+D <= H*W){
            int nx,ny;
            tie(nx,ny) = find_integer(A,now+D);
            route[k][now+D] = route[k][now] + abs(nx - x) + abs(ny - y);
            now += D;
            x = nx; y = ny;
        }
    }

    int Q; cin >> Q;
    for(int i=0;i<Q;i++){
        int L,R; cin >> L >> R;
        cout << route[L%D][R] - route[L%D][L] << endl;
    }

    return 0;
}

