struct Point {
    int y, x;
};
int kyori(Point a, Point b) {
    return abs(a.x - b.x) + abs(a.y - b.y);
}
int main() {

    int h, w, d;
    cin >> h >> w >> d;

    map<int, Point> mp;
    int tmp;
    REP(i, h) {
        REP(j, w) {
            cin >> tmp;
            mp[tmp] = {(int)i, (int)j};
        }
    }
    vector<vector<int>> grid(d, vector<int>((h * 2 + 3 * d - 1) / d, 0ll));
    for(auto x : mp) {
        grid[x.first % d][x.first / d] = kyori(mp[x.first], mp[x.first + d]);

        if(x.first == h * w - d) {
            break;
        }
    }
    mp.clear();
    vector<vector<int>> sum(d, vector<int>((h * 2 + 4 * d - 1) / d, 0ll));
    REP(i, d) {
        REP(j, (h * 2 + 2 * d - 1) / d) {
            sum[i][j + 1] = sum[i][j] + grid[i][j];
        }  
    }
    grid.clear();
    int q;
    cin >> q;
    int a, b;
    REP(i,q){
        scanf("%d %d", &a,&b);
        cout << sum[b % d][b / d] - sum[a % d][a / d] << endl;
    //    cout << "unko" << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int H,W,D;
vector<pair<int,pair<int,int>>> placement{};
int Q;
int cost[90010]={};

int main(){
  //input
  cin >> H >> W >> D;
  for(int i=0; i<H; i++){
    for(int j=0; j<W; j++){
      int x; cin >> x;
      placement.push_back(make_pair(x,make_pair(i,j)));
    }
  }

  //preprocess
  sort(placement.begin(),placement.end());
  for(int i=1; i<=D; i++){
    int k=i;
    cost[k]=0;
    while(k+D<=H*W){
      cost[k+D]
        +=(cost[k]
           +abs(placement[k+D-1].second.first-placement[k-1].second.first)
           +abs(placement[k+D-1].second.second-placement[k-1].second.second));
      k+=D;
    }
  }

  //query
  cin >> Q;
  for(int i=0; i<Q; i++){
    int L,R; cin >> L >> R;
    cout << cost[R]-cost[L] << endl;
  }
}

// AtCoder Beginner Contest 089 - Problem D: Practical Skill Test (https://atcoder.jp/contests/abc089/tasks/abc089_d)
#include <bits/stdc++.h>

using namespace std;
using ii = pair<int, int>;

const int MAX { 310 };

vector<ii> as(MAX*MAX);

vector<int> solve(int H, int W, int D, const vector<ii>& qs)
{
    vector<vector<int>> ps(D + 1);

    for (int x = 1; x <= D; ++x)
    {
        ps[x].push_back(0);
//cout << "-- x = " << x << " (" << as[x].first << ", " << as[x].second << ")" << endl;
        for (int y = x + D; y <= H*W; y += D)  
        {
            int dist = abs(as[y - D].first - as[y].first) + abs(as[y - D].second - as[y].second);
            ps[x].push_back(dist + ps[x].back());
//cout << "y = " << y << " (" << as[y].first << ", " << as[y].second << "), d = " << dist << ", ps = " << ps[x].back() << endl;
        }
    }

    vector<int> ans;

    for (auto q : qs)
    {
        auto L = q.first, R = q.second;

        auto r = (L % D) == 0 ? D : L % D;
        auto a = (L - r) / D, b = (R - r) / D;
        auto sum = ps[r][b] - ps[r][a];
        ans.push_back(sum);
//cout << "L = " << L << ", R = " << R << ", r = " << r << ", a = " << a << ", b = " << b << endl;
    }

    return ans;
}

int main()
{
    ios::sync_with_stdio(false);

    int H, W, D;
    cin >> H >> W >> D;    

    for (int i = 1; i <= H; ++i)
        for (int j = 1; j <= W; ++j)
        {
            int a;
            cin >> a;

            as[a] = ii(i, j);
        }

    int Q;
    cin >> Q;

    vector<ii> qs(Q);

    for (int i = 0; i < Q; ++i)
        cin >> qs[i].first >> qs[i].second;

    auto ans = solve(H, W, D, qs);

    for (auto x : ans)
        cout << x << endl;

    return 0;
}

