using namespace std;

int d;
vector<complex<int> > p;
map<pair<int, int>, long long> dp;

void hawawa()
{
  int h, w;
  cin >> h >> w >> d;
  p.resize(h * w + 1);
  for (int i = 0; i < h; i++) {
    for (int j = 0;j < w; j++) {
      int num;
      cin >> num;
      p[num] = complex<int>(i, j);
    }
  }
  int q;
  cin >> q;
  for (int i = 1; i <= h * w; i++) {
    dp[make_pair(i, i)] = 0;
    for (int j = 1; i + d * j <= h * w; j++) {
      auto status = make_pair(i, j);
      auto status2 = make_pair(i, i + (j - 1)* d);
      dp[status] = dp[status2] + abs(p[j - d].real() - p[j].real()) + abs(p[j - d].imag() - p[j].imag());
    }
  }
  while (q--) {
    int l, r;
    cin >> l >> r;
    cout << dp[make_pair(l, (r - l) / d)] << "\n";
  }
}

int main()
{
  ios::sync_with_stdio(false);
  cin.tie(0);
  hawawa();
  return 0;
}

