void addTree(int ii, int jj, int vv)
{
	int j = jj+n2;
	while(j>=1){
		Tree[ii][j] += vv;
		j /= 2;
	}
}

void pre()
{
	int i, j;
	n = (W*H-1)/D+1;
	n2 = 1;
	while(n2<n)
		n2 *= 2;
	for(j=0; j<n2; j++){
		///Left[j] = Right[j] = j;
		Left[n2+j] = Right[n2+j] = j;
	}
	for(j=n2-1; j>=1; j--){
		Left[j] = Left[2*j];
		Right[j] = Right[2*j+1];
	}
	for(i=0; i<50; i++){
		for(j=0; j<n2-2; j++){
			addTree(i, j, abs(x[j*D+i]-x[(j+1)*D+i])+abs(y[j*D+i]-y[(j+1)*D+i]));
		}
		if((j+1)*D+i <= W*H)
			addTree(i, j, abs(x[j*D+i]-x[(j+1)*D+i])+abs(y[j*D+i]-y[(j+1)*D+i]));
	}
}

int srch(int ii, int nd, int ll, int rr)
{
	if(Left[nd]>=ll && Right[nd]<=rr)
		return Tree[ii][nd];
	if(Left[nd]>rr || Right[nd]<ll)
		return 0;
	return srch(ii, 2*nd, ll, rr) + srch(ii, 2*nd+1, ll, rr);
}

