int getScore(int a, int b)
{
	if (!b) return 0;
	if (dp.count(make_pair(a, b))) return dp[make_pair(a, b)];
	if (b == 1) {
		return dp[make_pair(a, b)] = abs(p[a].real() - p[a + d].real()) + abs(p[a].imag() - p[a + d].imag());
	}
	int num = b / 2;
	return dp[make_pair(a, b)] = getScore(a, num) + getScore(a + num * d, b - num);
}

