struct Point {
    int y, x;
};
int kyori(Point a, Point b) {
    return abs(a.x - b.x) + abs(a.y - b.y);
}
int main() {

    int h, w, d;
    cin >> h >> w >> d;

    map<int, Point> mp;
    int tmp;
    REP(i, h) {
        REP(j, w) {
            cin >> tmp;
            mp[tmp] = {(int)i, (int)j};
        }
    }
    vector<vector<int>> grid(d, vector<int>((h * 2 + 3 * d - 1) / d, 0ll));
    for(auto x : mp) {
        grid[x.first % d][x.first / d] = kyori(mp[x.first], mp[x.first + d]);

        if(x.first == h * w - d) {
            break;
        }
    }
    mp.clear();
    vector<vector<int>> sum(d, vector<int>((h * 2 + 4 * d - 1) / d, 0ll));
