#define ABS(X) (((X)>0)?(X):-(X))

using namespace std;

int x[90001],y[90001];
int costs[90001][20] = {0};

int dist(int n, int m){
	return ABS(x[n] - x[m]) + ABS(y[n] - y[m]);
}

int main(){
	int h, w, d;
	int max = h*w;

	cin >> h >> w >> d;

	for(int i=0; i<h; i++)
		for(int j=0; j<w; j++){
			int a;
			cin >> a;
			y[a] = i;
			x[a] = j;
		}

	for(int n=1; n<=max; n++){
		if(n+d > max)
			costs[n][1] = -1;
		else
			costs[n][1] = dist(n, n+d);
	}

	for(int t=2; t<20; t++){
		for(int n=1; n<=max; n++){
			int next = n + d*(1<<t);
			if(next > max)
				costs[n][t] = -1;
			else
				costs[n][t] = costs[n][t-1] + costs[(n+next)/2][t-1];
		}
	}


	int q;
	cin >> q;

	for(int i=0; i<q; i++){
		int l, r;
		cin >> l >> r;

		int gap = (r - l)/d;
		int ans = 0;

		int doubling = 1;
		for(int t=1; t<20; doubling*=2,t++){
			if(gap & doubling){
				ans += costs[l][t];
				l += d * doubling;
			}
		}

		cout << ans << endl;

	}


	return 0;
}

