int calc_dist(int l) {
    if(l < d) return 0; 
    if(dist[l] != INF) return dist[l];
    int x = a_inv[l].first;
    int y = a_inv[l].second;
    int nx = a_inv[l-d].first;
    int ny = a_inv[l-d].second;
    return dist[l] = calc_dist(l-d) + abs(x-nx) + abs(y-ny);
}
