int jdz(int u,int v){
	if(u>=v) return u-v;
	else return v-u;
}

int main(){
	scanf("%d %d %d",&h,&w,&d);
	for(int i=1;i<=h*w;i++){
		scanf("%d",&z);
		if(b>w){
