using P = pair<int, int>;

int calc(vector<P>& aa, int s, int e, int d, map<P, int>& cost) {
  if (s == e) return 0;
  if (cost[{s, e}] != 0) return cost[{s, e}];
  int ans = 0;
  while (s != e) {
    if (cost[{s, e}] != 0) {
      ans += cost[{s, e}];
      break;
    }
    ans += abs(aa[s].first - aa[s+d].first) + abs(aa[s].second - aa[s+d].second);
    s += d;
  }
  return ans;
}

