//メモリを圧迫する可能性あり

void IsPrime_Contain(ll num){
    IS_PRIME_CONTAINER[0] = false;
    IS_PRIME_CONTAINER[1] = false;
    FOR(i,2,sqrt(num)+1){
        if(IS_PRIME_CONTAINER[i]){
            FOR(j,2,num/i + 1){
                if(j*i<=num){
                    IS_PRIME_CONTAINER[i*j]=false;
                }
            }
        }
    }
}

inline bool IsPrime(ll num){
    return IS_PRIME_CONTAINER[num];
}



