#include <bits/stdc++.h>

using namespace std;

map<pair<int, int>, long long> dp;


int h, w, d;
pair<int, int> score[90000];

long long get(int s, int g) {
	if (s == g) return 0;
	if (g - s == d) return abs(score[s].first - score[g].first) + abs(score[s].second - score[g].second);
	pair<int, int> status = make_pair(s, g);
	if (dp.count(status)) return dp[status];
	int num = (g - s) / d / 2;
	return dp[status] = get(s, s + d * num) + get(s + d * num, g);
}

void hawawa()
{
	cin >> h >> w >> d;
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			int num;
			cin >> num;
			num--;
			score[num] = make_pair(i, j);
		}
	}
	for (int i = 0; i < h * w; i++) {
		dp[make_pair(i, i)] = 0;
		for (int j = i + d; j < h * w; j += d) {
			dp[make_pair(i, j)] = get(i, j);
		}
	}
	int q;
	cin >> q;
	while (q--) {
		int l, r;
		cin >> l >> r;
		l--;
		r--;
		cout << get(l, r) << "\n";
	}
}

