	    lg2[i]=abs(lg[i][0]-lg[i-D][0])+abs(lg[i][1]-lg[i-D][1]);
	}

	for(int i=1;i<=H*W;i++){
	    if(i<=D){
	        lg3[i]=lg2[i];
	    }else{
	        lg3[i]=lg2[i]+lg3[i-D];
	    }
	}

	//cout << Q << endl;
	for(int i=0;i<Q;i++){
	    Ans=0;
	    x=L[i];
	    y=R[i];
	    Ans+=lg3[y]-lg3[x];
	    cout << Ans << endl;
	}
	return 0;
}

