					}
					if ((A[y2][x2] - A[y][x]) % D > 0) {
						continue;
					}
					stringstream ss;
					ss << A[y][x] << "_" << A[y2][x2];
					int dist = abs(y2 - y) + abs(x2 - x);
					memo[ss.str()] = dist;
				}
			}
		}
	}
	for (auto a : memo) {
		cout << a.first << " = " << a.second << endl;
	}

	for (int i = 0; i < Q; ++i) {
		int answer = 0;
		for (int n = L[i]; n < R[i]; n += D) {
			stringstream ss;
			ss << n << "_" << (n + D);
			answer += memo[ss.str()];
		}
		cout << answer << endl;
	}

}

