  for (int i = 1; i <= h * w; i++) {
    dp[make_pair(i, i)] = 0;
    for (int j = i + d; j <= h * w; j += d) {
      auto status = make_pair(i, j);
      auto status2 = make_pair(i, j - d);
      auto status3 = make_pair(j - d, j);
      if (dp.count(status)) continue;
      dp[status3] = abs(p[j - d].real() - p[j].real()) + abs(p[j - d].imag() - p[j].imag());
      dp[status] = dp[status2] + dp[status3];
    }
  }
  while (q--) {
    int l, r;
    cin >> l >> r;
    cout << dp[make_pair(l, r)] << "\n";
  }
}

