int main() {
    int H, W, D; std::cin >> H >> W >> D;
    std::vector<std::vector<int>> a(H, std::vector<int>(W));
    std::vector<std::pair<int, int>> pos(H*W + 2);
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            std::cin >> a[i][j];
            pos[a[i][j]] = { i, j };
        }
    }
    std::vector<std::vector<std::vector<std::pair<int, int>>>>
        p(30, std::vector<std::vector<std::pair<int, int>>>(
            H, std::vector<std::pair<int, int>>(W)));
    std::vector<std::vector<std::vector<int>>>
        q(30, std::vector<std::vector<int>>(H, std::vector<int>(W)));
    auto cost = [](const auto &p, const auto &q) {
        return std::abs(p.first - q.first) + std::abs(p.second - q.second);
    };
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (a[i][j] + D > H*W) continue;
            p[0][i][j] = pos[a[i][j] + D];
            q[0][i][j] = cost(std::make_pair(i, j), p[0][i][j]);
        }
    }
    for (int t = 1; t < 21; t++) {
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (a[i][j] + D*(1LL << t) > H*W) continue;
                p[t][i][j] =
                    p[t - 1][p[t - 1][i][j].first][p[t - 1][i][j].second];
                q[t][i][j] = q[t - 1][i][j] +
                    q[t - 1][p[t - 1][i][j].first][p[t - 1][i][j].second];
            }
        }
    }
    int Q; std::cin >> Q;
    while (Q--) {
        int l, r; std::cin >> l >> r;
        int d = (r - l) / D;
        std::pair<int, int> c = pos[l];
        long long ans = 0;
        for (int t = 0; t < 21; t++) {
            if (~(d >> t) & 1) continue;
            ans += q[t][c.first][c.second];
            c = p[t][c.first][c.second];
        }
        std::cout << ans << std::endl;
    }
    return 0;
}

