int main()
{
    int H, W, D; cin >> H >> W >> D;
    vector<pair<int, int>> rowColPairs(H * W);
    for (int r = 1; r <= H; ++r)
    {
        for (int c = 1; c <= W; ++c)
        {
            int Arc; cin >> Arc;
            rowColPairs[Arc - 1] = { r, c };
        }
    }
    // Dを法とする各集合に対して，必要な魔力を累積和で管理
    // 計算量は累積和計算＋クエリでO(HW+Q)~O(10^5)
    vector<vector<LLONG>> cumSums(D, vector<LLONG>((H * W + D - 1) / D));
    // 1~Dは必要魔力ゼロ
    for (int i = 1; i <= D; ++i)
    {
        cumSums[i % D][0] = 0;
    }
    // 累積和の計算：O(HW)
    for (int i = D + 1; i <= H * W; ++i)
    {
        int x = (i - 1) / D;
        const auto prevPos = rowColPairs[i - D - 1];
        const auto curPos = rowColPairs[i - 1];
        cumSums[i % D][x] = cumSums[i % D][x - 1]
            + abs(prevPos.first - curPos.first)
            + abs(prevPos.second - curPos.second);
    }
    // クエリに答える：O(Q)
    int Q; cin >> Q;
    for (int i = 0; i < Q; ++i)
    {
        int Li, Ri; cin >> Li >> Ri;
        cout << cumSums[Li % D][(Ri - 1) / D]
            - cumSums[Li % D][(Li - 1) / D] << endl;
    }

