void AddCost(uint64_t* totalCost, int D, std::unordered_map<int, std::pair<int, int>>& mapMemo, int l, int r)
{
    static std::unordered_map<int, uint64_t> costMemo;

    const auto searchNum = [](int l, int r) {
        return 1000 * r + l;
    };

    if (l == r) return;

    auto costItr = costMemo.find(searchNum(l, r));
    if (costItr != costMemo.end()) {
        *totalCost = costItr->second;
        return;
    }

    // コストがメモ化されていないので計算する

    // R_i = L_i + nD なので、L, L + D, L + 2D, ... で R になるまでの整数値だけが必要
    // x_j = L_i + jD とする
    // x_j - L_i % D == 0 && x_j >= L_i なら true
    // cost_j = |x_(j + 1) - x_j

    // DP 化:
    // sum cost_j = L + (n - 1) * D + D
    // L + (n - 1) * D を R' として、L, R' がメモされていれば、
    // sum cost_j = memo(L, R') + cost_n だけで計算が終わる

    std::unordered_map<int, std::pair<int, int>> map;

    // r は計算用に挿入しとく
    map[r] = mapMemo[r];
    for (int rd = r - D; rd >= l; rd -= D)
    {
        // break していないということは L, rd + D のペアはまだメモされていない
        // = map に追加して、rd から rd + D までのコストを計算対象にする
        map[rd] = mapMemo[rd];

        auto costItr = costMemo.find(searchNum(l, rd));
        if (costItr != costMemo.end()) {
            // L から rd までのコストはすでにメモされている
            // これ以上計算しなくていいので、メモされていたコストを足して break
            *totalCost += costItr->second;
            break;
        }
    }

    for(auto& elem : map)
    {
        int v = elem.first;
        if (v == r) continue; // v == R は計算用に保存してあるだけなので skip

        const auto& currentPair = elem.second;
        const auto& nextPair = map[v + D];
        const int cost =
            std::abs(nextPair.first - currentPair.first) + 
            std::abs(nextPair.second - currentPair.second);
        *totalCost += static_cast<uint64_t>(cost);

        // rd と r 間のコストも使い回せるのでメモっておく
        costMemo.emplace(searchNum(v, v + D), cost);
    }

    // メモ化
    costMemo.emplace(searchNum(l, r), *totalCost);
}

