    rep(y, h) rep(x, w) {
        int a;
        cin >> a;
        --a;
        X[a] = x;
        Y[a] = y;
    }
    rep(i, n) rep(j, 20) {
        cost[i][j] = 0;
        nxt[i][j] = -1;
    }
    rep(i, n - d) {
        cost[i][0] = abs(X[i] - X[i+d]) + abs(Y[i] - Y[i+d]);
        nxt[i][0] = i+d;
    }
    REP(k, 1, 20) {
        rep(i, n) {
            if(nxt[i][k-1] == -1) continue;
            nxt[i][k] = nxt[nxt[i][k-1]][k-1];
            cost[i][k] = cost[i][k-1] + cost[nxt[i][k-1]][k-1];
        }
    }

    #ifdef DEBUG_MODE
    //DEBUG_2D
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < 20; j++) printf("%2d",nxt[i][j]);
