    rep(i, q) {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        ll ans = 0LL;
        while(x < y) {
            // cout << x << " " << y << endl;
            repr(i, 20) {
                if(nxt[x][i] >= 0 && nxt[x][i] <= y) {
                    ans += cost[x][i];
                    x = nxt[x][i];
                    break;
                }
            }
        }
        // cout << x << " " << y << endl;
        cout << ans << endl;
    }
    return 0;
}

