#define DUMP2D(a, n, m) REP(i, n) REP(j, m) printf("%d%c", a[i][j], j + 1 == m ? '\n' : ' '); puts("")

const int H_MAX = 300;
const int W_MAX = 300;
const int Q_MAX = 100000;
const int N_MAX = H_MAX * W_MAX;
const int N_LOG = 16;

int H, W, D;
int A[H_MAX][W_MAX];
int Q;
int L[Q_MAX];
int R[Q_MAX];

int N;
int h[N_MAX];
int w[N_MAX];
int m[N_LOG + 1][N_MAX];

void solve() {
  N = H * W;
  REP(i, H) REP(j, W) {
    h[A[i][j] - 1] = i;
    w[A[i][j] - 1] = j;
  }
  REP(i, N - D) {
    // m[0][i] = abs(h[i] - h[i + D]) + abs(w[i] - w[i + D]);
  }

  int d = D;
  REP(j, N_LOG) {
    REP(i, N - d) {
      // m[j + 1][i] = m[j][i] + m[j][i + d];
    }
    d *= 2;
  }

  // DUMP2D(m, 5, N);

  REP(i, Q) {
    int ans = 0;
    int f = L[i] - 1, t = R[i] - 1;
    int l = (t - f) / D;
    int k = 0, d = D;
    while (l > 0) {
      if (l & 1) {
        // ans += m[k][f];
        f += d;
      }
      l /= 2;
      k++;
      d *= 2;
    }
    printf("%d\n", ans);
  }
}

