#include <cstdio>
#include <cstdlib>

class Vector1D {
public:
    int x;
};

/// @brief Represents a point.
class Vector2D : public Vector1D {
public:
    int y;

    /// @brief Returns Manhattan distance.
    int get_dist(Vector2D *dst) {
        return std::abs(dst->x - this->x) + std::abs(dst->y - this->y);
    }
};

static Vector2D points[90001];
static int d_cum[90001];  ///< Cumulative distance.

/// @brief Prints the distance for each query.
int main() {
    int H, W, D, Q, L, R;
    int A[301][301];
    Vector2D* point;

    scanf("%d %d %d", &H, &W, &D);

    for (int h = 1; h <= H; ++h) {
        for (int w = 1; w <= W; ++w) {
            scanf("%d", &A[h][w]);
            point = &points[A[h][w]];
            point->x = w;
            point->y = h;
        }
    }

    for (int i = 1; i <= H * W; ++i) {
        if (i <= D) {
            d_cum[i] = 0;
        } else {
            d_cum[i] = d_cum[i - D] + points[i].get_dist(&points[i - D]);
        }
    }

    scanf("%d", &Q);

    for (int q = 1; q <= Q; ++q) {
        scanf("%d %d", &L, &R);
        printf("%d\n", d_cum[R] - d_cum[L]);
    }
}

