int move(int l, int r, int d) {
    int ans = 0;
    for (int b = 20; b >= 0; --b) {
        int bit = 1 << b;
        if ((d & bit) != 0) {
            ans += cost[b][l];
            d -= bit;
            l += bit * D;
            if (l != r) {
                ans += move(l, r, d);
            }
            return ans;
        }
    }
