#define FOR(i, a, b) for(int i=a; i<=b; i++)

int H, W, D;
int A[H_MAX][W_MAX];
int Q;
int ans_buf[100000];

int is_num_in_A(int num, int *a)
{
	FOR(i, 0, H-1){
		FOR(j, 0, W-1){
			if(a[i*W_MAX+j] == num) return 1;
		}
	}
	return 0;
}

int cal_magic(int num, int *a)
{
	int from_i = 0, from_j = 0;
	int to_i = 0, to_j = 0;

	FOR(i, 0, H-1){
		FOR(j, 0, W-1){
			if(a[i*W_MAX+j] == num){
				from_i = i;
				from_j = j;
				goto FROM_FOUND;
			}
		}
	}

printf("AAAA impossible 1\n");
FROM_FOUND:
	FOR(i, 0, H-1){
		FOR(j, 0, W-1){
			if(a[i*W_MAX+j] == num + D){
				to_i = i;
				to_j = j;
				goto TO_FOUND;
			}
		}
	}
printf("AAAA impossible 2\n");

TO_FOUND:

	return abs(to_i-from_i) + abs(to_j-from_j);
}

void find_answer(int l, int r, int *a, int index)
{
	int magic = 0;
	int n = 1;

	// LをAからさがす ないとreturn 0
	if(is_num_in_A(l, a) == 0) goto CHECK_ERROR;

	// RをAからさがす ないとreturn 0
	if(is_num_in_A(r, a) == 0) goto CHECK_ERROR;

	// (R - L)/Dをチェック
	if((r-l)%D != 0)  goto CHECK_ERROR;
	if(r==l) goto SAME_POS;

	// L + n*d全部あることを確認
	if(is_num_in_A(l+n*D, a) == 0) goto CHECK_ERROR;

	do{
		n++;
		if(is_num_in_A(l+n*D, a) == 0) goto CHECK_ERROR;
	}while((l+n*D)!=r);

	//計算
	n = 0;
	while(l+n*D!=r){
		magic += cal_magic(l+n*D, a);
		n++;
	};

	ans_buf[index] = magic;
	return;

CHECK_ERROR:
SAME_POS:
	ans_buf[index] = 0;
	return;
}

int main(void){
	int L, R;

	scanf("%d%d%d", &H, &W, &D);

	FOR(i, 0, H-1){
		FOR(j, 0, W-1){
			scanf("%d", &A[i][j]);
		}
	}

	scanf("%d", &Q);

	FOR(i, 0, Q-1){
		scanf("%d%d", &L, &R);
		find_answer(L, R, &A[0][0], i);
	}

	FOR(i, 0, Q-1){
		printf("%d\n", ans_buf[i]);
	}
	return 0;
}

