int calcMagic(int a,int b,int c,int d){
  int cnt=abs(a-c)+abs(b-d);
  return cnt;
}

int magic(int p,int q, int r){
  if(p==q)return 0;
  int a,b,c,d;
  a=A[p].first;
  b=A[p].second;
  c=A[p+r].first;
  d=A[p+r].second;
  return calcMagic(a,b,c,d)+magic(p+r,q,r);
}

