using namespace std;

int H, W, D;
map<int, int> m;

int hw_to_id(int h, int w)
{
  return h*H + w;
}

void id_to_hw(int id, int& h, int& w)
{
  h = id/H;
  w = id%W;
}

int move(int& L)
{
  int h0,w0;
  int id0 = m[L];
  id_to_hw(id0,h0,w0);
  L+=D;
  int h1,w1;
  int id1 = m[L];
  id_to_hw(id1,h1,w1);
  return abs(h1-h0) + abs(w1-w0);
}

int trial(int L, int R)
{
  int x = 0;
  while (L!=R)
    x += move(L);
  return x;
}

int main()
{
  std::cin >> H >> W >> D;

  for (int h=0; h<H; ++h) {
    for (int w=0; w<W; ++w) {
      int key;
      cin >> key; // A[h][w]
      int value = hw_to_id(h,w);
      m[key] = value;
    }
  }

  int Q;
  cin >> Q;

  for (int q=0; q<Q; ++q) {
    int L, R;
    cin >> L >> R;
    cout << trial(L,R) << endl;
  }

  return 0;
}

