uint64_t calcCost(const std::pair<int, int>& c, const std::pair<int, int>& o)
{
    return static_cast<uint64_t>(std::abs(c.first - o.first) + std::abs(c.second - o.second));
}

int main()
{
    int H, W, D;
    cin >> H >> W >> D;

    int** s;
    input2DArray(s, H, W);

    uint32_t Q;
    cin >> Q;

    int** lr;
    input2DArray(lr, Q, 2);

    // index map を作っておく
    std::unordered_map<int, std::pair<int, int>> mapMemo;
    ForIndex2D(H, W)
    {
        mapMemo[ s[i][j] ] = std::make_pair(i, j);
    }}

    // 完全なコストマップを作る
    std::unordered_map<int, uint64_t> costMemo;
    const auto searchIndex = [](int l, int r) {
        return 1000 * r + l;
    };

    const int maxSize = H * W;
    for (int l = 1; l <= maxSize; l++)
    {
        int prevIndex = searchIndex(l, l);
        costMemo[prevIndex] = 0; // l が同じ時はコストゼロ

        for (int r = l + D; r <= maxSize; r += D)
        {
            const auto& currentPair = mapMemo[r];
            const auto& prevPair = mapMemo[r - D];

            const int newIndex = searchIndex(l, r);

            // 1つ手前の
            costMemo[newIndex] =
                costMemo[prevIndex] + calcCost(currentPair, prevPair);

            prevIndex = newIndex;
        }
    }

    ForIndex(Q)
    {
        const int l = lr[index][0];
        const int r = lr[index][1];
        if (l == r) 
        {
            cout << 0 << endl;
        }
        else
        {
            cout << costMemo[searchIndex(lr[index][0], lr[index][1])] << endl;
        }
    }

    delete2DArray(lr, Q);
    delete2DArray(s, H);
    return 0;
}

