vector<vector<int>> A;
vector<int> cost_sub;
vector<int> cost_stock;


void find_next(int i, int j)
{
    for (int ni = 0; ni < H; ni++) {
        for (int nj = 0; nj < W; nj++) {
            if (A[ni][nj] == A[i][j] + D) {
                cost_sub[A[i][j]] += abs(ni - i) + abs(nj - j);
                return;
            }
        }
    }
}


void calc_cost()
{
    for (size_t i = 0; i < H; i++) {
        for (size_t j = 0; j < W; j++) {
            if (A[i][j] <= H * W - D) {
                find_next(i, j);
            }
        }
    }
    return;
}


int main()
{
    cin >> H >> W >> D;
    A.resize(H);
    for (size_t i = 0; i < H; i++) {
        A[i].resize(W);
        for (size_t j = 0; j < W; j++) {
            cin >> A[i][j];
        }
    }

    cost_sub.resize(H * W - Q + 1);

    calc_cost();

    cin >> Q;

    cost_stock.resize(Q);

    for (size_t i = 0; i < Q; i++) {
        int cost = 0;
        cin >> L >> R;
        size_t j = L;
        while (j < R) {
            cost += cost_sub[j];
            j += D;
        }
        cost_stock[i] = cost;
    }

    for (size_t i = 0; i < Q; i++) {
        cout << cost_stock[i] << endl;
    }

    return 0;
}

