typedef struct pt{
  int XX;
  int YY;
}point;

int move(point now,point next){
  return abs(now.XX-next.XX)+abs(now.YY-next.YY);
}

int main(void){
  int H,W,D,Q;
  int R,L,MP;
  int temp;
  point nowpoint,nextpoint;
  scanf("%d %d %d",&H,&W,&D);
  point num[H*W+1]; //0,0は捨てる
  for(int j=1;j<=W;j++){
    for(int i=1;i<=H;i++){
      scanf("%d",&temp);
      num[temp].XX=i;
      num[temp].YY=j;
    }
  }
  scanf("%d",&Q);
  for(int i=0;i<Q;i++){
    MP=0;
    scanf("%d %d",&L,&R);
    nowpoint=num[L];
    while(L!=R){
      L+=D;
      nextpoint=num[L];
      MP+=move(nowpoint,nextpoint);
      nowpoint=nextpoint;
    }
    cout<<MP<<endl;
  }
  return 0;
}

