#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define MAX 90100
#define NIL -1

int main() {
	int H, W, D; scanf("%d%d%d", &H, &W, &D);
	pair<int, int> A[MAX]; int G[MAX]; FOR(i, 0, MAX) G[i] = NIL;

	FOR(y, 1, H + 1) FOR(x, 1, W + 1) {
		int a; scanf("%d", &a);
		A[a] = make_pair(x, y);
	}

	int Q; scanf("%d", &Q);

	FOR(i, 0, Q) {
		int L, R, MP = 0; scanf("%d%d", &L, &R);

		while (L != R) {
			if (G[L] == NIL) {
				int p = abs(A[L].first - A[L + D].first) + abs(A[L].second - A[L + D].second);
				G[L] = p; MP += p;
			}
			else {
				MP += G[L];
			}
			L += D;
		}

		printf("%d\n", MP);
	}

	return 0;
}

