using namespace std;

const int maxH = 3e2, maxW = maxH;
const int maxA = 9e4;
const int maxQ = 10e5;
int H, W, D;
int Q;
int A[maxH + 1][maxW + 1];
int L, R;

int magic(int i, int j, int x, int y)
{
    return abs(x - i) + abs(y - j);
}

void findsq(int val, int& x, int& y)
{
    x = -1;

    for (int i = 1; i <= H; ++i) {
        for (int j = 1; j <= W; ++j) {
            if (A[i][j] == val) {
                x = i;
                y = j;
                return;
            }
        }
    }    
}

void solve(int L, int R)
{
    int i, j, previ, prevj;
    long long sum = 0;

    findsq(L, previ, prevj);
    if (previ == -1) cout << "Impossible start" << endl;

    while (L != R) {
        L += D;
        findsq(L, i, j);
        if (i == -1) cout << "Impossible middle point" << endl;

        sum += magic(previ, prevj, i, j);

        previ = i;
        prevj = j;
    }

    cout << sum << endl;
}

int main()
{
    scanf("%d %d %d", &H, &W, &D);
    for (int i = 1; i <= H; ++i) {
        for (int j = 1; j <= W; ++j) {
            scanf("%d", &A[i][j]);
        }
    }
    scanf("%d", &Q);
    for (int i = 1; i <= Q; ++i) {
        scanf("%d %d", &L, &R);
        solve(L, R);
    }

    return 0;
}

