using namespace std;

int magic(pair<int,int> p, pair<int,int> q){
  return abs(p.first - q.first) + abs(p.second - q.second);
}

int main(){
  int H, W, D, A, Q, L, R = 0;
  map<int, pair<int,int>> mapping;
  int graph[100000];                //graph[x]はxからx+Dのマスへの移動コストを表す
  cin >> H >> W >> D;
  for(int i = 0; i < H; ++i){
    for(int j = 0; j < W; ++j){
      cin >> A;
      mapping[A] = {i,j};             //マスの値をキーとしてそのマスの座標を保存
    }
  }

  for(int i = 1; i <= D; ++i){
    graph[i] = 0;
    for(int j = i; j <= H * W - D; j += D){
      //x=Dのマスを始点としてx=jまでの移動コストを計算し結果を配列に保存
      graph[j + D] = magic(mapping[j], mapping[j + D]) + graph[j];
    }
  }

  cin >> Q;
  for(int i = 0; i < Q; ++i){
    cin >> L >> R;
    //求める値は x=Dからx=Rまでのコスト - x=Dからx=Lまでのコスト
    cout << graph[R] - graph[L] << endl;
  }

  return 0;
}

