  cin >> h >> w >> d;
  vector<vector<int>> in(h, vector<int>(w));
  for (int i=0; i<h; i++) {
    for (int j=0; j<w; j++) {
      cin >> in.at(i).at(j);
    }
  }
  vector<pair<int, int>> pla(h*w+1);
  for (int i=0; i<h; i++) {
    for (int j=0; j<w; j++) {
      pla.at(in.at(i).at(j)) = make_pair(i, j);
    }
  }

  vector<int> dis(h*w+1);
  for (int i=1; i<=d; i++) {
    dis.at(i) = 0;
    int cur = i + d;
    while (cur <= h * w) {
      int magic = abs(pla.at(cur).first - pla.at(cur-d).first) + abs(pla.at(cur).second - pla.at(cur-d).second);
      dis.at(cur) = dis.at(cur-d) + magic;
      cur += d;
    }
  }

  int q = 0;
  cin >> q;
  vector<int> ans(q);
  int l = 0, r = 0;
  for (int i=0; i<q; i++) {
    cin >> l >> r;
    ans.at(i) = dis.at(r) - dis.at(l);
  }
  for (int x : ans) {
    cout << x << endl;
  }
  return 0;
