int main(int argc, char const *argv[]) {
  int H, W, D, Q;
  scanf("%d %d %d", &H, &W, &D);
  int x[H*W];
  int y[H*W];
  int A[H][W];
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      scanf("%d", &A[i][j]);
      x[A[i][j]] = i;
      y[A[i][j]] = j;
    }
  }
  scanf("%d", &Q);
  int L[Q];
  int R[Q];
  for (int i = 0; i < Q; i++) {
    scanf("%d %d", &L[i], &R[i]);
  }
  int mana[Q];
  for (int q = 0; q < Q; q++) {
    mana[q] = 0;
    int l = L[q];
    int r = R[q];
    int diff = INT_MAX;
    for (int k = 0; k < q; k++) {
      if (L[k] == L[q] && R[k] <=  R[q] && diff > R[q] - R[k]) {
        mana[q] = mana[k];
        r = L[q];
        l = R[k];
        diff = R[q] - R[k];
      } else if (R[k] == R[q] && L[q] <=  L[k] && diff > L[k] - L[q]) {
        mana[q] = mana[k];
        r = L[k];
        l = R[q];
        diff = L[k] - L[q];
      }
    }
    // printf("%d\n", L[q]);
    // printf("%d\n", R[q]);
    while (l != r) {
      // printf("%d\n", abs(x[l] - x[l + D]));
      // printf("%d\n", abs(y[l] - y[l + D]));
      mana[q] += abs(x[l] - x[l + D]) + abs(y[l] - y[l + D]);
      l += D;
    }
    printf("%d\n", mana[q]);
  }
  return 0;
}

