template <class T> T mandist(int x1, int y1, int x2, int y2) {
    return abs(x2 - x1) + abs(y2 - y1);
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int H, W, D;
    cin >> H >> W >> D;
    vector<pair<int, int>> v(H * W + 1);
    REP(i, H) {
        REP(j, W) {
            int x;
            cin >> x;
            v[x] = {i, j};
        }
    }
    vector<ll> cost(H * W + 1);
    REP(i, H * W + 1) {
        if (i <= D)
            continue;
        cost[i] = cost[i - D] + mandist<ll>(v[i].first, v[i].second,
                                            v[i - D].first, v[i - D].second);
    }
    int Q;
    cin >> Q;
    REP(i, Q) {
        int l, r;
        cin >> l >> r;
        print(cost[r] - cost[l]);
    }

    return 0;
}

