struct WeightedUnionFind{
  vector<long long> data;
  vector<long long> dif;
  void boot(long long n){
    for(long long i = 0;i < n;i++)data.push_back(-1);
    for(long long i = 0;i < n;i++)dif.push_back(0);
    return;
  }
  long long root(long long x){
    if(data[x] < 0)return x;
    long long r = root(data[x]);
    dif[x] += dif[data[x]];
    return data[x] = root(data[x]);
  }
  long long weight(long long x){
    root(x);
    return dif[x];
  }
  bool same(long long x,long long y){
    return root(x) == root(y);
  }
  void unite(long long x,long long y,long long w){
    if(!same(x,y)){
      w += weight(x);
      w -= weight(y);
      x = root(x);
      y = root(y);
      if(data[x] < data[y]){
        data[x] += data[y];
        data[y] = x;
        dif[y] = w;
      }
      else{
        data[y] += data[x];
        data[x] = y;
        dif[x] = -w;
      }
    }
    return;
  }
  long long getsize(long long x){
    return -data[root(x)];
  }
  long long diff(long long x,long long y){
    return dif[y] - dif[x];
  }
};

