#include <bits/stdc++.h>
using namespace std;

int h, w, d;
map<pair<int,int>, int> cost;
map<int, pair<int,int>> mp;

int totalCost(int l, int r) {
    if (l == r) return 0;
    if (cost[{l, r}] != 0) return cost[{l, r}];

    auto pos1 = mp[l];
    auto pos2 = mp[l + d];
    cost[{l, r}] = abs(pos2.f - pos1.f) + abs(pos2.s - pos1.s)
                    + totalCost(l + d, r);
    return cost[{l, r}];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> h >> w >> d;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int x;
            cin >> x;
            mp[x] = {i, j};
        }
    }

    int q;
    cin >> q;
    while (q--) {
        int l, r;
        cin >> l >> r;
        cout << totalCost(l, r) << '\n';
    }
    return 0;
}

