const int INF=1e9+7;
const int MOD=1e9+7;
//
struct edge {int to,cost;};
int V=90001;
vector<edge> G[90001];
int D[90001];
void dijkstra(int S){
  priority_queue<PA,vector<PA>,greater<PA> > que;
  fill(D,D+V,INF);
  D[S]=0;
  que.push(make_pair(0,S));
  while(que.size()){
    PA P=que.top();
    que.pop();
    int vv=P.SE;
    if(D[vv]<P.FI){
      continue;
    }else{
      FOR(i,0,(int)G[vv].size()){
        edge e=G[vv][i];
        if(D[e.to]>D[vv]+e.cost){
          D[e.to]=D[vv]+e.cost;
          que.push(make_pair(D[e.to],e.to));
        }
      }
    }
  }
}
int main(){
  int H,W,d;
  pair<int,int> P[90001];
  cin>>H>>W>>d;
  FOR(i,0,H){
    FOR(j,0,W){
      int num;
      cin>>num;
      P[num]=make_pair(i,j);
    }
  }
  FOR(i,1,H*W+1){
    edge E;
    E.to=i+d;
    E.cost=abs(P[i+d].FI-P[i].FI)+abs(P[i+d].SE-P[i].SE);
    G[i].PB(E);
  }
  int Q;
  cin>>Q;
  FOR(i,0,Q){
    int L,R;
    cin>>L>>R;
    dijkstra(L);
    cout<<D[R]<<endl;
  }
  return 0;
}

