pair<int, int> find_a (vector<vector<int>>& A, int number)
{
	static pair<int, int> memo[90001] = {};

	if ((memo[number].first == 0) && (memo[number].second == 0))
	{
		REP (i, A.size())
		REP (j, A[i].size())
		{
			if (A[i][j] == number)
			{
				memo[number].first = i;
				memo[number].second = j;
				return memo[number];
			}
		}
	}

	return memo[number];
}

int main () {
