	REP (i, H)
	for (auto& a : A[i]) cin >> a;

	int Q;
	cin >> Q;

	int memo[90001] = {};

	int l, r;
	vector<int> magic(Q);
	REP (q, Q)
	{
		magic[q] = 0;
		cin >> l >> r;

		while (l != r)
		{
			l += D;
			if (memo[l] == 0)
			{
				auto c = find_a(A, l - D);
				auto n = find_a(A, l);
				memo[l] = abs(c.first - n.first) + abs(c.second - n.second);
			}
			magic[q] += memo[l];
		}
	}

	for (auto m : magic)
	{
		cout << m << endl;
	}
}

