const int sqrtN = 512;
const int logN = 32;
const ll LINF=1e18;

struct Node{
	int data;

	Node(int data) : data(data) {}
	Node operator*(const Node r){return Node(data + r.data);}
} e(0);

struct SegmentTree{
	vector<Node> seg;
	int sz = 1;

	SegmentTree(int n){
		while(sz < n) sz *= 2;
		seg.assign(sz * 2, e);
	}

	void update(int k, int x){
		k += sz - 1;
		seg[k] = Node(x);

		while(k){
			k = (k - 1) / 2;
			seg[k] = seg[2 * k + 1] * seg[2 * k + 2];
		}
	}

	int get(int a, int b){
		return get(a, b, 0, 0, sz).data;
	}

	Node get(int a, int b, int k, int l, int r){
		if(b<=l||r<=a) return e;
		if(a<=l&&r<=b) return seg[k];

		return get(a, b, 2 * k + 1, l, (l + r) / 2) * get(a, b, 2 * k + 2, (l + r) / 2, r);
	}
};

int main(){
	int h, w, d; cin >> h >> w >> d;
	SegmentTree seg[d](h * w / 4 + 1);
	int a[300][300]; map<int, P> mp;
	for(int i = 0; i < h; i++){
		for(int j = 0; j < w; j++){
			cin >> a[i][j];
			mp[a[i][j]] = {i, j};
		}
	}

	map<int, int> mp2;
	for(int i = 1; i <= d; i++){
		int c = 0;
		for(int j = i; j <= h * w; j += d){
			mp2[j] = c++;
			if(j + d > h * w) break;

			P s = mp[j], t = mp[j + d];
			int cost = abs(s.first - t.first) + abs(s.second - t.second);
			seg[i % d].update(mp2[j], cost);
		}
	}

	int q; cin >> q;
	for(int i = 0; i < q; i++){
		int l, r; cin >> l >> r;

		cout << seg[l % d].get(mp2[l], mp2[r]) << endl;
	}
	return 0;
}

