int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0);	
	int h,w,d;
	cin>>h>>w>>d;
	for(int i=0;i<h;i++){
		for(int ii=0;ii<w;ii++){
			cin>>arr[i][ii];
		}
	}
	pair<int,int> result;
	int q;
	cin>>q;
	int l,r;
	while(q--){
		cin>>l>>r;
		result=search(l,arr,h,w);
		// teleport a piece placed on Square (i,j) to Square (x,y) by consuming |x−i|+|y−j| magic points.
		int mpcon=0;
		int counter=1;
		pair<int,int> prevresult=result;
		while(arr[result.first][result.second]!=r){
			result=search(l+(counter*d),arr,h,w);
			if (result.first==-1){
				break;
			}
			mpcon+=abs(result.first-prevresult.first)+abs(result.second-prevresult.second);
			counter++;
			prevresult=result;
		}
		if (result.first==-1){
			cout<<"0\n";
		}
		else{
			cout<<mpcon<<"\n";
		}
	}

	return 0;
}

