int main(){
	int H, W, D;
	scanf("%d %d %d", &H, &W, &D);
	int row[H*W+1], column[H*W+1];
	for (int i = 0; i < H; ++i)	{
		for (int j = 0; j < W; ++j)	{
			int tmp;
			scanf("%d", &tmp);
			row[tmp] = i;
			column[tmp] = j;
		}
	}
	int Q;
	scanf("%d", &Q);
	for (int i = 0; i < Q; ++i) {
		int present, previous, R;
		scanf("%d %d", &present, &R);
		long long int cost = 0;
		int limit = (R-present) / D;
		for (int i = 0; i < limit; ++i)	{
			previous = present;
			present += D;
			cost += (abs(row[present] - row[previous]) + abs(column[present] - column[previous]));
		}
		printf("%lld\n", cost);
	}
	return 0;
}

