            int x;
            cin >> x;
            mp[x] = {i, j};
        }
    }

    int q;
    cin >> q;
    while (q--) {
        int l, r;
        cin >> l >> r;
        cout << totalCost(l, r) << '\n';
    }
    return 0;
}

