int main() {
    int H, W, D;
    std::cin >> H >> W >> D;
    int N = H * W;
    std::vector<int> i_s(N), j_s(N);
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int a;
            std::cin >> a;
            --a;
            i_s[a] = i;
            j_s[a] = j;
        }
    }
    std::vector<std::vector<ll>> anss(D);
    for (int st = 0; st < D; ++st) {
        ll ans = 0;
        anss[st].push_back(ans);

        int L = st;
        int i = i_s[L], j =  j_s[L];
        while (L < N) {
            L += D;
            int new_i = i_s[L], new_j = j_s[L];
            ans += std::abs(new_i - i) + std::abs(new_j - j);
            i = new_i;
            j = new_j;
            anss[st].push_back(ans);
        }
    }

    int Q;
    std::cin >> Q;
    while (Q--) {
        int L, R;
        std::cin >> L >> R;
        --L, --R;
        int st = L % D;
        std::cout << anss[st][(R - st) / D] - anss[st][(L - st) / D] << std::endl;
    }
}

