void solve() {
	int H, W, D; cin >> H >> W >> D;
	vector<vector<int> > A(H, vector<int>(W));
	vector<pii> p(H*W+1);
	REP(i, H) REP(j, W) {
		cin >> A[i][j];
		p[A[i][j]] = make_pair(i, j);
	}

	vector<int> G(H*W+1);
	REP(d, D) {
		FOR(i,1,(H*W-1)/D + 1) {
			int oldnum = (i - 1)*D + d + 1;
			int num = i*D + d + 1;
			if(num <= H*W) G[num] = abs(p[num].first - p[oldnum].first) + abs(p[num].second - p[oldnum].second);
		}
	}

	REP(d, D) {
		FOR(i,1,(H*W-1)/D + 1) {
			int oldnum = (i - 1)*D + d + 1;
			int num = i*D + d + 1;
			if (num <= H*W) G[num] = G[num] + G[oldnum];
		}
	}

	int Q; cin >> Q;
	REP(i, Q) {
		int l, r; cin >> l >> r;
		cout << G[r] - G[l] << endl;
	}
}

