// 累積和
template <class T>
struct RuisekiwaT : vector<T>
{
	using vector<T>::at;
	RuisekiwaT(const vector<T>& A) : vector<T>(A.size() + 1)
	{
		REP(i, A.size()) { at(i + 1) = at(i) + A[i]; }
	}

	// [l..r) の累積和
	T Range(int l, int r) { return at(r) - at(l); }
}; template <class T> RuisekiwaT<T> Ruisekiwa(const vector<T>& A) { return RuisekiwaT<T>(A); }


void solve()
{
	READ(int, H, W, D);
	auto A = read<int>(H, W);
	auto Q = read<int>();
	auto Qs = read<pair<int, int>>(Q);

	auto N = H * W;

	vector<pair<int, int>> pos(H * W);
	REP(i, H)REP(j, W)
	{
		pos[A[i][j] - 1] = { i, j };
	}

	vevector<int> m(D);

	FOR(i, D, N)
	{
		m[i % D].push_back(abs(pos[i].first - pos[i - D].first) + abs(pos[i].second - pos[i - D].second));
	}

	vector<RuisekiwaT<int>> mm;
	REP(i, D) { mm.push_back(Ruisekiwa(m[i])); }

	FORE(q : Qs)
	{
		int l = q.first - 1;
		int r = q.second - 1;

		WRITE(mm[l % D].Range(l / D, r / D));
	}
}

