map<ll, pair<ll, ll>> mp;
map<ll, ll[100000]> d_mp;

//ll c[100000][100000] = {};
int main() {
	ll h, w, d; cin >> h >> w >> d;

	rep(i, 0, h)rep(j, 0, w) {
		ll v; cin >> v;
		mp[v] = make_pair(i, j);
	}

	for (map<ll, pair<ll, ll>>::iterator it = mp.begin(); it != mp.end(); it++) {
		ll v = 0;;
		if (it->first <= d) {
			v = 0;
		}
		else {
			ll sx = mp[it->first].first + 1;
			ll sy = mp[it->first].second + 1;
			ll nx = mp[it->first - d].first + 1;
			ll ny = mp[it->first - d].second + 1;
			v = abs(nx - sx) + abs(ny - sy);
		}

		d_mp[it->first % d][it->first / d + ((it->first % d) ? 0 : -1)] = v;
		//c[it->first % d][it->first / d + ((it->first % d) ? 0 : -1)] = v;
	}

	repe(i, 0, d) {
		repe(j, 1, h*w / d) {
			//c[i][j] += c[i][j - 1];
			d_mp[i][j] += d_mp[i][j - 1];
		}
	}

	ll q; cin >> q;
	rep(i, 0, q) {
		ll l, r; cin >> l >> r;
		//ll ans = c[l%d][r / d + ((r % d) ? 0 : -1)] - c[l%d][l / d + ((l % d) ? 0 : -1)];
		ll ans = d_mp[l%d][r / d + ((r % d) ? 0 : -1)] - d_mp[l%d][l / d + ((l % d) ? 0 : -1)];
		cout << ans << endl;
	}

	return 0;
}

