	int N = H*W;
	vector<int> A(N);
	vector<int> AS(N+1);
	AS[0] = 0;
	for( int i=0; i<N; i++ ){
		int temp;
		scanf("%d", &temp);
		A[i] = temp;
	}

	for( int i = 1; i <= N; i++ ){
		if( i <= D ){
			AS[i] = 0;
			continue;
		}
		auto itrX = find(A.begin(), A.end(), i-D);  
		int disX = distance(A.begin(), itrX);
		auto itrY = find(A.begin(), A.end(), i);  
		int disY = distance(A.begin(), itrY);
		int l_ength = abs(disX%W-disY%W) + ( abs((disX-disX%W)-(disY-disY%W)) ) / W;
		AS[i] = AS[i-D] + l_ength;
	}

	int Q;
	scanf("%d", &Q);
	for(int i=0; i<Q; i++){
		int L, R;
		scanf("%d", &L);
		scanf("%d", &R);
		printf("%d\n", AS[R] - AS[L]);
	}

	return 0;
}

