int h, w, d, q;
void solve() {
  for (int y=0;y<h;y++) {
    for (int x=0;x<w;x++) {
      field[a[y][x] - 1] = P(x, y);
    }
  }

  for (int i=0;i<=w*h;i++) {
    if (!visited[i]) {
      cost[i].reserve((w*h-i) / d);
      cost[i].push_back(0);
      for (int j=1;i + j * d<=w*h;j++) {
        visited[i + j * d] = true;
        P& p1 = field[i + (j-1) * d];
        P& p2 = field[i + j * d];
        cost[i].push_back(cost[i][j-1] + abs(p1.first - p2.first) + abs(p1.second - p2.second));
      }
    }
  }


  for (int i=0;i<q;i++) {
    l[i]--;r[i]--;
    int start = l[i] % d;
    cout << (cost[start][(r[i] - start) / d] - cost[start][(l[i] - start) / d]) << endl;
  }
}

