struct MyMain {
	int H = in;
	int W = in;
	int D = in;
	arr2<int> A = in(H, W);
	int Q = in;
	pints T = in(Q);

	void Run() {
		int maxValue = H * W;
		arr<pint> A2P(maxValue + 1);
		REP(y, H) {
			REP(x, W) {
				A2P[A(x, y)] = pint(x, y);
			}
		}

		arr<int> dists(maxValue + 1);
		REP(d, D) {
			int totalDist = 0;
			pint lastP = A2P(d);
			for (int i = 0;; ++i) {
				int index = d + i * D;
				if (index >= A2P.size()) {
					break;
				}
				pint p = A2P(index);
				int dist = abs(p.x - lastP.x) + abs(p.y - lastP.y);
				totalDist += dist;
				dists[index] = totalDist;

				lastP = p;
			}
		}

		REP(q, Q) {
			pint t = T[q];
			int ans = dists[t.b] - dists[t.a];
			out << ans;
		}
	}

};

