int memo[300 * 300 + 1][300 * 300 + 1];
int dfs(int x, int y, int L, int R, int D, vector<pair<int,int>>& mp) {
  if (memo[L][R] != -1) return memo[L][R];
  if (L == R) return 0;
  int nx = mp[L + D].first, ny = mp[L + D].second;
  int cost = dfs(nx, ny, L+D, R, D, mp) + abs(x - nx) + abs(y - ny);
  return memo[L][R] = cost;
}

