Position getposi(int x){
    Position cposi;
    bool endflag = false;
    for(int i = 1; i <= H; i++) {
        for(int j = 1; j <= W; j++) {
            if(A[i][j] == x) {
                endflag = true;
                cposi.x = i;
                cposi.y = j;
                break;
            }
        }
        if(endflag) break;
    }
    return cposi;
}

int main() {
