            return true;
        }
    }
    return false;
}
lint digit(lint a,lint b){
    lint ad = 1,bd = 1;
    while(a > 9){
        ad++;
        a /= 10;
    }
    while(b > 9){
        bd++;
        b /= 10;
    }
