        C[k][j+D] = C[k][j] + cost;
    }
  }

  int Q;
  cin >> Q;
  for(int i=0; i<Q; i++){
    int l, r;
    cin >> l >> r;
    cout << C[l-1][r-1] << endl;
  }
  return 0;
}

