ll gcd(ll a, ll b) { //最大公約数
	if(a==0||b==0) return 0;
	if(a<b) swap(a,b);
	ll tmp = a%b;
	while(tmp!=0) {
		a = b;
		b = tmp;
		tmp = a%b;
	}
	return b;
}

ll modpow(ll a, ll ex, ll p) { //繰り返し二乗法
	if(ex==1) return a%p;
	if(ex%2) return a%p*modpow(a,ex-1,p)%p;
	ll tmp=modpow(a,ex/2,p)%p;
	return tmp*tmp%p;
}

ll factorial(ll x) { //階乗
	ll f=1;
	for(ll i=2; i<=x; i++) {
		f*=i;
	}
	return f;
}

