void solve() {
    i64 H,W; RD(H); RD(W);
    i64 D; RD(D);

    vector<Index2> pos(H*W);
    REP(y, H) REP(x, W) {
        i64 a; RD(a); --a;  // 0-based
        pos[a] = { y, x };
    }

    auto f = MEMOIZE<300*300>([D,&pos](auto self, i64 x) -> i64 {
        if(x < D) return 0;
        i64 cost = (pos[x]-pos[x-D]).norm1();
        return cost + self(x-D);
    });

    i64 Q; RD(Q);
    REP(_, Q) {
        i64 l,r; RD(l); RD(r); --l; --r;  // 0-based
        i64 ans = f(r) - f(l);
        PRINTLN(ans);
    }
}

