int a,h,w,d,q,l,r,start,cost;
pair<int,int> N[900005];
int C[900005];
int main()
{
	cin.tie(0);ios::sync_with_stdio(false);
	cin>>h>>w>>d;
	REP(i,h)
	{
		REP(j,w)
		{
			cin>>a;
			N[a].first=i;
			N[a].second=j;
		}
	}

	for(int k=1;k<=d;k++)
	{
		for(int i=0;k+d+i*d<=h*w;i++)
		{
			int x=N[k+i*d].first-N[k+d+i*d].first;
			int y=N[k+i*d].second-N[k+d+i*d].second;
			C[k+i*d]=abs(x)+abs(y);
		}
	}

	cin>>q;
	for(int k=0;k<q;k++)
	{
		cost=0;
		cin>>l>>r;
		start=l;
		if(l!=r)
		{
			for(;start!=r;)
			{
				cost+=C[start];
				start+=d;
			}
		}
		cout<<cost<<endl;
	}
	return 0;
}

