      if(s+D > H*W)
        break;
      n = mp[s+D];
      d[s+D] = d[s] + abs(p.first-n.first)+abs(p.second-n.second);
      s += D;
      p = n;
    }
  }
  cin >> Q;
  REP(i,Q){
    cin >> L[i] >> R[i];
  }
  REP(i,Q){
    cout << d[R[i]]-d[L[i]] << endl;
  }
  return 0;
}

int par[MAX_N];
int ranks[MAX_N];

//n要素で初期化
void init(int n){
  REP(i,n){
    par[i] = i;
    ranks[i] = 0;
  }

}

//木の根を求める
int find(int x){
  if(par[x] == x){
    return x;
  }else{
    return par[x] = find(par[x]);
  }
}

void unite(int x,int y){
  x = find(x);
  y = find(y);
  if(x == y) return ;
  if(ranks[x] < ranks[y]){
    par[x] = y;
  }else{
    par[y] = x;
    if(ranks[x] == ranks[y]) ranks[x]++;
  }
}

bool same(int x, int y){
  return find(x) == find(y);
}

