const int MAX_N=300+1;
int H,W,D,Q;
II P[MAX_N*MAX_N];
const int MAX_Q=1e5+1;
int L[MAX_Q],R[MAX_Q];
vector<LL> cum[MAX_N*MAX_N];
void solve() {
  REP(d,D) {
    int x=d;
    cum[d].clear();
    cum[d].push_back(0);
    while(x+D<H*W) {
      cum[d].push_back(cum[d].back());
      int xx=x+D;
      auto p1=P[x],p2=P[xx];
      LL cost=abs(p1.first-p2.first)+abs(p1.second-p2.second);
      cum[d].back()+=cost;
      dump4(d,x,xx,cost);
      x=xx;
    }
  }
  REP(i,Q) {
    int g=L[i]%D;
    int l=L[i]/D,r=R[i]/D;
    dump4(i,L[i],R[i],g);
    dump4(l,cum[g][l],r,cum[g][r]);
    cout<<cum[g][r]-cum[g][l]<<endl;
  }
}

