int main(int argc, char *argv[]) {
  // read inputs
  int H, W, D, As[MAX_H * MAX_W], Q, Ls[MAX_Q], Rs[MAX_Q];
  scanf("%d %d %d", &H, &W, &D);
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      scanf("%d", &As[j + i * W]);
    }
  }
  scanf("%d", &Q);
  for (int q = 0; q < Q; q++) {
    scanf("%d %d", &Ls[q], &Rs[q]);
  }

  // reverse
  int Bs[MAX_H * MAX_W + 1];
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      Bs[As[j + i * W]] = j + i * W;
    }
  }

  // calculate accumulated cost
  int acc_costs[MAX_H * MAX_W + 1];
  for (int k = 1; k <= D; k++) {
    acc_costs[k] = 0;
    int i_prev = Bs[k] / W, j_prev = Bs[k] % W;
    for (int l = k + D; l <= H * W; l += D) {
      const int i_cur = Bs[l] / W, j_cur = Bs[l] % W;
      acc_costs[l] =
          acc_costs[l - D] + abs(i_cur - i_prev) + abs(j_cur - j_prev);
      i_prev = i_cur;
      j_prev = j_cur;
    }
  }

  for (int q = 0; q < Q; q++) {
    const int L = Ls[q], R = Rs[q];
    printf("%d\n", acc_costs[R] - acc_costs[L]);
  }

  return 0;
}

