typedef long long ll;
typedef pair<int, int> Pair;

const int kMaxH = 300;
const int kMaxW = 300;
const int kMaxQ = 100000;
const int kInf = 1000000000;

int H, W, D;
int A[kMaxH][kMaxW];
int Q;
int L[kMaxQ], R[kMaxQ];
int ans;

int nxt[kMaxH*kMaxW+1];
int cost[kMaxH*kMaxW+1];

int main() {
  cin >> H >> W >> D;
  REP(i, H) { REP(j, W) { cin >> A[i][j]; } }
  cin >> Q;
  REP(i, Q) { cin >> L[i] >> R[i]; }

  map<int, Pair> m;
  REP(i, H) {
    REP(j, W) {
      auto k = m.find(A[i][j]-D);
      if (k != m.end()) {
        Pair p = k->second;
        nxt[A[i][j]-D] = ABS(i - p.first) + ABS(j - p.second);
      }

      auto k2 = m.find(A[i][j]+D);
      if (k2 != m.end()) {
        Pair p2 = k2->second;
        nxt[A[i][j]] = ABS(p2.first - i) + ABS(p2.second - j);
      }

      m.insert(make_pair(A[i][j], Pair(i, j)));
    }
  }
  FOR(i, 1, D+1) {
    cost[i] = 0;
    int j = i;
    while (j+D <= H*W) {
      cost[j+D] = cost[j] + nxt[j];
      j += D;
    }
  }

  REP(i, Q) {
    ans = cost[R[i]] - cost[L[i]];
    cout << ans << endl;
  }

  return 0;
}

