	pair<int, int> idxtoxy(int idx) {
		return make_pair(idx / W, idx % W);
	}
	static ll dp[305][305];
	static int idx[100000];
	ll dfs(int l, int r) {
		if (l == r) return 0;
		int next = l + D;
		if (dp[l][next] != -1) return dp[l][next];
		else {
			auto before = idxtoxy(idx[l]);
			auto after = idxtoxy(idx[next]);
			int ans = abs(before.first - after.first) + abs(before.second - after.second);
			dp[l][next] = ans;
			if (next == r) return ans;
			else return ans + dfs(next, r);
		}
	}
