int calc_dist(int l, int r) {
    if(l == r) return 0; 
    if(dist[l][r] != INF) return dist[l][r];
    int x = a_map[l].first;
    int y = a_map[l].second;
    int nx = a_map[l+d].first;
    int ny = a_map[l+d].second;
