map<P, ll> memo;
ll A[10000][10000];
map<int, P> s;
int dfs(int l, int r, int d) {
  if (l == r) return 0;
  if (memo[P(l, r)] != 0) return memo[P(l, r)];
  return memo[P(l, r)] = abs(s[l].first - s[l + d].first) +
                         abs(s[l].second - s[l + d].second) + dfs(l + d, r, d);
}
