template<typename T>
string join(const vector<T>& vec, string sep = " "){
    stringstream ss;
    for(int i = 0; i < vec.size(); i++){
        ss << vec[i] << (i + 1 == vec.size() ? "" : sep);
    }
    return ss.str();
}

V solve(int h, int w, int d, const M& ass, int q, const V& ls, const V& rs){
    M cost(h * w + 1, V(h * w + 1));
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            for(int x = 0; x < h; x++){
                for(int y = 0; y < w; y++){
                    int a = ass[i][j] - 1;
                    int b = ass[x][y] - 1;
                    cost[a][b] = abs(x - i) + abs(y - j);
                }
            }
        }
    }

    /*
      dp[i][j] 
        | i == j = 0
        | i != j = cost[i][i + d] + dp[i + d][j]
      return dp[l][r]
     */
    M dp(h * w, V(h * w));
    for(int i = 0; i < h * w; i++){
        dp[i][i] = 0;
        for(int j = i + d; j < h * w; j += d){
            dp[i][j] = cost[j - d][j] + dp[i][j - d];
        }
    }

    V ms(q);
    for(int i = 0; i < q; i++){
        int l = ls[i] - 1;
        int r = rs[i] - 1;
        ms[i] = dp[l][r];
    }
    return ms;
