    vector<int> ans(q);
    for (int i = 0; i < q; ++i) {
        int a, b;
        cin >> a >> b;
        int g = a % d;
        int k = find_index(group[g], a);
        int l = find_index(group[g], b);

        if (k < l) {
            ans[i] = power1[g][l] - power1[g][k];
        } else if (k > l) {
            ans[i] = power1[g][l] + power2[g][k];
        }
    }
    for (int a : ans) {
        cout << a << endl;
    }
    return 0;
}

