          if ( tmp < 0 ) {
            int tmp2 = myabs(i, next_i) + myabs(j, next_j);
            answer += tmp2;
            if ( tmp == NOT_YET_ANSWERED ) {
              answerMap[x][next] = tmp2;
            }
          }
          else {
            answer += tmp;
          }
          tmp = cache_value(answerMap, LL, next);
          if ( tmp == NOT_YET_ANSWERED ) {
            answerMap[LL][next] = answer;
          }
          x = next;
          i = next_i;
          j = next_j;
        }
      }
      else {
        answerMap[LL][RR] = answer;
      }
