int magic(pair<int,int> p, pair<int,int> q){
  return abs(p.first - q.first) + abs(p.second - q.second);
}

int main(){
  int H, W, D, A, Q, L, R, ans = 0;
  map<int, pair<int,int>> mapping;
  cin >> H >> W >> D;
  for(int i = 0; i < H; ++i){
    for(int j = 0; j < W; ++j){
      cin >> A;
      mapping[A] = {i,j};             //マスの値をキーとしてそのマスの座標を保存
    }
  }
  pair<int, int> rook, next;          //駒と移動先の座標
  cin >> Q;
  for(int i = 0; i < Q; ++i){
    cin >> L >> R;
    ans = 0;
    rook = mapping[L];                //コマの位置を値Lが書かれている座標に初期化
    for(int j = L; j < R; j += D){
      next = mapping[j + D];          //移動先は現在位置の値からDだけ大きい値が書かれている座標
      ans += magic(rook, next);       //移動に消費する魔力を計算
      rook = next;
    }
    cout << ans << endl;
  }
  return 0;
}

