    auto H = read<i64>();
    auto W = read<i64>();
    auto D = read<i64>();
    auto As = make_matrix<i64, 2>({H, W}, 0);
    REP (i, H) {
        REP (j, W) {
            As[i][j] = read<i64>();
        }
    }
    auto Q = read<i64>();
    auto qs = read<i64, i64>(Q);

    OrderedMap<i64, pair<i64, i64>> n2p;
    REP (i, H) {
        REP (j, W) {
            n2p[As[i][j] - 1] = {i, j};
        }
    }

    // ns[x][n] := x??x+nD???????????
    auto ns = make_matrix<i64, 2>({D, H * W / D + 1}, 0);
    REP (x, D) {
        auto p = n2p[x];
        ns[x][0] = 0;

        i64 n = 1;
        while (true) {
            auto y = x + n * D;
            if (y >= H * W) break;

            auto p2 = n2p[y];
            auto m = std::abs(p2.first - p.first) + std::abs(p2.second - p.second);

            ns[x][n] = ns[x][n - 1] + m;

            p = p2;
            n += 1;
        }
    }

    EACH (q, qs) {
        auto R = q.first - 1;
        auto L = q.second - 1;

        auto x = L % D;
        auto n1 = (L - x) / D;
        auto n2 = (R - x) / D;

        cout << ns[x][n1] - ns[x][n2] << endl;
    }
}

