		int dis = 0;
		cin >> start >> end;
		if (start == end) {
			cout << 0 << endl;
			continue;
		}
		auto s = find(forest.at(start%d).begin(), forest.at(start%d).end(), start);
		auto e = find(forest.at(end%d).begin(), forest.at(end%d).end(), end);
		auto before = s;
		for (auto j = s; j <= e; j++) {
			if (j == s)continue;
			dis += abs(before->first - j->first) + abs(before->second - j->second);
			before = j;
		}
		cout << dis << endl;
	}
	return 0;
}

