int memo[400][400];
int dfs(int l, int r, int d, const vector<vector<int>> &A, const vector<P> &s) {
  if (l == r) return 0;
  if (memo[l][r] != 0) return memo[l][r];
  return memo[l][r] = abs(s[l].first - s[l + d].first) +
                      abs(s[l].second - s[l + d].second) +
                      dfs(l + d, r, d, A, s);
}
