const int Nmax=200010;

int main() {
	int H,W,D;
	cin >> H >> W >> D; //H×W D移動幅
	int A[300][300],Ax[Nmax]={},Ay[Nmax]={}; //(x,y) に書かれている整数
	for(int i=0;i < H;i++){
		for(int j=0;j < W;j++){
			cin >> A[i][j];
			Ax[A[i][j]]=i; //A[i][j]の値が書かれているマスのx座標
			Ay[A[i][j]]=j; //A[i][j]の値が書かれているマスのy座標
		}
	}
	int Q,L[Nmax],R[Nmax]; //L i回目の初期位置 R i回目のgoal Q実技試験数
	cin >> Q;
	for(int i=0;i < Q;i++) cin >> L[i] >> R[i];

	int n=0,X,Y,I,J,ans;
	for(int i=0;i < Q;i++){
		ans=0;n=0;
		for(;;){
			X = Ax[L[i]+n*D];
			Y = Ay[L[i]+n*D];
			if(A[X][Y] == R[i]) break;
			n++;
			I=Ax[L[i]+n*D];
			J=Ay[L[i]+n*D];
			ans+=abs(X-I)+abs(Y-J);
		}
		cout << ans << endl;
	}

	return 0;
}

