ll memo[305][305];
ll solve(int from, int to) {
    if(from == to) return 0;

    ll& ret = memo[from][to];
    if(ret != -1) return ret;
    ret = 0;

    int y = r[from].F;
    int x = r[from].S;
    int ny = r[from+d].F;
    int nx = r[from+d].S;
    int cost = abs(y - ny) + abs(x - nx);
    ret = solve(from+d, to) + cost;
    return ret;
