class D {
	int rows, cols;
	int d, q;
	vector<pii> pos;
	vector<ll> memo;
public:
	D()
	{
		cin >> rows >> cols;
		cin >> d;

		pos.resize(rows * cols + 1);
		memo.resize(rows * cols + 1);

		int v;
		REP(y, rows)
			REP(x, cols)
		{
			cin >> v;
			pos[v] = MP(y, x);
		}

		cin >> q;

	}

	inline ll diff(const int& s, const int& g)
	{
		return (ll)abs(pos[s].first - pos[g].first) + abs(pos[s].second - pos[g].second);
	}

	void memoize()
	{

		for (int s{ 1 }; s <= d; s++)
		{
			memo[s] = 0;

			for (int g{ s + d }; g <= rows * cols; g += d)
				memo[g] = memo[g - d] + diff(g, g - d);

		}

	}

	void solve()
	{
		memoize();

		int s, g;
		REP(_q, q)
		{
			ll ans{ 0 };
			cin >> s >> g;

			ans += memo[g] - memo[s];

			cout << ans << endl;
		}

