int main(){
  int h,w,d;
  cin >> h >> w >> d;
  map<int,pair<int,int>> dict;
  for(int i = 0;i < h;i++){
    for(int j = 0;j < w;j++){
      int a;
      cin >> a;
      dict[a] = make_pair(i+1,j+1);
    }
  }

  map<int,int> dist;
  for(int i = 1;i <= h * w;i++)dist[i] = -1;

  for(auto p:dict){
    if(dist[p.first] != -1)continue;
    dist[p.first] = 0;
    int now = p.first;
