      int nx = dict[now+d].second;
      sum += abs(x - nx) + abs(y - ny);
      dist[now+d] = sum;
      now += d;
      x = nx;
      y = ny;
    }
  }

  int q;
  cin >> q;
  vector<int> ans(q);
  for(int i = 0;i < q;i++){
    int l,r;
    cin >> l >> r;
    ans[i] = dist[r] - dist[l];
  }

  for(int i = 0;i < q;i++)cout << ans[i] << endl;
}

