std::tuple<int, int>
find_pos(int h,
         std::vector<std::vector<int>> const & table,
         int number) {
  for (int y=0; y<h; y++) {
    auto res = std::find(table[y].begin(),
                         table[y].end(),
                         number);
    if (res != table[y].end()) {
      return std::make_tuple(std::distance(table[y].begin(), res),
                             y);
    }
  }
}

int
move_piece(std::tuple<int, int> a,
           std::tuple<int, int> b) {
  return
    std::abs(std::get<0>(a) - std::get<0>(b)) +
    std::abs(std::get<1>(a) - std::get<1>(b));
}

