int main()
{
	int H, W, D;
	cin >> H >> W >> D;

	vector<pair<int, int>> v(H * W);
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < W; ++j) {
			int A;
			cin >> A;
			v[A - 1] = make_pair(i, j);
		}
	}

	auto mp = [&](int x, int y) {
		return abs(v[x].first - v[y].first) + abs(v[x].second - v[y].second);
	};

	vector<vector<int>> ans(H * W, vector<int>(H * W));

	for (int s = 0; s < D; ++s) {
		ans[s][s] = 0;
		for (int x = s + D; x < H * W; x += D) {
			ans[s][x] = ans[s][x - D] + mp(x - D, x);
		}
	}

	int Q;
	cin >> Q;
	for (int i = 0; i < Q; ++i) {
		int L, R;
		cin >> L >> R;
		--L;
		--R;
		if (L == R) {
			cout << 0 << endl;
		}
		else {
			cout << ans[L % D][R] - ans[L % D][L] << endl;
		}
	}
}

