struct point{
	int x;
	int y;
	int p;
	bool operator<(const point& another) const {
		return p < another.p;
	}
};

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int h, w, d, a[300][300], q, l, r, p;
	vector<unsigned long long int> result;
	unordered_map<int,vector<point>> memo;
	cin >> h >> w >> d;
	for (int i = 0; i < h; ++i) {
		for (int k = 0; k < w; ++k) {
			cin >> a[i][k];
		}
	}
	for (int g = 0; g < d; ++g) {
		vector<point> list;
		for (int i = 0; i < h; ++i) {
			for (int k = 0; k < w; ++k) {
				if ((a[i][k] - g) % d == 0) {
					point tmp;
					tmp.x = i;
					tmp.y = k;
					tmp.p = a[i][k];
					list.push_back(tmp);
				}
			}
		}
		sort(list.begin(), list.end());
		memo[g] = list;
	}
	cin >> q;
	for (int g = 0; g < q; ++g) {
		unsigned long long int tmpresult = 0;
		cin >> l >> r;
		p = l;
		int index = l % d;
		vector<point> list = memo[index];

		point last = list[0];
		list.erase(list.begin());
		for (auto tmp : list) {
			if (tmp.p <= l) {
				last = tmp;
				continue;
			}
			if (tmp.p > r) break;
			tmpresult += abs(last.x - tmp.x) + abs(last.y - tmp.y);
			last = tmp;
		}
		result.push_back(tmpresult);
	}
	for (auto tmp : result) {
		cout << tmp << endl;
	}
	return 0;
}

