using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(i, n) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ')
#define DUMP2D(a, n, m) REP(i, n) REP(j, m) printf("%d%c", a[i][j], j + 1 == m ? '\n' : ' '); puts("")

typedef long long ll;

const int H_MAX = 300;
const int W_MAX = 300;
const int Q_MAX = 100000;
const int N_MAX = H_MAX * W_MAX;
const int N_LOG = 16;

int H, W, D;
int A[H_MAX][W_MAX];
int Q;
int L[Q_MAX];
int R[Q_MAX];

int N;
int ph[N_MAX];
int pw[N_MAX];
int m[N_LOG + 1][N_MAX];

void solve() {
  N = H * W;
  REP(i, H) REP(j, W) {
    ph[A[i][j] - 1] = i;
    pw[A[i][j] - 1] = j;
  }
  REP(i, N - D) {
    m[0][i] = abs(ph[i] - ph[i + D]) + abs(pw[i] - pw[i + D]);
  }

  int d = D;
  REP(j, N_LOG) {
    REP(i, N - d) {
      m[j + 1][i] = m[j][i] + m[j][i + d];
    }
    d <<= 1;
  }

  // DUMP2D(m, 5, N);

  REP(i, Q) {
    ll ans = 0;
    int f = L[i] - 1, t = R[i] - 1;
    int l = (t - f) / D;
    int d = D;
    FOR(k, 0, N_LOG) {
      if (l == 0) break;
      if (l & 1) {
        // printf("k=%d,f=%d\n", k, f);
        ans += m[k][f];
        f += d;
      }
      l >>= 1;
      d <<= 1;
    }
    printf("%lld\n", ans);
  }
}

void input() {
  scanf("%d%d%d", &H, &W, &D);
  REP(i, H) REP(j, W) scanf("%d", &A[i][j]);
  scanf("%d", &Q);
  REP(i, Q) scanf("%d%d", L + i, R + i);
}

int main() {
  input();
  solve();
  return 0;
}

