using namespace std;
int q,n ,m,d;map <int,pair<int,int>> mp;vector <int> ans;
void solve(int x,int y)
{
  long long sum = 0,u = x;
  while(u != y - d)
  {
    u+=d;
    sum = abs(abs(mp[u].first - mp[x].first)+ abs(mp[u].second - mp[x].second));
    sum += abs(abs(mp[u].first - mp[y].first)+ abs(mp[u].second - mp[y].second));
  }
  ans.push_back(sum);
}
int main()
{
  cin>>n>>m>>d;
  for(int i = 1 ; i <= n ;i ++)
  {
    for(int j = 1; j <= m ;j ++)
    {
      int o;
      cin>>o;
      mp[o].first = i;
      mp[o].second = j;
    }
  }
  cin>>q;
  for(int i =0 ; i < q;i ++)
  {
     int l,r;
    cin>>l>>r;
    if(l == r)
    {
      ans.push_back(0);
    }else
    {
      solve(l,r);
    }
  }
  for(int i =0 ; i < ans.size(); i ++)
  {
    cout<<ans[i]<<endl;
  }
}

