vector<int> empty;
vector<vector<int> > a;
vector<pair<int,int> > loc;
int calc(int l, int r, int d){
	int x, y;
	x = loc[l].first;
	y = loc[l].second;
	int res = 0;
	while(l != r){
		l += d;
		int x1 = loc[l].first;
		int y1 = loc[l].second;
		res += abs(x1 - x) + abs(y1 - y);
		x = x1;
		y = y1;
	}
	return res;
}
int main(){
	int h, w, d, l, r; 
	cin>>h>>w>>d;
	empty.resize(w);
	a.resize(h, empty);
	loc.resize(h * w + 1);
	for(int i = 0; i < h; ++i){
		for(int j = 0; j < w; ++j){
			cin>>a[i][j];
			a[i][j]--;
			loc[a[i][j]] = make_pair(i, j);
		}
	}
	vector<int> distance(h * w + 1, 0);
	for(int i = 0; i <= h * w; ++i){
		int r = i;
		int l = r - d;
		if(l < 0)continue;
		int x = calc(l, r, d);
		distance[i] = x;
	}
	int q;
	cin>>q;
	for(int i = 0; i < q; ++i){
		cin>>l>>r;
		l--, r--;
		int res = 0;
		for(int j = l + d; j <= r; j += d){
			res += distance[j];
		}
		cout<<res<<endl;
	}
	return 0;
}

