class D {
	int rows, cols;
	int d, q;
	vector<vector<pii>> pos;
	vector<vector<ll>> memo;
public:
	D()
	{
		cin >> rows >> cols;
		cin >> d;

		pos.resize(d, vector<pii>((int)ceil((double)rows * cols / d)));

		int v;
		REP(y, rows)
			REP(x, cols)
		{
			cin >> v;

			pos[v % d][(v - v % d) / d] = MP(y, x);
		}

		cin >> q;

	}

	inline ll diff(const pii& left, const pii& right)
	{
		return ((ll)abs(left.first - right.first) + abs(left.second - right.second));
	}

	void memoize()
	{
		memo.resize(d, vector<ll>((int)ceil((double)rows * cols / d)));

		REP(y, d)
		{		
			memo[y][0] = 0;

			REP1O(x, SZ(memo[y]))
			{
				memo[y][x] = memo[y][x - 1] + diff(pos[y][x], pos[y][x - 1]);
			}
		}

	}

	void solve()
	{
		memoize();

		int s, g;
		REP(_q, q)
		{
			ll ans{ 0 };
			cin >> s >> g;

			ans += memo[g % d][(g - g % d) / d] - memo[s % d][(s - s % d) / d];

			cout << ans << endl;
		}


	}
};


int main()
