int myabs(int a, int b) {
  if ( a > b ) {
    return a - b;
  }
  else {
    return b - a;
  }
}

int main() {
  int H, W, D;
  cin >> H >> W >> D;
  vector<int> ii(H*W), jj(H*W);
  rep(i,H) {
    rep(j,W) {
      int A;
      cin >> A;
      ii.at(A-1) = i;
      jj.at(A-1) = j;
    }
  }
  int Q;
  cin >> Q;
  int L, R;
  map<int,map<int,int>> cache;
  rep(q,Q) {
    cin >> L >> R;
    int answer = 0;
    bool cache_found = false;
    if ( cache.count(L) ) {
      if ( cache.at(L).count(R) ) {
        answer = cache.at(L).at(R);
        cache_found = true;
      }
    }
    if ( cache_found == false ) {
      if ( L < R ) {
        int x = L;
        int i = ii.at(x-1);
        int j = jj.at(x-1);
        while(x < R) {
          int next = x + D;
          int next_i = ii.at(next-1);
          int next_j = jj.at(next-1);
          answer += myabs(i, next_i) + myabs(j, next_j);
          x = next;
          i = next_i;
          j = next_j;
        }
      }
      cache[L][R] = answer;
    }
    cout << answer << endl;
  }
}

