  }
  vector<BIT<int>> tree(d,BIT<int>(h*w/d+1));
  for(int i = 0;i < h*w;i++){
    if(i/d == 0) tree[i%d].add(0,0);
    else {
      int cost = abs(mp[i]/w - mp[i-d]/w) + abs(mp[i]%w - mp[i-d]%w);
      //printf("%d %d %d %d\n",i,cost,mp[i],mp[i-d]);
      tree[i%d].add(i/d,cost);
    }
  }

  int q;cin >> q;
