long long solve(long long lval, long long rval){
	if(lval == rval)
		return 0;
	if(memo[lval][rval] != 0)
		return memo[lval][rval];

	long long tmp = solve(lval + D, rval);
	tmp += abs(posmap[lval].first - posmap[lval + D].first);
	tmp += abs(posmap[lval].second - posmap[lval + D].second);
	memo[lval][rval] = tmp;
	return tmp;
}

