int main(){
    ll H, W, D; cin >> H >> W >> D;
    vvl as(H, vl(W, 0)); REP(i, H) REP(j, W) cin >> as[i][j];
    ll Q; cin >> Q;
    vl ls(Q,0), rs(Q,0); REP(i, Q) cin >> ls[i] >> rs[i];

    vector<map<ll, PL>> vmap(D);
    REP(i, H){
        REP(j, W){
            ll a = as[i][j];
            vmap[a % D][a] = P(i, j);
        }
    }

    vvl cost_sum(D);
    REP(i, D){
        ll sum = 0; PL p_pre = vmap[i].begin()->ss;
        cost_sum.reserve(vmap[i].size());
        FORMAP(it, vmap[i]){
            if(cost_sum[i].size() == 0){
                cost_sum[i].pb(0); continue;
            }
            PL p_cur = it->ss;
            sum += abs(p_cur.ff - p_pre.ff) + abs(p_cur.ss - p_pre.ss);
            cost_sum[i].pb(sum);
            p_pre = it->ss;
        }
    }

    REP(i, Q){
        ll l = ls[i], r = rs[i]; auto m = cost_sum[l % D];
        ll ridx = r/D - (r%D==0 ? 1 : 0);
        ll lidx = l/D - (l%D==0 ? 1 : 0);
        cout << m[ridx] - m[lidx] << endstr;
    }
    return 0;
}

