vector<LL> ans;

void solve(){
	//i(1<=i<=D)と書かれたマスからjと書かれたマスに移動するのに必要なコストをcost[i][j]とおく
	vector<vector<LL>> cost(H*W+1,vector<LL>(H*W+1,-1));
	for(int i=1;i<=D && i<=H*W;i++) cost[i][i] = 0;

