using namespace std;

int memo[301][301];
int dfs(int x, int y, int L, int R, int D, vector<pair<int,int>>& mp) {
  if (memo[L][R] != -1) return memo[L][R];
  if (L == R) return 0;
  int nx = mp[L + D].first, ny = mp[L + D].second;
  int cost = dfs(nx, ny, L+D, R, D, mp) + abs(x - nx) + abs(y - ny);
  return memo[L][R] = cost;
}

int main(void) {
  int H, W, D;
  cin >> H >> W >> D;
  vector<vector<int>> A(H, vector<int>(W));
  vector<pair<int,int>> mp(H * W + 1);
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      cin >> A[i][j];
      mp[A[i][j]] = pair<int,int>(j, i);
    }
  }
  memset(memo, -1, sizeof(memo));
  int Q;
  cin >> Q;
  for (int i = 0; i < Q; i++) {
    int L, R;
    cin >> L >> R;
    cout << dfs(mp[L].first, mp[L].second, L, R, D, mp) << endl;
  }

  return 0;
}

