#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

//累積和の問題
//R-L % D == 0であるから，R%D ≡ L%D = xとおく
//クエリは，（xからRに行くためにかかるコスト）-（xからLに行くためにかかるコスト）に単純化される
//即ち，y = 0~D-1において，xからyまでDずつ移動するのにかかるコストをtableで保持し，table[x][y]をもとにクエリ処理する
//計算量は，(D*(H*W) + Q)で，十分間に合う

ll H, W, D;
vector<pair<ll, ll>> idx;
vector<vector<ll>> table;

void tableau() {
    for (int i = 0; i < D; i++) {
        table[i][i] = 0;
        ll s = i;
        ll g = i+D;
        while(g < H*W) {
            ll cost = abs(idx[s].first - idx[g].first) + abs(idx[s].second-idx[g].second);
            table[i][g] = table[i][s] + cost;
            s += D;
            g += D;
        }
    }
}

int main() {
    cin >> H >> W >> D;
    idx.resize(H*W);
    table.resize(D, vector<ll> (H*W));
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            ll a; cin >> a; a--;
            idx[a] = make_pair(i, j);
        }
    }
    tableau();
    ll Q; cin >> Q;
    for (int i = 0; i < Q; i++) {
        ll L, R; cin >> L >> R; L--; R--;
        ll dist;
        ll s = L%D;
        dist = table[s][R]-table[s][L];
        cout << dist << endl;
    }
}

