    for(int i = 0; i < h; i++)
        for(int j = 0; j < w; j++) {
            cin >> g[i][j];
            l[g[i][j]] = i;
            c[g[i][j]] = j;
        }

    build();
    int q; cin >> q;
    while(q--) {
        int a,b; cin >> a >> b;
        cout << query(a,b) << endl;
    }

    return 0;
}

