int main(){
	int h, w, d;
	int max = h*w;

	cin >> h >> w >> d;

	for(int i=0; i<h; i++)
		for(int j=0; j<w; j++){
			int a;
			cin >> a;
			y[a] = i;
			x[a] = j;
		}

	for(int n=1; n<=max; n++){
		if(n+d <= max)
			costs[n][0] = dist(n, n+d);
	}

	for(int t=1; t<20; t++){
		for(int n=1; n<=max; n++){
			long long next = n + d*(1<<t);
			if(next <= max)
				costs[n][t] = costs[n][t-1] + costs[(n+next)/2][t-1];
		}
	}


	int q;
	cin >> q;

	for(int i=0; i<q; i++){
		int l, r;
		cin >> l >> r;

		int gap = (r - l)/d;
		int ans = 0;

		int doubling = 1;
		for(int t=0; t<20; doubling*=2,t++){
			if(doubling > max)
				break;

			if(gap & doubling){
				ans += costs[l][t];
				l += d * doubling;
			}
		}

		cout << ans << endl;

	}


	return 0;
}

