int power(int L, int R,int D, int H, int W, int A[][])
{
	int ans = 0;
	int x, y,px,py;
	for (int k = 0; k < (R - L) / D; k++) {
		for (int l = 0; l < H; l++)
			for (int m = 0; m < W; m++)
				if (A[l][m] == L)
					x, y = l, m;
		if (k != 0)
			ans += (x - px) > 0 ? x - px : -(x - px) + (y - py) > 0 ? y - py : -(y - py);
			px, py = x, y;
		L += D;
	}
	cout << ans
}

