class masu{
 public:
  int x;
  int y;
  masu(){x=0,y=0;}
  masu(int a,int b){
    this->x=a;
    this->y=b;
  };
};


int kyori(int x1,int x2,int y1,int y2){
  return abs(x1-x2) + abs(y1-y2);
}
int masu_kyori(masu a,masu b){
  return kyori(a.x,b.x,a.y,b.y);
}

int siken(int L, int R, vector<masu>& M, int D){
  int cost = 0;
  while(L!=R){
    cost += masu_kyori(M[L],M[L+D]);
    L += D;
  }
  return cost;
}

