    vector<pair<ll, ll>> xy(H * W); //座標を数字から逆算できるようにする
    loop(i, H) loop(j, W)
    {
        cin >> field[i][j];
        field[i][j]--;
        xy[field[i][j]] = make_pair(i, j);
    }
    ll Q;
