class Solver {
public:
  int H, W;

  bool ng(int y, int x) {
    return y < 0 || H <= y || x < 0 || W <= x;
  }

  struct Point {
    int y, x;
  };

  int D, Q, N;
  vector<Point> p;
  vector<int> dist;

  void shortest_path_search() {
    dist.resize(N);
    rep2(i, 1, D + 1) {
      dist[i] = 0;
      for (int j = i + D; j < N; j += D) {
        dist[j] = dist[j - D] + abs(p[j].y - p[j - D].y) + abs(p[j].x - p[j - D].x); 
      }
    }
  }

  void solve() {
    cin >> H >> W >> D;
    N = H * W + 1;
    p.resize(N);
    rep(y, H) rep(x, W) {
      int v; cin >> v;
      p[v] = {y, x};
    }

    shortest_path_search();

    cin >> Q;
    rep(i, Q) {
      int l, r; cin >> l >> r;
      cout << dist[r] - dist[l] << endl;
    }
  }
};

