using namespace std;

struct Number{
     int line;
     int row;
};

int main(){
    int H, W, D;
    cin >> H >> W >> D;
    int A[90000];
    for(int i=0;i<H*W;i++)
        cin >> A[i];

    //1からH*Wまで座標を求める
    struct Number N[90001];
    for(int i=1;i<=H*W;i++){
        //iを探す
        for(int j=0;j<H*W;j++){
            if(A[j]==i){
                N[i].line = j/H + 1; //行
                N[i].row = j%W + 1; //列
            }
        }
    }

    //実技試験の回数Q
    int Q;
    cin >> Q;
    int L[100000], R[100000];
    for(int i=0;i<Q;i++)
        cin >> L[i] >> R[i];

    //Q回実技試験を行う
    int count;
    int sum = 0;
    for(int i=0;i<Q;i++){
        //1回の試験における移動回数
        count = (R[i] - L[i])/D;
        int num;
        num = L[i];
        for(int j=0;j<count;j++){
            sum += abs(N[num + D].line - N[num].line) + abs(N[num + D].row - N[num].row);
            //cout << abs(N[num + D].line - N[num].line) << " + " << abs(N[num + D].row - N[num].row) << endl;
            num += D;
        }
        cout << sum << endl;
      	sum = 0;
    }
    return 0;
}

