using namespace std;

int dist(pair<int,int> a, pair<int,int> b){
    int x,y;
    x=a.first-b.first;
    if(x<0) x*=-1;
    y=a.second-b.second;
    if(y<0) y*=-1;

    return x+y;
}

int main(){
    int H,W,D;
    cin >> H >> W >> D;

    map<int,pair<int,int>> bd;
    for(int i=1;i<=H;i++){
        for(int j=1;j<=W;j++){
            int A;
            cin >> A;
            bd[A]=make_pair(i,j);
        }
    }

    int Q;
    cin >> Q;

    unsigned long long d[180001];
    for(int i=1;i<=D;i++){
        int max=0;
        for(int j=0;j*D+i<=H*W;j++){
            d[j*D+i]=dist(bd[j*D+i],bd[j*D+i+D]);
            max=j;
        }
        for(int j=max-1;j>=0;j--){
            d[j*D+i]+=d[j*D+i+D];
        }
    }

    for(int i=0;i<Q;i++){
        int L,R;
        cin >> L >> R;

        cout << (d[L]-d[R]) << endl;
    }

    return 0;
}

