using namespace std;

vector<vector<int>> grid;

void Main() {
    int H, W, D;
    cin >> H >> W >> D;
    map<int, pair<int, int>> indexes;
    grid = vector<vector<int>>(H, vector<int>(W, 0));
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            cin >> grid[i][j];
            indexes.insert(make_pair(grid[i][j], make_pair(i, j)));
        }
    }
    int Q;
    cin >> Q;
    map<int, int> memo;
    for (int i = 0; i < Q; ++i) {
        int l, r;
        cin >> l >> r;
        if (memo.count(l) > 0) {
            cout << memo[l] << endl;
            continue;
        }

        int power = 0;
        int x = l;
        pair<int, int> curr_ij = indexes[x];
        while (x != r) {
            int next_x = x + D;
            pair<int, int> next_ij = indexes[next_x];
            power += abs(next_ij.first - curr_ij.first) + abs(next_ij.second - curr_ij.second);
            x = next_x;
            curr_ij = next_ij;
        }
        memo.insert(make_pair(l, power));
        cout << power << endl;
    }
}

int main() {
    std::cout << std::fixed << std::setprecision(15);
    Main();
    return 0;
}

