int recur(int L, int R, int D, unordered_map<pii, int> &memo, unordered_map<int, pii> &m){

    if( L == R ) return 0;
    if( memo[pii(L, R)]!= -1 ) return memo[pii(L, R)];

    auto prev = m[L];
    auto next = m[L+D];
    int res = recur(L+D, R, D, memo, m) + abs(prev.first-next.first) + abs(prev.second-next.second);
    memo[pii(L, L+D)] = res;
    return res;

}

