using namespace std;
int main() {
	int h, w, d; cin >> h >> w >> d;
	pair<int, int> a[1000];
	for (int i = 1; i <= h; i++) {
		for (int j = 1; j <= w; j++) {
			int k; cin >> k;
			a[k] = make_pair(i, j);
		}
	}
	int cost[1000];
	for (int i = 1; i <= h*w; i++) {
		if (i <= d)cost[i] = 0;
		else {
			int xi = a[i].first - a[i - d].first;
			int yj = a[i].second - a[i - d].second;
			cost[i] = cost[i - d] + abs(xi) + abs(yj);
		}
	}
	int q; cin >> q;
	for (int i = 0; i < q; i++) {
		int l, r; cin >> l >> r;
		cout << cost[r] - cost[l] << endl;
	}
}

