int main(){
	int H,W,D,Q;
	cin >> H >> W >> D;
	vector<vi> B(H*W,vi(2));
	for(int i=1; i<=H; i++){
		for(int j=1; j<=W; j++){
			int A;
			cin >> A;
			A--;
			B[A][0]=i;
			B[A][1]=j;
		}
	}
	cin >> Q;
	vi L(Q),R(Q);
	for(int i=0; i<Q; i++){
		cin >> L[i] >> R[i];
		L[i]--;
		R[i]--;
	}

	vector<vi> dp(D,vi(0));
	for(int i=0; i<D; i++){
		dp[i%D].push_back(abs(B[i+D][0]-B[i][0])+abs(B[i+D][1]-B[i][1]));
	}
	for(int i=D; i<H*W-D; i++){
		dp[i%D].push_back(dp[i%D][dp[i%D].size()-1]+abs(B[i+D][0]-B[i][0])+abs(B[i+D][1]-B[i][1]));
	}

	for(int i=0; i<Q; i++){
		int end=R[i]/D;
		int start=L[i]/D;
		int ans=0;
		if(end>0){
			ans=dp[L[i]%D][end-1]-dp[L[i]%D][start-1];
		}else{
			ans=dp[L[i]%D][end-1];
		}
		cout << ans << endl;
	}

	return 0;
}

