			if(tests[i][0] == tests[j][0] &&
					tests[i][1] == tests[j][1]){
				cost = tests[j][2];
				has = true;
				break;
			}
		}

		if(L != R && !has){
			now = a[L];

			for(;;){
				L += D;
				next = a[L];
				int d = now.dist(next);
				cost += d;
				if(L == R) break;
				now = next;
			}
		}

		tests[i][0] = cost;
		cout << cost << endl;

	}

	return 0;
}

