int calcMagicPower(vector<int> A, int start, int end, int preX, int preY, int w, int D){
    auto itr = find(A.begin(), A.end(), start);
    int index = itr - A.begin();
    int x = index / w;
    int y = index % w;
    int magicalPower = abs(x - preX) + abs(y - preY);

    if(start == end){
        return magicalPower;
    }else{
        return magicalPower + calcMagicPower(A, start + D, end, x, y, w, D);
    }
}

