			cin >> buf;
			x[buf] = i;
			y[buf] = j;
		}
	}
	cin >> Q;
	for(i=0;i<Q;i++){
		cin >> L >> R;
		dl = test_dp(L,D,x,y,dp);
		dr = test_dp(R,D,x,y,dp);
		cout << (dr-dl) << endl;
	}
	delete[] dp;
	delete[] x;
	delete[] y;
	return 0;
}

int test_dp(int n,int D,int *x,int *y,int *dp){
	if(dp[n] != -1) return dp[n];
	dp[n] = test_dp(n-D,D,x,y,dp) + abs(x[n]-x[n-D]) + abs(y[n]-y[n-D]);
	return dp[n];
}

