using namespace std;

map<int, pair<int, int>> p;
map<int, int> d;

int main()
{
    int H, W, D;
    if (scanf("%d%d%d", &H, &W, &D) < 3) return 0;

    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            int x;
            if (scanf("%d", &x) < 1) return 0;
            p[x] = {i, j};
        }
    }

    map<int, pair<int, int>>::reverse_iterator ri = p.rbegin();
    int mx = ri->first;

    while (ri != p.rend())
    {
        int key = ri->first;
        pair<int, int> nw = ri->second;

        if (key <= mx - D)
        {
            int nxkey = key + D;
            pair<int, int> nx = p[nxkey];

            // Manhattan distance
            d[key] = abs(nx.first - nw.first) + abs(nx.second - nw.second);
            // Next distance
            d[key] += d[nxkey];
        }
        else
        {
            d[key] = 0;
        }

        ri++;
    }

    int Q;
    if (scanf("%d", &Q) < 1) return 0;
    for (int i = 0; i < Q; i++)
    {
        int L, R;
        if (scanf("%d%d", &L, &R) < 2) return 0;
        printf("%d\n", d[L] - d[R]);
    }

    return 0;
}

