void solve()
{
	ll h, w, d;  cin >> h >> w >> d;
	vector<vector<ll>> a = cinvv<ll>(h, w);
	ll q;  cin >> q;
	vector<pair<ll, ll>> lr = cinv2<ll, ll>(q);
	each(e, lr){
		e.first--; e.second--;
	}

	vpll ij(h*w);
	rep(i, 0, h-1)rep(j, 0, w-1){
		ll val=a[i][j];
		val--;
		ij[val]=pll(i, j);
	}

	vll sc(h*w);
	rep(i, 0, h*w-1){
		ll prei=i-d;
		if (prei<0)continue;
		ll x; ll y;  tie(x, y) = ij[i];
		ll px; ll py;  tie(px, py) = ij[prei];
		sc[i]=sc[prei]+abs(px-x)+abs(py-y);
	}
	vll ans;
	rep(i, 0, q-1){
		ll l; ll r;  tie(l, r) = lr[i];
		ans.push_back(sc[r]-sc[l]);
	}
	coutv(ans,"\n");
}

