        for(int j=0; j<W; j++){
            cin >> A[i][j];
            A[i][j]--;
        }
    }
    vector<vector<int>>Dists(D, vector<int>((H*W)/D + 1, 0));
    for(int k=0; k<D; k++){
        pair<int, int>prevP = searchA(k, A);
        Dists[k][0]=0;
        for(int i=1; i<(H*W)/D +1; i++){
            pair<int, int>tmpP = searchA(D*i+k, A);
            Dists[k][i]=mdist(tmpP, prevP);
