        }
    }
    int Q;
    cin >> Q;
    vector<pair<int, int>>T(Q); //L, R
    for(int i=0; i<Q; i++){
        cin >> T[i].first >> T[i].second;
        T[i].first--;
        T[i].second--;
    }
    for(int i=0; i<Q; i++){
        int surp=T[i].first % D;
        int ln=T[i].first/D, rn=T[i].second/D;
        int retd=0;
        for(int i=ln+1; i<=rn; i++){
            retd += Dists[surp][i];
        }
        cout << retd << '\n';
