i64 H, W;
i64 D;

vector<i64> X;
vector<i64> Y;

i64 cost(i64 a, i64 b) {
    return abs_diff(X[a],X[b]) + abs_diff(Y[a],Y[b]);
}

void solve() {
    vector<vector<i64>> table(D);
    REP(i, D) {
        table[i].emplace_back(0);
        for(i64 j = 1; i + D*j < H*W; ++j) {
            i64 a = i + D*(j-1);
            i64 b = i + D*j;
            i64 val = table[i].back() + cost(a,b);
            table[i].emplace_back(val);
        }
    }
    DBG(table);

    i64 Q; RD(Q);
    REP(_, Q) {
        i64 L, R; RD(L); RD(R); --L; --R; // 0-based

        i64 base = L % D;
        i64 ln = (L-base) / D;
        i64 rn = (R-base) / D;

        i64 ans = table[base][rn] - table[base][ln];
        PRINTLN(ans);
    }
}

signed main(signed /*argc*/, char** /*argv*/) {
    RD(H); RD(W);
    RD(D);

    X.resize(H*W);
    Y.resize(H*W);
    REP(y, H) REP(x, W) {
        i64 a; RD(a); --a; // 0-based
        X[a] = x;
        Y[a] = y;
    }



    solve();

    EXIT();
}

