int main(){
  int H, W, D, Q;
  cin >> H >> W >> D;

  vector<vector<long>> v(H, vector<long>(W));
  for (int i=0; i<H; i++)
    for (int l=0; l<W; l++)
      cin >> v[i][l];

  cin >> Q;
  vector<long> L(Q);
  vector<long> R(Q);
  for (int i=0; i<Q; i++)
    cin >> L[i] >> R[i];

  vector<pair<int,int>> vr(H*W+1);
  for (int i=0; i<H; i++) {
    for (int k=0; k<W; k++) {
      vr[v[i][k]] = make_pair(i+1, k+1);
    }
  }

  vector<vector<int>> memo(H*W+1, vector<int>(H*W+1, -1));
  for (int i=0; i<Q; i++) {
    if (L[i] == R[i]) {
      cout << 0 << endl;
      continue;
    }
    if (memo[L[i]][R[i]] != -1) {
      cout << memo[L[i]][R[i]] << endl;
      continue;
    }
    long res = 0;
    for (int k=L[i]+D; k<=R[i]; k+=D) {
      res += abs(vr[k].first - vr[k-D].first) + abs(vr[k].second - vr[k-D].second);
      memo[L[i]][k] = res;
    }
    cout << res << endl;
  }
}

