map<pair<int, int>, int> d;

int main() {
    int H, W, D;
    cin >> H >> W >> D;
    vector<int> A(H * W, 0);
    REP(i, H) {
        REP(j, W) { cin >> A[i * W + j]; }
    }
    int Q;
    cin >> Q;
    vector<int> L(Q);
    vector<int> R(Q);
    REP(i, Q) { cin >> L[i] >> R[i]; }
    REP(i, Q) {
        if(L[i] == R[i] and R[i] == 0) {
            cout << 0 << endl;
        } else {
            int cnt = 0;
            int prev = find(A.begin(), A.end(), L[i]) - A.begin();
            int pi = prev / W;
            int pj = prev - pi * W;
            m[L[i]] = make_pair(pi, pj);
            while(L[i] != R[i]) {
                if(d.count(make_pair(L[i], L[i] + D)) == 0) {
                    cnt += d[make_pair(L[i], L[i] + D)];
                } else {
                    L[i] += D;
                    int ni;
                    int nj;
                    if(m.count(L[i]) == 0) {
                        int next = find(A.begin(), A.end(), L[i]) - A.begin();
                        ni = next / W;
                        nj = next - W * ni;
                        m[L[i]] = make_pair(ni, nj);
                    }
                    ni = m[L[i]].first;
                    nj = m[L[i]].second;
                    d[make_pair(L[i], L[i] + D)] = abs(ni - pi) + abs(pj - nj);
                    cnt += d[make_pair(L[i], L[i] + D)];
                    pi = ni;
                    pj = nj;
                }
            }
            cout << cnt << endl;
        }
    }
}

