    int x[W * H + 1];
    int y[W * H + 1];

    int tmp;
    for(int i = 0; i < W * H; i++){
        cin>>tmp;
        x[tmp] = i / W;
        y[tmp] = i % W;
    } 

    int Q;
    cin>>Q;
    int L[Q];
    int R[Q];
    for(int i = 0; i < Q; i++){
        cin>>L[i]>>R[i];
    }
