		}
	}
	cin >> Q;
	for (int i = 0; i < Q; i++) cin >> L[i] >> R[i];
}

void preparation() {
	for (int i = 1; i <= D; i++) {
		int k = 0;
		while (i + (k+1) * D <= H*W) {
			p c_pos = pos[i + k * D]; // 移動前
			p n_pos = pos[i + (k + 1)*D]; // 移動先

			cost[i + (k + 1)*D] = cost[i + k * D] + abs(c_pos.first - n_pos.first) + abs(c_pos.second - n_pos.second);
			k++;
		}
	}
}

void solve() {
	for (int i = 0; i < Q; i++) {
		cout << cost[R[i]] - cost[L[i]] << " ";
	}
}

int main() {
	input();
	preparation();
	solve();

	return 0;
}

