using namespace std;

typedef long long ll;

ll H, W, D, Q;
struct Square {
    ll i;
    ll j;
};
Square A[100000];

int main()
{

    cin >> H >> W >> D;
    for (int i = 1; i <= H; ++i)
    {
        for (int j = 1; j <= W; ++j)
        {
            struct Square s = {i, j};
            ll p;
            scanf("%lld", &p);
            A[p] = s;
        }
    }

    cin >> Q;

    ll result[Q];
    for (int q = 0; q < Q; ++q)
    {
        int L, R;
        scanf("%d", &L);
        scanf("%d", &R);

        ll d = L;
        struct Square prev = A[d];
        result[q] = 0;
        while (d != R)
        {
            d += D;
            result[q] += abs(prev.i - A[d].i) + abs(prev.j - A[d].j);
            prev = A[d];
        }
    }
    for (int q = 0; q < Q; ++q)
    {
        printf("%lld\n", result[q]);
    }

    return 0;
}

