int main(){
    int H, W, D; cin >> H >> W >> D;
    vector<pair<int, int>> A(H*W+5);

    for(int i=1; i<=H; i++){
        for(int j=1; j<=W; j++){
            int a; cin >> a;
            A[a].first = i; A[a].second = j;
        }
    }

    ll dp[W*H+1][W*H+1];
    for(int i=0; i<W*H+1; i++) for(int j=0; j<W*H+1; j++) dp[i][j] = 0;

    for(int i=1; i<=W*H; i++){
        for(int j=i; j<=W*H; j+=D){
            if(i == j) dp[i][j] = 0;
            else dp[i][j] = dp[i][j-D] + abs(A[j].first - A[j-D].first) + abs(A[j].second - A[j-D].second);
        }
    }

    int q; cin >> q;
    vector<ll> ans(q);
    for(int i=0; i<q; i++){
        int L, R; cin >> L >> R;
        ans[i] = dp[L][R];
    }

    for(int i=0; i<q; i++) cout << ans[i] << endl;
}

