int main(void){
    //入力部分
    int H, W, D;
    cin>>H>>W>>D;

    int x[W * H];
    int y[W * H];

    int tmp;
    for(int i = 0; i < W * H; i++){
        cin>>tmp;
        tmp--;
        x[tmp] = i / W;
        y[tmp] = i % W;
    } 

    int Q;
    cin>>Q;
    int L[Q];
    int R[Q];
    for(int i = 0; i < Q; i++){
        cin>>L[i]>>R[i];
        L[i]--;
        R[i]--;
    }
    //入力部分終わり

    //動的計画法
    int memo[W * H][(W * H - 1)/ D + 1];

    for(int j = 0; j <= (W * H -1) / D; j++){
        for(int i = 0; i < W * H; i++){
            if(i + (j - 1) * D <= W * H && i +j* D < W * H){
                if(j == 0){
                    memo[i][j] = 0;
                }
                else 
                    if(j == 1) {
                        memo[i][j] = abs(x[i] - x[i+D]) + abs(y[i] - y[i+D]);
                    }
                    else{
                        memo[i][j] = memo[i][j-1] + memo[i+(j-1)*D][1];
                    }
            }else{
                memo[i][j] = 0;
            }
        }
    }

    for(int i = 0; i < Q; i++){
        cout<<memo[L[i]][(R[i]-L[i])/D]<<endl;
    }
    return 0;
}

