#include <stdio.h>
#include <stdlib.h>

#define MAX_LEN 300

int board[MAX_LEN][MAX_LEN];
int height, width, diff;
int current_x, current_y;

void search(int num)
{
  for(int x = 0; x < height; x++) {
    for(int y = 0; y < width; y++) {
      if(board[x][y] == num) {
        current_x = x;
        current_y = y;
        return;
      }
    }
  }
}

int go_next(int begin, int end)
{
  if(begin == end) {
    return 0;
  }
  int prev_x = current_x;
  int prev_y = current_y;
  search(begin + diff);
  int consumed_mp = abs(prev_x - current_x) + abs(prev_y - current_y);
  return go_next(begin+diff, end) + consumed_mp;
}

void solve(int begin, int end)
{
  search(begin);
  printf("%d\n", go_next(begin, end));
  return;
}

