int main(void){
    int H, W, D;

    scanf("%d%d%d", &H, &W, &D);

    int **masu;

    masu = (int **) malloc(sizeof(int *) * H);

    int i, j;

    for(i = 0; i < H; i ++){
        masu[i] = (int *) malloc(sizeof(int) * W);

        for(j = 0; j < W; j ++){
            scanf("%d", masu[i] + j);
        }
    }
    int *masu_x = (int *) malloc(sizeof(int) * (H * W + 1));
    int *masu_y = (int *) malloc(sizeof(int) * (H * W + 1));

    for(i = 0; i < H; i ++){
        for(j = 0; j < W; j ++){
            masu_x[masu[i][j]] = j;
            masu_y[masu[i][j]] = i;
        }
    }
    int Q;

    scanf("%d", &Q);

    int *sum = (int *) malloc(sizeof(int) * Q);
    int *L = (int *) malloc(sizeof(int) * Q);
    int *R = (int *) malloc(sizeof(int) * Q);

    int **sums = (int **) malloc(sizeof(int *) * H * W);

    for(i = 0; i < H*W; i ++){
        sums[i] = (int *) malloc(sizeof(int) * H * W);

        sums[i] = -1;
    }

    for(i = 0; i < Q; i ++){
        sum[i] = 0;

        scanf("%d%d", L + i, R + i);

        int sum2 = sums[L[i]][R[i]];

        if(sum2 >= 0){
            sum[i] = sum2;

            continue;
        }

        int x, y;
        int cur_L = L[i];
        x = masu_x[cur_L];
        y = masu_y[cur_L];

        while(cur_L < R[i]){
            int x2, y2;

            cur_L += D;

            x2 = masu_x[cur_L];
            y2 = masu_y[cur_L];

            sum[i] += abs(x2 - x) + abs(y2 - y);
            x = x2;
            y = y2;
        }
        sums[L[i]][R[i]] = sum[i];
    }
    for(i = 0; i < Q - 1; i ++){
        printf("%d\n", sum[i]);
    }
    printf("%d", sum[Q - 1]);

