#endif

	// 高さ・幅・移動量取得
	int liH, liW, liMv;
#ifdef D_TEST
	fgets(lc1Buf, sizeof(lc1Buf), szpFpT);
#else
	fgets(lc1Buf, sizeof(lc1Buf), stdin);
#endif
	sscanf(lc1Buf, "%d%d%d", &liH, &liW, &liMv);

	// 位置情報取得
	for (i = 1; i <= liH; i++) {
		for (j = 1; j <= liW; j++) {
			int liNo;
