		fgets(lc1Buf, sizeof(lc1Buf), szpFpT);
#else
		fgets(lc1Buf, sizeof(lc1Buf), stdin);
#endif
	}

	// 総和セット
	for (i = 1; i <= liMv; i++) {

		// 初期位置
		si1Sum[i] = 0;

		// 順に移動
		int liFNo = i;
		int liTNo;
		while (1) {
			liTNo = liFNo + liMv;
			if (liTNo > D_POS_MAX) {
				break;
			}
