typedef struct {
	int A;
	int x, y;
} ITEM;

int compare( const void *p, const void *q ) {
	return ((ITEM*)p)->A - ((ITEM*)q)->A;
}

int main() {
	ITEM *map;
	ITEM current;
	int H, W, D;
	int HW;
	int Q, L, R;
	int i,j,k;
	int idx;
	int S;
	int sum;

	scanf("%d", &H);
	scanf("%d", &W);
	scanf("%d", &D);
	HW = H*W;

	map = (ITEM *)malloc(HW * sizeof(ITEM));

	for(i = 0, idx = 0;i < W; i++) {
		for(j = 0;j < H;j++) {
			scanf("%d ", &map[idx].A);
			map[idx].x = j;
			map[idx].y = i;
			idx++;
		}
	}

	qsort( map, HW, sizeof(ITEM), compare );

	/*
	for(i = 0;i < H*W; i++) {
		printf("%d ", map[i].A);
	}printf("\n");
	*/

	scanf("%d", &Q);
	for(k = 0;k < Q;k++) {
		scanf("%d", &L);
		scanf("%d", &R);
		sum = 0;
		current.A = 0;
		S = L;

		for(i = 0;i < HW;i++) {
			if(map[i].A == S) {
				//printf("%d ", S);
				if(current.A != 0) {
					sum += abs(map[i].x - current.x) + abs(map[i].y - current.y);
				}
				current.A = map[i].A;
				current.x = map[i].x;
				current.y = map[i].y;
				S += D;
			}
			if(S > R) break;
		}//printf("\n");

		printf("%d\n", sum);
	}

	free(map);
	return 0;
}

#include <stdio.h>
typedef struct{
    int x;
    int y;
}point;

int abs(int a){
    return a > 0? a : -a;
}

int magic_power(point from, point to){
    return abs(from.x-to.x) + abs(from.y-to.y);
}

int main(){
    int H, W,D;
    int x, y;

    scanf("%d %d %d", &H, &W, &D);
    point A[H * W];
    int temp;

    for(y = 0; y < H; ++y){
        for(x = 0; x < W; ++x){
            scanf("%d", &temp);
            A[temp - 1].x = x;
            A[temp - 1].y = y;
        }
    }

    int Q, L, R;
    int ans = 0;
    int answers[H * W][H * W];

    for(y = 0; y < H * W; ++y){
        for(x = 0; x < H * W; ++x){
            answers[y][x] = -1;
        }
    }

    scanf("%d", &Q);
    for(x = 0; x < Q; ++x){
        ans = 0;
        scanf("%d %d", &L, &R);

        int firstL = L;
        if(answers[L - 1][R - 1] != -1){
            ans = answers[L - 1][R - 1];
        }else{
            while(L < R){
                if(answers[L - 1][L + D - 1] == -1){
                    answers[L - 1][L + D - 1] = magic_power(A[L - 1], A[L + D - 1]);
                }
                int s;
                for(s = firstL; s <= L; s+=D){
                    if(answers[firstL - 1][L + D - 1] != -1 && answers[firstL - 1][s - 1]!= -1){
                        answers[s - 1][L + D - 1] = answers[firstL - 1][L + D - 1] - answers[firstL - 1][s - 1];
                    }
                }

                ans += answers[L - 1][L + D - 1];
                answers[firstL - 1][L + D - 1] = ans;
                L+=D;
            }
        }

        printf("%d\n", ans);

    }
    return 0;
}

