    int i, j;

    for(i = 0; i < H; i ++){
        masu[i] = (int *) malloc(sizeof(int) * W);

        for(j = 0; j < W; j ++){
            scanf("%d", masu[i] + j);
        }
    }
    int *masu_x = (int *) malloc(sizeof(int) * (H * W + 1));
    int *masu_y = (int *) malloc(sizeof(int) * (H * W + 1));

    for(i = 0; i < H; i ++){
        for(j = 0; j < W; j ++){
            masu_x[masu[i][j]] = j;
            masu_y[masu[i][j]] = i;
        }
    }
    int Q;

    scanf("%d", &Q);

    int *sum = (int *) malloc(sizeof(int) * Q);
    int *L = (int *) malloc(sizeof(int) * Q);
    int *R = (int *) malloc(sizeof(int) * Q);

    for(i = 0; i < Q; i ++){
        sum[i] = 0;

        scanf("%d%d", L + i, R + i);

        int index = -1; //judge(L[i], R[i], L, R, i - 1);

        if(index >= 0){
            sum[i] = sum[index];

            continue;
        }

        int x, y;
        int cur_L = L[i];
        x = masu_x[cur_L];
        y = masu_y[cur_L];

        while(cur_L < R[i]){
