#include <stdio.h>
typedef struct{
    int x;
    int y;
}point;

int abs(int a){
    return a > 0? a : -a;
}

int magic_power(point from, point to){
    return abs(from.x-to.x) + abs(from.y-to.y);
}

int main(){
    int H, W,D;
    int x, y;

    scanf("%d %d %d", &H, &W, &D);
    point A[H * W];
    int temp;

    for(y = 0; y < H; ++y){
        for(x = 0; x < W; ++x){
            scanf("%d", &temp);
            A[temp - 1].x = x;
            A[temp - 1].y = y;
        }
    }

    int Q, L, R;
    int ans = 0;
    int answers[H*W][H*W];

    for(y = 0; y < H*W; ++y){
        for(x = 0; x < H*W; ++x){
            answers[y][x] = -1;
        }
    }

    scanf("%d", &Q);
    for(x = 0; x < Q;  ++x){
        ans = 0;
        scanf("%d %d", &L, &R);
        int firstL = L;
        if(answers[L - 1][R - 1] != -1){
            ans = answers[L - 1][R - 1];
        }else{
            while(L < R){
                ans += answers[L - 1][L + D - 1] != -1?
                answers[L - 1][L + D - 1]
                :(answers[L - 1][L + D - 1] = magic_power(A[L - 1], A[L + D - 1]));

                answers[firstL - 1][L + D - 1] = ans;
                L+=D;
            }
        }
        printf("%d\n", ans);
    }
    return 0;
}

