void pointSearchapply(int p, int *x, int *y, int h, int w, int a[h][w])
{
    int f = 0;
    int i, j;
    for (i = 0; i < h; i++) {
        for (j = 0; j < w; j++)
            if (p == a[i][j]) {
                *x = i;
                *y = j;
                f = 1;
                break;
            }
        if (f)
            break;
    }
}

