        long sum = 0;
        int e, f, g, hh;
        while (l != r) {

            pointSearchapply(l, &e, &f, h, w, a);
            pointSearchapply(l + d, &g, &hh, h, w, a);
            sum += abs(g - e) + abs (hh - f);
            l += d;
        }

        printf("%ld\n", sum);

    }

    return 0;
}

