    int *R = (int *) malloc(sizeof(int) * Q);

    for(i = 0; i < Q; i ++){
        sum[i] = 0;

        scanf("%d%d", L + i, R + i);

        int index = judge(L[i], R[i], L, R, i - 1);

        if(index >= 0){
            sum[i] = sum[index];

            continue;
        }

        int x, y;
        int cur_L = L[i];
        x = masu_x[cur_L];
        y = masu_y[cur_L];

        while(cur_L < R[i]){
            int x2, y2;

            cur_L += D;

            x2 = masu_x[cur_L];
            y2 = masu_y[cur_L];

            sum[i] += abs(x2 - x) + abs(y2 - y);
            x = x2;
            y = y2;
        }
    }
    for(i = 0; i < Q - 1; i ++){
        printf("%d\n", sum[i]);
    }
    printf("%d", sum[Q - 1]);

    return 0;
}

