void set_pos(int** values, int H, int W, int* fpx, int* fpy, int target_value) {
    int fps = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (values[i][j] == target_value) {
                *fpx = i;
                *fpy = j;
                fps = 1;
                break;
            }
