    for(i=0;i<H;i++){
        for(j=0;j<W;j++){
            if(j==0)A[i] = malloc(sizeof(long int)*(H+1));
            scanf("%ld ",&A[i][j]);
        }
    }

    long int Q;

    fgets(line,sizeof(line),stdin);
    sscanf(line,"%ld", &Q);

    long int *R = malloc(sizeof(long int)*Q);   
    long int *L = malloc(sizeof(long int)*Q);   

    for(i=0;i<Q;i++){
        fgets(line,sizeof(line),stdin);
        sscanf(line,"%ld %ld",&L[i],&R[i]);
    }

    int count=0;
    long int ans=0;

    for(k=0;k<Q;k++){

    long int *X = malloc(sizeof(long int)* ((R[k]-L[k])/D+1));   
    long int *Y = malloc(sizeof(long int)* ((R[k]-L[k])/D+1));   

        for(i=0;i<H;i++){
            for(j=0;j<W;j++){

                if( ((A[i][j]-L[k]) % D == 0) && (A[i][j] <= R[k] && A[i][j] >= L[k])){
                    X[(A[i][j]-L[k]) / D] = i;
                    Y[(A[i][j]-L[k]) / D] = j;
                    count += 1;
                }

            }
        }

        while(count-1>=0){
            ans += X[count]-X[count-1];
            ans += Y[count]-Y[count-1];
            count --;
            X[count] = 0;
            Y[count] = 0;
        }

        printf("%ld\n",ans);
        ans = 0;
        count = 0;        

        free(X);
        free(Y);
    }

