int main(void){
    int H, W, D;

    scanf("%d%d%d", &H, &W, &D);

    int **masu;

    masu = (int **) malloc(sizeof(int *) * H);

    int i, j;

    for(i = 0; i < H; i ++){
        masu[i] = (int *) malloc(sizeof(int) * W);

        for(j = 0; j < W; j ++){
            scanf("%d", masu[i] + j);
        }
    }
    int *masu_x = (int *) malloc(sizeof(int) * (H * W + 1));
    int *masu_y = (int *) malloc(sizeof(int) * (H * W + 1));

    for(i = 0; i < H * W + 1; i ++){
        masu_x[i] = 0;
        masu_y[i] = 0;
    }

    for(i = 0; i < H; i ++){
        for(j = 0; j < W; j ++){
            masu_x[masu[i][j]] = i;
            masu_y[masu[i][j]] = j;
        }
    }
    int Q;

    scanf("%d", &Q);

    int *sum = (int *) malloc(sizeof(int) * Q);
    int *L = (int *) malloc(sizeof(int) * Q);
    int *R = (int *) malloc(sizeof(int) * Q);

    for(i = 0; i < Q; i ++){
        sum[i] = 0;

        scanf("%d%d", L + i, R + i);

        if(i >= 1){
            if(L[i] == L[i - 1] && R[i] == R[i - 1]){
                sum[i] = sum[i - 1];

                continue;
            }else if(i >= 2){
                if(L[i] == L[i - 2] && R[i] == R[i - 2]){
                    sum[i] = sum[i - 2];

                    continue;
                }
            }
        }

        int x, y;
        int cur_L = L[i];
        x = masu_x[cur_L];
        y = masu_y[cur_L];

        while(cur_L < R[i]){
            int x2, y2;

            cur_L += D;

            x2 = masu_x[cur_L];
            y2 = masu_y[cur_L];

            sum[i] += abs(x2 - x) + abs(y2 - y);
            x = x2;
            y = y2;
        }
    }
    for(i = 0; i < Q; i ++){
        printf("%d\n", sum[i]);
    }

    return 0;
}

