int main(){
	int H,W,D;
	scanf("%d%d%d",&H,&W,&D);
	int pos[H*W+1];
	int d[H*W+1];

	for(int i=0;i<H*W;i++){
		int A;
		scanf("%d",&A);
		pos[A]=i;
	}
	for(int i=1;i<=H*W;i++)d[i]=0;
	for(int i=1;i<=H*W-D;i++){
		int x1=pos[i]/W,y1=pos[i]%W;
		int x2=pos[i+D]/W,y2=pos[i+D]%W;
		d[i+D]=d[i]+ab(x1-x2)+ab(y1-y2);
	}

	int Q;
