fun abc089d() {
    val (h, w, d) = readLine()!!.split(' ').map { it.toInt() }
    val grid = (1..h).map { readLine()!!.split(' ').map { it.toInt() - 1 } }
    val q = readLine()!!.toInt()
    val queries = (1..q)
        .map { readLine()!!.split(' ').map { it.toInt() - 1 }.let { Pair(it[0], it[1]) } }

    val gridSize = h * w
    val numberToId = mutableMapOf<Int, Pair<Int, Int>>()
    val minCosts = IntArray(gridSize)

    for (y in 0 until h) {
        for (x in 0 until w) {
            numberToId[grid[y][x]] = y to x
        }
    }

    for (i in 0 until gridSize - d) {
        val fromXy = numberToId[i] ?: error("なんで？")
        val toXy = numberToId[i + d] ?: error("なんで？")
        minCosts[i + d] = minCosts[i] +
                Math.abs(fromXy.first - toXy.first) + Math.abs(fromXy.second - toXy.second)
    }

    val answer = queries.map { minCosts[it.second] - minCosts[it.first] }.joinToString(System.lineSeparator())

    println(answer)
}

