fun main(args: Array<String>) {
    val (H, W, D) = readInputLine().split(" ").map { it.toInt() }

    val pos = Array(H * W) { Pair(-1, -1) }

    for (i in 0 until H) {
        readInputLine().split(" ").forEachIndexed {
            j, a -> pos[a.toInt() - 1] = Pair(i, j)
        }
    }

    val ans = Array(H * W) { mutableListOf<Int>() }

    for (i in 0 until H * W) {
        if (i - D >= 0) {
            val dec = ans[i - D][1]
            ans[i] = ans[i - D].drop(1).map { it - dec }.toMutableList()
        } else {
            ans[i].add(0)
            for (j in i + D until H * W step D) {
                ans[i].add(ans[i].last() + Math.abs(pos[j].first - pos[j - D].first) + Math.abs(pos[j].second - pos[j - D].second))
            }
        }
    }

    val Q = readInputLine().toInt()

    for (i in 1..Q) {
        val (L, R) = readInputLine().split(" ").map { it.toInt() - 1 }
        println(ans[L][(R - L) / D])
    }
}

