operator fun Pair<Int, Int>.plus(pair: Pair<Int, Int>) = Pair(first + pair.first, second + pair.second)
operator fun Pair<Int, Int>.minus(pair: Pair<Int, Int>) = Pair(first - pair.first, second - pair.second)
fun Pair<Int, Int>.manhattanTo(pair: Pair<Int, Int>) = (this - pair).manhattanLength()
fun Pair<Int, Int>.manhattanLength() = Math.abs(first) + Math.abs(second)

private fun List<IntRange>.zipWithIndices() =
        mapIndexed { first, range ->
            range.map { second -> Pair(first, second) }
        }.flatten()

fun main(args: Array<String>) {
    val (H, W, D) = readLine()!!.split(" ").map { it.toInt() }
    val A = (0 until H).map { readLine()!!.split(" ").map { it.toInt() } }
    val numberCache = {
        val result = mutableMapOf<Int, Pair<Int, Int>>()
        (0 until H).map{ (0 until W) }.zipWithIndices().forEach { pair ->
            val (h, w) = pair
            result[A[h][w]] = Pair(h, w)
        }
        result
    }()

    val mpCache: Map<Int, Int> = {
        val result = mutableMapOf<Int, Int>()
        (1 until D + 1).forEach { width ->
            var index = width
            while (index <= H * W) {
                val prevIndex = index - D
                val totalMp = result[prevIndex]?.let { previous ->
                    val diff = numberCache[prevIndex]!!.manhattanTo(numberCache[index]!!)
                    previous + diff
                } ?: 0

                result[index] = totalMp
                index += width
            }
        }
        result
    }()

    val Q = readLine()!!.toInt()
    (0 until Q).forEach {
        val (L, R) = readLine()!!.split(" ").map { it.toInt() }
        println(mpCache[R]!! - mpCache[L]!!)
    }
}

fun main(args: Array<String>) {
    val (H, W, D) = readLine()!!.split(" ").map { it.toInt() }
    val A = mutableListOf<IntArray>()
    (1..H).forEach {
        val ai = readLine()!!.split(" ").map { it.toInt() }.toIntArray()
        A.add(ai)
    }
    // O(HW) Create function to retrieve the poistion of num N in O(1)
    val numToPosition = Array(H * W + 1, { Pair(-1, -1) })
    (0 until H).forEach {h ->
        (0 until W).forEach {w ->
            val num = A[h][w]
            numToPosition[num] = Pair(h, w)
        }
    }
    fun getPositionByNumber(num: Int) : Pair<Int, Int> {
        return numToPosition[num]
    }

    val Q = readLine()!!.toInt()

    // Return cost
    fun useMagic(i: Int, j: Int, x: Int, y: Int) : Int {
        return Math.abs(x - i) + Math.abs(y - j)
    }

    // O(Q)
    (1..Q).forEach {
        var cost = 0L
        val (L, R) = readLine()!!.split(" ").map { it.toInt() }
        var x = L
        // R - L = DX // R = DX + L
        // O((R-L)/D) (<= O(HW)) // TODO should be faster, could be written in graph
        while (x != R) {
            var next = x + D
            val (currentX, currentY) = getPositionByNumber(x)
            val (nextX, nextY) = getPositionByNumber(next)
            cost += useMagic(currentX, currentY, nextX, nextY)
            x = next
        }
        println(cost)
    }
}

