class TaskB {

	int id[];
	int sz[];
	double eps = 1e-10;
	long INF = (long) 1e15;
	int c[][];

	void solve(int testNumber, InputReader in, PrintWriter pw) {
		int h = in.nextInt();
		int w = in.nextInt();
		int d = in.nextInt();
		int pos[][] = new int[h * w + 1][2];
		for (int i = 0; i < h; ++i) {
			for (int j = 0; j < w; ++j) {
				int a = in.nextInt();
				pos[a][0] = i;
				pos[a][1] = j;
			}
		}

		ArrayList<Integer> dist[] = new ArrayList[h * w + 1];
		Arrays.setAll(dist, i -> new ArrayList<>());
		for (int i = 1; i <= h * w; ++i) {
			int j = i;
			int t = i;
			int sum = 0;
			while (j <= h * w) {
				sum += Math.abs(pos[t][0] - pos[j][0]) + Math.abs(pos[t][1] - pos[j][1]);
				dist[i].add(sum);
				t = j;
				j += d;
			}
		}
		int q = in.nextInt();
		for (int i = 0; i < q; ++i) {
			int l = in.nextInt();
			int r = in.nextInt();
			int div = (r - l) / d;
//			System.err.println(dist[l]);
			pw.println(dist[l].get(div));
		}
	}

	boolean inter(long rec1[], long rec2[]) {
		if (rec1[0] < rec2[0]) {
			if (rec2[0] <= rec1[2]) {
				if (rec1[1] < rec2[1]) {
//					System.err.println(rec2[1] + " " + rec1[3]);
					if (rec2[1] <= rec1[3]) {
						return true;
					}
				} else {
					if (rec1[1] <= rec2[3]) {
						return true;
					}
				}
			}
		} else {
			if (rec1[0] <= rec2[2]) {
//				System.err.println("hello");
				if (rec1[1] < rec2[1]) {
					if (rec2[1] <= rec1[3])
						return true;
				} else {
					if (rec1[1] <= rec2[3])
						return true;
				}

			}
		}
		return false;
	}

	long ar(long rec[]) {
		long l = Math.abs(rec[0] - rec[2]) + 1;
		long b = Math.abs(rec[1] - rec[3]) + 1;
		return l * b;

	}

	long pow(int n, int m) {
		if (m == 0)
			return 1;
		long ans = pow(n, m / 2);
		ans = (ans * ans);
		if (m % 2 == 1) {
			ans = (ans * n);
		}
		return ans;
	}

	double pow(double n, int m) {
		if (m == 0)
			return 1;
		double ans = pow(n, m / 2);
		ans = (ans * ans);
		if (m % 2 == 1) {
			ans = (ans * n);
		}
		return ans;
	}
}

class InputReader {
	BufferedReader br;
	StringTokenizer st;

	public InputReader(InputStream in) {
		br = new BufferedReader(new InputStreamReader(in));
		st = null;
	}

	public String next() {
		while (st == null || !st.hasMoreTokens()) {
			try {
				st = new StringTokenizer(br.readLine());
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
		}
		return st.nextToken();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
