		out.close();
	}

	static class TaskD {
		public void solve(int testNumber, Scanner sc, PrintWriter out) {

			int h = sc.nextInt();
			int w = sc.nextInt();
			int d = sc.nextInt();
			Point[] map = new Point[h * w + 1];
			for (int y = 0; y < h; y++) {
				for (int x = 0; x < w; x++) {
					int a = sc.nextInt();
					map[a] = new Point(x, y);
				}
			}
			int q = sc.nextInt();
			for (int i = 0; i < q; i++) {
				long mp = 0;
				int l = sc.nextInt();
