        public void solve() {
        	int H = ni();
        	int W = ni();
        	int D = ni();
        	Map<Integer, PP> map = new HashMap<>();
        	int a;
        	for (int i = 0; i < H; i++) {
				for (int j = 0; j < W; j++) {
					a = ni();
					map.put(a, new PP(i+1, j+1));
				}
			}
        	long[] sum = new long[H*W+D+1];
        	for (int i = 1; i <= H * W - D; i++) {
        		sum[i+D] = sum[i] + Math.abs(map.get(i+D).key - map.get(i).key)
        							+ Math.abs(map.get(i+D).val - map.get(i).val);
//        		prn("sum[" + i + "] = " + sum[i] + " -->  sum[" + (i+D) + "] = " + sum[i+D]);
			}
        	int Q = ni();
        	int l, r;
        	for (int i = 0; i < Q; i++) {
				l = ni();
				r = ni();
				prn(sum[r] - sum[l]);
			}
    	}

