        for(int i = 1; i <= h*w; i++){
            int ci = i%d;
            int cj = i/d;
            if(cj != 0){
                int prev = i-d;
                cum[ci][cj] += cum[ci][cj-1] + Math.abs(arr[i]/w - arr[prev]/w) + Math.abs(arr[i]%w - arr[prev]%w);
            }
        }
        int q = sc.nextInt();
        for(int i = 0; i < q; i++){
            int s = sc.nextInt();
