public class Main {

    public static void main(String[] args) {
        final Scanner scanner = new Scanner(System.in);
        solve(scanner);
    }


    static class Pos {
        int h;
        int w;

        Pos(int h, int w) {
            this.h = h;
            this.w = w;
        }

        int diff(Pos other) {
            return Math.abs(h - other.h) + Math.abs(w - other.w);
        }
    }

    static void solve(Scanner scanner) {
        int H = scanner.nextInt(), W = scanner.nextInt(), D = scanner.nextInt();
        scanner.nextLine();
        Map<Integer, Pos> m = new HashMap<>();
        for (int h = 0; h < H; h++){
            for (int w = 0; w < W; w++) {
                int n = scanner.nextInt();
                m.put(n, new Pos(h, w));
            }
        }
        scanner.nextLine();

        int Q = Integer.parseInt(scanner.nextLine());
        for (int i = 0; i < Q; i++) {
            int[] q = Arrays.stream(scanner.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
            int ans = 0;
            while (q[0] < q[1]) {
                ans += m.get(q[0]).diff(m.get(q[0] + D));
                q[0] = q[0] + D;
            }
            System.out.println(ans);
        }
    }

}

