/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int H = in.nextInt();
            int W = in.nextInt();
            int D = in.nextInt();
            int[][] A = new int[H][W];
            int[] map = new int[H * W];
            long[][] dist = new long[D][H * W];
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    A[i][j] = in.nextInt() - 1;
                    map[A[i][j]] = i * 300 + j;
                }
            }
            for (int i = 0; i < H * W; i++) {
                if (i + D >= H * W) continue;
                ;
                int nowI = map[i] / 300;
                int nowJ = map[i] % 300;
                int nxtI = map[i + D] / 300;
                int nxtJ = map[i + D] % 300;
                dist[i % D][i + D] += dist[i % D][i] + Math.abs(nowI - nxtI) + Math.abs(nowJ - nxtJ);
            }
            int Q = in.nextInt();
            int[] L = new int[Q];
            int[] R = new int[Q];
            for (int i = 0; i < Q; i++) {
                L[i] = in.nextInt() - 1;
                R[i] = in.nextInt() - 1;
                int d = L[i] % D;
                out.println(dist[d][R[i]] - dist[d][L[i]]);
            }

        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main implements Runnable { // クラス名はMain1

	PrintWriter out = new PrintWriter(System.out);
	InputReader sc = new InputReader(System.in);

	public static void main(String[] args) {
		Thread.setDefaultUncaughtExceptionHandler((t, e) -> System.exit(1));
		new Thread(null, new Main(), "", 256 * 1024 * 1024).start();
	}

	public void run() {

		try {
			//String S = sc.next().trim();
			int H = sc.nextInt();
			int W = sc.nextInt();
			int D = sc.nextInt();
			InfoInt[] xy = new InfoInt[H * W + 1];
			xy[0] = new InfoInt(0, 0);

			for (int i = 0; i < H; i++) {
				for (int j = 0; j < W; j++) {
					int a = sc.nextInt();
					xy[a] = new InfoInt(i + 1, j + 1);
				}
			}
			int Q = sc.nextInt();
			Long[][] visit = new Long[H * W + 1][H * W + 1];

			for (int i = 0; i < Q; i++) {
				int l = sc.nextInt();
				int r = sc.nextInt();
				long ans = 0;
				if (l != r) {
					if (visit[l][r] == null) {
						int now = l;
						while (now != r) {
							int next = now + D;
							if (visit[now][next] == null) {
								int nextx = xy[next].x;
								int nexty = xy[next].y;
								int nowx = xy[now].x;
								int nowy = xy[now].y;
								long t = Math.abs(nextx - nowx) + Math.abs(nexty - nowy);
								ans += t;
								visit[now][next] = t;
							} else {
								ans += visit[now][next];
							}
							now = next;
						}
						visit[l][r] = ans;
					} else {
						ans = visit[l][r];
					}
				}
				out.println(ans);
			}

		} catch (ArithmeticException ae) {
			ae.printStackTrace();
			throw new RuntimeException();
		} catch (Exception e) {
			e.printStackTrace();
			throw new RuntimeException();
		} finally {
			out.flush();
			out.close();
		}

	}

	class InfoInt {
		public int x;
		public int y;

		public InfoInt(int x, int y) {
			this.x = x;
			this.y = y;
		}
	}

	// 高速なScanner
	static class InputReader {
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}
}

import java.io.IOException;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) throws IOException {

		Scanner in = new Scanner(System.in);
		// input
		int h = in.nextInt();
		int w = in.nextInt();
		int d = in.nextInt();

		Point[] p = new Point[90001];
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				int a = in.nextInt();
				p[a] = new Point(i, j);
			}
		}
		int q = in.nextInt();
		int[] l = new int[q];
		int[] r = new int[q];
		for (int i = 0; i < q; i++) {
			l[i] = in.nextInt();
			r[i] = in.nextInt();
		}

		// solve
		for (int i = 0; i < q; i++) {
			long ans = 0;
			int left = l[i];
			int right = r[i];
			while (left != right) {

				int moveLeft = left + d;
				ans += move(
						p[left].x
						, p[left].y
						, p[moveLeft].x
						, p[moveLeft].y);

				left = moveLeft;

			}
			System.out.println(ans);
		}
	}
	static class Point {
		int x;
		int y;
		Point (int x, int y) {
			this.x = x;
			this.y = y;
		}
	}
	static int move (int x, int y, int i, int j) {
		int abs = 0;
		abs = Math.abs(x-i) + Math.abs(y-j);
		return abs;
	}
}

