			R[i] = Integer.parseInt(tokens[1]) - 1;
		}
		map = new HashMap<>();
		for (int i = 0; i < H; ++i) {
			for (int j = 0; j < W; ++j) {
				Tuple tuple = new Tuple(i, j);
				map.put(A[i][j], tuple);
			}
		}

		distMat = new int[H * W][H * W];
		for (int i = 0; i < H * W; ++i) {
			Tuple from = map.get(i);
			int prev = i;
			int next = i + D;
			distMat[i][prev] = 0;
			distMat[prev][i] = 0;

			while (next < H * W) {
				Tuple prevTuple = map.get(prev);
				Tuple nextTuple = map.get(next);
				distMat[i][next] = distMat[i][prev] + Math.abs(nextTuple.h - prevTuple.h)
						+ Math.abs(nextTuple.w - prevTuple.w);
