import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;
import java.util.ArrayList;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            final int h = in.nextInt();
            final int w = in.nextInt();
            final int d = in.nextInt();
            TaskD.Vertex[][] field = new TaskD.Vertex[h][w];

            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    field[i][j] = new TaskD.Vertex(in.nextInt());
                }
            }

            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    int vx = i;
                    int vy = j;
                    int cv = field[i][j].getValue();
                    int tv = cv + d;
                    int cost = 0;
                    while (true) {
                        boolean found = false;
                        for (int k = 0; k < h; k++) {
                            for (int l = 0; l < w; l++) {
                                if (field[k][l].getValue() == tv) {
                                    cost += Math.abs(vx - k) + Math.abs(vy - l);
                                    TaskD.Edge e = new TaskD.Edge(field[k][l], cost);
                                    field[i][j].setEdge(e);
                                    vx = k;
                                    vy = l;
                                    k = h;
                                    l = w;
                                    found = true;
                                }
                            }
                        }
                        if (found) tv += d;
                        else break;
                    }
                }
            }

            final int q = in.nextInt();
            for (int i = 0; i < q; i++) {
                int c = in.nextInt();
                int t = in.nextInt();
                TaskD.Vertex cv = new TaskD.Vertex();

                for (int j = 0; j < h; j++) {
                    for (int k = 0; k < w; k++) {
                        if (field[j][k].getValue() == c) {
                            cv = field[j][k];
                            j = h;
                            k = w;
                        }
                    }
                }

                long cost = 0;
                if (c != t) {
                    for (int j = 0; j < cv.getDegree(); j++) {
                        if (cv.getEdge(j).getVertex().getValue() == t) {
                            cost = cv.getEdge(j).getCost();
                            break;
                        }
                    }
                }
                out.println(cost);
            }
        }

        static class Vertex {
            private int value;
            private ArrayList<TaskD.Edge> edges = new ArrayList<TaskD.Edge>();

            Vertex() {
            }

            Vertex(int v) {
                this.value = v;
            }

            void setEdge(TaskD.Edge e) {
                this.edges.add(e);
            }

            int getValue() {
                return this.value;
            }

            int getDegree() {
                return this.edges.size();
            }

            TaskD.Edge getEdge(int index) {
                return this.edges.get(index);
            }

        }

        static class Edge {
            private TaskD.Vertex v;
            private int cost;

            Edge() {
                this.v = v;
            }

            Edge(TaskD.Vertex v) {
                this.v = v;
            }

            Edge(TaskD.Vertex v, int c) {
                this.v = v;
                this.cost = c;
            }

            TaskD.Vertex getVertex() {
                return this.v;
            }

            int getCost() {
                return this.cost;
            }

        }

    }
}

import java.util.*;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int h = sc.nextInt();
		int w = sc.nextInt();
		int d = sc.nextInt();
		Map<Integer, Integer> hs = new HashMap<>();
		Map<Integer, Integer> ws = new HashMap<>();

		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				int x = sc.nextInt() - 1;
				hs.put(x, i);
				ws.put(x, j);
			}
		}

		int maxSteps = (h * w / d) + 1;
		int[][] costs = new int[d][maxSteps];

		for (int i = 0; i < d; i++) {
			int ihPrev = hs.get(i);
			int iwPrev = ws.get(i);
			int steps = 1;
			while (steps < maxSteps) {
				if (i + steps * d >= h * w - 1) break;
				int ih = hs.get(i + steps * d);
				int iw = ws.get(i + steps * d);
				costs[i][steps] = Math.abs(ih - ihPrev) + Math.abs(iw - iwPrev) + costs[i][steps - 1];
				ihPrev = ih;
				iwPrev = iw;
				steps++;
			}
		}

		int q = sc.nextInt();
		StringBuilder sb = new StringBuilder();
		while (q-- > 0) {
			int l = sc.nextInt() - 1;
			int r = sc.nextInt() - 1;
			sb.append(costs[r % d][r / d] - costs[l % d][l / d]);
			sb.append("\n");
		}

		System.out.print(sb.toString());
	}
}

