public class Main {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        int h = sc.nextInt();
        int w = sc.nextInt();
        int d = sc.nextInt();
        Pair[] lookup = new Pair[w * h + 1];
        int value;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                value = sc.nextInt();
                lookup[value] = new Pair(i + 1, j + 1);
            }
        }
        int numQueries = sc.nextInt();
        long[] cost = new long[w * h + 1];
        for(int i = 1; i <= w*h; i++){
            if(i > d)
                cost[i] = cost[i - d] + Math.abs(lookup[i].getFirst() - lookup[i - d].getFirst()) +
                        Math.abs(lookup[i].getSecond() - lookup[i - d].getSecond());
        }
        for (int i = 0; i < numQueries; i++) {
            int start = sc.nextInt();
            int end = sc.nextInt();

            System.out.println(cost[end] - cost[start]);
        }
    }
}

