//		S = in.nextLine();

		H = in.nextInt();
		W = in.nextInt();
		D = in.nextInt();
		A = in.nextInt(new int[H*W]);
		Q = in.nextInt();
		L = new int[Q];
		R = new int[Q];
		for (int i=0; i<Q; i++) {
			L[i] = in.nextInt();
			R[i] = in.nextInt();
		}
		AX = new int[H*W];
		AY = new int[H*W];
		for (int x=0; x<H; x++) {
			for (int y=0; y<W; y++) {
				int a = getA(x,y);
				AX[a-1] = x;
				AY[a-1] = y;
			}
		}
		AD = new int[H*W];
		for (int i=D; i<H*W; i++) {
			AD[i] = AD[i-D] + Math.abs(AX[i]-AX[i-D]) + Math.abs(AY[i]-AY[i-D]);
		}
		ans = new long[Q];
	}

	private int getA(int x, int y) {
		return A[y * H + x];
	}

	public void solve() throws IOException {
		for (int i=0; i<Q; i++) {
			int l = L[i];
			int r = R[i];
			ans[i] = AD[r-1] - AD[l-1];
		}
	}



	public void output() {
//		out.println(ansb?"Yes":"No");
		for (int i=0; i<Q; i++)
			out.println(ans[i]);
		out.flush();
	}
