          diffX = -diffX;
        }
        if (diffY < 0) {
          diffY = -diffY;
        }
        acc += diffX + diffY;
        accs[num] = acc;
      }
    }

    int q = scanner.nextInt();
    StringBuilder output = new StringBuilder();
    for (int k = 0 ; k < q ; k ++) {
      int l = scanner.nextInt() - 1;
      int r = scanner.nextInt() - 1;
      long result = accs[r] - accs[l];
      output.append(result).append("\n");
    }

    System.out.println(output.toString());
  }

  public static void main(String[] args) {
    Main main = new Main();
    main.run();
  }

  // scanner slightly faster than usual ones
  public static class BetterScanner {

    private InputStream stream;
    private byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bufferLength = 0;

    public BetterScanner(InputStream stream) {
      this.stream = stream;
    }

    private boolean updateBuffer() {
      if (pointer >= bufferLength) {
        pointer = 0;
        try {
          bufferLength = stream.read(buffer);
        } catch (IOException exception) {
          exception.printStackTrace();
        }
        return bufferLength > 0;
      } else {
        return true;
      }
    }

    private int read() {
      if (updateBuffer()) {
        return buffer[pointer ++];
      } else {
        return -1;
      }
    }

    public boolean hasNext() {
      skipUnprintable();
      return updateBuffer();
    }

    private void skipUnprintable() { 
      while (updateBuffer() && !isPrintableChar(buffer[pointer])) {
        pointer ++;
      }
    }

    public String next() {
      if (hasNext()) {
        StringBuilder builder = new StringBuilder();
        int codePoint = read();
        while (isPrintableChar(codePoint)) {
          builder.appendCodePoint(codePoint);
          codePoint = read();
        }
        return builder.toString();
      } else {
        throw new NoSuchElementException();
      }
    }

    public long nextLong() {
      if (hasNext()) {
        long number = 0;
        boolean minus = false;
        int codePoint = read();
        if (codePoint == '-') {
          minus = true;
          codePoint = read();
        }
        if (codePoint >= '0' && codePoint <= '9') {
          while (true) {
            if (codePoint >= '0' && codePoint <= '9') {
              number *= 10;
              number += codePoint - '0';
            } else if (codePoint < 0 || !isPrintableChar(codePoint)) {
              return (minus) ? -number : number;
            } else {
              throw new NumberFormatException();
            }
            codePoint = read();
          }
        } else {
          throw new NumberFormatException();
        }
      } else {
        throw new NoSuchElementException();
      }
    }

    public int nextInt() {
      long number = nextLong();
      if (number >= Integer.MIN_VALUE && number <= Integer.MAX_VALUE) {
        return (int)number;
      } else {
        throw new NumberFormatException();
      }
    }

    private boolean isPrintableChar(int codePoint) {
      return codePoint >= 33 && codePoint <= 126;
    }

  }

}

import java.util.*;
import java.io.*;

public class Main{
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int h=fsc.nextInt(), w=fsc.nextInt(), d=fsc.nextInt();
        int len=(int) Math.ceil((double)h*(double)w/(double)d);
        int[][][] group=new int[d][len][2];
        int aij, modD, div;
        for(int i=0;i<h;i++){
            for(int j=0;j<w;j++){
                aij=fsc.nextInt()-1;
                modD=aij%d;
                div=aij/d;
                group[modD][div][0]=i;
                group[modD][div][1]=j;
            }
        }
        int[][] accumPower=new int[d][len];
        int dist;
        for(int divGroup=0;divGroup<d;divGroup++){
            for(int q=0;q<len;q++){
                if(q*d+divGroup<h*w){
                    if(q==0) accumPower[divGroup][q]=0;
                    else{
                        dist=Math.abs(group[divGroup][q][0]-group[divGroup][q-1][0])+Math.abs(group[divGroup][q][1]-group[divGroup][q-1][1]);
                        accumPower[divGroup][q]=accumPower[divGroup][q-1]+dist;
                    }
                }
            }
        }
        int q=fsc.nextInt();
        int l,r,g,quoL,quoR;
        StringBuilder sb=new StringBuilder("");
        for(int i=0;i<q;i++){
            l=fsc.nextInt()-1;
            r=fsc.nextInt()-1;
            g=l%d;
            quoL=l/d;
            quoR=r/d;
            if(quoL>=1) sb.append((accumPower[g][quoR]-accumPower[g][quoL])+"\n");
            else sb.append(accumPower[g][quoR]+"\n");
        }
        fsc.close();
        System.out.print(sb);
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            }else{
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }else if(b == -1 || !isPrintableChar(b)){
                    return minus ? -n : n;
                }else{
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

import java.util.*;
public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int H = sc.nextInt(), W = sc.nextInt(), D = sc.nextInt();
		List<int[]> access= new ArrayList<int[]>();
		for(int i=0;i<=H*W;i++)access.add(null);

		for(int i=0;i<H;i++) {
			for(int j=0;j<W;j++) {
				int num = sc.nextInt();
				int address[] = {i,j};
				access.set(num, address);
			}
		}
		int Q = sc.nextInt();
		int query[][] = new int[Q][2];
		for(int i=0;i<Q;i++) {
			query[i][0] = sc.nextInt();
			query[i][1] = sc.nextInt();
		}
		sc.close();

		int cost[][] = new int[D+1][H*W];

		for(int i=1;i<=D;i++) {
			cost[i][0]=0;
			int now = i;
			int next = 0;
			for(int j=0;j<H*W;j++) {
				next = now + D;
				if(next>H*W)break;
				int dist = Math.abs(access.get(next)[0]-access.get(now)[0])+Math.abs(access.get(next)[1]-access.get(now)[1]);
				cost[i][j+1]=cost[i][j]+dist;
				now = next;
			}
		}

		//answer

		StringBuilder sb = new StringBuilder();
		for(int i=0;i<Q;i++) {
			int start = query[i][0], goal = query[i][1];
			int series = start%D==0 ? D:start%D;
			int ans = cost[series][(goal-series)/D]-cost[series][(start-series)/D];
			sb.append(ans + "\n");
		}
		System.out.println(sb.toString());


	}
}

