		}
	}

	private static class Pair {
		int y;
		int x;
		Pair(int y, int x) {
			this.y = y;
			this.x = x;
		}
	}

	private static int mp(Pair p, Pair q) {
		return Math.abs(p.y - q.y) + Math.abs(p.x - q.x);
	}
