		Q = in.nextInt();
		L = new int[Q];
		R = new int[Q];
		for (int i=0; i<Q; i++) {
			L[i] = in.nextInt();
			R[i] = in.nextInt();
		}
		AX = new int[H*W];
		AY = new int[H*W];
		for (int x=0; x<H; x++) {
			for (int y=0; y<W; y++) {
				int a = getA(x,y);
				AX[a-1] = x;
				AY[a-1] = y;
			}
		}
		AD = new int[H*W];
