/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int H = in.nextInt();
            int W = in.nextInt();
            int D = in.nextInt();
            int[] map = new int[H * W];
            int[] dist = new int[H * W];
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    int A = in.nextInt() - 1;
                    map[A] = i * 300 + j;
                }
            }
            for (int i = 0; i < H * W; i++) {
                if (i + D >= H * W) continue;
                int nowI = map[i] / 300;
                int nowJ = map[i] % 300;
                int nxtI = map[i + D] / 300;
                int nxtJ = map[i + D] % 300;
                dist[i + D] += dist[i] + Math.abs(nowI - nxtI) + Math.abs(nowJ - nxtJ);
            }
            int Q = in.nextInt();
            for (int i = 0; i < Q; i++) {
                int L = in.nextInt() - 1;
                int R = in.nextInt() - 1;
                int d = L % D;
                out.println(dist[R] - dist[L]);
            }

        }

    }
}

