    for (int i = 0; i < h; i ++) {
      for (int j = 0; j < w; j ++) {
        int a = ni() - 1;
        map.put(a, new int[] {i, j});
      }
    }
    long[][] arr = new long[d][h * w / d + 1];
    for (int i = 0; i < d; i ++) {
      for (int j = i + d; j < w * h; j += d) {
        int[] p1 = map.get(j - d);
        int[] p2 = map.get(j);
        int len = Math.abs(p1[0] - p2[0]) + Math.abs(p1[1] - p2[1]);
