	private static int getManhattanDistance(Point a, Point b) {
		return Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
	}
	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * ABC089 D問題
		 * 考察メモ
		 * 予め累積和をやるだけ、O(HW)
		 *
		 */
		int H = io.nextInt(), W = io.nextInt(), D = io.nextInt();
		int[][] A = io.nextInt(W, H);
		Map<Integer, Point> map = new HashMap<>();
		for (int y : IntRange.open(A.length)) {
			for (int x : IntRange.open(A[y].length)) {
				map.put(A[y][x], new Point(x, y));
			}
		}
		int[] cumsum = new int[H*W+1];
		for (final int i : IntRange.closed(1, D)) cumsum[i] = 0;
		for (final int i : IntRange.open(D, cumsum.length)) cumsum[i] = cumsum[i - D] + getManhattanDistance(map.get(i - D), map.get(i));
		for (@SuppressWarnings("unused")final int i : IntRange.open(io.nextInt())) {
			int L = io.nextInt(), R = io.nextInt();
			io.println(cumsum[R] - cumsum[L]);
