			for(int w=0;w<W;w++){
				int val = sc.nextInt();

				rem[val%D][val/D]= h*W + w;

			}
		}

		for(int d=0;d<D;d++){
			for(int n=rem[d].length-1;n>=0;n--){
				if(n==0) rem[d][n] = 0;
				else	rem[d][n] = res(rem[d][n]/W - rem[d][n-1]/W , rem[d][n]%W - rem[d][n-1]%W);
			}
		}


