class Solver {
  final int h, w, d, q;
  final int[][] am;
  final int[] ls, rs;

  Solver(int h, int w, int d, int[][] am, int q, int[] ls, int[] rs) {
    this.h = h;
    this.w = w;
    this.d = d;
    this.am = am;
    this.q = q;
    this.ls = ls;
    this.rs = rs;
  }

  public long[] solve() {
    int[] nToI = new int[h * w + 1];
    int[] nToJ = new int[h * w + 1];
    for (int i = 0; i < h; i++) {
      for (int j = 0; j < w; j++) {
        int a = am[i][j];
        nToI[a] = i;
        nToJ[a] = j;
      }
    }

    int[] costs = new int[h * w + 1];
    for (int k2 = d + 1; k2 <= h * w; k2++) {
      int k1 = k2 - d;
      int i1 = nToI[k1];
      int j1 = nToJ[k1];
      int i2 = nToI[k2];
      int j2 = nToJ[k2];
      costs[k2] = costs[k1] + Math.abs(i2 - i1) + Math.abs(j2 - j1);
    }

    long[] answers = new long[q];
    for (int i = 0; i < q; i++) {
      answers[i] = costs[rs[i]] - costs[ls[i]];
    }
    return answers;
  }
}

