		for(int j = 0; j < w; j ++) {
			g[array[i][j]] = new Grid(i, j);
		}
	}

	long need[][] = new long[d + 10][h * w / d + 10];
	for(int i = 1; i <= d; i ++) {
		need[i][0] = 0;
		for(int j = 1; i + j * d <= h * w; j ++) {
			need[i][j] = need[i][j - 1]
					+ abs(g[i + j * d].h - g[i + (j - 1) * d].h)
					+ abs(g[i + j * d].w - g[i + (j - 1) * d].w);
		}
	}

