/*
 * H 行 W 列のマス目があり、i 行目の j 列目のマスをマス (i,j) と呼びます。
 * 
 * このマス目には 1 から H×W までの整数が重複なく書かれており、マス (i,j) に書かれている整数は Ai,j です。
 * 
 * 魔法少女であるあなたは、魔力 |x−i|+|y−j| を消費することでマス (i,j) に置かれた駒をマス (x,y) に瞬間移動させることができます。
 * 
 * あなたは、魔法少女としての能力を計るために、Q 回の実技試験を受けなければなりません。
 * 
 * i 回目の実技試験は、以下の手順で行われます。
 * 
 *     初めに、駒が整数 Li の書かれているマスに置かれている。
 * 
 *     駒の置かれているマスに書かれている整数を x とする。x が Ri でない限り、駒を x+D の書かれているマスに移動することを繰り返す。x=Ri となったら終了する。
 * 
 *     ただし、Ri−Li が D の倍数であることは保証される。
 * 
 * それぞれの実技試験に対し、あなたの消費する魔力の総和を求めてください。
 */

import java.util.*;
	public class Main{
        public static void main(String[] args){
            Scanner sc = new Scanner(System.in);
            // 入力
            int h = Integer.parseInt(sc.next());
            int w = Integer.parseInt(sc.next());
            int d = Integer.parseInt(sc.next());
            int[][] location = new int[h*w][2];
            for(int i=0; i<h*w; i++){
            	int a = Integer.parseInt(sc.next())-1;
            	location[a][0] = i/w;
            	location[a][1] = i%w;
            }
            int q = Integer.parseInt(sc.next());

            for(int i=0; i<q; i++){
            	// 入力
            	int l = Integer.parseInt(sc.next())-1;
            	int r = Integer.parseInt(sc.next())-1;
            	long sum = 0;
                while(l!=r){
                	sum += (long)(Math.abs(location[l][0] - location[l+d][0]) + Math.abs(location[l][1] - location[l+d][1]));
                	l += d;
                }
             // 出力
                System.out.println(sum);
            }

            sc.close();
        }
    }

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

import static java.lang.Math.*;

public class Main {
    BufferedReader rd;

    Main() throws IOException {
        rd = new BufferedReader(new InputStreamReader(System.in));
        compute();
    }

    private void compute() throws IOException {
        int[] hwd = intarr();
        int h = hwd[0];
        int w = hwd[1];
        int d = hwd[2];

        int n = h*w;

        int[][] coords = new int[n + 5][2];
        int[][] a = new int[h][];
        for(int i=0;i<h;i++) {
            a[i] = intarr();
            for(int j=0;j<w;j++) {
                coords[a[i][j]][0] = i;
                coords[a[i][j]][1] = j;
            }
        }

        long[] s = new long[n+5];
        for(int i=1;i<=d;i++) {
            int u = i;
            while(u <= n) {
                int p = u;
                u += d;
                if(u <= n) {
                    long x1 = coords[p][0];
                    long y1 = coords[p][1];
                    long x2 = coords[u][0];
                    long y2 = coords[u][1];
                    long dist = abs(x1 - x2) + abs(y1 - y2);
                    s[u] = s[u-d] + dist;
                }
            }
        }

        int q = pint();
        StringBuilder buf = new StringBuilder();
        for(int i=0;i<q;i++) {
            if(i > 0) {
                buf.append('\n');
            }
            int[] lr = intarr();
            int l = lr[0];
            int r = lr[1];
            if(l == r) {
                buf.append(0);
            } else {
                buf.append(s[r] - s[l]);
            }
        }
        out(buf);
    }

    private int pint() throws IOException {
        return pint(rd.readLine());
    }

    private int pint(String s) {
        return Integer.parseInt(s);
    }

    private int[] intarr() throws IOException {
        return intarr(rd.readLine());
    }

    private int[] intarr(String s) {
        String[] q = split(s);
        int n = q.length;
        int[] a = new int[n];
        for(int i=0;i<n;i++) {
            a[i] = Integer.parseInt(q[i]);
        }
        return a;
    }

    private String[] split(String s) {
        if(s == null) {
            return new String[0];
        }
        int n = s.length();
        int start = -1;
        int end = 0;
        int sp = 0;
        boolean lastWhitespace = true;
        for(int i=0;i<n;i++) {
            char c = s.charAt(i);
            if(isWhitespace(c)) {
                lastWhitespace = true;
            } else {
                if(lastWhitespace) {
                    sp++;
                }
                if(start == -1) {
                    start = i;
                }
                end = i;
                lastWhitespace = false;
            }
        }
        if(start == -1) {
            return new String[0];
        }
        String[] res = new String[sp];
        int last = start;
        int x = 0;
        lastWhitespace = true;
        for(int i=start;i<=end;i++) {
            char c = s.charAt(i);
            boolean w = isWhitespace(c);
            if(w && !lastWhitespace) {
                res[x++] = s.substring(last,i);
            } else if(!w && lastWhitespace) {
                last = i;
            }
            lastWhitespace = w;
        }
        res[x] = s.substring(last,end+1);
        return res;
    }

    private boolean isWhitespace(char c) {
        return c==' ' || c=='\t';
    }

    private static void out(Object x) {
        System.out.println(x);
    }

    public static void main(String[] args) throws IOException {
        new Main();
    }
}

