    static class TaskD {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int h = in.nextInt();
            int w = in.nextInt();
            int D = in.nextInt();
            EHashMap<Integer, Point> map = new EHashMap<>();
            for (int i = 0; i < h; ++i) {
