	void solve(int testNumber, InputReader in, PrintWriter pw) {
		int h = in.nextInt();
		int w = in.nextInt();
		int d = in.nextInt();
		int pos[][] = new int[h * w + 1][];
		for (int i = 0; i < h; ++i) {
			for (int j = 0; j < w; ++j) {
				int a = in.nextInt();
				pos[a] = new int[] { i, j };
			}
		}
		int dist[][] = new int[h * w + 1][h * w + 1];
		for (int i = 1; i <= h * w; ++i) {
			for (int j = i + 1; j <= h * w; ++j) {
				dist[i][j] = Math.abs(pos[i][0] - pos[j][0]) + Math.abs(pos[i][1] - pos[j][1]);
			}
		}
		int q = in.nextInt();
		for (int i = 0; i < q; ++i) {
			int l = in.nextInt();
			int r = in.nextInt();
			int ans = 0;
			int u = l;
			for (int j = l + d; j <= r; j += d) {
				ans += dist[u][j];
//				System.err.println(dist[u][j] + " " + u + " " + j);
				u = j;
			}
			pw.println(ans);
		}
	}

	boolean inter(long rec1[], long rec2[]) {
		if (rec1[0] < rec2[0]) {
			if (rec2[0] <= rec1[2]) {
				if (rec1[1] < rec2[1]) {
//					System.err.println(rec2[1] + " " + rec1[3]);
					if (rec2[1] <= rec1[3]) {
						return true;
					}
				} else {
					if (rec1[1] <= rec2[3]) {
						return true;
					}
				}
			}
		} else {
			if (rec1[0] <= rec2[2]) {
//				System.err.println("hello");
				if (rec1[1] < rec2[1]) {
					if (rec2[1] <= rec1[3])
						return true;
				} else {
					if (rec1[1] <= rec2[3])
						return true;
				}

			}
		}
		return false;
	}

	long ar(long rec[]) {
		long l = Math.abs(rec[0] - rec[2]) + 1;
		long b = Math.abs(rec[1] - rec[3]) + 1;
		return l * b;

	}

	long pow(int n, int m) {
		if (m == 0)
			return 1;
		long ans = pow(n, m / 2);
		ans = (ans * ans);
		if (m % 2 == 1) {
			ans = (ans * n);
		}
		return ans;
	}

	double pow(double n, int m) {
		if (m == 0)
			return 1;
		double ans = pow(n, m / 2);
		ans = (ans * ans);
		if (m % 2 == 1) {
			ans = (ans * n);
		}
		return ans;
	}
}

