                        int h = in.i();
                        int w = in.i();
                        int d = in.i();
                        for (int i = 0; i <= h * w; i++) {
                                map.put(i, new TaskD.Point());
                        }
                        for (int i = 0; i < h; i++) {
                                for (int j = 0; j < w; j++) {
                                        int x = in.i();
                                        map.get(x).x = i;
                                        map.get(x).y = j;
                                }
                        }
                        long[] dis = new long[90000];
                        for (int i = d + 1; i <= h * w; i++) {

                                dis[i] = dis[i - d] + Math.abs(map.get(i).x - map.get(i - d).x) + Math.abs(map.get(i).y - map.get(i - d).y);
                        }
                        int q = in.i();
                        while (q-- > 0) {
                                int a = in.i();
                                int b = in.i();
                                out.println(dis[b] - dis[a]);
                        }
