public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int h = sc.nextInt();
		int w = sc.nextInt();
		int d = sc.nextInt();

		Map<Integer, Pair> hm = new HashMap<>();
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				int a = sc.nextInt();

				hm.put(a, new Pair(j, i));
			}
		}

		List<List<Long>> dp = new ArrayList<>(d);
		for (int i = 0; i < d; i++) {
			dp.add(new ArrayList<>());

			dp.get(i).add(0L);
			int tmp = i + 1;
			long ans = 0;
			int px = hm.get(tmp).a;
			int py = hm.get(tmp).b;
			tmp += d;
			while (tmp < h * w) {
				int x = hm.get(tmp).a;
				int y = hm.get(tmp).b;

				ans += Math.abs(x - px) + Math.abs(y - py);
				dp.get(i).add(ans);

				px = x;
				py = y;
				tmp += d;
			}

		}

		int q = sc.nextInt();
		for (int i = 0; i < q; i++) {
			int l = sc.nextInt() - 1;
			int r = sc.nextInt() - 1;

			int mod = l % d;

			pr.println(dp.get(mod).get(r / d) - dp.get(mod).get(l / d));
		}
	}

	private static class Pair implements Comparable<Pair> {
		int a;
		int b;

		Pair(int a, int b) {
			this.a = a;
			this.b = b;
		}

		@Override
		public int compareTo(Pair o) {
			if (a == o.a) {
				return Integer.compare(b, o.b);
			}

			return Integer.compare(a, o.a);
		}

		@Override
		public int hashCode() {
			return Integer.hashCode(a);
		}

		@Override
		public String toString() {
			// [xxx, xxxx]
			StringBuilder stmp = new StringBuilder(32);
			stmp.append('[');
			stmp.append(a);
			stmp.append(',');
			stmp.append(' ');
			stmp.append(b);
			stmp.append(']');

			return stmp.toString();
		}
	}

