      while(n + D <= H * W){
        number[n+D][2] = number[n][2] + Math.abs(number[n][0]-number[n+D][0]) + Math.abs(number[n][1]-number[n+D][1]);
        n += D;
      }
    }
    int Q = sc.nextInt();
