class Solver {
	Scanner sc;
	PrintWriter out;
    public Solver(InputStream in, PrintWriter out) {
    	sc = new Scanner(in);
    	this.out = out;
    }
    // ==================================================================
    PP[] A;
    int[] WA;
    public void solve() {
    	int H = Integer.parseInt(sc.next());
    	int W = Integer.parseInt(sc.next());
    	int D = Integer.parseInt(sc.next());
    	A = new PP[H * W];
    	int a;
    	for (int i = 0; i < H; i++) {
    		for (int j = 0; j < W; j++) {
