			for (int i = 0; i < Q; i++) {
				int l = sc.nextInt();
				int r = sc.nextInt();
				long ans = 0;
				if (l != r) {
					int now = l;
					while (now != r) {
						int next = now + D;
						int nextx = xy[next].x;
						int nexty = xy[next].y;
						int nowx = xy[now].x;
						int nowy = xy[now].y;
						ans += Math.abs(nextx - nowx) + Math.abs(nexty - nowy);
						now = next;
					}
				}
				out.println(ans);
			}

		} catch (ArithmeticException ae) {
			//ae.printStackTrace();
			throw new RuntimeException();
		} catch (Exception e) {
			//e.printStackTrace();
