		int w = in.nextInt();
		int d = in.nextInt();
		int pos[][] = new int[h * w + 1][];
		for (int i = 0; i < h; ++i) {
			for (int j = 0; j < w; ++j) {
				int a = in.nextInt();
				pos[a] = new int[] { i, j };
			}
		}
		int dist[][] = new int[h * w + 1][h * w + 1];
		for (int i = 1; i <= h * w; ++i) {
			for (int j = i + 1; j <= h * w; ++j) {
				dist[i][j] = Math.abs(pos[i][0] - pos[j][0]) + Math.abs(pos[i][1] - pos[j][1]);
			}
		}
		int q = in.nextInt();
		for (int i = 0; i < q; ++i) {
			int l = in.nextInt();
			int r = in.nextInt();
			int ans = 0;
			int u = l;
			for (int j = l + d; j <= r; j += d) {
				ans += dist[u][j];
