		if (rec1[0] < rec2[0]) {
			if (rec2[0] <= rec1[2]) {
				if (rec1[1] < rec2[1]) {
//					System.err.println(rec2[1] + " " + rec1[3]);
					if (rec2[1] <= rec1[3]) {
						return true;
					}
				} else {
					if (rec1[1] <= rec2[3]) {
						return true;
					}
				}
			}
		} else {
			if (rec1[0] <= rec2[2]) {
//				System.err.println("hello");
				if (rec1[1] < rec2[1]) {
					if (rec2[1] <= rec1[3])
						return true;
				} else {
					if (rec1[1] <= rec2[3])
						return true;
				}

			}
		}
		return false;
	}

