class InputUtil {
	//Static Fields
	private static final int BUFSIZ = 100000;
	boolean lineMode = false;

	//Fields
	protected InputStream in;
	private byte[] buf = null;
	private int ptr = 0;
	private int max = -1;
	private DataInputStream dis = null;
	//Constructors
	public InputUtil() {this(System.in,BUFSIZ);}
	public InputUtil(InputStream in, int bufsiz) {
		initBuf(bufsiz);
		initIn(in);
	}

	//Methods
	//Initializer
	protected void initIn(InputStream in) {dis = new DataInputStream(this.in = in);}
	protected void initBuf(int bufsiz) {buf = new byte[bufsiz];}

	//buffer operation
	private void next() throws IOException {ptr++; readBuf();}
	private void readBuf() throws IOException {
		if(ptr >= max && dis.available()>0) {
			if(max>0) Arrays.fill(buf,0,max,(byte)0);
			max = dis.read(buf);
			ptr = 0;
		}
	}


	//String Input Reader/Parser
	private boolean isCrLf(byte b) {return b == 0x0a || b == 0x0d; }

	private void skipOneCrLf() throws IOException {
		byte b = buf[ptr];
		if (isCrLf(b)) {
			ptr++;
			if (b == 0x0d) {
				readBuf();
				if (ptr < max && buf[ptr] == 0x0a) {
					ptr++;
				}
			}
		}
	}

	public String nextLine() throws IOException {
		StringBuilder sb = new StringBuilder();
		boolean isFirst = true;
		for(readBuf(); ptr < max ;readBuf()) {
			byte b = buf[ptr];
			if(isCrLf(b)) {
				skipOneCrLf();
				if (!isFirst || lineMode) {
					break;
				}
			}else{
				int strPtr = ptr++;
				int endPtr = -1;
				for(int i = ptr; i<max; i++) {
					if(isCrLf(buf[i])) {
						endPtr = i;
						break;
					}
				}
				if(endPtr == -1) endPtr = max;
				sb.append(new String(buf,strPtr,endPtr-strPtr,"UTF-8"));
				ptr = endPtr;
			}
			isFirst = false;
		}
		lineMode = true;
		return sb.toString();
	}

	public byte nextByte() throws IOException {
		lineMode=false;
		readBuf();
		if(ptr < max) {
			return buf[ptr++];
		}else{
			return -1;
		}
	}

	//Number Input Reader/Parser
	private boolean isNum(byte b) {return '0' <= b && b <= '9'; }
	private boolean isMinus(byte b) {return b=='-'; }

	public int nextInt() throws IOException {
		lineMode=false;
		readBuf();
		return (int)_nextLong();
	}

	public int[] nextInt(int[] result) throws IOException {
		lineMode=false;
		readBuf();
		for(int i=0; i<result.length; i++) {
			result[i] = (int)_nextLong();
		}
		return result;
	}

	private long _nextLong() throws IOException {
		int sign = 1;
		long res = 0;
		byte c;
		while (!isNum(c=buf[ptr]) && !isMinus(c)) 
			next();
		if (isMinus(buf[ptr])) {
			sign = -1;
			next();
		}
		while (isNum(c=buf[ptr])) {
			res *= 10;
			res += c - '0' ;
			next();
		}
		next();
		return sign * res;
	}

	public long nextLong() throws IOException {
		lineMode=false;
		readBuf();
		return _nextLong();
	}

	public long[] nextLong(long[] result) throws IOException {
		lineMode=false;
		readBuf();
		for(int i=0; i<result.length; i++) {
			result[i] = _nextLong();
		}
		return result;
	}

	//Close 
	public void close() throws IOException {
		if(!this.in.equals(System.in)) 
			this.in.close();
	}

}

class OutputUtil {
	public static final String EOF = System.lineSeparator();

	public static void outputDivSpace(PrintWriter out, int[] a) {
		OutputUtil.output(out,a,0,a.length," ");
	}

	public static void outputDivEOF(PrintWriter out, int[] a) {
		OutputUtil.output(out,a,0,a.length,EOF);
	}

	public static void output(PrintWriter out, int[] a, int off, int len, String delim) {
		out.print(a[off]);
		for(int i=off+1; i<len; i++){
			out.print(delim);
			out.print(a[i]);
		}
		out.println("");
		out.flush();
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.HashMap;

public class Main
{
  static class Data
  {
    public int v;
    public int i;
    public int j;

    public Data
    (
      int v,
      int i,
      int j
    )
    {
      this.v = v;
      this.i = i;
      this.j = j;
    }
  }

  public static void main
  (
    String[] args
  )
  {
    BufferedReader in_stream;
    String         in_str;
    String[]       in_str_split;

    int    in_H;
    int    in_W;
    int    in_D;
    Data[] in_A;
    int    in_Q;
    int[]  in_L;
    int[]  in_R;

    int cnt_h;
    int cnt_w;
    int cnt_q;

    int tmp;
    int now;
    int goal;
    Data now_data;
    Data next_data;
    int ans;

    try
    {
      in_stream = new BufferedReader(new InputStreamReader(System.in));

      /*----------------
       * 引数
       *----------------*/
      in_str       = new String(in_stream.readLine());
      in_str_split = in_str.split(" ");
      in_H   = Integer.parseInt(in_str_split[0]);
      in_W   = Integer.parseInt(in_str_split[1]);
      in_D   = Integer.parseInt(in_str_split[2]);

      in_A = new Data[(in_H * in_W) + 1];
      for(cnt_h=0; cnt_h<in_H; cnt_h++)
      {
        in_str       = new String(in_stream.readLine());
        in_str_split = in_str.split(" ");

        for(cnt_w=0; cnt_w<in_W; cnt_w++)
        {
          tmp = Integer.parseInt(in_str_split[cnt_w]);
          in_A[tmp] = new Data(tmp, cnt_h, cnt_w);
        }
      }

      in_str = new String(in_stream.readLine());
      in_Q   = Integer.parseInt(in_str);

      in_L = new int[in_Q];
      in_R = new int[in_Q];
      for(cnt_q=0; cnt_q<in_Q; cnt_q++)
      {
        in_str       = new String(in_stream.readLine());
        in_str_split = in_str.split(" ");

        in_L[cnt_q] = Integer.parseInt(in_str_split[0]);
        in_R[cnt_q] = Integer.parseInt(in_str_split[1]);
      }


      /*----------------
       * 計算
       *----------------*/
      for(cnt_q=0; cnt_q<in_Q; cnt_q++)
      {
        ans = 0;

        now  = in_L[cnt_q];
        goal = in_R[cnt_q];

        now_data = in_A[now];
        while(goal != now_data.v)
        {
          next_data = in_A[now_data.v + in_D];
          ans += Math.abs(next_data.i - now_data.i) + Math.abs(next_data.j - now_data.j);

          now_data = next_data;
        }

        System.out.println("" + ans);
      }

    }
    catch(Exception e)
    {
      e.printStackTrace();
    }
  }
}

