public class Main {

	public static void main(String args[]) throws IOException{
		Scanner sc = new Scanner(System.in);

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(br.readLine());

		StringBuilder sb = new StringBuilder();

		int H = Integer.parseInt(st.nextToken()), W = Integer.parseInt(st.nextToken()), D = Integer.parseInt(st.nextToken());
		int r[] = new int[H*W+1];
		int c[] = new int[H*W+1];

		for(int i=1;i<=H;i++){
			st = new StringTokenizer(br.readLine());
			for(int j=1;j<=W;j++){
				int A = Integer.parseInt(st.nextToken());
				r[A] = i;
				c[A] = j;
			}
		}

		int dp[][] = new int[D+1][H*W/D+10];

		for(int i=1;i<=D && i+D <= H*W;i++){
			for(int j = 1;i+D*j<=H*W;j++){
				dp[i][j] = dp[i][j-1] + Math.abs(r[i+D*(j-1)]-r[i+D*j]) + Math.abs(c[i+D*(j-1)]-c[i+D*j]); 
			}
		}
		st = new StringTokenizer(br.readLine());
		int Q = Integer.parseInt(st.nextToken());

		while(Q-->0){
			st = new StringTokenizer(br.readLine());
			int L = Integer.parseInt(st.nextToken()), R = Integer.parseInt(st.nextToken());

			int i = (L-1)%D + 1;

			sb.append(dp[i][(R-i)/D] - dp[i][(L-i)/D]+"\n");
		}
		System.out.print(sb);
	}
}

import java.util.HashMap;
import java.util.Scanner;

public class Main {

  static class Vec2 {
    int x, y;

    public Vec2(int x, int y) {
      this.x = x;
      this.y = y;
    }

    int diff(Vec2 other) {
      return Math.abs(x - other.x) + Math.abs(y - other.y);
    }

    @Override
    public boolean equals(Object obj) {
      if (obj.getClass() != Vec2.class)
        return false;
      Vec2 o = (Vec2) obj;
      return x == o.x && y == o.y;
    }

    @Override
    public int hashCode() {
      return x ^ (y << 16);
    }
  }

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int h = sc.nextInt(), w = sc.nextInt(), d = sc.nextInt();

    Vec2[] map = new Vec2[h * w + 1];
    int[][] A = new int[h][w];
    for (int i = 0; i < A.length; i++) {
      for (int j = 0; j < A[i].length; j++) {
        A[i][j] = sc.nextInt();
        map[A[i][j]] = new Vec2(i, j);
      }
    }

    HashMap<Integer, Vec2> cache = new HashMap<Integer, Vec2>();
    int q = sc.nextInt();
    for (int i = 0; i < q; i++) {
      int l = sc.nextInt(), r = sc.nextInt();
      int cost = 0;
      Vec2 pos = map[l];
      //System.out.println(l + " " + r);
      while (A[pos.x][pos.y] != r) {

        //System.out.println("Debug: " + (A[pos.x][pos.y] + d));
        cost += map[A[pos.x][pos.y] + d].diff(pos);
        pos = map[A[pos.x][pos.y] + d];
      }
      cache.put(l, new Vec2(r, cost));
      System.out.println(cost);
    }
  }

}

