            int[] o2 = original[i];
            s[i+D] = s[i]
                    + Math.abs(o1[0]-o2[0])
                    + Math.abs(o1[1]-o2[1]);
        }
        int Q = scan.nextInt();
        for (int i = 0; i < Q; i++) {
            int L = scan.nextInt();
            int R = scan.nextInt();
            System.out.println(s[R]-s[L]);
        }
    }
}

