    static class coord{
        int x;
        int y;

        public coord(int xx, int yy){
            x = xx;
            y = yy;
        }
    }

    static int cost(coord[] location, int cur, int end, int add){
        int ans = 0;
        while(cur < end){
            ans += Math.abs(location[cur].x - location[cur+add].x) + Math.abs(location[cur].y - location[cur+add].y);
            cur += add;
        }

        return ans;
    }
