	public static int[] makedist2(HashMap<Integer, int[]> map, int d, int hw) {
		int[] ret = new int[hw+1];
		for(int i=1;i<=d;i++) {
			for(int j=i+d;j<=hw;j++) {
				ret[j] = ret[j-d]+ Math.abs(map.get(j)[0]-map.get(j-d)[0]) + Math.abs(map.get(j)[1]-map.get(j-d)[1]);
			}
		}
