	public static int solve(int p[][], int h, int w, int l, int r, int d) {
		int ans = 0, tmp = l;
		if(solved[l][r] != 0)return solved[l][r];
		while(tmp != r) {
			ans += Math.abs(p[tmp][0] - p[tmp + d][0]) + Math.abs(p[tmp][1]-p[tmp + d][1]);
			tmp += d;
		}
		solved[l][r] = ans;
		return ans;
	}

