class Main {

    static PrintWriter out;
    static InputReader sc;

    public static void main(String[] args) {
        sc = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    static void solve() {
        Map<Integer, Pair> map = new HashMap<>();
        int H = sc.nextInt();
        int W = sc.nextInt();
        int D = sc.nextInt();
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int a = sc.nextInt();
                map.put(a, new Pair(i, j));
            }
        }
        int[][] cost = new int[D][H * W / D + 1];
        for (int i = 0; i < D; i++) {
            int x = i;
            for (int k = 0; x + D < H * W; k++, x += D) {
                Pair p1 = map.get(x + 1);
                Pair p2 = map.get(x + D + 1);
                cost[i][k + 1] = cost[i][k] + Math.abs(p1.first - p2.first) + Math.abs(p1.second - p2.second);
            }
        }
        int Q = sc.nextInt();
        for (int i = 0; i < Q; i++) {
            int l = sc.nextInt() - 1;
            int r = sc.nextInt() - 1;
            out.println(cost[l % D][r / D] - cost[l % D][l / D]);
        }
    }

    /**
     * C++のPairと同じ
     */
    public static class Pair implements Comparable<Pair> {
        int first;
        int second;

        public Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public int hashCode() {
            return Integer.valueOf(this.first + this.second).hashCode();
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (!(obj instanceof Pair)) {
                return false;
            }
            Pair pair = (Pair) obj;
            return this.first == pair.first && this.second == pair.second;
        }

        @Override
        public int compareTo(Pair o) {
            return Integer.compare(this.first, o.first);
        }

        @Override
        public String toString() {
            return String.format("%d %d", this.first, this.second);
        }

    }

