    public void inputData() {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        D = sc.nextInt();
        A = new int[H][W];
        posX = new int[H * W];
        posY = new int[H * W];
        score = new int[H * W][H * W];
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                A[i][j] = sc.nextInt();
                posX[A[i][j] - 1] = j;
                posY[A[i][j] - 1] = i;
            }
        }
        for (int i = 0; i < H * W; i++) {
            for (int j = 0; j < H * W; j++) {
                score[i][j] = Integer.MAX_VALUE;
            }
        }
        Q = sc.nextInt();
        L = new int[Q];
        R = new int[Q];
        for (int i = 0; i < Q; i++) {
            L[i] = sc.nextInt();
            R[i] = sc.nextInt();
        }
    }

    public void printAnswer() {
