using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AtCoder2 {
	class Program {
		static void Main(string[] args) {

		　　var inputArray = retreiveLongArray();
			var inputCount = 3;

			// 不正な入力は処理しない
			if (inputArray.Length != inputCount) {
				Console.WriteLine("invalid input");
				return;
			}
			var H = (int)inputArray[0];
			var W = (int)inputArray[1];
			var D = (int)inputArray[2];

			var zahhyou = new Dictionary<int, Tuple<int, int>>();

			for (int i = 0; i < H; i++) {
				var inp = retreiveLongArray();
				for (int j = 0; j < W; j++) {
					var input = (int)inp[j];
					zahhyou.Add(input, new Tuple<int, int>(i, j));
				}
			}
			var Q = retreiveLongArray()[0];
			var Questions = new List<Tuple<int, int>>();

			for (int i = 0; i < Q; i++) {
				var inp = retreiveLongArray();
				Questions.Add(new Tuple<int, int>((int)inp[0], (int)inp[1]));
			}
			var ruiseki = new Dictionary<int, int>();
			for (int i = 1; i <= D; i++) {
				ruiseki.Add(i, 0);
				var k = i+D;
				var previous = zahhyou[i];
				while (k <= H*W) {
					var current = zahhyou[k];
					var distanse = Math.Abs(current.Item1 - previous.Item1) + Math.Abs(current.Item2 - previous.Item2);
					ruiseki.Add(k, ruiseki[k - D] + distanse);
					previous = current;
					k += D;
				}

			}
			foreach (var question in Questions) {
				Console.WriteLine(ruiseki[question.Item2] - ruiseki[question.Item1]);
			}



		}

		/// <summary>
		/// スペースで区切られた文字列配列の入力を受け取る
		/// </summary>
		/// <returns></returns>
		private static string[] retreiveStringArray() {
			var inputArray = Console.ReadLine().Split(' ');
			return inputArray;
		}

		/// <summary>
		/// スペースで区切られた整数配列の入力を受け取る
		/// </summary>
		/// <returns></returns>
		private static long[] retreiveLongArray() {
			var inputArray = Console.ReadLine().Split(' ');
			var longArray = inputArray.Select(s => long.Parse(s));
			return longArray.ToArray();
		}
	}
