        public void Solve()
        {
            int H = cin.ReadInt;
            int W = cin.ReadInt;
            int D = cin.ReadInt;

            int[][] A = JagArray2D<int>(H, W);
            for (int i = 0; i < H; i++)
            {
                A[i] = cin.ReadIntArray(W);
            }

            Pair[] numToPos = new Pair[H * W +1];


            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    int num = A[i][j];
                    numToPos[num] = new Pair(i, j);
                }
            }

            // long[] S = new long[H * W + 1];
            //
            // for (int i = D + 1; i <= H * W; i++)
            // {
            //     S[i] = S[i - D] + Math.Abs(numToPos[i].First - numToPos[i - D].First) + Math.Abs(numToPos[i].Second - numToPos[i - D].Second);
            // }
            //
            // int Q = cin.ReadInt;
            //
            // for (int i = 0; i < Q; i++)
            // {
            //     int l = cin.ReadInt;
            //     int r = cin.ReadInt;
            //
            //     long ans = S[r] - S[l];
            //     cou.WriteLine(ans);
            // }

            int Q = cin.ReadInt;

            int Len = (H * W + D - 1) / D;

            // S[i][j] : [Dで割ったあまりがiであるマス][j + 1番目まで]の総和
            long[][] S = JagArray2D<long>(D, Len + 2);

            for (int k = 0; k < D; k++)
            {
                int num = k;

                // if (num <= 0) num += D;

                int currX = -1;
                int currY = -1;

                int ind = 0;

                while (true)
                {
                    if (num > H * W) break;

                    Pair tmp   = numToPos[num];
                    int nextX = tmp.First;
                    int nextY = tmp.Second;

                    // if (tmp == 0)
                    // {
                    //     nextX = -1;
                    // }

                    if (currX >= 0)
                    {
                        S[k][ind + 1] = S[k][ind] + (Math.Abs(nextX - currX) + Math.Abs(nextY - currY));
                    }

                    ind++;
                    num += D;

                    currX = nextX;
                    currY = nextY;
                }
            }

            for (int query = 0; query < Q; query++)
            {
                int l = cin.ReadInt;
                int r = cin.ReadInt;

                int k = l % D;

                int start = l / D;
                int goal  = r / D;

                long ans = S[k][goal + 1] - S[k][start + 1];

                cou.WriteLine(ans);
            }
        }

