    {
        static void Main(string[] args)
        {
            string[] str = Console.ReadLine().Split(' ');

            int H = int.Parse(str[0]);
            int W = int.Parse(str[1]);
            int D = int.Parse(str[2]);

            var A = new int[H, W];

            for(int i = 0; i < H; i++)
            {
                string[] num = Console.ReadLine().Split(' ');
                for(int k = 0; k < W; k++)
                {
                    A[i, k] = int.Parse(num[k]);
                }
            }

            int Q = int.Parse(Console.ReadLine());

            int[] L = new int[Q];
            int[] R = new int[Q];
            for(int i = 0; i < Q; i++)
            {
                string[] lr = Console.ReadLine().Split(' ');
                L[i] = int.Parse(lr[0]);
                R[i] = int.Parse(lr[1]);
            }

            int[] ans = new int[Q];

            int[] count = new int[Q];
            for (int i = 0; i < Q; i++)
            {
                count[i] = (R[i] - L[i]) / D;
            }
            int[][] lX = new int[Q][];
            int[][] lY = new int[Q][];

            for(int i = 0; i < Q; i++)
            {
                lX[i] = new int[count[i] + 1];
                lY[i] = new int[count[i] + 1];
            }

            for (int j = 0; j < H; j++)
            {
                for (int k = 0; k < W; k++)
                {
                    for (int i = 0; i < Q; i++)
                    {
                        if (A[j, k] >= L[i] && A[j, k] <= R[i] && (A[j, k] - L[i]) % D == 0)
                        {
                            lX[i][(A[j, k] - L[i]) / D] = j;
                            lY[i][(A[j, k] - L[i]) / D] = k;
                        }
                    }
                }
            }

            for(int i = 0; i <= Q; i++)
            {
                for(int j = 1; j <= count[i]; j++)
                {
                    ans[i] += Math.Abs(lX[i][j - 1] - lX[i][j]);
                    ans[i] += Math.Abs(lY[i][j - 1] - lY[i][j]);
                }
            }

            foreach(var item in ans)
            {
                Console.WriteLine(item);
            }
        }
    }
}

