	using Ll = List<long>;
	using ti3 = Tuple<int, int, int>;
	using ti2 = Tuple<int, int>;
	internal class Program {
		private static void Main(string[] args) {
			var sw = new StreamWriter(OpenStandardOutput()) { AutoFlush = false };
			SetOut(sw);
			new Calc().Solve();
			Out.Flush();
		}

		public class Calc {
			public void Solve() {
				int H = NextInt(), W = NextInt(), D = NextInt();
				var dic = new Map<int, ti2>();

				H.REP(y=>W.REP(x => { dic[NextInt()] = new ti2(x, y); }));

				var wf=new WarshallFloyd(H*W);

				foreach (var item in dic) {
					if(item.Key+D>H*W)continue;
					var s = item.Value;
					var t = dic[item.Key + D];
					long cost = Abs(s.Item1 - t.Item1) + Abs(s.Item2 - t.Item2);
					wf.Add(item.Key-1, item.Key + D-1, cost);
				}

				var res = wf.Run();


				NextInt().REP(i =>
				{
					int Li = NextInt()-1, Ri = NextInt()-1;
					 res[Li][Ri].WL();
				});



				return;
			}
		}
		public class CostGraph {
			public struct Edge {
				public int To { get; set; }
				public long Cost { get; set; }


				public Edge(int to, long cost) {
					To = to;
					Cost = cost;
				}

			}

			public int Size { get; set; }
			public List<List<Edge>> Adjacency { get; set; }
			public const long Inf = (long)1e15;

			public CostGraph(int size) {
				Size = size;
				Adjacency = new List<List<Edge>>();
				Size.REP(_ => Adjacency.Add(new List<Edge>()));
			}

			public void Add(int s, int t, long c, bool dir = true) {
				Adjacency[s].Add(new Edge(t, c));
				if (!dir) Adjacency[t].Add(new Edge(s, c));
			}

		}
		public class WarshallFloyd : CostGraph {
			public WarshallFloyd(int size) : base(size) {
			}

			public List<Ll> Run() {
				var rt = new List<Ll>();
				Size.REP(_ => rt.Add(new Ll()));

				Size.REP(i => Size.REP(k => rt[i].Add(i == k ? 0 : Inf)));

				Adjacency.ForeachWith((i, item) => {
					foreach (var k in item) {
						rt[i][k.To] = k.Cost;
					}
				});

				Size.REP(i => Size.REP(j => Size.REP(k => {
					rt[j][k] = Min(rt[j][k], rt[j][i] + rt[i][k]);
				})));

				return rt;
			}
		}


	}
}
namespace Nakov.IO {
	using System;
	using System.Text;
	using System.Globalization;

	public static class Cin {
		public static string NextToken() {
			StringBuilder tokenChars = new StringBuilder();
			bool tokenFinished = false;
			bool skipWhiteSpaceMode = true;
			while (!tokenFinished) {
				int nextChar = Console.Read();
				if (nextChar == -1) {
					tokenFinished = true;
				} else {
					char ch = (char)nextChar;
					if (char.IsWhiteSpace(ch)) {
						if (!skipWhiteSpaceMode) {
							tokenFinished = true;
							if (ch == '\r' && (Environment.NewLine == "\r\n")) {
								Console.Read();
							}
						}
					} else {
						skipWhiteSpaceMode = false;
						tokenChars.Append(ch);
					}
				}
			}

			string token = tokenChars.ToString();
			return token;
		}

		public static int NextInt() {
			string token = Cin.NextToken();
			return int.Parse(token);
		}
		public static long NextLong() {
			string token = Cin.NextToken();
			return long.Parse(token);
		}
		public static double NextDouble(bool acceptAnyDecimalSeparator = true) {
			string token = Cin.NextToken();
			if (acceptAnyDecimalSeparator) {
				token = token.Replace(',', '.');
				double result = double.Parse(token, CultureInfo.InvariantCulture);
				return result;
			} else {
				double result = double.Parse(token);
				return result;
			}
		}
		public static decimal NextDecimal(bool acceptAnyDecimalSeparator = true) {
			string token = Cin.NextToken();
			if (acceptAnyDecimalSeparator) {
				token = token.Replace(',', '.');
				decimal result = decimal.Parse(token, CultureInfo.InvariantCulture);
				return result;
			} else {
				decimal result = decimal.Parse(token);
				return result;
			}
		}

	}
