    class Program
    {
        static void Solve(Input input)
        {
            var h = input.NextInt();
            var w = input.NextInt();
            var d = input.NextInt();

            var a = Utils.Create2DArray(h, w, 0);

            for (int i = 0; i < h; i++)
            {
                for (int j = 0; j < w; j++)
                {
                    a[i][j] = input.NextInt();
                }
            }

            // keyが存在する(x,y)座標
            var dic = new Dictionary<int, Tuple<int, int>>();
            for (int i = 0; i < h; i++)
            {
                for (int j = 0; j < w; j++)
                {
                    dic.Add(a[i][j], new Tuple<int, int>(j, i));
                }
            }

            // [i][j]: iからjに移動するときのコスト
            var dp = Utils.Create2DArray(h * w + 1, h * w + 1, -1);
            var q = input.NextInt();
            for (int i = 0; i < q; i++)
            {
                var l = input.NextInt();
                var r = input.NextInt();

                var cost = solvedp(dic, dp, l, r, d);

                Console.WriteLine(cost);
            }
        }

        static int solvedp(Dictionary<int, Tuple<int, int>> dic, int[][] dp, int l, int r, int d)
        {
            if (l == r)
            {
                return 0;
            }

            if (dp[l][r] >= 0)
            {
                return dp[l][r];
            }

            var cost = Math.Abs(dic[l].Item1 - dic[l + d].Item1) + Math.Abs(dic[l].Item2 - dic[l + d].Item2);
            dp[l][l + d] = cost;

            if (dp[l][r] < 0)
            {
                cost += solvedp(dic, dp, l + d, r, d);
                dp[l][r] = cost;
            }

            return dp[l][r];
        }

        #region Competitive Template
        static readonly int MOD = (int)1e9 + 7;

        public static void Main(string[] args)
        {
            // 出力が少ないときはこれをセットする方が時間かかるけれど
            // その場合は出力がボトルネックになっていないので、まあ良しとする
            var needsFlushOutput = true;
            if (needsFlushOutput)
            {
                // 細かく出力しないようにする
                var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
                Console.SetOut(sw);
            }

            // 通常は引数無しで、ファイルから読み出したい場合はpath指定する
            var input = new Input();
