namespace ABC089_D
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] strs = Console.ReadLine().Split(' ');
            int h = int.Parse(strs[0]);
            int w = int.Parse(strs[1]);
            int d = int.Parse(strs[2]);

            int hw = h * w;

            int[,] offset = new int[d, hw / d + 1];

            int[] row = new int[hw + 1];
            int[] column = new int[hw + 1];

            string[] strsTmp = new string[h];

            for (int i = 0; i < h; ++i)
            {
                string[] strs_ = Console.ReadLine().Split(' ');

                for (int j = 0; j < w; ++j)
                {
                    int tmp_ = int.Parse(strs_[j]);
                    column[tmp_] = j + 1;
                    row[tmp_] = i + 1;

                    int next = tmp_ + d;
                    if (next <= hw)
                    {
                        if (column[next] != 0)
                        {
                            offset[tmp_ % d, tmp_ / d] = Math.Abs((i+1) - row[next]) + Math.Abs((j+1) - column[next]);
                        }
                    }

                    int prev = tmp_ - d;
                    if (prev >= 1 && offset[prev % d, prev / d] == 0)
                    {
                        if (column[prev] != 0)
                        {
                            offset[prev % d, prev / d] = Math.Abs((i + 1) - row[prev]) + Math.Abs((j + 1) - column[prev]);
                        }
                    }
                }
            }

            int q = int.Parse(Console.ReadLine());

            int[] ans = new int[q];

            for (int i = 0; i < q; ++i)
            {
                string[] strs3 = Console.ReadLine().Split(' ');
                int l = int.Parse(strs3[0]);
                int r = int.Parse(strs3[1]);

                //ans[i] = CalcMP(l, r, d);
                {
                    int mp = 0;

                    int mod = l % d;
                    int div = l / d;

                    if (l < r)
                    {
                        int loopCount = (r - l) / d;

                        for (int j = 0; j < loopCount; ++j)
                        {
                            mp += offset[mod, div + j];
                        }
                    }
                    else
                    {
                        int loopCount = -(r - l) / d;

                        for (int j = loopCount - 1; j >= 0; --j)
                        {
                            mp += offset[mod, div + j];
                        }
                    }

                    ans[i] = mp;
                }
            }

            for (int i = 0; i < q; ++i)
            {
                Console.WriteLine("{0}", ans[i]);
            }
        }
    }
}

