class Program
{
    public static int Main()
    {
        string[] imp = Console.ReadLine().Split(' ');
        int h, w, d;
        h = int.Parse(imp[0]);
        w = int.Parse(imp[1]);
        d = int.Parse(imp[2]);
        int[,] a2 = new int[h * w, 2];
        for (int i = 0; i < h; i++)
        {
            imp = Console.ReadLine().Split(' ');
            for (int j = 0; j < w; j++)
            {
                a2[int.Parse(imp[j]) - 1, 0] = i;
                a2[int.Parse(imp[j]) - 1, 1] = j;
            }
        }
        int[] sum = new int[h * w];
        for (int i = 0; i < h * w; i++)
        {
            if (i < d)
                sum[i] = 0;
            else
                sum[i] = sum[i - d] + Math.Abs(a2[i, 0] - a2[i - d, 0]) + Math.Abs(a2[i, 1] - a2[i - d, 1]);
