        {
            SolveA(args);
            //SolveB(args);
            //SolveC(args);
            //SolveD(args);


        }
        private struct Pos
        {
            public int row;
            public int col;
        }
        private const long MOD = 1000000007;
        static void SolveA(string[] args)
        {
            var hwd = ReadAndParseIntArr();
            int h = hwd[0];
            int w = hwd[1];
            int d = hwd[2];
            int[,] A = new int[h, w];
            for (int i = 0; i < h; ++i)
            {
                var a = ReadAndParseIntArr();
                for (int j = 0; j < w; ++j)
                {
                    A[i, j] = a[j];
                }
            }
            var coordinate = new Pos[h * w + 1];
            for(int i=0;i<h;++i)
            {
                for(int j=0;j<w;++j)
                {
                    coordinate[A[i, j]] = new Pos() { row = i, col = j };
                }
            }
            int q = ReadAndParseInt();
            int[] L = new int[q];
            int[] R = new int[q];
            for(int i=0;i<q;++i)
            {
                var lr = ReadAndParseIntArr();
                L[i] = lr[0];
                R[i] = lr[1];
            }

            for(int i=0;i<q;++i)
            {
                long cost = 0;
                int l = L[i];
                int r = R[i];
                for(int start=l;start+d<=r;start+=d)
                {
                    int srow, scol;
                    Find(start, coordinate, out srow, out scol);
                    int drow, dcol;
                    Find(start +d , coordinate, out drow, out dcol);
                    cost += Math.Abs(drow - srow) + Math.Abs(dcol - scol);
                }
                Console.WriteLine(cost);
            }
        }
        private static void Find(int x, Pos[] coordinate, out int row, out int col)
        {
            row = coordinate[x].row;
            col = coordinate[x].col;
        }
    }
