class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        H = sc.ReadInt();
        W = sc.ReadInt();
        D = sc.ReadInt();
        A = new int[H, W];
        B = new Tuple<int, int>[H * W];
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                A[i, j] = sc.ReadInt() - 1;
                B[A[i, j]] = Tuple.Create(i, j);
            }
        }
        Memo = new Dictionary<Tuple<int, int>, long>();
        var Q = sc.ReadInt();
        while (Q-- > 0)
        {
            var L = sc.ReadInt();
            var R = sc.ReadInt();
            L--; R--;
            var rem = (R - L) / D;

            var l = 0;
            var r = rem + 1;
            while (r - l > 1)
            {
                var mid = l + (r - l) / 2;
                var key = Tuple.Create(L, mid);
                if (Memo.ContainsKey(key)) l = mid;
                else r = mid;
            }
            var cost = l > 0 ? Memo[Tuple.Create(L, l)] : 0;
            var ans = Rec(L, rem - l) + cost;
            Console.WriteLine(ans);
        }
    }
    static Dictionary<Tuple<int, int>, long> Memo;
    static long Rec(int now, int rem)
    {
        var key = Tuple.Create(now, rem);
        if (Memo.ContainsKey(key)) return Memo[key];
        if (rem == 0) return 0;

        var nowH = B[now].Item1;
        var nowW = B[now].Item2;
        var nextH = B[now + D].Item1;
        var nextW = B[now + D].Item2;
        var cost = Math.Abs(nextH - nowH) + Math.Abs(nextW - nowW);
        var next = A[nextH, nextW];
        var res = Rec(next, rem - 1) + cost;
        Memo[key] = res;
        return res;
    }
    static int H, W, D;
    static int[,] A;
    static Tuple<int, int>[] B;
    static Scanner sc = new Scanner();
}
