            new Program().Solve();
        }

        void Solve()
        {
            var tmp = ReadIntArray();
            int h = tmp[0];
            int w = tmp[1];
            int d = tmp[2];
            var dict = new Dictionary<int, Position>();
            for (int i = 0; i < h; i++)
            {
                tmp = ReadIntArray();
                for (int j = 0; j < tmp.Length; j++)
                {
                    dict.Add(tmp[j], new Position(j, i));
                }
            }

            var total = new Dictionary<int, int>();
            for (int i = 1; i <= h * w; i++)
            {
                total.Add(i, 0);
            }

            for (int i = 1; i <= d; i++)
            {
                total[i] = 0;
                for (int next = i + d; next <= h * w; next += d)
                {
                    var diff = GetPower(dict[next - d], dict[next]);
                    total[next] = total[next - d] + diff;
                }
            }

            int q = int.Parse(Console.ReadLine());
            for (int i = 0; i < q; i++)
            {
                tmp = ReadIntArray();
                Console.WriteLine(total[tmp[1]] - total[tmp[0]]);
            }
        }

        int[] ReadIntArray()
        {
            return Console.ReadLine().Split().Select(x => int.Parse(x)).ToArray();
        }

        int GetPower(Position a, Position b)
        {
            return Math.Abs(a.X - b.X) + Math.Abs(a.Y - b.Y);
        }

        struct Position
        {
            public int X { get; set; }
            public int Y { get; set; }
            public Position(int x, int y)
            {
                X = x;
                Y = y;
