                else
                {
                    int[] lX = new int[count + 1];
                    int[] lY = new int[count + 1];

                    for (int j = 0; j < H; j++)
                    {
                        for (int k = 0; k < W; k++)
                        {
                            if (A[j, k] >= l && A[j, k] <= r && (A[j, k] - l) % D == 0)
                            {
                                lX[(A[j, k] - l) / D] = j;
                                lY[(A[j, k] - l) / D] = k;
                            }
                        }
                    }

                    for(int j = 1; j <= count; j++)
                    {
                        ans[i] += Math.Abs(lX[j] - lX[j - 1]);
                        ans[i] += Math.Abs(lY[j] - lY[j - 1]);
                    }
                }
            }

            foreach(var item in ans)
            {
                Console.WriteLine(item);
            }
        }
    }
}

