                    if (to > H * W)
                    {
                        break;
                    }
                    var pre = point + (x - 1) * D;
                    var prePoint = dicPoint[pre];
                    var toPoint = dicPoint[to];
                    var cost = Math.Abs(prePoint.X - toPoint.X) + Math.Abs(prePoint.Y - toPoint.Y);
