public class Solver
{
	public void Solve()
	{
		long H = GetLong();
		long W = GetLong();
		long D = GetLong();
		var xy = new (long, long)[H * W];
		for(long i = 0; i < H; i++)
		{
			for(long j = 0; j < W; j++)
				xy[GetLong() - 1] = (i, j);
		}

		var dp = new long[H * W];
		for(long i = 0; i < H * W - D; i++)
		{
			var (cx, cy) = xy[i];
			var (nx, ny) = xy[i + D];
			dp[i + D] = dp[i] + Abs(nx - cx) + Abs(ny - cy);
		}

		long Q = GetLong();
		var ans = new long[Q];
		for(long i = 0; i < Q; i++)
		{
			long L = GetLong() - 1;
			long R = GetLong() - 1;
			ans[i] = dp[R] - dp[L];
		}
		WriteLine(string.Join("\n", ans));
	}
}

