        for (int i = 0; i < Q; i++) {
            L[i] = sc.nextInt();
            R[i] = sc.nextInt();
        }

        var dic = new Dictionary<int, Zahyo>();
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) dic.Add(A[i, j], new Zahyo { i = i, j = j });
        }

        for (int i = 0; i < Q; i++) {
            var ans = 0;
            var l = L[i];
            while (l < R[i]) {
                ans += Math.Abs(dic[l].i - dic[l + D].i) +
                           Math.Abs(dic[l].j - dic[l + D].j);
                l += D;
            }
            WriteLine(ans);
        }
    }
}



