class MainClass : Scanner
{
    static void Main()
    {
        var (H, W, D) = ReadTuple<int,int,int>();
        var A = new int[H, W];
        var dic = new Dictionary<int, (int y, int x)>();
        for (int i = 0; i < H; i++)
        {
            var line = RInts();
            for (int j = 0; j < W; j++)
            {
                A[i, j] = line[j];
                dic[line[j]] = (i, j);
            }
        }
        var Q = RInt();
        var LR = new int[Q][];
        for (int i = 0; i < Q; i++)
        {
            LR[i] = RInts();
        }
        var costs = Enumerable.Repeat(-1L, H * W + 1).ToArray();
        int start = 0;
        while (costs[++start]==-1)
        {
            long cost = 0;
            int now = start;
            costs[now] = cost;
            while (now + D <= H * W)
            {
                var nowpos = dic[now];
                var nextpos = dic[now + D];
                cost += (Abs(nowpos.x - nextpos.x) + Abs(nowpos.y - nextpos.y));

                now += D;
                costs[now] = cost;
            }
        }


        for (int i = 0; i < Q; i++)
        {
            long ans = 0;
            int L = LR[i][0];
            int R = LR[i][1];
            ans = Abs(costs[L] - costs[R]);
            WriteLine(ans);
        }

    }
}



