class Program
{
    public static void Main()
    {
	var tmp = ReadIntArray();
	int h = tmp[0], w = tmp[1], d = tmp[2];

	var pos = new Tuple<int,int>[h*w+1];
	for (int i = 1; i <= h; i++)
	{
	    var a = ReadIntArray();
	    for (int j = 1; j <= w; j++)
	    {
		pos[a[j-1]] = Tuple.Create(i, j);
	    }
	}

	var s = new int[h*w+1];

	for (int i = d; i <= h*w; i += d)
	{
	    for (int j = 1; j <= d; j++)
	    {
		int n1 = i+j, n0 = n1 - d;
		if (n1 > h*w) break;
		var t0 = pos[n0];
		var t1 = pos[n1];
		int dist = Math.Abs(t1.Item1 - t0.Item1) +
		    Math.Abs(t1.Item2 - t0.Item2);
		s[n1] = s[n0] + dist;
	    }
	}

	int q = int.Parse(ReadLine());
	for (int i = 0; i < q; i++)
	{
	    tmp = ReadIntArray();
	    int l = tmp[0], r = tmp[1];
	    WriteLine(s[r] - s[l]);
	}
    }
}

