public class Program
{

    public void Proc()
    {
        int[] inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
        this.RowCount = inpt[0];
        this.ColCount = inpt[1];
        this.Jump = inpt[2];

        for (int i = 0; i < RowCount; i++) {
            inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
            for (int j = 0; j < ColCount; j++) {
                Map.Add(inpt[j], new Pos(i, j));
            }
        }

        int queryCount = int.Parse(Reader.ReadLine());
        List<int[]> query = new List<int[]>();
        for (int i = 0; i < queryCount; i++)
        {
            query.Add(Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray());
        }

        for (int i = 1; i <= Jump; i++) {
            this.JumpLen[i] = 0;
            int prevNum = i;
            for (int j = i+Jump; j <= this.RowCount * this.ColCount; j+=Jump) {
                int addNum = Math.Abs(Map[prevNum].Row - Map[j].Row) + Math.Abs(Map[prevNum].Col - Map[j].Col);
                JumpLen[j] = JumpLen[prevNum] + addNum;
                prevNum = j;
            }
        }

        StringBuilder ans = new StringBuilder();

        foreach(int[] q in query) {
            long tmp = JumpLen[q[1]] - JumpLen[q[0]];
            ans.AppendLine(tmp.ToString());
        }
        Console.Write(ans.ToString());
    }

    private int RowCount;
    private int ColCount;
    private int Jump;

    private Dictionary<int, Pos> Map = new Dictionary<int, Pos>();

    private Dictionary<int, long> JumpLen = new Dictionary<int, long>();

    private class Pos {
        public int Row;
        public int Col;
        public Pos(int r, int c) {
            this.Row = r;
            this.Col = c;
        }
