class MainClass
{
    public static void Main(string[] args)
    {

        string[] s = Console.ReadLine().Split(' ');
        int H = int.Parse(s[0]);
        int W = int.Parse(s[1]);
        int D = int.Parse(s[2]);
        int[,] A = new int[H,W];
        int[,] magic = new int[H, W];
        for (int i = 0; i < H;i++)
        {
            s = Console.ReadLine().Split(' ');
            for (int j = 0; j < W; j++)
            {
                A[i,j] = int.Parse(s[j]);
            }
        }
        int Q = int.Parse(Console.ReadLine());
        int[] L = new int[Q];
        int[] R = new int[Q];

        for (int i = 0; i < Q;i++)
        {
            s = Console.ReadLine().Split(' ');
            L[i] = int.Parse(s[0]);
            R[i] = int.Parse(s[1]);
        }

        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                for (int k = 0; k < H; k++)
                {
                    for (int l = 0; l < W; l++)
                    {
                        if(A[i,j] + D == A[k,l])
                        {
                            magic[i,j] += Math.Min(Math.Abs(i - k), Math.Abs(k - i));
                            magic[i,j] += Math.Min(Math.Abs(j - l), Math.Abs(l - j));
                        }
                    }
                } 
            }
        }

        for (int num = 0; num < Q; num++)
        {
            int ans = 0;
            if(L[num] == R[num])
            {
                Console.WriteLine("0");
                continue;
            }

            while(true)
            {

                for (int i = 0; i < H; i++)
                {
                    for (int j = 0; j < W; j++)
                    {
                        if(L[num] == A[i,j])
                        {
                            ans += magic[i,j];
                            break;
                        }
                    }
                }

                L[num] += D;

                if (L[num] == R[num])
                {
                    Console.WriteLine(ans);
                    break;
                }
            }
        }

    }
