using System.Numerics;
using static System.Console;

class Solver {
    Scanner sc = new Scanner();

    struct Zahyo {
        public int i;
        public int j;
    }

    public void Solve() {
        var H = sc.nextInt();
        var W = sc.nextInt();
        var D = sc.nextInt();
        var A = new int[H, W];
        var dic = new Dictionary<int, Zahyo>();
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                A[i, j] = sc.nextInt();
                dic.Add(A[i, j], new Zahyo { i = i, j = j });
            }
        }
        var Q = sc.nextInt();
        var L = new int[Q];
        var R = new int[Q];
        for (int i = 0; i < Q; i++) {
            L[i] = sc.nextInt();
            R[i] = sc.nextInt();
        }

        var cost = new int[H * W + 10, H * W + 10];
        for (int i = 1; i <= H * W; i++) {
            for (int j = i + D; j <= H * W; j += D) {
                if (j > dic.Count) continue;
                cost[i, j] = cost[i, j - D] + Math.Abs(dic[j - D].i - dic[j].i) + Math.Abs(dic[j - D].j - dic[j].j);
            }
        }

        for (int i = 0; i < Q; i++) {
            WriteLine(cost[L[i], R[i]]);
        }
    }
}



