            for (int i = 0; i < len; i++)
            {
                T[] inner       = source[i];
                int innerLength = inner.Length;
                T[] newer       = new T[innerLength];
                Array.Copy(inner, newer, innerLength);
                dest[i] = newer;
            }

            return dest;
        }

        /// <summary>
        /// 昇順にソートされたlong配列で、threshold以上の値をカウントする
        /// </summary>
        public static int LargerCount(this long[] a, long threshold)
        {
            int ng = -1;
            int ok = a.Length;

            while (Math.Abs(ng - ok) > 1)
            {
                int mid = (ok + ng) / 2;
                if (threshold <= a[mid])
                {
                    ok = mid;
                }
                else
                {
                    ng = mid;
                }
            }

            return a.Length - ok;
        }
    }

    public class IntLargeComparer : IComparer<int>
    {
        public static IntLargeComparer Instance = new IntLargeComparer();

        public int Compare(int x, int y)
