    class Abc089d
    {
        static void Main(string[] args) {
            var h_w_d = Console.ReadLine().Split();
            var h = int.Parse(h_w_d[0]);
            var w = int.Parse(h_w_d[1]);
            var d = uint.Parse(h_w_d[2]);

            var a = new uint[(h+1) * (w+1)];
            for (var row = 1; row <= h; ++row) {
                var line = Console.ReadLine().Split().ToList().ConvertAll(uint.Parse);
                for(var col=1; col <=w; ++col) {
                    a[row * ( w + 1 ) + col] = line[col - 1];
                }
            }

            var q = uint.Parse(Console.ReadLine());
            var answers = new List<ulong>();
            for(var i = 1; i <=q; ++i) {
                var l_r = Console.ReadLine().Split();

                var x = uint.Parse(l_r[0]);
                var answer = 0u;
                while (x != uint.Parse(l_r[1])) {
                    var curIndex = a.ToList().IndexOf(x);
                    var curX = curIndex / ( w + 1 );
                    var curY = curIndex % ( w + 1 );
                    var destIndex = a.ToList().IndexOf(x + d);
                    var destX = destIndex / ( w + 1 );
                    var destY = destIndex % ( w + 1 );

                    answer += (uint)Math.Abs(destX - curX) + (uint)Math.Abs(destY - curY);
                    x = x+d;
                }
                answers.Add(answer);
            }

            foreach(var answer in answers) {
                Console.WriteLine(answer);
            }

        }
    }
