namespace AtCoderBS
{
    class Program
    {
        static void Main(string[] args)
        {
            int[] n = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            int h = n[0];
            int w = n[1];
            int d = n[2];
            int[,] map = new int[h, w];

            for (int i = 0; i < h; i++)
            {
                int[] mapLine = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

                for (int j = 0; j < w; j++)
                {
                    map[i, j] = mapLine[j];
                }
            }

            int q = int.Parse(Console.ReadLine());
            int[] mp = new int[q];

            for (int k = 0; k < q; k++)
            {
                int[] m = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                int beforeX = 0;
                int beforeY = 0;
                int afterX = 0;
                int afterY = 0;

                for (int l = m[0]; l != m[1]; l += d)
                {
                    for (int x = 0; x < w; x++) // l 
                    {
                        for (int y = 0; y < h; y++)
                        {
                            if (map[x, y] == l)
                            {
                                beforeX = x;
                                beforeY = y;
                                goto afterXY;
                            }
                        }
                    }

                    afterXY:
                    for (int x = 0; x < w; x++) // l + d
                    {
                        for (int y = 0; y < h; y++)
                        {
                            if (map[x, y] == l + d)
                            {
                                afterX = x;
                                afterY = y;
                                goto mpPlus;
                            }
                        }
                    }

                    mpPlus:
                    mp[k] += Math.Abs(afterX - beforeX) + Math.Abs(afterY - beforeY);
                }
            }
            foreach(int i in mp)
            {
                Console.WriteLine(i);
            }
            Console.Read();
        }
    }
}

