				}

			}

			int[] p = new int[h * w];
			for (int i = 0; i < h * w; i++) {
				if (i / d == 0) {
					p[i] = 0;
				} else {
					var dst = a[i];
					var src = a[i - d];
					p[i] = Math.Abs(src.X - dst.X) + Math.Abs(src.Y - dst.Y)
						+ p[i - d];
				}
			}

			int q = int.Parse(Console.ReadLine());
			for (int i = 0; i < q; i++) {
				int[] lr = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
				Console.WriteLine(p[lr[1] - 1] - p[lr[0] - 1]); 
			}
		}
	}

	public struct Point
	{
		public int X;
		public int Y;
	}
}

