namespace AtCoder_ABC089_A
{
    class Program
    {
        static int[,] a;

        static int h;
        static int w;

        static void Find(int number, out int row, out int column)
        {
            column = 0;

            for (row = 0; row < h; ++row)
            {
                for (column = 0; column < w; ++column)
                {
                    if (a[row, column] == number)
                    {
                        return;
                    }
                }
            }
        }


        static void Main(string[] args)
        {
            string[] hwd = Console.ReadLine().Split(' ');
            h = int.Parse(hwd[0]);
            w = int.Parse(hwd[1]);
            int d = int.Parse(hwd[2]);

            a = new int[h, w];
            for (int i = 0; i < h; ++i)
            {
                string[] tmp = Console.ReadLine().Split(' ');
                for (int j = 0; j < w; ++j)
                {
                    a[i, j] = int.Parse(tmp[j]);
                }
            }

            int q = int.Parse(Console.ReadLine());

            int[] l = new int[q];
            int[] r = new int[q];

            for (int i = 0; i < q; ++i)
            {
                string[] tmp = Console.ReadLine().Split(' ');
                l[i] = int.Parse(tmp[0]);
                r[i] = int.Parse(tmp[1]);
            }


            for (int q_ = 0; q_ < q; ++q_)
            {
                int magic = 0;
                int number = l[q_];
                int row = 0;
                int column = 0;

                Find(number, out row, out column);

                while (number != r[q_])
                {
                    number += d;

                    int row2, column2;
                    Find(number, out row2, out column2);

                    magic += Math.Abs(row - row2) + Math.Abs(column - column2);

                    row = row2;
                    column = column2;
                }

                Console.WriteLine(magic);
            }
        }
    }
}

