    {
        static void Main(string[] args)
        {
            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            int[] hwd = ReadInts();
            var grid = new int[hwd[0]][];
            var posDict = new Dictionary<int, int[]>();
            for(int i = 0; i < hwd[0]; i++)
            {
                grid[i] = ReadInts();
                for (int j = 0; j < hwd[1]; j++)
                {
                    posDict.Add(grid[i][j], new int[2] { i, j });
                }
            }
            var costGrid = new int[hwd[0], hwd[1]];
            for(int i = 0; i < hwd[0]; i++)
            {
                for(int j = 0; j < hwd[1]; j++)
                {
                    if(posDict.ContainsKey(grid[i][j] + hwd[2]))
                    {
                        int[] pos = posDict[grid[i][j] + hwd[2]];
                        costGrid[i, j] = Math.Abs(i - pos[0])
                            + Math.Abs(j - pos[1]);
                    }
                    else
                    {
                        costGrid[i, j] = 0;
                    }
                }
            }

            int q = ReadInt();
            var lrs = new int[q][];
            for(int i = 0; i < q; i++)
            {
                lrs[i] = ReadInts();
            }
            for(int i = 0; i < q; i++)
            {
                int l = lrs[i][0];
                int r = lrs[i][1];
                int cost = 0;
                while (l < r)
                {
                    int[] pos = posDict[l];
                    cost += costGrid[pos[0], pos[1]];
                        l += hwd[2];
                }
                Console.WriteLine(cost);
            }
        }

