                {
                    Console.WriteLine(Maryoku(Amat, i, lrList, D));
                }
                else
                {
                    Console.WriteLine(0);
                }
            }
        }

        static long Maryoku(List<List<int>> Amat, int index, List<List<int>> lrList, int D)
        {
            var list = SearchList(Amat, lrList[index][0], lrList[index][1], D);
            //ListDebug(list);
            long sum = 0;
            for(int i = 0; i < list.Count - 1; i++)
            {
                sum += Math.Abs(list[i][0] - list[i + 1][0]) + Math.Abs(list[i][1] - list[i + 1][1]);
            }
            return sum;
        }

        static void ListDebug(List<List<int>> list)
        {
            Console.WriteLine("debug");
            for(int i = 0; i < list.Count; i++)
            {
                for(int j = 0; j < list[i].Count; j++)
                {
                    Console.Write(list[i][j] + " ");
                }
                Console.WriteLine();
            }
        }


        static List<List<int>> SearchList(List<List<int>> Amat, int val, int dist, int D)
        {
            var valList = new List<int>();
            for(int i = val; i <= dist; i += D)
            {
                valList.Add(i);
            }
            var ret = new List<List<int>>();
            for(int i = 0; i < Amat.Count; i++)
            {
                for(int j = 0; j < Amat[i].Count; j++)
                {
                    for(int k = 0; k < valList.Count; k++)
                    {
                        if(Amat[i][j] == valList[k])
                        {
                            ret.Add(new List<int> { i, j, valList[k] });
                            valList.Remove(valList[k]);
                        }
                    }
                }
            }
            ret = ret.OrderBy(se => se[2]).ToList();
            return ret;
        }
    }
}

