public class Solver
{
	public void Solve()
	{
		long H = GetLong();
		long W = GetLong();
		long D = GetLong();
		var xy = new (long, long)[H * W];
		for(long i = 0; i < H; i++)
		{
			for(long j = 0; j < W; j++)
				xy[GetLong() - 1] = (i, j);
		}

		var dp = new long[H * W];
		for(long i = 0; i < D; i++)
		{
			for(long j = 0; (j + 1) * D + i < H * W; j++)
			{
				long c = j * D + i;
				long n = (j + 1) * D + i;
				var (cx, cy) = xy[c];
				var (nx, ny) = xy[n];
				dp[n] = dp[c] + Abs(nx - cx) + Abs(ny - cy);
			}
		}

		long Q = GetLong();
		var ans = new long[Q];
		for(long i = 0; i < Q; i++)
		{
			long L = GetLong() - 1;
			long R = GetLong() - 1;
			ans[i] = dp[R] - dp[L];
		}
		WriteLine(string.Join("\n", ans));
	}
}

