public class D
{
	public static void Main()
	{
		string[] args;

		args = Console.ReadLine().Split(' ');
		int H = Int32.Parse(args[0]);
		int W = Int32.Parse(args[1]);
		int D = Int32.Parse(args[2]);

		Pair[] pairs = new Pair[H * W + 1];
		for(int i = 1; i <= H; i++)
		{
			args = Console.ReadLine().Split(' ');
			for(int j = 1; j <= W; j++)
				pairs[Int32.Parse(args[j-1])] = new Pair(i,j);
		}

		int Q = Int32.Parse(Console.ReadLine());
		int[] L = new int[Q];
		int[] R = new int[Q];
		for(int i = 0; i < Q; i++)
		{
			args = Console.ReadLine().Split(' ');
			L[i] = Int32.Parse(args[0]);
			R[i] = Int32.Parse(args[1]);
		}

		int[] csum = new int[H * W + 1];  // csum[1] = ... = csum[D] = 0
		for(int i = D + 1; i <= H * W; i++)
		{
			Pair current = pairs[i];
			Pair prev = pairs[i - D];
			int mp = Math.Abs(current.I - prev.I) + Math.Abs(current.J - prev.J);
			csum[i] = csum[i - D] + mp;
		}

		for(int i = 0; i < Q; i++)
			Console.WriteLine(csum[R[i]] - csum[L[i]]);
	}	
}

