	internal class Program {
		private static void Main(string[] args) {
			var sw = new StreamWriter(OpenStandardOutput()) { AutoFlush = false };
			SetOut(sw);
			new Calc().Solve();
			Out.Flush();
		}

		public class Calc
		{
			public void Solve() {
			    int H = NextInt(), W = NextInt(), D = NextInt();
			    var map = new Map<int, List<ti3>>();
			    var dic = new Map<int, int>();

			    D.REP(i => map[i] = new List<ti3>());

                H.REP(i =>
                {
                    W.REP(j =>
                    {
                        var Aij = NextInt();
                        map[Aij%D].Add(new ti3(i,j,Aij));
                    });
                });

                D.REP(i => { map[i] = map[i].OrderBy(x => x.Item3).ToList(); });

			    var imos = Generate.Repeat(x => new Li(),D);

			    foreach (var item in map) {
			        var d = item.Key;
                    imos[d].Add(0);

			        for (int i = 0; i < item.Value.Count; i++) {
			            dic[item.Value[i].Item3] = i;
			        }

			        for (int i = 0; i < item.Value.Count-1; i++) {
			            var s = item.Value[i];
			            var t = item.Value[i + 1];

			            imos[d].Add(Abs(s.Item1 - t.Item1) + Abs(s.Item2 - t.Item2));
			        }

                    for (int i = 0; i < imos[d].Count - 1; i++)
                    {
                        imos[d][i + 1] += imos[d][i];
                    }

			    }

			    var Q = NextInt();
                Q.REP(i =>
                {
                    int Li = NextInt(), Ri = NextInt();
                    var d = Li % D;
                    int li = dic[Li], ri = dic[Ri];
                    (imos[d][ri]-imos[d][li]).WL();
                });


                return;
			}
		}

	}
