namespace Competitive
{
    internal class Solution
    {
        public void Run()
        {
            int H, W, D;
            {
                int[] tmp = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                H = tmp[0];
                W = tmp[1];
                D = tmp[2];
            }

            int[] X = Enumerable.Range(0, H * W + 1).Select(i => 0).ToArray();
            int[] Y = Enumerable.Range(0, H * W + 1).Select(i => 0).ToArray();
            for (int y = 0; y < H; y++)
            {
                int[] line = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                for (int x = 0; x < W; x++)
                {
                    int a = line[x];
                    X[a] = x;
                    Y[a] = y;
                }
            }

            int Q = int.Parse(Console.ReadLine());
            int[] DD = Enumerable.Range(0, H * W + 1).Select(i => 0).ToArray();

            for (int m = 1; m <= D; m++)
            {
                int d = 0;
                int i = m;
                DD[i] = d;

                while (true)
                {
                    i += D;
                    if (i > H * W) break;
                    d += Math.Abs(X[i] - X[i - D]) + Math.Abs(Y[i] - Y[i - D]);
                    DD[i] = d;
                }
            }

            for (int q = 0; q < Q; q++)
            {
                int[] line = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                int start = line[0];
                int end = line[1];
                Console.WriteLine(DD[end] - DD[start]);
            }
        }

    }

    internal class Program
    {
        public static void Main(string[] args)
        {
            var s = new Solution();
            s.Run();
        }
    }
}

