class Solver {
    Scanner sc = new Scanner();

    struct Zahyo {
        public int i;
        public int j;
    }

    public void Solve() {
        var H = sc.nextInt();
        var W = sc.nextInt();
        var D = sc.nextInt();
        var A = new int[H, W];
        var dic = new Dictionary<int, Zahyo>();
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                A[i, j] = sc.nextInt();
                dic.Add(A[i, j], new Zahyo { i = i, j = j });
            }
        }
        var Q = sc.nextInt();

        var cost = new int[H * W + 1];
        for (int i = 1 + D; i < H * W; i++) {
            cost[i] = cost[i - D] + Math.Abs(dic[i - D].i - dic[i].i) + Math.Abs(dic[i - D].j - dic[i].j);
        }

        for (int i = 0; i < Q; i++) {
            var l = sc.nextInt();
            var r = sc.nextInt();
            WriteLine(cost[r] - cost[l]);
        }
    }
}



