                len++;
            }

            var p = points[c];
            var u = c;
            var cost = 0L;
            for (var i = 0; i < len; i++)
            {
                var w = c + (1 << i) * D;
                // Debug.Assert(w <= HW, $"w={w} HW={HW}");

                while (u < w)
                {
                    // Debug.Assert(u + D <= w);
                    var q = points[u + D];
                    cost += Distance(p, q);
                    u += D;
                }

                // Debug.Assert(u == w);
                skip[c].Add(cost);
            }
        }

        Skip = skip.Select(xs => xs.ToArray()).ToArray();
    }

    long Cost(int c, int v)
    {
        if (v == c) return 0;
        // Debug.Assert(v % D == c);

        var i = 0;
        while (c + (1 << (i + 1)) * D < v)
        {
            i++;
        }

        var cost = Skip[c][i];
        var u = c + (1 << i) * D;
        var p = points[u];

        for (; u < v; u += D)
        {
            var q = points[u + D];
            cost += Distance(p, q);
        }

        return cost;
    }

    private long Solve(int l, int r)
    {
        var c = l % D;
        // Debug.Assert(r % D == c);

        var lc = Cost(c, l);
        var rc = Cost(c, r);
        // Console.WriteLine($"{rc} - {lc}");
        return rc - lc;
    }

    public void EntryPoint()
    {
        var I = _scanner;
        H = I.N();
        W = I.N();
        D = I.N();
        A = H.MakeArray(y => W.MakeArray(x => I.N() - 1));
        Q = I.N();
        L = new int[Q];
        R = new int[Q];
        for (var i = 0; i < Q; i++)
        {
            L[i] = I.N() - 1;
            R[i] = I.N() - 1;
        }

        Build();

        for (var i = 0; i < Q; i++)
        {
            WriteLine(Solve(L[i], R[i]));
        }
    }
}

