    class Program
    {
        static void Main(string[] args)
        {
            int[] HWD = ReadLine().Split(' ').Select(int.Parse).ToArray();
            Npos[] Points = new Npos[HWD[0] * HWD[1]];
            for(int iy = 1; iy <= HWD[0]; iy++)
            {
                int[] numw = ReadLine().Split(' ').Select(int.Parse).ToArray();
                for (int ix = 1; ix <= HWD[1]; ix++)
