namespace ABC089D2 {
    class Program {
        static void Main(string[] args) {
            int[] HWDInput = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
            int H = HWDInput[0];
            int W = HWDInput[1];
            int D = HWDInput[2];
            int[] xpos = new int[H * W];
            int[] ypos = new int[H * W];
            int[,] alldis = new int[D, (H * W + D - 1) / D];
            for (int i = 0; i < H; i++) {
                int[] input = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
                for (int j = 0; j < W; j++) {
                    int n = input[j] - 1;
                    xpos[n] = i;
                    ypos[n] = j;
                }
            }
            for (int i = 0; i < D; i++) {
                for (int j = 0; j < (H * W + D - 1) / D; j++) {
                    if(j == 0) {
                        alldis[i, j] = 0;
                    } else {
                        int num = i + j * D;
                        if(num < H * W) {
                            int xdis = Math.Abs(xpos[num] - xpos[num - D]);
                            int ydis = Math.Abs(ypos[num] - ypos[num - D]);
                            alldis[i, j] = alldis[i, j - 1] + xdis + ydis;
                        }
                    }
                }
            }
