		public class Calc
		{
			public void Solve() {
				int H = NextInt(), W = NextInt(), D = NextInt();
				var dic = new Map<int, ti2>();

				H.REP(y => W.REP(x => { dic[NextInt()] = new ti2(x, y); }));

