            {
                string[] strs_ = strsTmp[i].Split(' ');

                for (int j = 0; j < w; ++j)
                {
                    int tmp_ = int.Parse(strs_[j]);
                    column[tmp_] = j;
                    row[tmp_] = i;
                }
            }

            int[] ans = new int[q];

            ans[0] = CalcMP(l0, r0, d);

            for (int i = 1; i < q; ++i)
            {
                string[] strs3 = Console.ReadLine().Split(' ');
                int l = int.Parse(strs3[0]);
                int r = int.Parse(strs3[1]);

                ans[i] = CalcMP(l, r, d);
            }

            for (int i = 0; i < q; ++i)
            {
                Console.WriteLine("{0}", ans[i]);
            }
        }

        static int CalcMP(int l, int r, int d)
        {
            int mp = 0;

            while (l != r)
            {
                int next = (r > l)? l + d : l - d;
                mp += Math.Abs(row[l] - row[next]) + Math.Abs(column[l] - column[next]);

                l = next;
            }

            return mp;
        }
    }
