        {
            readonly int x;
            readonly int y;

            public Point(int x, int y)
            {
                this.x = x;
                this.y = y;
            }

            public int GetManhattanDistance(Point other)
            {
                return Math.Abs(x - other.x) + Math.Abs(y - other.y);
            }
        }

        void Solve(StreamScanner ss, StreamWriter sw)
        {
            //---------------------------------
            var H = ss.Next(Int);
            var W = ss.Next(Int);
            var D = ss.Next(Int);
            var A = ss.Next(Int, W, H);
            var Q = ss.Next(Int);
            var LR = ss.Next(Int, 2, Q).Select(a => new {L = a[0], R = a[1]});

            var ps = new Point[H * W];
            for (var i = 0; i < H; i++)
            {
                for (var j = 0; j < W; j++)
                {
                    ps[A[i][j] - 1] = new Point(j, i);
                }
            }

            var dist = new int[H * W - D];
            for (var i = 0; i < D; i++)
            {
                for (var j = i + D; j < H * W; j += D)
                {
                    dist[j - D] = ps[j - D].GetManhattanDistance(ps[j]);
                }
            }


            var acs = new long[H * W];
            for (var i = 0; i < D; i++)
            {
                for (var j = i + D; j < H * W; j += D)
                {
                    acs[j] = acs[j - D] + dist[j - D];
                }
            }

            foreach (var lr in LR)
            {
                sw.WriteLine(acs[lr.R - 1] - acs[lr.L - 1]);
            }
            //---------------------------------
        }

