class WarshallFloyd
{
    public readonly long Inf;
    public WarshallFloyd(long Inf = long.MaxValue / 2) { this.Inf = Inf; }

    /// <summary>
    /// WarshallFloydな入力を行う
    /// </summary>
    /// <param name="n">頂点数</param>
    /// <param name="m">辺数</param>
    /// /// <param name="dir">有向/無向 デフォルト: 無向</param>
    /// <param name="indexed">indexedの補正 デフォルト: 1</param>
    /// <returns>n*nの自明な距離行列</returns>
    public long[][] Input(int n, int m, bool dir = false, int indexed = 1, bool cost = true)
    {
        Scanner cin = new Scanner();
        var ret = new long[n][];
        for (int i = 0; i < n; i++)
        {
            ret[i] = new long[n];
            for (int j = 0; j < n; j++)
            {
                if (i != j)
                {
                    ret[i][j] = Inf;
                }
            }
        }
        for (int i = 0; i < m; i++)
        {
            int a = cin.nextint - indexed;
            int b = cin.nextint - indexed;
            var c = true ? cin.nextlong : 1;
            ret[a][b] = Min(ret[a][b], c);
            if (!dir) ret[b][a] = Min(ret[b][a], c);
        }
        return ret;
    }
    public long[][] Run(long[][] d)
    {
        int n = d.Length;
        for (int k = 0; k < n; k++)
        {
            for (int i = 0; i < n; i++)
            {
                if (d[i][k] == Inf) continue;
                for (int j = 0; j < n; j++)
                {
                    if (d[k][j] == Inf) continue;
                    d[i][j] = Min(d[i][j], d[i][k] + d[k][j]);
                }
            }
        }
        return d;
    }
    /// <summary>
    /// n*n距離行列が与えられるときに変換に便利
    /// </summary>
    /// <param name="g">n*n距離行列</param>
    /// <param name="param">辺がないときのパラメタ</param>
    /// <returns></returns>
    public long[][] Copy(long[][] g, long param = 0)
    {
        int n = g.Length;
        var ret = new long[n][];
        for (int i = 0; i < n; i++)
        {
            ret[i] = new long[n];
            for (int j = 0; j < n; j++)
            {
                if (i != j && g[i][j] == param) ret[i][j] = Inf;
                else ret[i][j] = g[i][j];
            }
        }
        return ret;
    }
}

