public sealed partial class Program
{
    int H, W, D;
    int[][] A;

    int HW { get { return H * W; } }

    Tuple<int, int>[] Ps;
    long[] Costs;

    long Distance(Tuple<int, int> p, Tuple<int, int> q)
    {
        return Math.Abs(p.Item1 - q.Item1) + Math.Abs(p.Item2 - q.Item2);
    }

    void Build()
    {
        Ps = new Tuple<int, int>[HW];
        for (var y = 0; y < H; y++)
        {
            for (var x = 0; x < W; x++)
            {
                Ps[A[y][x]] = Tuple.Create(y, x);
            }
        }

        Costs = new long[HW];
        for (var i = 0; i < HW; i++)
        {
            if (i < D)
            {
                Costs[i] = 0;
            }
            else
            {
                var c = i % D;
                Costs[i] = Costs[i - D] + Distance(Ps[i], Ps[i - D]);
            }
        }
    }

    public void EntryPoint()
    {
        var I = _scanner;
        H = I.N();
        W = I.N();
        D = I.N();
        A = H.MakeArray(y => W.MakeArray(x => I.N() - 1));

        Build();

        var Q = I.N();
        for (var i = 0; i < Q; i++)
        {
            var l = I.N() - 1;
            var r = I.N() - 1;
            WriteLine(Costs[r] - Costs[l]);
        }
    }
}

