        /// <summary>
        /// 昇順にソートされたlong配列で、threshold以上の値をカウントする
        /// </summary>
        public static int LargerCount(this long[] a, long threshold)
        {
            int ng = -1;
            int ok = a.Length;

            while (Math.Abs(ng - ok) > 1)
            {
                int mid = (ok + ng) / 2;
                if (threshold <= a[mid])
                {
                    ok = mid;
                }
                else
                {
                    ng = mid;
                }
            }

            return a.Length - ok;
        }
    }

