public class Prog
{
    public struct Pair { public int x, y; public Pair(int x, int y) { this.x = x; this.y = y; } }
    public static void Solve()
    {
        int H = NextInt();
        int W = NextInt();
        int D = NextInt();
        int[][] A = Enumerable.Range(0, H).Select(v => LineInt()).ToArray();
        Pair[] B = new Pair[H * W + 10];
        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
                B[A[i][j]] = new Pair(i, j);
        int[] memo = new int[H * W + 10];
        for (int i = 0; i < D; i++)
        {
            int n = i;
            memo[n] = 0;
            while (n + D <= H * W)
            {
                memo[n + D] = memo[n] + Math.Abs(B[n].x - B[n + D].x) + Math.Abs(B[n].y - B[n + D].y);
                n += D;
            }
        }
        int Q = NextInt();
        for (int i = 0; i < Q; i++)
        {
            int L = NextInt(), R = NextInt();
            Console.WriteLine(memo[R] - memo[L]);
        }
    }
