public sealed partial class Program
{
    int H, W, D;
    int HW;
    int[][] A;
    int Q;
    int[] L, R;

    Tuple<int, int>[][] Points;
    long[][][] Skip;

    long Distance(Tuple<int, int> p, Tuple<int, int> q)
    {
        return Math.Abs(p.Item1 - q.Item1) + Math.Abs(p.Item2 - q.Item2);
    }

    int Length(int c)
    {
        return (HW - c + D - 1) / D;
    }

    int Height(int c, int s)
    {
        var h = 0;
        while (c + (s + (1 << h)) * D < HW)
        {
            h++;
        }
        return h;
    }

    void Build()
    {
        HW = H * W;
        Points = D.MakeArray(c => new Tuple<int, int>[Length(c)]);
        for (var y = 0; y < H; y++)
        {
            for (var x = 0; x < W; x++)
            {
                var u = A[y][x];
                var c = u % D;
                var i = (u - c) / D;
                Points[c][i] = Tuple.Create(y, x);
            }
        }

        var baseCosts = D.MakeArray(c => new long[Length(c)]);
        var skip = D.MakeArray(c => Length(c).MakeArray(s => new long[Height(c, s)]));
        for (var c = 0; c < D; c++)
        {
            var ps = Points[c];
            var length = Length(c);
            var cost = 0L;
            var p = ps[0];
            for (var i = 0; i < length; i++)
            {
                baseCosts[c][i] = cost;
                for (var h = 0; 1 << h <= i; h++)
                {
                    var u = i - (1 << h);
                    skip[c][u][h] = cost - baseCosts[c][u];
                }

                if (i + 1 < length)
                {
                    cost += Distance(ps[i], ps[i + 1]);
                }
            }
        }

        Skip = skip;//.Select(xs => xs.ToArray()).ToArray();
    }

    long Cost(int c, int v)
    {
        if (v == c) return 0;
        // Debug.Assert(v % D == c);

        var len = Length(c);
        var k = (v - c) / D;

        var i = 0;
        var cost = 0L;
        while (i < k)
        {
            var h = 0;
            while (i + (1 << (h + 1)) <= k)
            {
                h++;
            }
            cost += Skip[c][i][h];
            i += 1 << h;
        }
        return cost;
    }

    private long Solve(int l, int r)
    {
        var c = l % D;
        // Debug.Assert(r % D == c);

        var lc = Cost(c, l);
        var rc = Cost(c, r);
        // Console.WriteLine($"{rc} - {lc}");
        return rc - lc;
    }

    public void EntryPoint()
    {
        var I = _scanner;
        H = I.N();
        W = I.N();
        D = I.N();
        A = H.MakeArray(y => W.MakeArray(x => I.N() - 1));
        Q = I.N();
        L = new int[Q];
        R = new int[Q];
        for (var i = 0; i < Q; i++)
        {
            L[i] = I.N() - 1;
            R[i] = I.N() - 1;
        }

        Build();

        for (var i = 0; i < Q; i++)
        {
            WriteLine(Solve(L[i], R[i]));
        }
    }
}

