            int[] ydis = new int[H * W + 1];
            int[,] alldis = new int[H * W + 1, H * W + 1];
            for (int i = 0; i < H; i++) {
                int[] input = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
                for (int j = 0; j < W; j++) {
                    int n = input[j];
                    if (xdis[n] == 0) {
                        xdis[n] = i + 1;
                    } else {
                        xdis[n] = Math.Abs(xdis[n] - (i + 1));
                    }
                    if (ydis[n] == 0) {
                        ydis[n] = j + 1;
                    } else {
                        ydis[n] = Math.Abs(ydis[n] - (j + 1));
                    }
                    if (n > D) {
                        if (xdis[n - D] == 0) {
                            xdis[n - D] = i + 1;
                        } else {
                            xdis[n - D] = Math.Abs(xdis[n - D] - (i + 1));
                        }
                        if (ydis[n - D] == 0) {
                            ydis[n - D] = j + 1;
                        } else {
                            ydis[n - D] = Math.Abs(ydis[n - D] - (j + 1));
                        }
                    }
                }
            }
            for (int i = 1; i < H * W + 1 - D; i++) {
                int num = (H * W - i) / D + 1;
                int magic = 0;
                for(int j = 0; j < num; j++) {
                    alldis[i, j] = magic;
