                            xdis[n - D] = Math.Abs(xdis[n - D] - (i + 1));
                        }
                        if (ydis[n - D] == 0) {
                            ydis[n - D] = j + 1;
                        } else {
                            ydis[n - D] = Math.Abs(ydis[n - D] - (j + 1));
                        }
                    }
                }
            }
            for (int i = 1; i < H * W + 1 - D; i++) {
                int num = (H * W - i) / D + 1;
                int magic = 0;
                for(int j = 0; j < num; j++) {
                    alldis[i, j] = magic;
                    if(j != num - 1) {
                        magic += xdis[i + j * D] + ydis[i + j * D];
                    }
                }
            }
            int Q = int.Parse(Console.ReadLine());
            for(int i = 0; i < Q; i++) {
                int[] LRInput = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
                int L = LRInput[0];
                int R = LRInput[1];
                int num = (R - L) / D;
                Console.WriteLine(alldis[L, num]);
            }
        }
    }
}

