        // すべてのStからEdまで移動Mg取得
        private static void GetMagAll()
        {
            for (int k = 0; k < lstQ.Count; k++)
            {
                int iSt = lstQ[k].iL;
                int iNw = iSt;
                int iEd = lstQ[k].iR;
                if (iSt == iEd) { lstQ[k].iM = 0; continue; }                   // StとEdが同じは移動なし
                int iMg = 0;
                if (chkEx(iSt, iEd, ref iMg)) { lstQ[k].iM = iMg; continue; }   // 既存にあれば・・・
                GetMagOne(iNw, iEd, ref iMg);                                   // 既存にないので計算
                lstQ[k].iM = iMg;
                lstM.Add(new ClsMag() { iL = iSt, iR = iEd, iM = iMg });        // 既存にないので保持
            }
        }

        // あるマスからあるマスまで移動Mg取得
        private static void GetMagOne(int iNw, int iEd, ref int iMg)
        {
            int iB = lstA[iNw].iY, jB = lstA[iNw].iX;                           // 最初のマス位置
            int iN = 0, jN = 0;
            while (true)                                                        // ここが最高だと90000回繰り返すから10万件あると大変か・・・
            {
                iNw = iNw + iD;                                                 // 次マス
                if (iNw > iEd) { break; }
                iN = lstA[iNw].iY; jN = lstA[iNw].iX;                           // 次のマス位置
                iMg += Math.Abs(iN - iB) + Math.Abs(jN - jB);                   // 移動Mg加算
                iB = iN; jB = jN;
            }
        }

        // 既存移動Mgログに存在すればそこから取得
        private static Boolean chkEx(int iSt, int iEd, ref int iMg)
        {
            Boolean bEx = false;
            int iMgTmp = 0;
            for (int i = 0; i < lstM.Count; i++)
            {
                if (lstM[i].iL == iSt && lstM[i].iR == iEd) { iMg = lstM[i].iM; bEx = true; return bEx; }       // まったく同じのあれば抜ける
            }
            for (int i = 0; i < lstM.Count; i++)                                                                // 開始または終了が一致
            {
                if (lstM[i].iL == iSt)                                                                          // 開始だけ同じ
                {
                    if (lstM[i].iR < iEd)                                                                       // 新規のが終了が大きい
                    {
                        GetMagOne(lstM[i].iR, iEd, ref iMgTmp);                                                 // 残り取得
                        iMg = lstM[i].iM + iMgTmp;                                                              // 続きを加算
                        lstM.Add(new ClsMag() { iL = iSt, iR = iEd, iM = iMg });                                // 既存にないので保持
                        bEx = true;
                        return bEx;
                    }
                    else                                                                                        // 新規のが小さい
                    {
                        GetMagOne(iEd, lstM[i].iR, ref iMgTmp);
                        iMg = lstM[i].iM - iMgTmp;                                                              // 重複してる箇所を引く
                        lstM.Add(new ClsMag() { iL = iSt, iR = iEd, iM = iMg });                                // 既存にないので保持
                        bEx = true;
                        return bEx;
                    }
                }
                else if (lstM[i].iR == iEd)                                                                     // 終了だけ同じ
                {
                    if (lstM[i].iL > iSt)                                                                       // 新規のが開始が小さい
                    {
                        GetMagOne(iSt, lstM[i].iL, ref iMgTmp);                                                 // 先頭部取得
                        iMg = lstM[i].iM + iMgTmp;                                                              // 先頭を加算
                        lstM.Add(new ClsMag() { iL = iSt, iR = iEd, iM = iMg });                                // 既存にないので保持
                        bEx = true;
                        return bEx;
                    }
                    else                                                                                        // 新規のが開始が大きい
                    {
                        GetMagOne(lstM[i].iL, iSt, ref iMgTmp);                                                 // 重複してる箇所取得
                        iMg = lstM[i].iM - iMgTmp;                                                              // 重複してる箇所を引く
                        lstM.Add(new ClsMag() { iL = iSt, iR = iEd, iM = iMg });                                // 既存にないので保持
                        bEx = true;
                        return bEx;
                    }
                }
            }
            for (int i = 0; i < lstM.Count; i++)                                                                // 開始も終了も一致しないけど中間があるか
            {
                if (lstM[i].iL % iD == iSt % iD && lstM[i].iR % iD == iEd % iD)                                 // 中間あり
                {
                    iMg = lstM[i].iM;
                    if (lstM[i].iL > iSt)                                                                       // 新規のが開始が小さい
                    {
                        GetMagOne(iSt, lstM[i].iL, ref iMgTmp);                                                 // 先頭部取得
                        iMg += iMgTmp;                                                                          // 先頭を加算
                    }
                    else                                                                                        // 新規のが小さい
                    {
                        GetMagOne(lstM[i].iL, iSt, ref iMgTmp);                                                 // 重複してる箇所取得
                        iMg -= iMgTmp;                                                                          // 重複してる箇所を引く
                    }

                    if (lstM[i].iR < iEd)                                                                       // 新規のが終了が大きい
                    {
                        GetMagOne(lstM[i].iR, iEd, ref iMgTmp);                                                 // 残り取得
                        iMg += iMgTmp;                                                                          // 続きを加算
                    }
                    else                                                                                        // 新規のが小さい
                    {
                        GetMagOne(iEd, lstM[i].iR, ref iMgTmp);
                        iMg -= iMgTmp;                                                                          // 重複してる箇所を引く
                    }
                    lstM.Add(new ClsMag() { iL = iSt, iR = iEd, iM = iMg });                                    // 既存にないので保持
                    bEx = true;
                    break;
                }
            }
            return bEx;
        }

        // マス位置情報
        private class ClsPot
        {
            public int iY { get; set; } = 0;                    // 行位置0始まり
            public int iX { get; set; } = 0;                    // 列位置0始まり
        }

