namespace D
{
    class Program
    {
        static void Main(string[] args)
        {
            var inputs = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToList();
            int H = inputs[0];
            int W = inputs[1];
            int D = inputs[2];
            var Amat = new List<List<int>>();
            for(int i = 0; i < H; i++)
            {
                var temp = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToList();
                Amat.Add(temp);
            }
            int Q = int.Parse(Console.ReadLine());
            var lrList = new List<List<int>>();
            for(int i = 0; i < Q; i++)
            {
                var temp = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToList();
                lrList.Add(temp);
            }

            long sum = 0;
            for(int i = 0; i < Q; i++)
            {
                if (lrList[i][0] != lrList[i][1])
                {
                    Console.WriteLine(Maryoku(Amat, i, lrList, D));
                }
                else
                {
                    Console.WriteLine(0);
                }
            }
        }

        static long Maryoku(List<List<int>> Amat, int index, List<List<int>> lrList, int D)
        {
            int L = lrList[index][0];
            int R = lrList[index][1];
            var lpos = Search(Amat, L);
            long sum = 0;
            for (int next = L + D; next <= R; next += D)
            {
                var nextPos = Search(Amat, next);
                sum += Math.Abs(lpos[0] - nextPos[0]) + Math.Abs(lpos[1] - nextPos[1]);
                lpos = nextPos;
            }
            return sum;
        }

        static List<int> Search(List<List<int>> Amat, int val)
        {
            for(int i = 0; i < Amat.Count; i++)
            {
                for(int j = 0; j < Amat[i].Count; j++)
                {
                    if(Amat[i][j] == val)
                    {
                        return new List<int>() { i, j };
                    }
                }
            }
            return null;
        }
    }
}

