    class Program
    {
        private int H, W, D;
        private int[][] A;
        private int Q;
        private int[][] Sum;
        public void Solve()
        {
            var sc = new Scanner();
            sc.GetIntRow(out H, out W, out D);
            A = sc.GetIntMatrix(H);
            Q = sc.NextInt();

            Dictionary<int, int> x = new Dictionary<int, int>();
            Dictionary<int, int> y = new Dictionary<int, int>();

            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    x[A[i][j]] = j;
                    y[A[i][j]] = i;
                }
            }

            Sum = new int[D][];
            for (int i = 0; i < D; i++)
            {
                Sum[i] = new int[H * W / D + 1];
            }
            for (int i = 1 + D; i <= H * W; i++)
            {
                int ii = i % D;
                int index = i / D;
                Sum[ii][index] = Sum[ii][index - 1] + Math.Abs(x[i] - x[i - D]) + Math.Abs(y[i] - y[i - D]);
            }

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < Q; i++)
            {
                int l = sc.NextInt();
                int r = sc.NextInt();
                sb.AppendLine(S(l, r).ToString());
                //Console.WriteLine(S(l,r));
            }
            Console.Write(sb.ToString());
        }

        private int S(int l, int r)
        {
            int ii = l % D;
            return Sum[ii][r / D] - Sum[ii][l / D];
        }

        static void Main(string[] args) => new Program().Solve();
    }
}

