    {
        public int X, Y;
        public SS(int x, int y)
        {
            X = x;
            Y = y;
        }
    }

    class Program
    {
        private int H, W;
        private int D;
        private int[] A;
        private int Q;
        private int[] L, R;
        private int N;
        private Dictionary<int, int> Map = new Dictionary<int, int>();
        private void Scan()
        {
            var sc = new Scanner();
            H = sc.NextInt();
            W = sc.NextInt();
            D = sc.NextInt();
            A = new int[H * W];
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    A[i * W + j] = sc.NextInt();
                }
            }
            Q = sc.NextInt();
            L = new int[Q];
            R = new int[Q];
            for (int i = 0; i < Q; i++)
            {
                L[i] = sc.NextInt();
                R[i] = sc.NextInt();
            }
        }

        private int Dist(int i, int j)
        {
            var x = Math.Abs(i / W - j / W);
            var y = Math.Abs(i % W - j % W);
            return x + y;
        }

        public void Solve()
        {
            Scan();
            N = H * W;
            for (int i = 0; i < H * W; i++)
            {
                Map[A[i]] = i;
            }
            var dist = new long[N + 1, N + 1];
            for (int i = 0; i <= N; i++)
            {
                for (int j = 0; j <= N; j++)
                {
                    dist[i, j] = int.MaxValue;
                }
            }
            for (int i = 1; i <= H * W - D; i++)
            {
                int s = Map[i];
                int e = Map[i + D];
                dist[i, i + D] = Dist(s, e);
            }
            for (int k = 0; k < N; k++)
            {
                for (int i = 0; i < N; i++)
                {
                    for (int j = 0; j < N; j++)
                    {
                        dist[i, j] = Math.Min(dist[i, k] + dist[k, j], dist[i, j]);
                    }
                }
            }
            var sb = new StringBuilder();
            for (int i = 0; i < Q; i++)
            {
                if (L[i] == R[i])
                {
                    sb.AppendLine("0");
                }
                else
                {
                    sb.AppendLine(dist[L[i], R[i]].ToString());
                }
            }
            Console.Write(sb.ToString());
        }

        static void Main(string[] args)
        {
            new Program().Solve();
        }
    }
}

