    static void Solve()
    {
        var H = sc.ReadInt();
        var W = sc.ReadInt();
        var D = sc.ReadInt();
        var A = new int[H, W];
        var B = new Tuple<int, int>[H * W];
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                A[i, j] = sc.ReadInt() - 1;
                B[A[i, j]] = Tuple.Create(i, j);
            }
        }

        var list = new List<int>[D];
        for (int i = 0; i < D; i++)
        {
            list[i] = new List<int>();
        }
        for (int rem = 0; rem < D; rem++)
        {
            var now = rem;
            while (now < H * W)
            {
                list[rem].Add(now);
                now += D;
            }
        }
        var sum = new List<int>[D];
        for (int i = 0; i < D; i++)
        {
            sum[i] = new List<int>();
            sum[i].Add(0);
            for (int j = 1; j < list[i].Count; j++)
            {
                var dh = Math.Abs(B[list[i][j - 1]].Item1 - B[list[i][j]].Item1);
                var dw = Math.Abs(B[list[i][j - 1]].Item2 - B[list[i][j]].Item2);
                var cost = dh + dw;
                sum[i].Add(sum[i].Last() + cost);
            }
        }
        var Q = sc.ReadInt();
        while (Q-- > 0)
        {
            var L = sc.ReadInt();
            var R = sc.ReadInt();
            L--; R--;
            var rem = L % D;
            var xl = L / D;
            var xr = (R - L) / D + xl;
