namespace AtCoder_ABC089_A
{
    class Program
    {
        static void Main(string[] args)
        {
            int h;
            int w;

            string[] hwd = Console.ReadLine().Split(' ');
            h = int.Parse(hwd[0]);
            w = int.Parse(hwd[1]);
            int d = int.Parse(hwd[2]);

            int[] _a = new int[h * w];
            for (int i = 0; i < h; ++i)
            {
                string[] tmp = Console.ReadLine().Split(' ');
                for (int j = 0; j < w; ++j)
                {
                    int number = int.Parse(tmp[j]) - 1;
                    _a[number] = i + j * 65536;
                }
            }

            int q = int.Parse(Console.ReadLine());

            int[] l = new int[q];
            int[] r = new int[q];

            for (int i = 0; i < q; ++i)
            {
                string[] tmp = Console.ReadLine().Split(' ');
                l[i] = int.Parse(tmp[0]);
                r[i] = int.Parse(tmp[1]);
            }


            for (int q_ = 0; q_ < q; ++q_)
            {
                int magic = 0;
                int number = l[q_] - 1;
                int a = _a[number];
                int row = a % 65536;
                int column = a / 65536;
                int end = r[q_];
                while (number + 1 != end)
                {
                    number += d;

                    int a2 = _a[number];
                    int row2 = a2 % 65536;
                    int column2 = a2 / 65536;

                    magic += Math.Abs(row - row2) + Math.Abs(column - column2);

                    row = row2;
                    column = column2;
                }

                Console.WriteLine(magic);
            }
        }
    }
}

