        public void Solve()
        {
            int H = cin.ReadInt;
            int W = cin.ReadInt;
            int D = cin.ReadInt;

            int[][] A = JagArray2D<int>(H, W);
            for (int i = 0; i < H; i++)
            {
                A[i] = cin.ReadIntArray(W);
            }

            int[] NumToIndex = new int[H * W + 1];

            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    int num = A[i][j];
                    NumToIndex[num] = H * i + j;
                }
            }

            int Q = cin.ReadInt;

            int Len = (H * W + D - 1) / D;

            // S[i][j] : [Dで割ったあまりがiであるマス][j + 1番目まで]の総和
            long[][] S = JagArray2D<long>(D, Len + 2);

            for (int k = 0; k < D; k++)
            {
                int num = k;

                // if (num <= 0) num += D;

                int currX = -1;
                int currY = -1;

                int ind = 0;

                while (true)
                {
                    if (num > H * W) break;

                    int tmp   = NumToIndex[num];
                    int nextX = tmp % H;
                    int nextY = tmp / H;

                    if (tmp == 0)
                    {
                        nextX = -1;
                    }

                    if (currX >= 0)
                    {
                        S[k][ind + 1] = S[k][ind] + (Math.Abs(nextX - currX) + Math.Abs(nextY - currY));
                    }

                    ind++;
                    num += D;

                    currX = nextX;
                    currY = nextY;
                }
            }

            for (int query = 0; query < Q; query++)
            {
                int l = cin.ReadInt;
                int r = cin.ReadInt;

                int k = l % D;

                int start = l / D;
                int goal  = r / D;

                long ans = S[k][goal + 1] - S[k][start + 1];

                cou.WriteLine(ans);
            }
        }
    }


