            //KeyValuePair<int, int>[] _a;

            int h;
            int w;

            string[] hwd = Console.ReadLine().Split(' ');
            h = int.Parse(hwd[0]);
            w = int.Parse(hwd[1]);
            int d = int.Parse(hwd[2]);

            int[] _a_h = new int[h*w];
            int[] _a_w = new int[h*w];
            //_a = new KeyValuePair<int, int>[h * w];
            //a = new int[h, w];
            for (int i = 0; i < h; ++i)
            {
                string[] tmp = Console.ReadLine().Split(' ');
                for (int j = 0; j < w; ++j)
                {
                    int number = int.Parse(tmp[j]) - 1;
                    _a_h[number] = i;
                    _a_w[number] = j;
                    //_a[int.Parse(tmp[j])-1] = new KeyValuePair<int, int>(i, j);
                }
            }

            int q = int.Parse(Console.ReadLine());

            int[] l = new int[q];
            int[] r = new int[q];

            for (int i = 0; i < q; ++i)
            {
                string[] tmp = Console.ReadLine().Split(' ');
                l[i] = int.Parse(tmp[0]);
                r[i] = int.Parse(tmp[1]);
            }


            for (int q_ = 0; q_ < q; ++q_)
