namespace AtCoder.D
{
    public class Program
    {
        public static void Main() { var r = GetResult(); Debug.WriteLine(r); Console.Write(r); }

        private static object GetResult()
        {
            var (H, W, D) = Read3Longs();
            var dicPoint = new Dictionary<long, Point>();
            var A = new long[H, W];
            for (int i = 0; i < H; i++)
            {
                var l = ReadLongs();
                for (int j = 0; j < W; j++)
                {
                    A[i, j] = l[j];
                    dicPoint.Add(l[j], new Point(i, j));
                }
            }

            var dicCost = new Dictionary<long, Dictionary<long, long>>();
            for (int from = 1; from < H * W - 1; from++)
            {
                for (int i = 1; i < H * W - 1; i++)
                {
                    var to = from + i * D;
                    if (to > H * W) break;

                    if (i == 1)
                    {
                        dicCost.Add(from, new Dictionary<long, long>());

                        var fromPoint = dicPoint[from];
                        var toPoint = dicPoint[to];
                        var cost = Math.Abs(fromPoint.X - toPoint.X) + Math.Abs(fromPoint.Y - toPoint.Y);
                        dicCost[from].Add(to, cost);
                    }
                    else
                    {
                        var preFrom = from + (i - 1) * D;
                        var preFromPoint = dicPoint[preFrom];
                        var toPoint = dicPoint[to];
                        var cost = dicCost[from][preFrom] + Math.Abs(preFromPoint.X - toPoint.X) + Math.Abs(preFromPoint.Y - toPoint.Y);
                        dicCost[from].Add(to, cost);
                    }
                }
            }

            var Q = ReadLong();
            var sb = new StringBuilder();
            for (int i = 0; i < Q; i++)
            {
                var (L, R) = Read2Longs();
                if (L == R)
                {
                    sb.AppendLine("0");
                    continue;
                }
                sb.AppendLine(dicCost[L][R].ToString());
            }

            return sb.ToString().Trim();
        }

        class Point
        {
            public int X { get; set; }
            public int Y { get; set; }

            public Point(int x, int y)
            {
                X = x;
                Y = y;
            }
        }

        #region Console.Read

        public static string ReadText() { return Console.ReadLine(); }
        public static List<string> ReadTexts() { return Console.ReadLine().Split(' ').ToList(); }
        public static long ReadLong() { return long.Parse(Console.ReadLine()); }
        public static (long, long) Read2Longs() { var ls = ReadLongs(); return (ls[0], ls[1]); }
        public static (long, long, long) Read3Longs() { var ls = ReadLongs(); return (ls[0], ls[1], ls[2]); }
        public static (long, long, long, long) Read4Longs() { var ls = ReadLongs(); return (ls[0], ls[1], ls[2], ls[3]); }
        public static (long, long, long, long, long) Read5Longs() { var ls = ReadLongs(); return (ls[0], ls[1], ls[2], ls[3], ls[4]); }
        public static List<long> ReadLongs() { return Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToList(); }

        #endregion
    }
