namespace CS_Contest {
	using Li = List<int>;
	using LLi = List<List<int>>;
	using Ll = List<long>;
	using ti3 = Tuple<int, int, int>;
	using ti2 = Tuple<int, int>;
	internal class Program {
		private static void Main(string[] args) {
			var sw = new StreamWriter(OpenStandardOutput()) { AutoFlush = false };
			SetOut(sw);
			new Calc().Solve();
			Out.Flush();
		}

		public class Calc {
			public void Solve() {
				int H = NextInt(), W = NextInt(), D = NextInt();
				var dic = new Map<int, ti2>();

				H.REP(y=>W.REP(x => { dic[NextInt()] = new ti2(x, y); }));

				var res = new int[H * W,H*W];

				dic.Foreach(pair =>
				{
					var n = pair.Key;
					var k = n;
					var s = pair.Value;
					var pow = 0;
					res[n - 1, n - 1] = pow;

					while (n+D<H*W) {
						n += D;
						var t = dic[n];
						pow += Abs(t.Item1 - s.Item1) + Abs(t.Item2 - s.Item2);
						res[k - 1, n - 1] = pow;
						s = t;
					}

				});

				NextInt().REP(i => {
					int Li = NextInt() - 1, Ri = NextInt() - 1;
					res[Li,Ri].WL();
				});



				return;
			}
		}


	}
