        public void WriteEnumerable<T>(IEnumerable<T> A, string delimiter = " ")
        {
            if (!A.Any())
            {
                return;
            }

            var sb = new StringBuilder();
            foreach (T v in A)
            {
                sb.Append(v);
                sb.Append(delimiter);
            }

            if (sb.Length > 0)
            {
                sb.Length--;
            }

            cou.WriteLine(sb.ToString());
        }
