using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace D
{
    public class Program
    {
        static void Main(string[] args)
        {
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            Solve();
            Console.Out.Flush();
        }

        public static void Solve()
        {
            var HWD = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
            var H = HWD[0];
            var W = HWD[1];
            var D = HWD[2];
            var A = new Dictionary<int, Location>();
            for (var i = 0; i < H; i++)
            {
                var a = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
                for (var j = 0; j < a.Length; j++)
                {
                    A[a[j]] = new Location { X = j, Y = i };
                }
            }

            var Q = int.Parse(Console.ReadLine());
            for (var i = 0; i < Q; i++)
            {
                var LR = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
                var L = LR[0];
                var R = LR[1];
                var answer = 0;
                while (true)
                {
                    if (L == R)
                    {
                        Console.WriteLine(answer);
                        break;
                    }
                    var next = L + D;
                    var currentLocation = A[L];
                    var nextLocation = A[next];
                    var cost = Math.Abs(nextLocation.X - currentLocation.X) + Math.Abs(nextLocation.Y - currentLocation.Y);
                    answer += cost;
                    L = next;
                }
            }

        }

        public class Location
        {
            public int X { get; set; }
            public int Y { get; set; }
        }
    }
}

