namespace ConsoleApp1
{
	class Program
	{
		static long MakeLong(int a_iX, int a_iY)
		{
			return (long)a_iY << 32 | (long)a_iX;
		}

		static int GetX(long a_iLong)
		{
			return (int)(a_iLong & 0xffffffff);
		}

		static int GetY(long a_iLong)
		{
			return (int)(a_iLong >> 32);
		}

		static void Main(string[] a_asArgs)
		{
			int[] l_aiInput = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
			int l_iH = l_aiInput[0];
			int l_iW = l_aiInput[1];
			int l_iD = l_aiInput[2];
			Dictionary<long, int> l_dicFore = new Dictionary<long, int>();
			Dictionary<int, long> l_dicBack = new Dictionary<int, long>();
			for (int l_iY = 0; l_iY < l_iH; l_iY++)
			{
				int[] l_aiValue = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
				for (int l_iX = 0; l_iX < l_iW; l_iX++)
				{
					long l_long = MakeLong(l_iX, l_iY);
					l_dicFore[l_long] = l_aiValue[l_iX];
					l_dicBack[l_aiValue[l_iX]] = l_long;
				}
			}
			int l_iQ = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray()[0];
			for (int l_iq = 0; l_iq < l_iQ; l_iq++)
			{
				l_aiInput = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
				int l_iL = l_aiInput[0];
				int l_iR = l_aiInput[1];
				int l_iValue = l_iL;
				int l_iPower = 0;
				while (l_iValue != l_iR)
				{
					long l_ilong1 = l_dicBack[l_iValue];
					long l_ilong2 = l_dicBack[l_iValue += l_iD];
					l_iPower += Math.Abs(GetX(l_ilong1) - GetX(l_ilong2)) + Math.Abs(GetY(l_ilong1) - GetY(l_ilong2));
				}
				Console.WriteLine(l_iPower);
			}
		}
	}
