    struct SS
    {
        public int X, Y;
        public SS(int x, int y)
        {
            X = x;
            Y = y;
        }
    }



    class Program
    {
        private int H, W;
        private int D;
        private int[,] A;
        private int Q;
        private int[] L, R;
        private int N;
        private Dictionary<int, SS> Map = new Dictionary<int, SS>();
        private void Scan()
        {
            var sc = new Scanner();
            H = sc.NextInt();
            W = sc.NextInt();
            D = sc.NextInt();
            A = new int[H, W];
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    A[i, j] = sc.NextInt() - 1;
                }
            }
            Q = sc.NextInt();
            L = new int[Q];
            R = new int[Q];
            for (int i = 0; i < Q; i++)
            {
                L[i] = sc.NextInt() - 1;
                R[i] = sc.NextInt() - 1;
            }
        }

        private int Dist(int i, int j)
        {
            var a = Map[i];
            var b = Map[j];
            return Math.Abs(a.X - b.X) + Math.Abs(a.Y - b.Y);
        }

        public void Solve()
        {
            Scan();
            int N = H * W;
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    Map[A[i, j]] = new SS(j, i);
                }
            }
            var ans = new long[N + 1, N + 1];
            for (int i = 0; i <= N; i++)
            {
                for (int j = 0; j <= N; j++)
                {
                    ans[i, j] = int.MaxValue;
                }
            }
            for (int i = 0; i < N - D; i++)
            {
                ans[i, i + D] = Dist(i, i + D);
            }
            for (int i = 0; i < D; i++)
            {
                for (int k = i; k < N; k += D)
                {
                    for (int j = i; j < N; j += D)
                    {
                        for (int l = i; l < N; l += D)
                        {
                            ans[j, l] = Math.Min(ans[j, l], ans[j, k] + ans[k, l]);
                        }
                    }
                }
            }
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            for (int i = 0; i < Q; i++)
            {
                if (L[i] == R[i])
                {
                    Console.WriteLine("0");
                    continue;
                }
                Console.WriteLine(ans[L[i], R[i]].ToString());
            }
            Console.Out.Flush();
        }

        static void Main(string[] args)
        {
            new Program().Solve();
        }
    }
}

