public class Program
{
    int H, W, D;
    int[][] A;
    int Q;
    int[] L, R;
    public void Solve()
    {
        var sc = new Scanner();
        H = sc.NextInt();
        W = sc.NextInt();
        D = sc.NextInt();

        A = new int[H][];
        for (int i = 0; i < H; i++)
        {
            A[i] = sc.IntArray();
            for (int j = 0; j < W; j++)
            {
                A[i][j]--;
            }
        }
        Q = sc.NextInt();

        L = new int[Q];
        R = new int[Q];
        for (int i = 0; i < Q; i++)
        {
            L[i] = sc.NextInt() - 1;
            R[i] = sc.NextInt() - 1;
        }

        var sb = new StringBuilder();

        var y = new int[H * W];
        var x = new int[H * W];

        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                y[A[i][j]] = i;
                x[A[i][j]] = j;
            }
        }

        var sum = new List<int>[D];
        for (int i = 0; i < D; i++)
        {
            sum[i] = new List<int>();
            sum[i].Add(0);
            for (int j = i + D; j < H * W; j += D)
            {
                int dx = Math.Abs(x[j - D] - x[j]);
                int dy = Math.Abs(y[j - D] - y[j]);

                sum[i].Add(sum[i][sum[i].Count - 1] + dx + dy);
            }
        }

        for (int i = 0; i < Q; i++)
        {
            int m = L[i] % D;

            int ll = L[i] / D;
            int rr = R[i] / D;

            sb.AppendLine((sum[m][rr] - sum[m][ll]).ToString());
        }

        Console.Write(sb.ToString());
    }

    public static void Main(string[] args) => new Program().Solve();
}

