	            });

                H.REP(i => {
                    W.REP(j => {
                        var Aij = NextInt();
                        box[Aij % D].Add(new ti3(Aij, i+1, j+1));
                    });
                });


                D.REP(d => {
                    box[d] = box[d].OrderBy(x => x.Item1).ToList();
                    bank[d].Add(0);
                    var N = box[d].Count;
                    for (var i = 0; i < N-1; i++) {
                        var s = box[d][i];
                        var t = box[d][i + 1];
                        bank[d].Add(Abs(t.Item3 - s.Item3) + Abs(t.Item2 - s.Item2));
                    }

                    for (var i = 0; i < N - 1; i++) bank[d][i + 1] += bank[d][i];
                });

                NextInt().REP(q => {
                    int Li = NextInt(), Ri = NextInt();
                    var d = Li % D;

                    Li -= box[d][0].Item1;
                    Ri -= box[d][0].Item1;

                    var index = new[] {Li / D, Ri / D};
                    //bank[d].JoinWL();
                    //box[d].JoinWL();
                    //index.JoinWL();

                    (bank[d][index[1]] - bank[d][index[0]]).WL();

                });

	        }

        }
    }
