    class Programk
    {
        static long H;
        static long W;
        static long D;
        static long[][] A;
        static long[] dis;
        static Tuple<long, long>[] point;
        static void Main(string[] args)
        {
            var HWD = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
            H = HWD[0];
            W = HWD[1];
            D = HWD[2];
            dis = new long[H * W + 1];
            A = new long[H][];
            for (int i = 0; i < H; i++)
            {
                A[i] = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
            }

            point = new Tuple<long, long>[H*W + 1];
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    point[A[i][j]] = new Tuple<long, long>(i, j);
                }
            }

            for (int i = 1; i <= D; i++)
            {
                Calculate(i);
            }

            var Q = long.Parse(Console.ReadLine());
            for (int i = 0; i < Q; i++)
            {
                var LR = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
                var L = LR[0];
                var R = LR[1];

                Console.WriteLine(dis[L]-dis[R]);
            }

        }

        static long Calculate(long num)
        {
            if(num >= H * W)
            {
                return 0;
            }
            else
            {
                var after = num + D;
                if(after > H * W)
                {
                    return 0;
                }
                dis[num] = Calculate(after) + Abs(point[after].Item1 - point[num].Item1) + Abs(point[after].Item2 - point[num].Item2);
                return dis[num];
            }
        }
    }
}

