        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }

        static void Solve()
        {
            var (H, W, D) = Slice3<long>();
            var Ddsts = Enumerable.Repeat(0, (int)D).Select(_ => new List<(long a, long x, long y)>()).ToArray();

            for (var i = 0; i < H; ++i)
            {
                var Aij = Sarray();
                for (var j = 0; j < W; ++j)
                    Ddsts[(Aij[j] - 1) % D].Add((Aij[j] - 1, i, j));
            }
            var ruis = new long[D][];
            for (var i = 0; i < D; ++i)
            {
                Ddsts[i].Sort();
                var dsts = Ddsts[i];
                var rui = new long[dsts.Count];
                for (var j = 1; j < Ddsts[i].Count; ++j)
                    rui[j] = rui[j - 1] + Abs(dsts[j].x - dsts[j - 1].x) + Abs(dsts[j].y - dsts[j - 1].y);
                ruis[i] = rui;
            }

            var Q = Sarray()[0];
            for (var i = 0; i < Q; ++i)
            {
                var (L, R) = Slice2<long>();
                --L; --R;
                var g = L % D;
                var b = L / D;
                var e = R / D;
                WriteLine(ruis[g][e] - ruis[g][b]);
            }
        }

