		to.push(Number(tmp[1]));
	}
	var memo = [];
	var ans = [];

	for(var k = 0; k < from.length; k++){
		ans[k] = 0;
		if(!memo[from[k]]) memo[from[k]] = [];
		if(memo[from[k]][to[k]]){
			ans[k] = memo[from[k]][to[k]];
			continue;
		}
		var loop = (to[k]-from[k])/step;
