var (
	sc = bufio.NewScanner(os.Stdin)
	wt = bufio.NewWriter(os.Stdout)
)

func next() string {
	sc.Scan()
	return sc.Text()
}

func nextInt() int {
	i, _ := strconv.Atoi(next())
	return i
}

func nextInts(n int) []int {
	slice := make([]int, n)
	for i := 0; i < n; i++ {
		slice[i] = nextInt()
	}
	return slice
}

func puts(a ...interface{}) {
	fmt.Fprintln(wt, a...)
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, initialBufSize), maxBufSize)
	defer wt.Flush()

	h, w, d := nextInt(), nextInt(), nextInt()
	a := make([][]int, h)
	for i := range a {
		a[i] = nextInts(w)
	}

	// point[x]: xが書かれているマスの座標(y,x)
	point := make([][2]int, h*w+1)
	for i := range a {
		for j := range a[i] {
			x := a[i][j]
			point[x] = [2]int{i, j}
		}
	}

	q := nextInt()
	for i := 0; i < q; i++ {
		ans := 0
		l, r := nextInt(), nextInt()
		x, i1, j1 := l, point[l][0], point[l][1]
		for x != r {
			i2, j2 := point[x+d][0], point[x+d][1]
			ans += abs(i1-i2) + abs(j1-j2)
			x, i1, j1 = x+d, i2, j2
		}
		puts(ans)
	}
}

