var (
	h, w, d int
	A       [][]int
	q       int
	L, R    []int

	memo [100000]Coord
	dist [100000][]int
	sums [100000][]int
)

func main() {
	h, w, d = ReadInt3()
	for i := 0; i < h; i++ {
		row := ReadIntSlice(w)
		A = append(A, row)
	}
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			A[i][j]--
			memo[A[i][j]].y = i
			memo[A[i][j]].x = j
		}
	}
	q = ReadInt()
	for i := 0; i < q; i++ {
		l, r := ReadInt2()
		l--
		r--
		L = append(L, l)
		R = append(R, r)
	}

	for s := 0; s < d; s++ {
		sub(s)
	}

	for s := 0; s < d; s++ {
		sums[s] = make([]int, len(dist[s])+1)
		for i := 0; i < len(dist[s]); i++ {
			sums[s][i+1] = sums[s][i] + dist[s][i]
		}
	}

	// for s := 0; s < d; s++ {
	// 	PrintfDebug("sid: %d -> %v\n", s, sums[s])
	// }

	for i := 0; i < q; i++ {
		l, r := L[i], R[i]
		lid, rid := l/d, r/d
		s := l % d

		ans := sums[s][rid+1] - sums[s][lid+1]
		fmt.Println(ans)
	}
}

func sub(sid int) {
	dist[sid] = append(dist[sid], 0)

	cid := sid
	for cid+d < h*w {
		nid := cid + d
		cy, cx := memo[cid].y, memo[cid].x
		ny, nx := memo[nid].y, memo[nid].x

		diff := AbsInt(cx-nx) + AbsInt(cy-ny)

		dist[sid] = append(dist[sid], diff)
		cid = nid
	}
}

