func getScanner(fp *os.File) *bufio.Scanner {
	scanner := bufio.NewScanner(fp)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 500001), 500000)
	return scanner
}

func getNextString(scanner *bufio.Scanner) string {
	scanner.Scan()
	return scanner.Text()
}

func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}

func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	h := getNextInt(scanner)
	w := getNextInt(scanner)
	d := getNextInt(scanner)
	var aa [300][300]int

	points := make([]Point, h*w)
	sums := make([]int, h*w)

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			aa[y][x] = getNextInt(scanner) - 1
			points[aa[y][x]] = Point{
				x: x,
				y: y,
			}
		}
	}
	for i := 0; i < h*w; i++ {
		if i-d < 0 {
			continue
		}
		sums[i] = sums[i-d]
		sums[i] += absint(points[i].x-points[i-d].x) + absint(points[i].y-points[i-d].y)
	}
	q := getNextInt(scanner)

	for i := 0; i < q; i++ {
		l := getNextInt(scanner) - 1
		r := getNextInt(scanner) - 1
		fmt.Fprintln(writer, sums[r]-sums[l])
	}

	writer.Flush()
}

