			var a int
			fmt.Scan(&a)
			po[a] = xy{i + 1, j + 1}
		}
	}

	cost := make([][]int, D)
	for i := 0; i < D; i++ {
		cost[i] = make([]int, H*W/D+10)
	}

	for i := D + 1; i <= W*H; i++ {
		cost[i%D][i/D] = calc(po[i-D], po[i]) + cost[i%D][i/D-1]
	}

	var Q int
	fmt.Scan(&Q)
	for i := 0; i < Q; i++ {
		var L, R int
		fmt.Scan(&L)
		fmt.Scan(&R)

		fmt.Println(cost[R%D][R/D] - cost[L%D][L/D])
	}
}
