	} else {
		return -a
	}
}

func (p pos) d(q pos) int {
	return abs(p.x-q.x) + abs(p.y-q.y)
}

var poss []pos

var dp [][]int

func dist(L, R int) int {
	if L == R {
		dp[L][R] = 0
		return 0
	} else if L+D == R {
		dp[L][R] = poss[L].d(poss[R])
		return dp[L][R]
	} else {
		if dp[L][L+D] == 0 {
			dp[L][L+D] = dist(L, L+D)
		}
		if dp[L+D][R] == 0 {
			dp[L+D][R] = dist(L+D, R)
		}
		return dp[L][L+D] + dp[L+D][R]
	}
}

