const (
	initialBufSize = 100000
	maxBufSize     = 10000000
)

var (
	sc = bufio.NewScanner(os.Stdin)
	wt = bufio.NewWriter(os.Stdout)
)

func next() string {
	sc.Scan()
	return sc.Text()
}

func nextInt() int {
	i, _ := strconv.Atoi(next())
	return i
}

func nextInts(n int) []int {
	slice := make([]int, n)
	for i := 0; i < n; i++ {
		slice[i] = nextInt()
	}
	return slice
}

func puts(a ...interface{}) {
	fmt.Fprintln(wt, a...)
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, initialBufSize), maxBufSize)
	defer wt.Flush()

	h, w, d := nextInt(), nextInt(), nextInt()
	a := make([][]int, h)
	for i := range a {
		a[i] = nextInts(w)
	}

	// point[x]: xが書かれているマスの座標(y,x)
	point := make([][2]int, h*w+1)
	for i := range a {
		for j := range a[i] {
			x := a[i][j]
			point[x] = [2]int{i, j}
		}
	}

	// cost[i][j]: 整数iから整数jへ遷移するときのコスト
	cost := make([][]int, h*w+1)
	for i := range cost {
		cost[i] = make([]int, h*w+1)
	}
	for i := 1; i <= h*w; i++ {
		for j := i + d; j <= h*w; j += d {
			x1, y1 := point[j-d][0], point[j-d][1]
			x2, y2 := point[j][0], point[j][1]
			cost[i][j] = cost[i][j-d] + abs(x2-x1) + abs(y2-y1)
		}
	}

	q := nextInt()
	for i := 0; i < q; i++ {
		l, r := nextInt(), nextInt()
		ans := cost[l][r]
		puts(ans)
	}
}

