		costs[i] = costs[i-D] + (abs(cPoint.x-bPoint.x) + abs(cPoint.y-bPoint.y))
	}

	var Q int
	fmt.Fscan(r, &Q)

	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()

	var L, R int
	for i := 0; i < Q; i++ {
		fmt.Fscan(r, &L)
		fmt.Fscan(r, &R)

		fmt.Fprintln(w, costs[R]-costs[L])
