// Data :
type Data struct {
	n, x, y int
	cost    int
}

// Datas :
type Datas []Data

func (p Datas) Len() int {
	return len(p)
}

func (p Datas) Swap(i, j int) {
	p[i], p[j] = p[j], p[i]
}

func (p Datas) Less(i, j int) bool {
	return p[i].n < p[j].n
}

func main() {
	sc.Split(bufio.ScanWords)
	H, W, D := getInt(), getInt(), getInt()
	N := H * W
	n := make(Datas, N)
	idx := 0
	for i := 0; i < H; i++ {
		for j := 0; j < W; j++ {
			a := getInt()
			n[idx] = Data{a, j, i, 0}
