		for j := i+D; j <= H*W; j += D {
			costs[index][j] = costs[index][j-D] + abs(numMap[j-D][0] - numMap[j][0]) + abs(numMap[j-D][1] - numMap[j][1])
		}
	}

	//for i := 0; i < D; i++ {
	//	fmt.Println(i, costs[i])
	//}

	for i := 0; i < Q; i++ {
		lIndex := L[i] % D
		rIndex := R[i] % D

		startCost := costs[lIndex][L[i]]
		endCost := costs[rIndex][R[i]]

		fmt.Println(endCost - startCost)
	}
}

