auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto hwd = input.front.split.to!( long[] );
	auto ass = new long[][]( hwd[ 0 ], hwd[ 1 ] );
	foreach( ref as; ass )
	{
		input.popFront;
		as = input.front.split.to!( long[] );
	}
	input.popFront;
	auto q = input.front.to!( long );
	auto lrs = new long[ 2 ][ q ];
	foreach( ref lr; lrs )
	{
		input.popFront;
		lr = input.front.split.to!( long[] );
	}
	return tuple( hwd[ 2 ], ass, lrs );
}

auto solve( long d, long[][] ass, long[ 2 ][] lrs )
{
	// マス目を番号基準の座標配列に変換
	auto ids = new Tuple!( long, long )[ 1 + ass.length * ass[ 0 ].length ];
	foreach( y, as; ass )
	{
		foreach( x, a; as )
		{
			ids[ a ] = tuple( y, x );
		}
	}

	// 消費魔力の累積和を計算
	auto cs = new long[ ids.length ];
	for( auto i = 1L; i + d < cs.length; i++ )
	{
		cs[ i + d ] = cs[ i ] + abs( ids[ i + d ][ 0 ] - ids[ i ][ 0 ] ) + abs( ids[ i + d ][ 1 ] - ids[ i ][ 1 ] );
	}

	// 試験ごとの消費魔力を計算
	return lrs.map!( ( lr ) => ( cs[ lr[ 1 ] ] - cs[ lr[ 0 ] ] ).to!string ).join( "\n" );
}

