    }
    long[2][] table = new long[2][](H * W + 1);
    foreach (h; 0 .. H)
    {
        auto input = readln.chomp.split(' ').map!(to!long).array;
        foreach (w, n; input)
        {
            table[n] = [h, w];
        }
