            table.memoize!calc(L, R, D).writeln();
        }
    }
}

long calc(ref long[2][] table, long L, long R, long D)
{
    if (L == R)
        return 0;
    auto from = table[L];
    auto to = table[L + D];
    long cost = abs(from[0] - to[0]) + abs(from[1] - to[1]);
    return table.memoize!calc(L + D, R, D) + cost;
}

