auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto hwd = input.front.split.to!( long[] );
	auto ass = new long[][]( hwd[ 0 ], hwd[ 1 ] );
	foreach( ref as; ass )
	{
		input.popFront;
		as = input.front.split.to!( long[] );
	}
	input.popFront;
	auto q = input.front.to!( long );
	auto lrs = new long[ 2 ][ q ];
	foreach( ref lr; lrs )
	{
		input.popFront;
		lr = input.front.split.to!( long[] );
	}
	return tuple( hwd[ 2 ], ass, lrs );
}

auto solve( long d, long[][] ass, long[ 2 ][] lrs )
{
	// マス目を番号基準の座標配列に変換
	auto ids = new Tuple!( long, long )[ 1 + ass.length * ass[ 0 ].length ];
	foreach( y, as; ass )
	{
		foreach( x, a; as )
		{
			ids[ a ] = tuple( y, x );
		}
	}

	// L % D に対するLの最小値とRの最大値を判定
	long[ long ] ps;
	long[ long ] lmins;
	long[ long ] rmaxs;
	foreach( lr; lrs )
	{
		auto p = lr[ 0 ] % d;
		ps[ lr[ 0 ] ] = p;
		if( p !in lmins ) lmins[ p ] = lr[ 0 ];
		else              lmins[ p ] = min( lmins[ p ], lr[ 0 ] );
		if( p !in rmaxs ) rmaxs[ p ] = lr[ 1 ];
		else              rmaxs[ p ] = max( rmaxs[ p ], lr[ 1 ] );
	}

	// Lの最小値からRの最大値まで移動したときの消費魔力を計算
	long[ long ][ long ] cs;
	foreach( p; ps )
	{
		auto lmin = lmins[ p ];
		auto rmax = rmaxs[ p ];
		cs[ lmin ][ lmin ] = 0L;
		for( auto r = lmin, rd = r + d; r < rmax; r += d, rd += d )
		{
			cs[ lmin ][ rd ] = cs[ lmin ][ r ] + abs( ids[ rd ][ 0 ] - ids[ r ][ 0 ] ) + abs( ids[ rd ][ 1 ] - ids[ r ][ 1 ] );
		}
	}

	// 試験ごとの消費魔力を取得
	auto anss = new long[]( lrs.length );
	foreach( ref ans, lr; lockstep( anss, lrs ) )
	{
		auto lmin = lmins[ ps[ lr[ 0 ] ] ];
		ans = cs[ lmin ][ lr[ 1 ] ] - cs[ lmin ][ lr[ 0 ] ];
	}
	return anss.to!( string[] ).join( "\n" );
}

