        while _st != ed:
            cy, cx = MAP[_st]
            ny, nx = MAP[_st + D]
            count += abs(ny - cy) + abs(nx - cx)
            DUP_CASE[(st, _st + D)] = count
            _st += D
        buff.write(str(count) + "\n")
    print(buff.getvalue())
    buff.close()

