def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap



@mt
def slv(H, W, D, A, Q, LR):
    A_ = {}
    for i, r in enumerate(A):
        for j, c in enumerate(r):
            A_[c] = (i, j)

    @lru_cache(maxsize=None)
    def f(l, r):
        if l == r:
            return 0
        ans = 0
        i, j = A_[l]
        x, y = A_[l+D]
        l += D
        ans += abs(x-i)
        ans += abs(y-j)
        ans += f(l, r)
        return ans

    for l, r in LR:
        print(f(l, r))




