def main():
    # find cumulative sum using a period of D O(N) -> O(1) for each query
    H, W, D, *X = map(int, open(0).read().split())
    memo = [None] * (H * W + 1)  # memo[x] := coordinate of x
    for i, a in enumerate(zip(*[iter(X[: H * W])] * W), 1):
        for j, x in enumerate(a, 1):
            memo[x] = (i, j)
    dist = [0] * (H * W + 1)  # dist[x] := distance to x from 1
    for r in range(D + 1, H * W + 1):
        (rx, ry), (lx, ly) = memo[r], memo[r - D]
        dist[r] = dist[r - D] + abs(rx - lx) + abs(ry - ly)
    ans = []
    for l, r in zip(*[iter(X[H * W + 1 :])] * 2):
        ans.append(dist[r] - dist[l])
    print("\n".join(map(str, ans)))


