def telepo_test(start, goal, delta, board):
    c_s = get_coordinate(start, board)
    c_g = get_coordinate(goal, board)

    mp = 0
    while c_s != c_g:
        target = board[c_s[0]][c_s[1]] + delta
        c_t = get_coordinate(target, board)
        mp += abs(c_t[0] - c_s[0]) + abs(c_t[1] - c_s[1])
        c_s = c_t
    return mp


def get_coordinate(n, board):
