class Square:
    def __init__(self, num, x, y):
        self.num = num
        self.x = x
        self.y = y
        self.adj = {self.num: 0}

    def merge(self, other):
        dist = abs(self.x - other.x) + abs(self.y - other.y)
        for k, m in other.adj.items():
            self.adj[k] = dist + m


