        for x in range(1, W + 1):
            if A[y][x] == num:
                return {
                    "y": y,
                    "x": x
                }

def calc_magic(src_y, src_x, dst_y, dst_x):
    return abs(dst_x - src_x) + abs(dst_y - src_y)

