def solve(string):
    h, w, d, *a = map(int, string.split())
    a, q, lr = a[:h * w], a[h * w], a[h * w + 1:]
    n = h * w
    index = [a.index(i + 1) for i in range(h * w)]
    costs = [
        [0 if j <= i or (j - i) % d != 0 else n * (j - i) // d for j in range(n)] for i in range(n)
    ]
    for s in range(n):
        if sum(costs[s]) == 0:
            continue
        for g in range(n):
            if costs[s][g] == 0:
                continue
            if s - d >= 0:
                costs[s][g] = costs[s - d][g] - costs[s - d][s]
                continue
            before = 0 if g - d < 0 else costs[s][g - d]
            costs[s][g] = abs(index[g - d] // w - index[g] // w) + abs(index[g - d] % w -
                                                                       index[g] % w) + before
    return "\n".join([str(costs[l - 1][r - 1]) for l, r in zip(lr[::2], lr[1::2])])


