def dp_search(L, R, D, num_dic):
    global dp
    if dp[L][R] != 0:
        return dp[L][R]
    if L== R:
        return 0

    if L + D == R:
        now_pos = num_dic[L]
        next_pos = num_dic[R]
        dp[L][R] =  abs(next_pos[0] - now_pos[0]) + abs(next_pos[1] - now_pos[1])
        return dp[L][R]

    dp[L][R] = dp_search(L , R - D, D , num_dic) + dp_search(L + D , R, D , num_dic)

    return dp[L][R]


