def uni_norm(pos_a, pos_b):
    return abs(pos_a[0] - pos_b[0]) + abs(pos_a[1] - pos_b[1])

def solve(l, r, d, posses):
    if l >= r:
        return 0
    else:
        return uni_norm(posses[l], posses[l+d]) + solve(l+d, r, d, posses)

