fn main() {
    let hwd: Vec<usize> = read_vec();
    let h = hwd[0];
    let w = hwd[1];
    let d = hwd[2] as usize;
    let mat: Vec<Vec<usize>> = read_vec2(h);
    let hw = h * w;
    let mut axis: Vec<(usize, usize)> = vec![(0, 0); hw];
    for i in 0..h {
        for j in 0..w {
            axis[mat[i][j] - 1] = (i, j);
        }
    }

    let mut mp: Vec<u32> = vec![0; hw];

    if hw % d == 0 {
        for _ in 0..d {
            let mut j = 0;
            let mut tmp = 0;
            loop {
                let nj = (j + d) % hw;
                tmp += abs(axis[nj].0, axis[j].0) + abs(axis[nj].1, axis[j].1);
                mp[nj] = tmp as u32;
                j = nj;
                if j == 0 {
                    break;
                }
            }
        }
    } else {
        let mut j = 0;
        let mut tmp = 0;
        loop {
            let nj = (j + d) % hw;
            tmp += abs(axis[nj].0, axis[j].0) + abs(axis[nj].1, axis[j].1);
            mp[nj] = tmp as u32;
            j = nj;
            if j == 0 {
                break;
            }
        }
    }

    let q: usize = read();
    let mut ans = vec![0; q];
    for i in 0..q {
        let lr: Vec<usize> = read_vec();
        let l = lr[0] - 1;
        let r = lr[1] - 1;
        ans[i] = mp[r] - mp[l];
    }

    for a in ans {
        println!("{}", a);
    }
}

