    for _ in 0..num_queries {
        let headers = read_cols::<u64>();
        let l = headers[0];
        let r = headers[1];

        let mut power = 0;
        for i in 0..(r - l)/d {
            let prev = l + i * d;
            let next = l + (i + 1) * d;

            let prev_cell = cell_indexes[prev as usize];
            let next_cell = cell_indexes[next as usize];

            power += (prev_cell.0 - next_cell.0).abs() + (prev_cell.1 - next_cell.1).abs();
        }

        println!("{}", power);
    }
}

