            grid[line[j-1]] = (i as i64, j as i64);
        }
    }
    let mut cost = vec![0;h*w+1];
    for i in 1..d+1{
        cost[i] = 0;
    }

    for i in d+1..h*w+1{
        cost[i] = cost[i - d] + (grid[i].0 - grid[i-d].0).abs() + (grid[i].1 - grid[i-d].1).abs();
    }

    //queries
    let q: usize = read_as_vec()[0];

    for _ in 0..q{
        let line = read_as_vec::<usize>();
        let (l, r) = (line[0], line[1]);

        println!("{}",cost[r] - cost[l]);
    }
}

