    io::stdin().read_line(&mut buf).unwrap();
    let mut iter = buf.trim().split_whitespace();
    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let d: usize = iter.next().unwrap().parse().unwrap();
    let mut pos = vec![(0, 0); (h * w)].into_boxed_slice();
    for i in 0..h as usize {
        let mut buf = String::new();
        io::stdin().read_line(&mut buf).unwrap();
        let mut iter = buf.trim().split_whitespace();
        for j in 0..w as usize{
            let num = iter.next().unwrap().parse::<usize>().unwrap();
            pos[num - 1] = (j, i);
        }
    }
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    let q = buf.trim().parse::<usize>().unwrap();
    for _ in 0..q {
