        D: usize,
        A: [[usize1;W];H],
        Q: usize,
        lr: [(usize1, usize1); Q],
    }

    let mut ind_flat: Vec<(usize, usize)> = (0..H*W).map(|i| (i/W, i%W)).collect();
    ind_flat.sort_by_key(|ind| A[ind.0][ind.1]);
    let mut sum_cost = vec![0; H*W]; 

    for score in D..H*W {
        sum_cost[score] = sum_cost[score - D] +
            cmp_cost(ind_flat[score-D], ind_flat[score]);
    }

    for &(l, r) in lr.iter() {
        println!("{}", sum_cost[r] - sum_cost[l]);
    }
}

fn cmp_cost(prev: (usize, usize), next: (usize, usize)) -> usize {
    cmp::max(prev.0, next.0) - cmp::min(prev.0, next.0) + 
        cmp::max(prev.1, next.1) - cmp::min(prev.1, next.1)
}

