use input::*;

const INF: isize = 999_999_999_999_999;

fn calc_cost(
    num: isize,
    d: isize,
    index: &mut Vec<(isize, isize)>,
    memo: &mut Vec<isize>,
) -> isize {
    if INF != memo[num as usize] {
        return memo[num as usize];
    }
    if num <= d {
        memo[num as usize] = 0;
        return 0;
    }
    let i1 = index[num as usize];
    let i2 = index[(num - d) as usize];
    let cost = (i1.0 - i2.0).abs() + (i1.1 - i2.1).abs() + calc_cost(num - d, d, index, memo);
    memo[num as usize] = cost;
    memo[num as usize]
}

