use std::io;

fn main() {
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    let mut iter = buf.trim().split_whitespace();
    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let d: usize = iter.next().unwrap().parse().unwrap();
    let mut pos = vec![(0, 0); (h * w)].into_boxed_slice();
    for i in 0..h {
        let mut buf = String::new();
        io::stdin().read_line(&mut buf).unwrap();
        let mut iter = buf.trim().split_whitespace();
        for j in 0..w {
            let num = iter.next().unwrap().parse::<usize>().unwrap();
            pos[num - 1] = (j as i64, i as i64);
        }
    }
    let mut costs = vec![0; (h * w)].into_boxed_slice();
    for i in d..(h * w) {
        costs[i] = costs[i - d] +
            (pos[i].0 - pos[i - d].0).abs() + (pos[i].1 - pos[i - d].1).abs();
    }
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    let q = buf.trim().parse::<usize>().unwrap();
    for _ in 0..q {
        let mut buf = String::new();
        io::stdin().read_line(&mut buf).unwrap();
        let mut iter = buf.trim().split_whitespace();
        let mut l = iter.next().unwrap().parse::<usize>().unwrap();
        let r = iter.next().unwrap().parse::<usize>().unwrap();
        println!("{}", costs[r - 1] - costs[l - 1]);
    }
}

use std::io::prelude::*;

fn input<T>() -> T
where
    T: std::str::FromStr,
{
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let h: usize = input();
    let w: usize = input();
    let d: usize = input();
    let a: Vec<Vec<usize>> = (0..h).map(|_| (0..w).map(|_| input()).collect()).collect();
    let q: usize = input();
    let lr: Vec<(usize, usize)> = (0..q)
        .map(|_| {
            let l = input();
            let r = input();
            (l, r)
        })
        .collect();

    let mut m = std::collections::HashMap::new();
    for i in 0..h {
        for j in 0..w {
            m.insert(a[i][j], (i, j));
        }
    }

    let mut s = vec![0; h * w + 1];
    for i in d + 1..h * w + 1 {
        let p = m.get(&i).unwrap();
        let q = m.get(&(i - d)).unwrap();
        s[i] = s[i - d] + (p.0 as i64 - q.0 as i64).abs() + (p.1 as i64 - q.1 as i64).abs();
    }

    for (l, r) in lr {
        println!("{}", s[r] - s[l]);
    }
}

