fn main() {
    read!(h = usize, w = usize, d = usize);
    let table = read_table_rows::<usize_>(h);
    let mut coordinates = vec![(0, 0); h*w];
    for i in table.indices() {
        coordinates[table[i]] = i;
    }
    let pref_sums: Vec<Vec<usize>> = (0..d).map(|i| {
        // let xs: Vec<(usize, usize)> = coordinates[i..].iter().cloned().step_by_(d).collect();
        let mut xs = Vec::new();
