            let x = map[j-d];
            let y = map[j]; 
            vec[i][(j-1)/d] = vec[i][(j-1)/d-1] + (x.0-y.0).abs() + (x.1-y.1).abs();
            j += d;
        }
    }

    for (l,r) in lr {
        let st = (l-1)%d+1;
        println!("{}", vec[st][(r-1)/d]-vec[st][(l-1)/d]);
    }
}

