fn solve(
    a: &Vec<(usize, usize)>,
    d: usize,
    l: usize,
    r: usize,
    cache: &mut BTreeMap<(usize, usize, usize), usize>,
) -> usize {
    if let Some(s) = cache.get(&(d, l, r)) {
        return *s;
    }
    let mut s = 0;
    let mut xy = a[l];
    let mut c = l;
    while c + d <= r {
        s += distance(xy, a[c + d]);
        xy = a[c + d];
        c += d;
    }
    cache.insert((d, l, r), s);
    s
}

fn distance(p1: (usize, usize), p2: (usize, usize)) -> usize {
    let (x1, y1) = p1;
    let (x2, y2) = p2;
    (if x1 > x2 { x1 - x2 } else { x2 - x1 }) + (if y1 > y2 { y1 - y2 } else { y2 - y1 })
}

fn compress(a: &Vec<Vec<usize>>) -> Vec<(usize, usize)> {
    let mut r = vec![(0, 0); 180000];
    for (i, l) in a.iter().enumerate() {
        for (j, x) in l.iter().enumerate() {
            r[*x] = (i, j);
        }
    }
    r
}

