fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let h: usize = sc.read();
    let w: usize = sc.read();
    let d: usize = sc.read();
    let mut ida = vec![(0, 0); h * w];
    for i in 0..h {
        for j in 0..w {
            let a: usize = sc.read();
            ida[a - 1] = (i, j);
        }
    }

    let def = |a, b| {
        if a > b {
            a - b
        } else {
            b - a
        }
    };
    let cst = |a, b| {
        let (i, j) = ida[a];
        let (p, q) = ida[b];
        def(i, p) + def(j, q)
    };

    let mut sum = vec![vec![0; h * w / d + 2]; d];
    for r in 0..d {
        let mut i = 0;
        let mut v = i * d + r;
        while v + d < h * w {
            sum[r][i + 1] = sum[r][i] + cst(v, v+d);
            i += 1;
            v += d;
        }
    }

    let mut ret = String::new();
    use std::fmt::Write;

    let q: usize = sc.read();
    for _ in 0..q {
        let l: usize = sc.read();
        let r: usize = sc.read();
        let (l, r) = (l-1, r-1);
        let rem = l % d;
        writeln!(&mut ret, "{}", sum[rem][r/d] - sum[rem][l/d]).unwrap();
    }

    ret
}
fn main() {
    let mut buf = String::new();
    use std::io::{Read, Write};
    std::io::stdin().read_to_string(&mut buf).unwrap();
    std::io::stdout().write_all(solve(&buf).as_bytes()).unwrap();
}
