fn run() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let h: usize = sc.read();
    let w: usize = sc.read();
    let d: usize = sc.read();
    let a = sc.read_matrix::<usize>(h, w);
    let q: usize = sc.read();

    let mut hmap = HashMap::new();
    for i in 0..h {
        for j in 0..w {
            hmap.insert(a[i][j] - 1, (i as i64, j as i64));
        }
    }

    let mut cum = vec![0; h * w];
    for i in d..(h * w) {
        cum[i] = cum[i - d]
            + (hmap[&i].0 - hmap[&(i - d)].0).abs()
            + (hmap[&i].1 - hmap[&(i - d)].1).abs();
    }
    for _ in 0..q {
        let l: usize = sc.read();
        let r: usize = sc.read();
        println!("{}", cum[r - 1] - cum[l - 1]);
    }
}

