   let mag_dif = |(x1, y1): (i32, i32), (x2, y2): (i32, i32)| (x1 - x2).abs() + (y1 - y2).abs();
   for i in 0..d {
      mag[i].push(0);
      let mut j = 1;
      while i + d * j < h * w {
         let x = mag[i][j - 1] + mag_dif(map[&(i + d * (j - 1))], map[&(i + d * j)]);
         mag[i].push(x);
         j += 1;
      }
   }
   for (l, r) in lr {
      let i = l % d;
      println!("{}", mag[i][r / d] - mag[i][l / d]);
   }
}

