fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(&mut i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: &mut R, o: &mut W) {
    let hwd = read_vec(i);
    let (h, w, d) = (hwd[0], hwd[1], hwd[2]);
    let wh = w * h;
    let mut a_to_xy = vec![(0, 0); wh + 1];
    for y in 0..h {
        let a: Vec<usize> = read_vec(i);
        for x in 0..w {
            a_to_xy[a[x]] = (x, y);
        }
    }
    fn abs_sub(x0: usize, s1: usize) -> usize {
        (x0 as isize - s1 as isize).abs() as usize
    }

    let mut mps = vec![0; wh + 1];
    for i in 1..wh + 1 - d {
        let xy0 = a_to_xy[i];
        let xy1 = a_to_xy[i + d];
        mps[i + d] = mps[i] + abs_sub(xy0.0, xy1.0) + abs_sub(xy0.1, xy1.1);
    }
    std::mem::drop(a_to_xy);

    let q = read(i);
    for _ in 0..q {
        let lr = read_vec(i);
        let (l, r): (usize, usize) = (lr[0], lr[1]);
        let mp = mps[r] - mps[l];
        writeln!(o, "{}", mp).unwrap();
    }
}

fn read_line<R: BufRead>(i: &mut R) -> String {
    let mut line = String::new();
    i.read_line(&mut line).unwrap();
    line.trim().to_string()
}

fn read<T: FromStr, R: BufRead>(i: &mut R) -> T {
    read_line(i).parse().ok().unwrap()
}
fn read_vec<T: FromStr, R: BufRead>(i: &mut R) -> Vec<T> {
    read_line(i)
        .split(' ')
        .map(|x| x.parse().ok().unwrap())
        .collect()
}

use proconio::marker::Usize1;
fn main() {
    proconio::input! {
        h: usize,
        w: usize,
        d: usize,
        a: [[Usize1;w];h],
        q: usize,
        lr: [(Usize1,Usize1);q],
    }
    let n=h*w;
    let mut p=vec![(0,0);n];
    for i in 0..h {
        for j in 0..w {
            p[a[i][j]]=(i,j);
        }
    }
    let m=n.next_power_of_two().trailing_zeros()as usize+1;
    let mut s=vec![vec![0;n];m];
    for i in 0..n-d {
        let (x1,y1)=p[i];
        let (x2,y2)=p[i+d];
        s[0][i]=x1.max(x2)-x1.min(x2)+y1.max(y2)-y1.min(y2);
    }
    for i in 0..m-1 {
        let d=d*(1<<i);
        for k in 0..n-d.min(n) {
            s[i+1][k]=s[i][k]+s[i][k+d];
        }
    }
    for (l,r) in lr {
        let k=(r-l)/d;
        let mut x=l;
        let mut t=0;
        for i in (0..m).rev() {
            if k>>i&1==1 {
                t+=s[i][x];
                x+=d*(1<<i);
            }
        }
        println!("{}",t);
    }
}

