macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (h, w, d): (usize, usize, usize) = parse!(it, 3);
    let mut map = vec![(0, 0); h * w];
    for i in 0..h {
        for j in 0..w {
            let k: usize = parse!(it);
            map[k - 1] = (i, j);
        }
    }
    let mut costs = vec![vec![]; d];
    let abs = |x, y| if x > y { x - y } else { y - x };
    for i in 0..d {
        let mut cur = i;
        let mut cost = 0;
        loop {
            let next = cur + d;
            if next >= h * w {
                break;
            }
            cost += abs(map[next].0, map[cur].0) + abs(map[next].1, map[cur].1);
            costs[i].push(cost);
            cur = next;
        }
    }

    let q: usize = parse!(it);
    for _ in 0..q {
        let (l, r): (usize, usize) = parse!(it, 2);
        let l = l - 1;
        let r = r - 1;
        println!(
            "{}",
            if r < d { 0 } else { costs[l % d][r / d - 1] }
                - if l < d { 0 } else { costs[l % d][l / d - 1] }
        );
    }
}

