       map:[[usize;W];H],
       Q:usize,
       query:[(usize,usize);Q],

    }

    let mut ans: usize = 0;
    let mut a = vec![];
    let mut s = vec![HashMap::new(); D];
    for i in 0..H {
        for j in 0..W {
            a.push((map[i][j], i, j));
        }
    }
    a.sort_by_key(|&(x, _, _)| x);

    for i in 0..D {
        let k = i + 1;
        s[k % D].insert(k, 0);
    }
    for i in D..a.len() {
        let (c, x, y) = a[i];
        let (d, ii, jj) = a[i - D];
        let b = c % D;
        s[b].entry(d).or_insert(0);
        let e = *s[b].get(&d).unwrap();

        s[b].insert(
            c,
            e + ((x as i32 - ii as i32).abs() + (y as i32 - jj as i32).abs()) as usize,
        );
    }

    for &(l, r) in &query {
        let b = l % D;
        let mut c = *s[b].get(&l).unwrap();
        let mut d = *s[b].get(&r).unwrap();
        echo!(d - c);
    }
}

