use std::str::FromStr;
use std::io::*;

fn main() {
    let i = stdin();
    let o = stdout();
    run(&mut i.lock(), &mut o.lock());
}

fn run(i: &mut BufRead, o: &mut Write) {
    let hwd = read_vec::<usize>(i);
    let (h, w, d) = (hwd[0], hwd[1], hwd[2]);
    let wh = w * h;
    let mut a_to_xy = vec![(0, 0); wh + 1];
    for y in 0..h {
        let a = read_vec::<usize>(i);
        for x in 0..w {
            a_to_xy[a[x]] = (x, y);
        }
    }
    fn abs_sub(x0: usize, s1: usize) -> usize {
        (x0 as isize - s1 as isize).abs() as usize
    }

    let mut mps = vec![0; wh + 1];
    for i in 1..wh + 1 - d {
        let xy0 = a_to_xy[i];
        let xy1 = a_to_xy[i + d];
        mps[i + d] = mps[i] + abs_sub(xy0.0, xy1.0) + abs_sub(xy0.1, xy1.1);
    }

    let q = read::<usize>(i);
    for _ in 0..q {
        let lr = read_vec::<usize>(i);
        let (l, r) = (lr[0], lr[1]);
        let mp = mps[r] - mps[l];
        writeln!(o, "{}", mp).unwrap();
    }
}

fn read_line(i: &mut BufRead) -> String {
    let mut line = String::new();
    i.read_line(&mut line).unwrap();
    line.trim().to_string()
}

fn read<T: FromStr>(i: &mut BufRead) -> T {
    read_line(i).parse().ok().unwrap()
}
fn read_vec<T: FromStr>(i: &mut BufRead) -> Vec<T> {
    read_line(i)
        .split(' ')
        .map(|x| x.parse().ok().unwrap())
        .collect()
}

use std::io;
use std::io::prelude::*;
use std::cmp::{max, min};
use std::str::FromStr;

fn main() {
    let hwd: Vec<usize> = reads(&get_line());
    let (h, w, d) = (hwd[0], hwd[1], hwd[2]);
    let locs = read_locs(h as usize, w as usize);
    let mut costs: Vec<Vec<u32>> = vec![vec![]];
    for offset in 1..d + 1 {
        // because 1-indexed
        // I would really like to use `scan`
        // but some interfaces I'd hope for are missing..??
        let mut costl = vec![0];
        let mut c = 0;
        for mul in 1..1 + (w * h - offset) / d {
            c += mhd(locs[offset + (mul - 1) * d], locs[offset + mul * d]);
            costl.push(c);
        }
        costs.push(costl);
    }
    let q: usize = get_line().parse().unwrap();
    let tasks: Vec<Task> = get_lines(q).iter().map(|l| parse_task(l)).collect();
    for task in tasks {
        let offset = match task.l % d as usize {
            0 => d as usize,
            m => m,
        };
        let this_cost = costs[offset][(task.r - offset) / d as usize]
            - costs[offset][(task.l - offset) / d as usize];
        println!("{}", this_cost);
    }
}

/// returns a Vec. locs[n] returns (x,y), the (0-origin) coordinate
/// of the grid with the value `n`.
fn read_locs(h: usize, w: usize) -> Vec<(u32, u32)> {
    let stdin = io::stdin();
    let mut locs: Vec<(u32, u32)> = Vec::with_capacity(h * w + 1);
    unsafe {
        // something I'd like to have entry?
        locs.set_len(h * w + 1);
    }
    // FIXME : locs[0] is unsafe. Option<_> will be too verbose, but.....
    let lock = stdin.lock();
    for (i, l) in lock.lines().take(h).enumerate() {
        // can't we just annotate type for `n`?
        // also, can't the rustc just infer n as usize?
        for (j, &n) in reads::<usize>(&l.unwrap()).iter().enumerate() {
            locs[n] = (i as u32, j as u32);
        }
    }
    locs
}

fn mhd(p0: (u32, u32), p1: (u32, u32)) -> u32 {
    max(p0.0, p1.0) - min(p0.0, p1.0) + max(p0.1, p1.1) - min(p0.1, p1.1)
}

fn get_line() -> String {
    let mut inp = String::new();
    io::stdin().read_line(&mut inp).expect("read error");
    inp.trim().to_string()
}

fn get_lines(n: usize) -> Vec<String> {
    let stdin = io::stdin();
    let lock = stdin.lock();
    let lines = lock.lines().take(n).map(|l| l.unwrap()).collect(); // for lifetime?
    lines
}

fn reads<T>(input: &str) -> Vec<T>
where
    T: FromStr,
    T::Err: std::fmt::Debug,
{
    input
        .trim()
        .split_whitespace()
        .map(|n| n.parse().unwrap())
        .collect()
}

fn parse_task(input: &str) -> Task {
    let ns: Vec<usize> = reads(input);
    Task { l: ns[0], r: ns[1] } // hate this verboseness
}

struct Task {
    l: usize,
    r: usize,
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

