static BINARY: &'static str = "";
static A_GZ_B64: &'static str = "/tmp/a.gz.b64";
static A_GZ: &'static str = "/tmp/a.gz";
static A_OUT: &'static str = "/tmp/a.out";

fn main() {
    write(A_GZ_B64, BINARY).unwrap();
    let gz = run("/usr/bin/base64", &["-d", A_GZ_B64]).unwrap();
    write(A_GZ, gz).unwrap();
    let bin = run("/bin/gunzip", &["-c", A_GZ]).unwrap();
    write(A_OUT, bin).unwrap();
    let mut permissions = fs::metadata(A_OUT).unwrap().permissions();
    permissions.set_mode(0o330);
    fs::set_permissions(A_OUT, permissions).unwrap();
    panic!("{}", Command::new(A_OUT).exec());
}

fn write<P: AsRef<Path>, C: AsRef<[u8]>>(path: P, contents: C) -> io::Result<()> {
    File::create(path)?.write_all(contents.as_ref())
}

fn run(arg0: &str, args: &[&str]) -> io::Result<Vec<u8>> {
    let child = Command::new(arg0)
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()?;
    let Output { status, stdout, .. } = child.wait_with_output()?;
    if status.success() {
        Ok(stdout)
    } else {
        Err(io::Error::new(io::ErrorKind::Other, status.to_string()))    }
}

