use std::cmp::*;
use std::io::*;

fn main() {
    let mut s: String = String::new();
    stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let h: usize = itr.next().unwrap().parse().unwrap();
    let w: usize = itr.next().unwrap().parse().unwrap();
    let d: usize = itr.next().unwrap().parse().unwrap();
    let mut a: Vec<(i64, i64)> = vec![(0i64, 0i64); h * w + d + 1];
    let mut dp: Vec<i64> = vec![0i64; h * w + d + 1];
    for i in 0..h {
        for j in 0..w {
            let b: usize = itr.next().unwrap().parse().unwrap();
            a[b] = (i as i64, j as i64);
        }
    }
    for i in 0..h * w {
        let from = a[i];
        let to = a[i + d];
        dp[i + d] = dp[i] + (from.0 - to.0).abs() + (from.1 - to.1).abs();
    }

    let q: usize = itr.next().unwrap().parse().unwrap();
    let mut out = Vec::new();
    for _ in 0..q {
        let l: usize = itr.next().unwrap().parse().unwrap();
        let r: usize = itr.next().unwrap().parse().unwrap();
        writeln!(out, "{}", dp[r] - dp[l]).ok();
    }
    stdout().write_all(&out).unwrap();
}

