    let N = H * W;
    let mut X = vec![0; N + 1];
    let mut Y = vec![0; N + 1];
    for i in 0..H {
        for j in 0..W {
            let a = A[i][j];
            X[a] = j as i64;
            Y[a] = i as i64;
        }
    }
    let mut dp = vec![0; N + 1];
    for i in (D + 1)..(N + 1) { dp[i] = dp[i - D] + (X[i] - X[i - D]).abs() + (Y[i] - Y[i - D]).abs(); }

    let ans = (0..Q)
        .map(|i| (dp[R[i]] - dp[L[i]]).to_string())
        .collect::<Vec<_>>()
        .join("\n");

    println!("{}", ans);
}

