fn solve(input: &str) -> String {
    let mut iterator = input.split_whitespace();

    let h: usize = iterator.next().unwrap().parse().unwrap();
    let w: usize = iterator.next().unwrap().parse().unwrap();
    let d: usize = iterator.next().unwrap().parse().unwrap();

    let mut points: Vec<(isize, isize)> = vec![(0, 0); h * w];
    for i in 0..h {
        for j in 0..w {
            let a: usize = iterator.next().unwrap().parse().unwrap();
            points[a - 1] = (i as isize, j as isize);
        }
    }

    let mut costs: Vec<usize> = vec![0; h * w];
    for i in 0..(h * w) {
        if i < d {
            continue;
        }
        costs[i] = costs[i - d] + (points[i].0 - points[i - d].0).abs() as usize + (points[i].1 - points[i - d].1).abs() as usize;
    }

    let mut result = String::new();
    let q: usize = iterator.next().unwrap().parse().unwrap();
    for _ in 0..q {
        let l: usize = iterator.next().unwrap().parse().unwrap();
        let r: usize = iterator.next().unwrap().parse().unwrap();
        let ans = costs[r - 1] - costs[l - 1];
        result.push_str(&format!("{}\n", ans));
    }
    result.trim().to_string()
}

use std::io::*;
use std::str::FromStr;

pub fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let h: usize = read();
    let w: usize = read();
    let d: usize = read();
    let mut map: Vec<(i64, i64)> = vec![(0, 0); h * w + 1];

    for i in 0..h {
        for j in 0..w {
            let a: usize = read();
            map[a] = (i as i64, j as i64);
        }
    }

    let mut a: Vec<(usize, usize)> = vec![];
    let q: usize = read();
    for _ in 0..q {
        let l: usize = read();
        let r: usize = read();
        a.push((l, r));
    }
    let mut dist: Vec<Vec<i64>> = vec![vec![0; (h * w / d + 1) as usize]; d];

    for i in 1..h * w + 1 {
        if i <= d {
            continue;
        }
        if i > d {
            let a = map[i];
            let b = map[i - d];
            dist[i % d][i / d] = dist[i % d][i / d - 1] + (a.0 - b.0).abs() + (a.1 - b.1).abs();
        }
    }

    for i in 0..a.len() {
        let ai = a[i];
        println!("{}", dist[ai.1 % d][ai.1 / d] - dist[ai.0 % d][ai.0 / d]);
    }
}

