fn main() {
    input! {
    h: usize,
    w:usize,
    d:usize,
    a:[[usize;w];h],
    q:usize,
    l:[(usize,usize);q],
    }

    let mut x = vec![0; h * w + 1];
    let mut y = vec![0; h * w + 1];

    for i in 0..h {
        for j in 0..w {
            x[a[i][j]] = j as i32;
            y[a[i][j]] = i as i32;
        }
    }

    let mut cache: HashMap<(usize, usize), i32> = HashMap::new();
    for &(start, end) in &l {
        let mut p = start;
        let mut cost = 0;
        while p != end {
            let mut p1 = p;
            let mut p2 = end;

            if p1 > p2 {
                std::mem::swap(&mut p1, &mut p2);
            }

            match cache.get(&(p1, p2)).clone() {
                Some(x) => {
                    cost += *x;
                    break;
                }
                None => {}
            }

            let to = p + d;

            let mut p1 = p;
            let mut p2 = to;

            if p1 > p2 {
                std::mem::swap(&mut p1, &mut p2);
            }

            let c = cache
                .entry((p1, p2))
                .or_insert((x[p1] - x[p2]).abs() + (y[p1] - y[p2]).abs());
            cost += *c;
            p = to;
        }
        println!("{}", cost);
    }
}

