    for y in 0..H {
        for (x, a) in read_words::<usize>().into_iter().enumerate() {
            A[y][x] = a - 1;
        }
    }

    let costs = {
        let HW = H * W;

        let distance =
            |(y1, x1): (i32, i32), (y2, x2): (i32, i32)| (y1 - y2).abs() + (x2 - x1).abs();

