use std::collections::*;
use std::cmp::*;

struct Scanner<I: Iterator<Item = char>> {
    iter: std::iter::Peekable<I>,
}

macro_rules! exit {
    () => {{
        exit!(0)
    }};
    ($code:expr) => {{
        if cfg!(local) {
            writeln!(std::io::stderr(), "===== Terminated =====")
                .expect("failed printing to stderr");
        }
        std::process::exit($code);
    }}
}

impl<I: Iterator<Item = char>> Scanner<I> {
    pub fn new(iter: I) -> Scanner<I> {
        Scanner {
            iter: iter.peekable(),
        }
    }

    pub fn safe_get_token(&mut self) -> Option<String> {
        let token = self.iter
            .by_ref()
            .skip_while(|c| c.is_whitespace())
            .take_while(|c| !c.is_whitespace())
            .collect::<String>();
        if token.is_empty() {
            None
        } else {
            Some(token)
        }
    }

    pub fn token(&mut self) -> String {
        self.safe_get_token().unwrap_or_else(|| exit!())
    }

    pub fn get<T: FromStr>(&mut self) -> T {
        self.token().parse::<T>().unwrap_or_else(|_| exit!())
    }

    pub fn vec<T: FromStr>(&mut self, len: usize) -> Vec<T> {
        (0..len).map(|_| self.get()).collect()
    }

    pub fn mat<T: FromStr>(&mut self, row: usize, col: usize) -> Vec<Vec<T>> {
        (0..row).map(|_| self.vec(col)).collect()
    }

    pub fn char(&mut self) -> char {
        self.iter.next().unwrap_or_else(|| exit!())
    }

    pub fn chars(&mut self) -> Vec<char> {
        self.get::<String>().chars().collect()
    }

    pub fn mat_chars(&mut self, row: usize) -> Vec<Vec<char>> {
        (0..row).map(|_| self.chars()).collect()
    }

    pub fn line(&mut self) -> String {
        if self.peek().is_some() {
            self.iter
                .by_ref()
                .take_while(|&c| !(c == '\n' || c == '\r'))
                .collect::<String>()
        } else {
            exit!();
        }
    }

    pub fn peek(&mut self) -> Option<&char> {
        self.iter.peek()
    }
}

fn main() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin.bytes().map(|c| c.unwrap() as char));
    let H: usize = sc.get();
    let W: usize = sc.get();
    let D: usize = sc.get();
    let A: Vec<Vec<i64>> = sc.mat(H, W);
    let mut pos = HashMap::new();
    for row in 0..H {
        for col in 0..W {
            pos.insert(A[row][col], (row as i64, col as i64));
        }
    }
    let mut cost = vec![-1i64; H*W+1];
    for i in 1..H*W+1 {
        if cost[i] != -1 {
            continue;
        }
        cost[i] = 0;
        let &(mut nowy, mut nowx) = pos.get(&(i as i64)).unwrap();
        let mut j = i + D;
        while j <= H * W {
            let &(ny, nx) = pos.get(&(j as i64)).unwrap();
            cost[j] = cost[j - D] + (ny - nowy).abs() + (nx - nowx).abs();
            j += D;
            nowy = ny;
            nowx = nx;
        }
    }
    let Q: usize = sc.get();
    for _ in 0..Q {
        let L: usize = sc.get();
        let R: usize = sc.get();
        let ans = cost[R] - cost[L];
        println!("{}", ans);
    }
}

use std::str::FromStr;
use std::io::*;

fn main() {
    let i = stdin();
    run(&mut i.lock(), &mut stdout());
}

fn run(i: &mut BufRead, o: &mut Write) {
    let hwd = read_vec::<usize>(i);
    let (h, w, d) = (hwd[0], hwd[1], hwd[2]);
    let mut a = Vec::new();
    for _ in 0..h {
        a.push(read_vec::<usize>(i));
    }
    let mut a_to_xy = vec![(usize::max_value(), usize::max_value()); w * h + 1];
    for y in 0..h {
        for x in 0..w {
            a_to_xy[a[y][x]] = (x, y);
        }
    }

    let q = read::<usize>(i);
    for _ in 0..q {
        let mut mp = 0;
        let lr = read_vec::<usize>(i);
        let (mut l, r) = (lr[0], lr[1]);
        while l != r {
            let (x0, y0) = a_to_xy[l];
            let (x1, y1) = a_to_xy[l + d];
            fn abs_sub(x0: usize, s1: usize) -> usize {
                (x0 as isize - s1 as isize).abs() as usize
            }
            mp += abs_sub(x0, x1) + abs_sub(y0, y1);
            l += d;
        }
        writeln!(o, "{}", mp).unwrap();
    }
}

fn read_line(i: &mut BufRead) -> String {
    let mut line = String::new();
    i.read_line(&mut line).unwrap();
    line.trim().to_string()
}

fn read<T: FromStr>(i: &mut BufRead) -> T {
    read_line(i).parse().ok().unwrap()
}
fn read_vec<T: FromStr>(i: &mut BufRead) -> Vec<T> {
    read_line(i)
        .split(' ')
        .map(|x| x.parse().ok().unwrap())
        .collect()
}

