    q:usize,
    l:[(usize,usize);q],
    }

    let mut x = vec![0; h * w + 1];
    let mut y = vec![0; h * w + 1];

    for i in 0..h {
        for j in 0..w {
            x[a[i][j]] = j as i32;
            y[a[i][j]] = i as i32;
        }
    }

