        let mut cost = 0;
        while p != end {
            let mut p1 = p;
            let mut p2 = end;

            if p1 > p2 {
                std::mem::swap(&mut p1, &mut p2);
            }

            match cache.get(&(p1, p2)).clone() {
                Some(x) => {
                    cost += *x;
                    break;
                }
                None => {}
            }

            let to = p + d;

