    let mut rev_field = vec![(0, 0); n];
    for y in 0..h {
        for x in 0..w {
            field[y][x] = read::<usize>() - 1;
            rev_field[field[y][x] as usize] = (y as i32, x as i32);
        }
    }
    let mut sums = vec![vec![0; n / d + 2]; d];
    for i in 0..(n-d) {
