        let offset = i % d;
        let index = i / d;
        sums[offset][index + 1] = sums[offset][index] + dist;
    }
    let q: usize = read();
    for _ in 0..q {
        let from: usize = read::<usize>() - 1;
        let to: usize = read::<usize>() - 1;
        let offset = from % d;
        let start = from / d;
        let end = to / d;
        println!("{}", sums[offset][end] - sums[offset][start]);
    }
}

