fn solve(a: &Vec<(usize, usize)>, d: usize, l: usize, r: usize) -> usize {
    let mut s = 0;
    let mut xy = a[l];
    let mut c = l;
    while c + d <= r {
        s += distance(xy, a[c + d]);
        xy = a[c + d];
        c += d;
    }
    s
}

fn distance(p1: (usize, usize), p2: (usize, usize)) -> usize {
    let (x1, y1) = p1;
    let (x2, y2) = p2;
    (if x1 > x2 { x1 - x2 } else { x2 - x1 }) + (if y1 > y2 { y1 - y2 } else { y2 - y1 })
}

