#[fastout()]
fn main() {
    input! {
        h: usize, w: usize, d: usize,
        a: [[usize; w]; h],
        q: usize,
        lr: [(usize, usize); q],
    }

    let mut i2pos = vec![(0, 0); h*w + 1];
    for y in 0..h {
        for x in 0..w {
            let i = a[y][x];
            i2pos[i] = (x as i64, y as i64);
        }
    }

    let mut cost = vec![vec![0; h*w + 1]; 20];
    for i in 1..=h*w - d{ 
        let (x1, y1) = i2pos[i];
        let (x2, y2) = i2pos[i+d];
        cost[0][i] = (x1 - x2).abs() + (y1 - y2).abs();
    }

    for exp in 1..cost.len() {
        let factor = min(h*w, (1<<exp) * d);
        for i in 1..=h*w - factor {
            cost[exp][i] = cost[exp-1][i] + cost[exp-1][i+factor/2];
        }
    }

    for (mut l, r) in lr {
        let mut count = (r - l) / d;
        let mut ans = 0;
        let mut exp = 0;
        while count > 0 {
            while count % 2 == 0 {
                exp += 1;
                count /= 2;
            }
            ans += cost[exp][l];
            l += (1<<exp) * d;
            count -= 1;
        }
        println!("{}", ans);
    }
}

