    let v: Vec<usize> = read_vec();
    (v[0], v[1], v[2])
  };

  let mut dist = vec![(0, 0); h * w + 1];
  for i in 0..h {
    let v: Vec<usize> = read_vec();
    for (j, e) in v.into_iter().enumerate() {
      dist[e] = (i as i64 + 1, j as i64 + 1);
    }
  }

  let mut lr: Vec<(i64, i64)> = Vec::new();
  let q: usize = read();
  for _ in 0..q {
