    lr.push((t[0], t[1]));
  }

  let mut costs = vec![vec![0; (h * w + d - 1) / d]; d];
  for (i, &posit) in dist.iter().enumerate() {
    if i + d < h * w + 1 {
      let (x, y) = decode(i, d);
      costs[x][y] = cost_calc(posit, dist[i + d]);
    }
  }
  let mut sums_costs = vec![vec![0; (h * w + d - 1) / d + 1]; d];

  for (i, line) in costs.iter().enumerate() {
    for (j, &val) in line.iter().enumerate() {
