    println!("{}", sums_costs[a][b] - sums_costs[i][j]);
  }
}

fn cost_calc(x: (i64, i64), y: (i64, i64)) -> i64 {
  (x.0 - y.0).abs() + (x.1 - y.1).abs()
}

