fn solve(d: i32, aa: Vec<Vec<i32>>, lrs: Vec<(i32, i32)>) -> Vec<i32> {

    let mut m = std::collections::HashMap::new();

    for (r, v) in aa.iter().enumerate() {
        for (c, a) in v.iter().enumerate() {
            m.insert(a, (r as i32,c as i32));
        }
    }


    let h = aa.len() as i32;
    let w = aa[0].len() as i32;

    let mut dd = vec![0; 300*300+1];
    for i in (d+1)..(h*w+1) {
        let &(xs, ys) = m.get(&(i-d)).unwrap();
        let &(x, y) = m.get(&i).unwrap();
        dd[i as usize] = dd[(i-d) as usize] + (xs-x).abs() + (ys-y).abs();
    }

    let mut ans = Vec::new();

    for (l, r) in lrs {
        ans.push(dd[r as usize]-dd[l as usize]);
    }

    ans
}

fn main() {
    let (h, _w, d) = parse_line!(usize, usize, i32);
    let aa = parse_table_ws(h);
    let q = parse_line!(usize);
    let lrs = (0..q).map(|_| parse_line!(i32, i32)).collect::<Vec<_>>();

    for v in solve(d, aa, lrs) {
        println!("{}", v);
    }
}

