#[allow(dead_code)]
fn calc_mp(val_to_grid: &HashMap<i64, (isize, isize)>, prev_val: i64, cur_val: i64, D: i64) -> i64 {
    if cur_val <= D {
        return 0;
    }

    let (prev_h, prev_w) = val_to_grid.get(&prev_val).unwrap();
    let (cur_h, cur_w) = val_to_grid.get(&cur_val).unwrap();
    let mp = ((prev_h - cur_h).abs() + (prev_w - cur_w).abs()) as i64;

    return mp;
}

#[fastout]
fn main() {
    input! {
        H: usize,
        W: usize,
        D: i64,
        Asz: [[i64; W]; H],
        Q: usize,
        LRs: [(i64, i64); Q],
    }

    // Asz -> 座標 は10^5オーダで分かる
    // なので、2つのマスに書かれた整数が与えられた時、ワープに必要な魔力はすぐ計算できる

    let mut val_to_grid: HashMap<i64, (isize, isize)> = HashMap::new();
    for h in 0..H {
        for w in 0..W {
            let a = Asz[h][w];
            val_to_grid.insert(a, (h as isize, w as isize));
        }
    }

    // 雰囲気としては、累積和の列がいくつもある感じ

    // 1, 1+D, 1+2D... → 必要な魔力の累積和にする
    // 2, 2+D, 2+2D...
    // 3, 3+D, 3+2D...
    // 0, 0+D, 0+2D... (便宜的に0から始まることにしよう)

    // あれ、イイとこ突いてそうだけど、なんで気付けた?
    // ・進む方向が一方向しかないので、レールがいくつかあってそれのどれかに乗るイメージ

    // 累積和の最初の0、初項の0 (1~D)
    let mut acc = vec![vec![0i64, 0]; D as usize];
    for group in 0..D as usize {
        for cur_val_usize in (group + D as usize..=H * W).step_by(D as usize) {
            let cur_val = cur_val_usize as i64;

            // 初項の0 (1~D)はもう入れたのでスキップ
            // if cur_val <= D {
            //     continue;
            // }

            let prev_val = cur_val - D;
            let mp = calc_mp(&val_to_grid, prev_val, cur_val, D);
            let cur_ind = (cur_val / D) as usize;

            let acc_mp = acc[group as usize][cur_ind] + mp;
            acc[group as usize].push(acc_mp);
        }
    }

    // dbg!(&acc);

    for &(l, r) in LRs.iter() {
        // let mut consumed_mp: i64 = 0;

        // このループ、mpの計算がO(1)で済むとしても最悪O(HW)かかる
        // for x in (l..=r).step_by(D as usize) {
        //     consumed_mp += calc_mp(x, x + D);
        // }

        if l == r {
            println!("0");
            continue;
        }

        // FIXME : group = 0 の時に特殊処理が必要なのはキレイじゃないなー
        let group: usize = (l % D) as usize;
        let l_ind: usize = if group == 0 {
            ((l - group as i64) / D) as usize - 1
        } else {
            ((l - group as i64) / D) as usize
        };
        let r_ind: usize = if group == 0 {
            ((r - group as i64) / D) as usize - 1
        } else {
            ((r - group as i64) / D) as usize
        };
        // dbg!(group);
        // dbg!(l_ind);
        // dbg!(r_ind);

        let consumed_mp: i64 = acc[group][r_ind + 1] - acc[group][l_ind];

        println!("{}", consumed_mp);
    }
}

