    let h: usize = sc.read();
    let w: usize = sc.read();
    let d: usize = sc.read();
    let a: Vec<Vec<usize>> = (0..h).map(|_| {
        (0..w).map(|_| sc.read()).collect()
    }).collect();

    let mut place = vec![(0, 0); h * w + 1];
    for i in 0..h {
        for j in 0..w {
            let x = a[i][j];
            place[x] = (i, j);
        }
    }

    let mut sum = vec![0; h * w + 1];

    for e in 1..(d + 1) {
        let mut cur = e;
        while cur + d <= h * w {
            let (fi, fj) = place[cur];
            let (ti, tj) = place[cur + d];
            let ei = if fi > ti { fi - ti } else { ti - fi };
            let ej = if fj > tj { fj - tj } else { tj - fj };

            sum[cur + d] = sum[cur] + (ei + ej);
            cur += d;
        }
    }


    let q: usize = sc.read();
    for _ in 0..q {
        let l: usize = sc.read();
        let r: usize = sc.read();
        let a = sum[r] - sum[l];
        println!("{}", a);
    }
