fn reads<T>() -> Vec<T>
where
    T: std::str::FromStr,
    <T as std::str::FromStr>::Err: std::fmt::Debug,
{
    read_line()
        .split_whitespace()
        .map(|w| w.parse().unwrap())
        .collect()
}

fn main() {
    let (h, w, d) = {
        let t = reads::<i32>();
        (t[0] as usize, t[1] as usize, t[2])
    };

    let bd: Vec<Vec<i32>> = (0..h).map(|_| reads()).collect();

    let mut rev = vec![(0, 0); h * w];

    for y in 0..h {
        for x in 0..w {
            rev[bd[y][x] as usize - 1] = (x, y);
        }
    }

    let mut acc = vec![0; h * w];

    let dist = |(a, b): (usize, usize), (c, d): (usize, usize)| -> i32 {
        (a as i32 - c as i32).abs() + (b as i32 - d as i32).abs()
    };

    for i in 0..h * w {
        if i as i32 - d >= 0 {
            acc[i] = acc[i - d as usize] + dist(rev[i], rev[i - d as usize]);
        }
    }

    let q = reads()[0];

    for _ in 0..q {
        let (l, r) = {
            let t = reads::<usize>();
            (t[0], t[1])
        };

        println!("{}", acc[r - 1] - acc[l - 1]);
    }
}

