    }
    for i in 0..m-1 {
        let d=d*(1<<i);
        for k in 0..n-d.min(n) {
            s[i+1][k]=s[i][k]+s[i][k+d];
        }
    }
    for (l,r) in lr {
        let k=(r-l)/d;
        let mut x=l;
        let mut t=0;
        for i in (0..m).rev() {
