use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        h: usize,
        w: usize,
        d: usize,
        xss: [[usize1; w]; h],
        q: usize,
        qs: [(usize1,usize1); q],
    }
    let mut a_to_rc = vec![(0, 0); h * w];
    for r in 0..h {
        for c in 0..w {
            a_to_rc[xss[r][c]] = (r, c);
        }
    }
    let mut ys = vec![0; 2 * h * w];
    for i in 0..d {
        let mut k = i;
        while k + d < h * w {
            let (r, c) = a_to_rc[k];
            let (r2, c2) = a_to_rc[k + d];
            let dr = (r as i64 - r2 as i64).abs() as usize;
            let dc = (c as i64 - c2 as i64).abs() as usize;
            ys[k + d] = ys[k] + (dr + dc);
            k += d;
        }
    }
    for &(l, r) in &qs {
        let res = ys[r] - ys[l];
        writeln!(buf, "{}", res);
    }
    buf
}

